// NATE Senior Technician -- 1000 Preguntas -- Maestro HVACR | maestrohvacr.com
// Generado desde archivo de 1001 preguntas del instructor

var NATE_SR_QUESTIONS = [
  { id:"ns_0001", categoria:"NATE_SR_CHILLERS", pregunta:"Un Chiller centrífugo con R-123 presenta una presión de condensación inusualmente alta, pero el flujo de agua y la temperatura de entrada son nominales. ¿Cuál es el paso de diagnóstico más crítico?", opciones:["Verificar la acumulación de gases no condensables y el funcionamiento de la unidad de purga.", "Realizar una limpieza química de los tubos del condensador para eliminar el fouling biológico.", "Ajustar la carga de refrigerante basándose en el subenfriamiento a la salida del condensador.", "Comprobar la calibración de los sensores de presión de descarga y de saturación del sistema."], respuesta_correcta:0, explicacion:"En chillers con R-123 (baja presión), los gases no condensables (aire) elevan la presión de condensación. La unidad de purga es el primer componente a verificar ya que su función es extraer estos gases del sistema." },
  { id:"ns_0002", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, se observa que el separador de aceite está caliente pero la línea de retorno de aceite al colector está fría. ¿Qué indica este síntoma técnico?", opciones:["El flotador interno del separador de aceite se encuentra bloqueado en la posición de cerrado.", "La válvula diferencial de presión del depósito de aceite está permitiendo un bypass excesivo.", "Existe una migración de refrigerante líquido hacia el cárter de los compresores de baja etapa.", "El elemento filtrante del separador está saturado y requiere un reemplazo de servicio urgente."], respuesta_correcta:0, explicacion:"Si el separador está caliente (recibe gas de descarga) pero la línea de retorno está fría, el flotador está trabado cerrado e impide que el aceite separado fluya de regreso al depósito o los compresores." },
  { id:"ns_0003", categoria:"NATE_SR_CEO", pregunta:"Desde la perspectiva de gestión financiera, ¿cuál es el impacto principal de un alto índice de 'callbacks' en una empresa de servicios HVAC de gran escala?", opciones:["La erosión del margen de beneficio neto debido a la duplicación de costos laborales directos.", "El incremento en el costo de oportunidad por la pérdida de nuevas llamadas de ventas de alta.", "La reducción de la moral del equipo técnico al ser asignados a corregir errores de sus colegas.", "El aumento en las primas de seguros de responsabilidad civil por riesgos de daños a la propiedad."], respuesta_correcta:0, explicacion:"Los callbacks duplican costos de mano de obra directa (segundo viaje, segundo diagnóstico) sin generar ingresos adicionales, erosionando directamente el margen de beneficio neto de la empresa." },
  { id:"ns_0004", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema Multi-split Inverter muestra un error de comunicación tras 20 minutos de operación. El voltaje entre S2 y S3 fluctúa entre 0 y 30VDC. ¿Cuál es la causa probable?", opciones:["Interferencia electromagnética causada por cables de comunicación no blindados cerca de AC.", "Un fallo térmico en el módulo de potencia (IPM) de la unidad exterior al alcanzar carga alta.", "La inversión accidental de la polaridad en los cables de interconexión entre las unidades.", "Una fuga de corriente a tierra a través del devanado del motor del ventilador del evaporador."], respuesta_correcta:0, explicacion:"Los cables de comunicación no blindados cerca de líneas de AC captan interferencia electromagnética (EMI), lo que corrompe la señal digital entre unidades y causa errores intermitentes tras estabilizarse la carga." },
  { id:"ns_0005", categoria:"NATE_SR_HEATPUMP", pregunta:"Durante el ciclo de deshielo en una bomba de calor, el soplador interior sigue operando pero el aire sale frío. ¿Qué componente del sistema ha fallado en activarse?", opciones:["El relé de calefacción auxiliar que compensa la caída de temperatura durante el defrost.", "La válvula inversora que no logró cambiar a la posición de refrigeración para el deshielo.", "El interruptor de presión de alta que debería detener el ventilador interior por seguridad.", "El sensor de temperatura de la tubería exterior que determina el fin del ciclo de deshielo."], respuesta_correcta:0, explicacion:"Durante el defrost, el sistema cambia a modo refrigeracion para calentar el serpentin exterior. El calefactor auxiliar (strip heat) debe activarse para compensar el aire frio; si su rele falla, el aire llega frio al interior." },
  { id:"ns_0006", categoria:"NATE_SR_CHILLERS", pregunta:"Se observa un aumento en el 'superheat' del vapor de succión en un chiller de tornillo con inundación de evaporador. ¿Qué ajuste de control es el más adecuado?", opciones:["Verificar el nivel de líquido en el evaporador y calibrar el sensor de nivel ultrasónico.", "Incrementar la apertura de la válvula de expansión para saturar más tubos del evaporador.", "Reducir la velocidad del compresor para permitir que el refrigerante absorba más calor total.", "Purgar el exceso de aceite acumulado en el evaporador que está aislando la transferencia."], respuesta_correcta:0, explicacion:"En un evaporador inundado, el superheat alto indica que el nivel de líquido no cubre suficientes tubos. El sensor de nivel ultrasónico controla la alimentación de refrigerante, y su calibración incorrecta causa bajo nivel y alto superheat." },
  { id:"ns_0007", categoria:"NATE_SR_MANAGEMENT", pregunta:"Al supervisar una cuadrilla, nota que los técnicos omiten la prueba de nitrógeno a 500 PSI en sistemas de R-410A. ¿Cuál es el argumento técnico más sólido para corregirlos?", opciones:["La presión de trabajo operativa puede exceder las presiones de prueba bajas, ocultando fugas.", "El nitrógeno a baja presión no es suficiente para desplazar la humedad atrapada en el aceite.", "Las normativas EPA exigen estrictamente el uso de presiones de prueba de grado industrial.", "El uso de presiones inferiores invalida la garantía del fabricante sobre la estanqueidad total."], respuesta_correcta:0, explicacion:"El R-410A opera a presiones mucho más altas que otros refrigerantes (alrededor de 400+ PSI en descarga). Si se prueba a baja presión, fugas que solo aparecen bajo presión operativa quedarán ocultas y causarán pérdida de gas en campo." },
  { id:"ns_0008", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete de 20 toneladas con dos etapas de enfriamiento, la primera etapa funciona pero la segunda no arranca a pesar del llamado del termostato. ¿Qué revisaría primero?", opciones:["La lógica del controlador de economizador que puede estar bloqueando la segunda etapa mecánica.", "El diferencial de presión del interruptor de flujo de aire que solo permite una etapa por seguridad.", "La continuidad de la bobina del contactor de la segunda etapa bajo condiciones de carga real.", "El sensor de temperatura de aire de retorno que podría estar detectando una carga insuficiente."], respuesta_correcta:0, explicacion:"En unidades paquete con economizador, el controlador puede bloquear la segunda etapa mecánica si detecta que el aire exterior libre puede satisfacer la demanda. Es la causa más común de que una etapa no arranque a pesar de la señal del termostato." },
  { id:"ns_0009", categoria:"NATE_SR_RACK", pregunta:"Un rack de baja temperatura experimenta un aumento en la presión de succión durante la noche. ¿Qué factor ambiental o técnico es el sospechoso más probable?", opciones:["Un fallo en el ventilador del condensador remoto que reduce la capacidad de rechazo de calor.", "La entrada en ciclo de deshielo simultáneo de varias vitrinas debido a una mala programación.", "Una válvula de retención defectuosa en la descarga de un compresor que está fuera de servicio.", "El ajuste incorrecto de la válvula EPR (Evaporator Pressure Regulator) en la línea principal."], respuesta_correcta:1, explicacion:"Cuando varias vitrinas entran en deshielo simultáneamente durante la noche, liberan vapor caliente al cabezal de succión y elevan la presión. Una programación escalonada de deshielos evita este problema." },
  { id:"ns_0010", categoria:"NATE_SR_CEO", pregunta:"Un CEO decide implementar un sistema de incentivos basado en la 'Eficiencia de Facturación' (Billable Efficiency). ¿Qué métrica define mejor este concepto?", opciones:["El porcentaje de horas facturadas al cliente frente al total de horas laboradas por el técnico.", "La cantidad total de ingresos generados por cada técnico en relación al costo de su vehículo.", "El número de reparaciones exitosas realizadas en el primer intento sin necesidad de retorno.", "La reducción porcentual en el inventario de piezas no utilizadas que se mantienen en la van."], respuesta_correcta:0, explicacion:"La Eficiencia de Facturación (Billable Efficiency) mide el porcentaje de horas que el técnico factura al cliente vs. las horas totales que la empresa le paga, revelando cuánto tiempo productivo realmente genera ingresos." },
  { id:"ns_0011", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller centrífugo, el fenómeno de 'Surge' (pumping) ocurre principalmente cuando existe una discrepancia crítica entre:", opciones:["La elevación de presión requerida por el condensador y la capacidad de flujo del impulsor.", "La temperatura del agua de entrada al evaporador y el punto de consigna del termostato.", "El nivel de aceite en el cárter y la presión de lubricación en los cojinetes de alta velocidad.", "La densidad del refrigerante líquido y la apertura de la válvula de expansión electrónica."], respuesta_correcta:0, explicacion:"El surge ocurre cuando el compresor centrífugo no puede generar suficiente elevación de presión (lift) para vencer la diferencia entre condensador y evaporador, causando una reversión del flujo de gas en el impulsor." },
  { id:"ns_0012", categoria:"NATE_SR_RACK", pregunta:"Se detecta una alta temperatura de descarga en un compresor de un rack paralelo, pero las presiones son normales. ¿Qué debe revisar el técnico Senior?", opciones:["El sobrecalentamiento excesivo en la succión o una falla en las válvulas internas del plato.", "La saturación del filtro deshidratador que limita el flujo de refrigerante hacia el evaporador.", "El ajuste del interruptor de seguridad de alta presión que podría estar actuando prematuramente.", "La velocidad del ventilador del condensador que no está evacuando el calor de forma eficiente."], respuesta_correcta:0, explicacion:"Con presiones normales pero descarga alta, la causa más probable es un sobrecalentamiento excesivo de succión o válvulas de plato dañadas que permiten re-compresión interna, elevando la temperatura de descarga sin alterar las presiones del sistema." },
  { id:"ns_0013", categoria:"NATE_SR_CEO", pregunta:"Un CEO analiza un reporte donde el 'Average Ticket' ha bajado un 20% a pesar de tener el mismo volumen de llamadas. ¿Cuál es la causa operativa más probable?", opciones:["Los técnicos están realizando reparaciones menores en lugar de identificar fallas sistémicas.", "El costo de las piezas ha disminuido gracias a una mejor negociación con los proveedores.", "El departamento de despacho está enviando a los técnicos más cercanos en lugar de los más aptos.", "La competencia ha reducido sus precios obligando a la empresa a realizar descuentos directos."], respuesta_correcta:0, explicacion:"Cuando el Average Ticket baja sin cambios en volumen, generalmente significa que los técnicos están haciendo reparaciones rápidas y superficiales en lugar de diagnosticar la causa raíz del problema." },
  { id:"ns_0014", categoria:"NATE_SR_MINISPLIT", pregunta:"Al instalar un sistema VRF, se encuentra que la tubería de comunicación excede la longitud máxima permitida. ¿Qué riesgo técnico es el más crítico?", opciones:["La caída de voltaje en la señal de datos causará errores de sincronización intermitentes.", "El retorno de aceite al compresor será insuficiente causando una falla mecánica prematura.", "La carga de refrigerante adicional requerida excederá la capacidad del tanque receptor.", "El tiempo de respuesta de las válvulas de expansión será demasiado lento para la carga."], respuesta_correcta:0, explicacion:"Cuando la tubería de comunicación excede la longitud máxima, la resistencia del cable causa caída de voltaje en la señal de datos, generando errores de sincronización entre la unidad exterior y las interiores." },
  { id:"ns_0015", categoria:"NATE_SR_HVAC", pregunta:"Un sistema de conductos presenta ruidos de 'booming' al arrancar el soplador. Desde una perspectiva de diseño Senior, ¿cuál es la solución técnica?", opciones:["Instalar refuerzos en cruz en los paneles de los conductos o añadir juntas de expansión.", "Aumentar la velocidad del motor del soplador para estabilizar la presión estática interna.", "Reemplazar el filtro de aire por uno de menor caída de presión para reducir la turbulencia.", "Cerrar parcialmente las rejillas de suministro para equilibrar la contrapresión del sistema."], respuesta_correcta:0, explicacion:"Los ruidos de 'booming' ocurren cuando los paneles del conducto flexionan por cambios bruscos de presión al arrancar el soplador. Los refuerzos en cruz rigidizan los paneles y las juntas de expansión absorben el movimiento, eliminando la vibración." },
  { id:"ns_0016", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calefacción, una bomba de calor se bloquea por alta presión. El filtro está limpio y el soplador funciona. ¿Qué componente está fallando?", opciones:["La válvula de expansión de la unidad interior está bloqueada o el orificio está obstruido.", "La válvula inversora no está desviando suficiente gas caliente hacia el serpentín exterior.", "El sensor de temperatura ambiente exterior está enviando una señal de frío extremo falsa.", "El acumulador de succión tiene un exceso de aceite que reduce el volumen útil de gas."], respuesta_correcta:0, explicacion:"En modo calor, el serpentin interior es el condensador. Si la TXV interior o el orificio esta bloqueado, el refrigerante no puede fluir y la presion de descarga sube hasta disparar el switch de alta presion." },
  { id:"ns_0017", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un líder de cuadrilla nota que los técnicos no están utilizando la bomba de vacío de 2 etapas correctamente. ¿Cuál es el error de procedimiento más común?", opciones:["No cambiar el aceite de la bomba después de cada proceso de evacuación en sistemas grandes.", "Utilizar mangueras de carga estándar de 1/4 en lugar de mangueras de vacío de gran diámetro.", "Conectar el vacuómetro directamente a la bomba en lugar de hacerlo en el punto más alejado.", "Abrir el lastre de gas (gas ballast) durante todo el proceso de vacío en lugar de solo al inicio."], respuesta_correcta:1, explicacion:"Las mangueras de 1/4\" crean una restricción severa que limita la capacidad de evacuación de la bomba. Mangueras de mayor diámetro (3/8\" o 1/2\") permiten un flujo adecuado para alcanzar vacío profundo en tiempo razonable." },
  { id:"ns_0018", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete con economizador introduce aire exterior cuando no debería. ¿Qué lógica de control Senior explica este comportamiento errático?", opciones:["El sensor de entalpía exterior está defectuoso o mal calibrado respecto a la humedad.", "El motor del damper ha perdido el torque necesario para cerrar contra la presión del aire.", "El termostato de la zona está configurado en modo ocupado permanentemente por el usuario.", "El interruptor de límite de aire mezclado está puenteado para evitar paros por congelación."], respuesta_correcta:0, explicacion:"Un sensor de entalpía defectuoso envía lecturas erróneas al controlador, haciéndole creer que el aire exterior es favorable cuando en realidad no lo es. Esto causa que el damper abra innecesariamente, introduciendo aire caliente o húmedo." },
  { id:"ns_0019", categoria:"NATE_SR_CHILLERS", pregunta:"Al realizar una prueba de espectro de vibración en un chiller, se detecta una frecuencia inusual en los cojinetes. ¿Qué acción debe tomar un CEO?", opciones:["Programar un paro preventivo inmediato para evitar un fallo catastrófico del equipo.", "Ignorar la lectura hasta que el aumento en el consumo eléctrico confirme el desgaste.", "Aumentar la viscosidad del aceite lubricante para amortiguar la vibración detectada.", "Delegar la decisión al técnico de nivel básico que realiza el mantenimiento de rutina."], respuesta_correcta:0, explicacion:"Una frecuencia anormal de vibración en cojinetes indica desgaste inminente. Un paro preventivo inmediato evita un fallo catastrófico que podría destruir el compresor y causar una pérdida total del equipo." },
  { id:"ns_0020", categoria:"NATE_SR_RACK", pregunta:"En un sistema de refrigeración de CO2 (Transcrítico), la presión de gas de salida excede el punto crítico. ¿Cómo debe responder el sistema de control?", opciones:["Modulando la válvula de alta presión para optimizar el enfriamiento del gas en el gas-cooler.", "Apagando los compresores inmediatamente para evitar una explosión por sobrepresión de gas.", "Inyectando refrigerante líquido directamente en la succión para bajar la entalpía del gas.", "Abriendo las válvulas de bypass hacia el recibidor para igualar las presiones de etapa."], respuesta_correcta:0, explicacion:"En operación transcrítica del CO2, el control modula la válvula de alta presión para optimizar la presión del gas-cooler y maximizar la eficiencia del ciclo, ya que por encima del punto crítico el CO2 no se condensa sino que se enfría como gas denso." },
  { id:"ns_0021", categoria:"NATE_SR_CEO", pregunta:"Si una empresa HVAC decide subcontratar la instalación de ductos, ¿cuál es el riesgo financiero más latente para el CEO?", opciones:["La pérdida de control sobre la calidad final que impacta directamente en las garantías.", "El aumento en los costos fijos de la empresa al tener que pagar facturas externas fijas.", "La dificultad para programar las visitas de mantenimiento preventivo con los clientes.", "La reducción en la compra de materiales por volumen que afecta los descuentos de fábrica."], respuesta_correcta:0, explicacion:"Al subcontratar instalaciones, el CEO pierde control directo sobre la calidad del trabajo, lo que puede resultar en reclamos de garantía costosos que la empresa debe asumir ante el cliente final." },
  { id:"ns_0022", categoria:"NATE_SR_HVAC", pregunta:"Un motor ECM de velocidad variable no arranca. Al medir la señal de control, hay 24V presentes. ¿Qué debe diagnosticar un Senior?", opciones:["El módulo de control del motor ha fallado internamente debido a picos de voltaje.", "Los rodamientos del motor están bloqueados mecánicamente por falta de lubricación.", "El termostato no está enviando la señal de PWM necesaria para definir la velocidad.", "El capacitor de marcha está desvalorizado y no provee el torque inicial de arranque."], respuesta_correcta:0, explicacion:"Los motores ECM requieren una señal PWM del termostato o placa de control para definir la velocidad de operación. Tener 24V presentes solo confirma alimentación, pero si el módulo interno falló por picos de voltaje, el motor no puede procesar la señal ni arrancar." },
  { id:"ns_0023", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller de absorción utiliza Bromuro de Litio. Si la solución se cristaliza, ¿cuál es la causa operativa más frecuente?", opciones:["Una caída repentina de la temperatura de la solución durante un paro de emergencia.", "Un exceso de calor en el generador que evapora demasiado refrigerante del sistema.", "La infiltración de aire atmosférico que reduce la eficiencia del proceso de absorción.", "El uso de agua de enfriamiento con una dureza mineral por encima de los límites."], respuesta_correcta:0, explicacion:"La cristalización del LiBr ocurre cuando la concentración de la solución aumenta excesivamente. Una caída repentina de temperatura durante un paro de emergencia reduce la solubilidad del LiBr, provocando cristalización." },
  { id:"ns_0024", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema inverter reporta error de sobrecorriente en el compresor. Al medir las bobinas, todas dan 1.2 Ohms. ¿Qué concluye un Senior?", opciones:["El compresor está mecánicamente trabado o el IPM de la placa exterior está dañado.", "Existe un cortocircuito entre las espiras del motor que no se refleja en la resistencia.", "La carga de refrigerante es insuficiente, causando que el compresor trabaje forzado.", "Los cables de alimentación tienen una sección transversal inadecuada para la corriente."], respuesta_correcta:0, explicacion:"Si las tres bobinas miden igual (1.2 Ohms) el motor está eléctricamente sano; el error de sobrecorriente apunta a un compresor mecánicamente trabado o un IPM dañado que envía corriente excesiva al motor." },
  { id:"ns_0025", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor geotérmica, el diferencial de temperatura del lazo de agua es de solo $2^{\\circ}F$. ¿Qué indica este valor?", opciones:["El flujo de agua es excesivo o la transferencia de calor en el intercambiador es nula.", "La bomba de circulación está fallando y no mueve el volumen de agua necesario.", "El intercambiador de calor de placas tiene una fuga interna entre refrigerante y agua.", "La temperatura del subsuelo es demasiado alta para el modo de operación actual."], respuesta_correcta:0, explicacion:"Un diferencial de solo 2F entre entrada y salida del lazo indica flujo de agua excesivo o nula transferencia de calor en el intercambiador. Lo normal es un delta de 10-12F en geotermica." },
  { id:"ns_0026", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior observa que sus ayudantes no usan 'brazing shield' al soldar cerca de válvulas de servicio. ¿Cuál es la consecuencia?", opciones:["El calor excesivo destruye los sellos internos de teflón causando fugas permanentes.", "La formación de escamas de óxido en el interior de la tubería obstruirá los filtros.", "El debilitamiento estructural del cobre en el punto de unión por recocido excesivo.", "La alteración de la composición química de la soldadura de plata por sobrecalentamiento."], respuesta_correcta:0, explicacion:"Las válvulas de servicio contienen sellos internos de teflón o nylon que se derriten a temperaturas relativamente bajas. Sin brazing shield, el calor de la antorcha daña estos sellos y provoca fugas que solo se detectan después de cargar el sistema." },
  { id:"ns_0027", categoria:"NATE_SR_PACKAGE", pregunta:"Al realizar un retrofit de refrigerante en una unidad paquete vieja, ¿cuál es la mayor preocupación técnica para un Senior?", opciones:["La compatibilidad del aceite mineral original con el nuevo refrigerante HFC/HFO.", "La capacidad del condensador para manejar las nuevas presiones de descarga altas.", "El ajuste de las válvulas de expansión térmicas para el nuevo diagrama de presión.", "El impacto en la eficiencia energética estacional (SEER) tras el cambio de gas."], respuesta_correcta:0, explicacion:"Los refrigerantes HFC/HFO no son miscibles con aceite mineral, lo que causa falta de lubricación y falla del compresor. Es obligatorio cambiar a aceite POE o AB antes de cargar el nuevo refrigerante." },
  { id:"ns_0028", categoria:"NATE_SR_RACK", pregunta:"Un rack de media temperatura usa descongelación por gas caliente. Una vitrina no descongela. ¿Qué componente revisaría?", opciones:["La válvula de retención en el cabezal de drenaje o la solenoide de gas caliente.", "El reloj de deshielo principal que controla la rotación de los sectores del rack.", "La presión del recibidor que podría estar por debajo del diferencial de empuje.", "El sensor de temperatura de ambiente que bloquea el deshielo por falta de carga."], respuesta_correcta:0, explicacion:"Si solo una vitrina no descongela, el problema es local: la solenoide de gas caliente de esa vitrina puede no estar abriendo, o la válvula de retención (check) en el drenaje impide que el gas caliente fluya por el evaporador." },
  { id:"ns_0029", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC busca reducir el 'Liability Risk'. ¿Cuál de estas políticas es la más efectiva?", opciones:["Documentación fotográfica obligatoria de antes y después en cada orden de trabajo.", "Comprar herramientas de marca premium para reducir la probabilidad de accidentes.", "Contratar solo técnicos con más de 15 años de experiencia probada en el campo.", "Instalar rastreadores GPS en las unidades para monitorear la velocidad de manejo."], respuesta_correcta:0, explicacion:"La documentación fotográfica de antes y después crea evidencia objetiva que protege a la empresa contra reclamos falsos y demuestra el estado previo del equipo ante cualquier disputa legal." },
  { id:"ns_0030", categoria:"NATE_SR_HVAC", pregunta:"Un sistema presenta un bajo sobrecalentamiento y un bajo subenfriamiento simultáneamente. ¿Qué indica este escenario?", opciones:["Una válvula de expansión sobredimensionada o que ha perdido el control del flujo.", "Una restricción parcial en la línea de líquido antes del dispositivo de expansión.", "Una falta severa de carga de refrigerante combinada con baja carga térmica.", "El compresor tiene una eficiencia volumétrica baja debido a desgaste de anillos."], respuesta_correcta:0, explicacion:"Bajo sobrecalentamiento indica exceso de refrigerante en el evaporador, y bajo subenfriamiento indica poco líquido en el condensador. Una TXV sobredimensionada alimenta demasiado refrigerante al evaporador, vaciando el condensador y reduciendo ambos valores simultáneamente." },
  { id:"ns_0031", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller enfriado por aire opera con una temperatura de descarga excesiva. El condensador está limpio y los ventiladores giran a RPM nominales. ¿Qué debe investigar el Senior?", opciones:["La presencia de gases no condensables atrapados en la parte superior del condensador.", "El ajuste del set-point del controlador que regula la velocidad de los ventiladores.", "Una posible inundación de refrigerante líquido en el acumulador de la línea de succión.", "La caída de presión de agua a través del evaporador debido a una bomba defectuosa."], respuesta_correcta:0, explicacion:"Si el condensador está limpio y los ventiladores funcionan correctamente, los gases no condensables atrapados en la parte superior del condensador son la causa más probable de una temperatura de descarga excesiva." },
  { id:"ns_0032", categoria:"NATE_SR_RACK", pregunta:"En un rack con compresores tipo scroll, se escucha un ruido metálico agudo tras un ciclo de deshielo. ¿Cuál es la preocupación técnica inmediata del líder?", opciones:["Un retorno de refrigerante líquido que causa un esfuerzo mecánico en las espirales.", "La falta de aceite debido a una falla en el sistema de gestión de retorno del rack.", "Una rotación inversa del compresor causada por una falla en el relé de secuencia.", "El desprendimiento de partículas metálicas del filtro de succión hacia la cámara."], respuesta_correcta:0, explicacion:"Tras un deshielo, el refrigerante líquido acumulado puede regresar al compresor scroll causando golpe de líquido (slugging). Las espirales del scroll no toleran líquido incompresible y producen un ruido metálico agudo característico." },
  { id:"ns_0033", categoria:"NATE_SR_CEO", pregunta:"Al evaluar el 'Cost of Goods Sold' (COGS), un CEO nota un aumento del 15% en suministros genéricos. ¿Qué acción estratégica recomienda para el control?", opciones:["Centralizar las compras y establecer un sistema de inventario por código de barras.", "Reducir el salario variable de los técnicos para compensar el gasto extra en piezas.", "Cambiar a proveedores locales de menor costo sin evaluar la calidad de los materiales.", "Eliminar el stock de las camionetas y obligar al técnico a ir a la tienda por cada pieza."], respuesta_correcta:0, explicacion:"Centralizar las compras y usar un sistema de inventario con código de barras permite controlar el consumo, detectar fugas de material y negociar mejores precios por volumen con proveedores." },
  { id:"ns_0034", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema Inverter de 1 a 1 presenta una presión de succión muy baja y un sobrecalentamiento de 30°F. ¿Qué indica este escenario técnico?", opciones:["Existe una restricción severa en el orificio de la válvula de expansión electrónica.", "El sistema tiene una carga excesiva de refrigerante que inunda el serpentín interior.", "El motor del ventilador del evaporador está girando a una velocidad insuficiente.", "La placa de control exterior está enviando una señal errónea de modulación al IPM."], respuesta_correcta:0, explicacion:"Una presión de succión muy baja con sobrecalentamiento alto (30°F) indica que el refrigerante no fluye adecuadamente al evaporador, típico de una restricción severa en la válvula de expansión electrónica (EEV)." },
  { id:"ns_0035", categoria:"NATE_SR_HVAC", pregunta:"Se instala un sistema de zonificación (Zoning) y el cliente se queja de flujo de aire excesivo en zonas pequeñas. ¿Cuál es el error de diseño?", opciones:["La omisión de un ducto de bypass con damper barométrico o un soplador con ECM.", "El uso de rejillas de suministro sobredimensionadas para el tamaño de la habitación.", "Un termostato mal ubicado que no detecta el cambio de temperatura de la zona.", "La falta de aislamiento térmico en los conductos que atraviesan áreas no acondicionadas."], respuesta_correcta:0, explicacion:"Sin un ducto de bypass o un soplador ECM que module el flujo, cuando las zonas pequeñas son las únicas demandando, todo el volumen de aire del sistema se fuerza a través de conductos reducidos, creando exceso de presión y flujo en esas zonas." },
  { id:"ns_0036", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor tiene una línea de succión escarchada hasta el compresor. ¿Qué componente defectuoso causaría esto?", opciones:["La válvula de expansión exterior (TXV) que está atascada en posición abierta total.", "La válvula inversora que está fugando gas caliente internamente hacia la succión.", "El sensor de defrost que no activa el ciclo de descongelamiento por temperatura.", "El ventilador interior que tiene el capacitor de marcha degradado o desvalorizado."], respuesta_correcta:0, explicacion:"Una TXV exterior atascada abierta permite paso excesivo de refrigerante liquido, inundando el serpentin exterior y causando que el liquido no evaporado regrese por la succion hasta escarchar la linea y el compresor." },
  { id:"ns_0037", categoria:"NATE_SR_MANAGEMENT", pregunta:"Durante un entrenamiento de seguridad OSHA, un líder Senior enfatiza el uso de doble bloqueo (LOTO). ¿En qué situación es más crítico este protocolo?", opciones:["Al realizar el reemplazo de un compresor en un rack que tiene múltiples fuentes.", "Al limpiar los serpentines de un condensador con agua a presión en una unidad paquete.", "Al cambiar un filtro deshidratador en una unidad residencial de 3 toneladas estándar.", "Al verificar el voltaje de control en el transformador de una manejadora de aire."], respuesta_correcta:0, explicacion:"Un rack comercial puede tener múltiples fuentes de energía eléctrica (circuitos de compresores, ventiladores, controles). El LOTO (Lock Out/Tag Out) doble es crítico cuando hay varias fuentes que podrían energizar el equipo accidentalmente mientras se trabaja." },
  { id:"ns_0038", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 15 toneladas presenta un Delta T de solo 10°F en enfriamiento. El flujo de aire es nominal. ¿Qué debe revisar el Senior?", opciones:["La eficiencia volumétrica de los compresores y la posible mezcla en la inversora.", "La limpieza del filtro de aire y la obstrucción de los difusores de suministro.", "La carga de refrigerante basándose únicamente en la presión de alta del sistema.", "La configuración de los jumpers en la placa de control para la velocidad del motor."], respuesta_correcta:0, explicacion:"Con flujo de aire normal, un Delta T bajo (10°F vs. 18-22°F esperado) indica falta de capacidad de enfriamiento. La causa más probable es baja eficiencia volumétrica del compresor o válvulas internas dañadas que permiten bypass de gas." },
  { id:"ns_0039", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo de baja temperatura, el acumulador de succión está constantemente lleno de líquido. ¿Cuál es el riesgo operativo?", opciones:["La dilución del aceite lubricante que provoca el desgaste acelerado de los cojinetes.", "El aumento excesivo del consumo eléctrico por la compresión de vapor saturado.", "La apertura de las válvulas de seguridad del rack por un aumento de presión súbito.", "La congelación del retorno de aceite que bloquea el suministro a los compresores."], respuesta_correcta:0, explicacion:"Un acumulador constantemente lleno de líquido indica exceso de retorno de refrigerante que diluye el aceite lubricante en los cárteres. Esto reduce la viscosidad del aceite y acelera el desgaste de cojinetes y partes móviles." },
  { id:"ns_0040", categoria:"NATE_SR_CEO", pregunta:"Como CEO, ¿cuál es el impacto legal principal de no mantener registros de recuperación de refrigerante según la Sección 608 de la EPA?", opciones:["Multas civiles federales sustanciales por cada día de incumplimiento de registro.", "La cancelación automática de la licencia de contratista estatal de la empresa.", "La pérdida de la garantía de fábrica en todos los equipos instalados ese año.", "El aumento de las tasas de interés en los préstamos bancarios para capital de trabajo."], respuesta_correcta:0, explicacion:"La EPA impone multas civiles federales significativas (hasta $44,539 por día por violación bajo la Clean Air Act Sección 608) por no mantener registros adecuados de recuperación de refrigerante." },
  { id:"ns_0041", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'low oil pressure differential'. El nivel de aceite es correcto. ¿Qué componente técnico es el sospechoso?", opciones:["La bomba de aceite mecánica o el sensor de presión diferencial defectuoso.", "El calentador de cárter que no está evaporando el refrigerante del aceite.", "La válvula de expansión que está alimentando demasiado líquido al evaporador.", "El filtro de succión del compresor que tiene una caída de presión excesiva."], respuesta_correcta:0, explicacion:"Con nivel de aceite correcto, una baja presión diferencial de aceite apunta a una bomba de aceite defectuosa que no genera suficiente presión, o un sensor de presión diferencial que lee incorrectamente." },
  { id:"ns_0042", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF tiene un error de 'Master/Slave address conflict'. ¿Cuál es el procedimiento de resolución Senior?", opciones:["Resetear los dip-switches de cada unidad interior y reiniciar el sistema completo.", "Reemplazar la placa electrónica de la unidad exterior por una versión más nueva.", "Cambiar el cableado de comunicación por uno de mayor calibre para reducir ruido.", "Desconectar la alimentación eléctrica de las unidades interiores durante 24 horas."], respuesta_correcta:0, explicacion:"El conflicto de direcciones Master/Slave se resuelve reseteando los dip-switches de cada unidad interior para reasignar direcciones únicas según el manual, y luego reiniciando el sistema completo." },
  { id:"ns_0043", categoria:"NATE_SR_HVAC", pregunta:"Un compresor residencial falla por 'acid burn'. Al instalar el nuevo, ¿cuál es el paso de seguridad técnica innegociable?", opciones:["Instalar un filtro de succión de alta capacidad y realizar cambios de aceite.", "Aumentar la carga de refrigerante un 10% para diluir los restos de ácido residual.", "Sustituir toda la línea de cobre de la casa para asegurar la pureza del sistema.", "Utilizar un fundente de soldadura más fuerte para evitar fugas en las uniones."], respuesta_correcta:0, explicacion:"Cuando un compresor falla por 'acid burn', los ácidos contaminan todo el sistema. Un filtro de succión de alta capacidad atrapa los residuos ácidos y partículas, y los cambios de aceite posteriores eliminan la contaminación remanente para proteger el compresor nuevo." },
  { id:"ns_0044", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete con gas, se detecta monóxido de carbono en el flujo de aire. ¿Qué diagnóstico técnico confirma la falla?", opciones:["Una fractura en el intercambiador de calor que permite la mezcla de gases.", "Un sensor de llama sucio que causa una combustión incompleta en el quemador.", "Una presión de gas de entrada demasiado alta para el diseño del colector.", "La falta de ventilación adecuada en el cuarto de máquinas donde está el equipo."], respuesta_correcta:0, explicacion:"La presencia de CO en el flujo de aire de suministro indica que los productos de combustión están cruzando al lado del aire acondicionado. Esto solo ocurre cuando hay una grieta o fractura en el intercambiador de calor, lo cual es una emergencia de seguridad." },
  { id:"ns_0045", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa la compra de software de gestión de campo (FSM). ¿Cuál es el principal beneficio operativo buscado?", opciones:["La optimización de rutas y la visibilidad en tiempo real de la productividad técnica.", "La capacidad de rastrear las conversaciones privadas de los técnicos con clientes.", "El ahorro en el costo de impresión de facturas y formularios de servicio físicos.", "La reducción de la necesidad de tener un equipo de soporte técnico en la oficina."], respuesta_correcta:0, explicacion:"El software FSM (Field Service Management) optimiza rutas de despacho y da visibilidad en tiempo real sobre la ubicación y productividad de cada técnico, mejorando la eficiencia operativa." },
  { id:"ns_0046", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un ciclo de calefacción muy corto (short-cycling). El termostato es nuevo. ¿Qué factor mecánico es la causa?", opciones:["El interruptor de alta presión está actuando debido a un flujo de aire insuficiente.", "La válvula inversora se está moviendo aleatoriamente por una falla en la bobina.", "El acumulador de succión está congelado impidiendo el flujo de vapor constante.", "El sensor de temperatura exterior está ubicado bajo la luz solar directa siempre."], respuesta_correcta:0, explicacion:"Si el flujo de aire es insuficiente, la presion de condensacion sube rapidamente en modo calor, disparando el switch de alta presion y causando ciclos cortos repetitivos (short-cycling)." },
  { id:"ns_0047", categoria:"NATE_SR_RACK", pregunta:"Se observa burbujeo en la mirilla de un rack, pero el subenfriamiento es de 15°F. ¿Qué diagnóstico daría un Senior?", opciones:["Existe una restricción importante antes de la mirilla o el filtro está saturado.", "El sistema tiene una falta de carga de refrigerante a pesar del subenfriamiento.", "La temperatura del aire en el condensador es demasiado alta para el refrigerante.", "El ventilador del recibidor de líquido no está funcionando para enfriar el gas."], respuesta_correcta:0, explicacion:"Si el subenfriamiento es adecuado (15°F) pero hay burbujas en la mirilla, la causa es una caída de presión (restricción) antes de la mirilla, como un filtro deshidratador saturado, que genera flash gas localizado sin que falte refrigerante." },
  { id:"ns_0048", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior reporta que su ayudante no sabe usar el multímetro. ¿Cuál es la responsabilidad administrativa inmediata?", opciones:["Retirar al ayudante de tareas eléctricas y programar una capacitación práctica.", "Asignar al ayudante a tareas de limpieza exclusivamente para evitar accidentes.", "Despedir al ayudante por falta de conocimientos básicos necesarios para el puesto.", "Darle un manual de usuario al ayudante y pedirle que lo lea durante su almuerzo."], respuesta_correcta:0, explicacion:"La prioridad es la seguridad: un técnico sin dominio del multímetro puede electrocutarse o dañar equipos. Retirarlo de tareas eléctricas elimina el riesgo inmediato, y programar capacitación asegura que desarrolle la competencia necesaria." },
  { id:"ns_0049", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller de tornillo, el compresor opera continuamente en el nivel más bajo de capacidad. ¿Qué impacto tiene esto a largo plazo?", opciones:["Una gestión deficiente del aceite y posibles problemas de lubricación interna.", "Un aumento en la eficiencia energética debido al bajo consumo de corriente.", "La formación de hielo en el evaporador por el bajo flujo de refrigerante total.", "El sobrecalentamiento del motor por la falta de enfriamiento por gas de succión."], respuesta_correcta:0, explicacion:"La operación continua a capacidad mínima en compresores de tornillo causa una mala gestión del aceite, ya que el flujo de gas es insuficiente para arrastrar y recircular el aceite correctamente por el sistema." },
  { id:"ns_0050", categoria:"NATE_SR_HVAC", pregunta:"Un sistema de 5 toneladas utiliza un orificio fijo. Si la carga térmica aumenta drásticamente, ¿cómo reaccionará el sobrecalentamiento?", opciones:["El sobrecalentamiento aumentará significativamente debido a la evaporación rápida.", "El sobrecalentamiento bajará porque el orificio enviará más líquido por presión.", "El sobrecalentamiento se mantendrá igual ya que el orificio es un punto fijo.", "El sobrecalentamiento fluctuará violentamente hasta que el sistema se estabilice."], respuesta_correcta:0, explicacion:"Con un orificio fijo, el flujo de refrigerante no se ajusta automáticamente. Al aumentar la carga térmica, el refrigerante se evapora más rápido en el evaporador pero el orificio no puede compensar, resultando en un sobrecalentamiento más alto por la evaporación acelerada." },
  { id:"ns_0051", categoria:"NATE_SR_CEO", pregunta:"Un CEO decide expandirse al mercado comercial de chillers. ¿Cuál es el desafío de flujo de caja más importante?", opciones:["El ciclo de facturación prolongado y los costos de materiales de alto valor inicial.", "La dificultad para encontrar técnicos que quieran trabajar en techos industriales.", "La variabilidad del clima que afecta la demanda de reparaciones de emergencia.", "El costo de la publicidad en medios digitales para atraer clientes industriales."], respuesta_correcta:0, explicacion:"Los proyectos de chillers comerciales requieren materiales de alto costo por adelantado y los ciclos de facturación son largos (30-90 días), creando una presión severa sobre el flujo de caja." },
  { id:"ns_0052", categoria:"NATE_SR_MINISPLIT", pregunta:"Durante el vaciado de un sistema VRF, el técnico no puede bajar de 1000 micrones. No hay fugas. ¿Cuál es el problema?", opciones:["Humedad atrapada o refrigerante disuelto en el aceite del compresor del sistema.", "La bomba de vacío no tiene la capacidad de CFM necesaria para el volumen total.", "Las válvulas de servicio están cerradas impidiendo la evacuación de las líneas.", "El vacuómetro digital está descalibrado por la presencia de aceite en el sensor."], respuesta_correcta:0, explicacion:"Si no hay fugas y el vacío no baja de 1000 micrones, la causa es humedad atrapada o refrigerante disuelto en el aceite que se desgasifica lentamente, impidiendo alcanzar el vacío profundo requerido." },
  { id:"ns_0053", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, la válvula inversora hace un ruido de 'chattering'. ¿Cuál es la causa eléctrica más probable?", opciones:["Bajo voltaje en el circuito de control de 24V o una bobina de solenoide débil.", "Falta de presión diferencial de refrigerante para mover el pistón de la válvula.", "Una señal de termostato que está alternando rápidamente entre calor y frío.", "El uso de un transformador de 40VA que está operando al límite de su capacidad."], respuesta_correcta:0, explicacion:"El chattering de la valvula inversora ocurre cuando la bobina solenoide no recibe suficiente voltaje (bajo voltaje en 24V) para mantener el piston piloto en posicion, causando vibracion entre las dos posiciones." },
  { id:"ns_0054", categoria:"NATE_SR_RACK", pregunta:"Un condensador evaporativo en un sistema de rack presenta incrustaciones blancas. ¿Qué debe corregir el Senior?", opciones:["El sistema de tratamiento químico del agua y la tasa de purga (blowdown).", "La velocidad de los ventiladores para reducir la evaporación directa del agua.", "El tipo de boquillas de aspersión para asegurar un patrón de mojado uniforme.", "La carga de refrigerante para bajar la temperatura de entrada al condensador."], respuesta_correcta:0, explicacion:"Las incrustaciones blancas son depósitos minerales (calcio/magnesio) causados por agua dura y una tasa de purga insuficiente. Se debe corregir el tratamiento químico del agua y aumentar el blowdown para controlar la concentración de minerales." },
  { id:"ns_0055", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior detecta que un compañero está robando piezas del inventario. ¿Cuál es la acción profesional correcta?", opciones:["Reportar el hallazgo de inmediato a la gerencia con la evidencia recolectada.", "Confrontar al compañero en privado y pedirle que devuelva las piezas robadas.", "Ignorar la situación para evitar conflictos internos en el equipo de trabajo.", "Hablar con los otros técnicos para ver si ellos también han notado el robo."], respuesta_correcta:0, explicacion:"La cadena de mando y la integridad profesional exigen reportar inmediatamente a la gerencia con evidencia. Confrontar directamente o ignorar puede escalar el problema, comprometer la investigación o hacer cómplice al observador." },
  { id:"ns_0056", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo tiene una purga de aire excesiva. El sistema opera a presión positiva. ¿Qué indica esto?", opciones:["Una fuga en el lado de alta que permite la salida de gas pero no entrada de aire.", "El sistema de purga está defectuoso y está detectando falsos no condensables.", "El refrigerante utilizado es R-134a y el sistema tiene una fuga en el evaporador.", "La temperatura del agua de la torre es demasiado baja para el condensador."], respuesta_correcta:1, explicacion:"Si el sistema opera a presión positiva (R-134a), el aire no puede infiltrarse. Una purga excesiva indica que el sistema de purga está defectuoso y detecta falsos no condensables cuando en realidad no hay infiltración de aire." },
  { id:"ns_0057", categoria:"NATE_SR_HVAC", pregunta:"Al medir la presión estática total externa (TESP), el valor es de 1.1 pulg. W.C. en un sistema nominal de 0.5. ¿Consecuencia?", opciones:["Falla prematura del motor del soplador y reducción drástica de la capacidad.", "Aumento en la eficiencia del intercambio de calor por la mayor presión de aire.", "Menor consumo eléctrico del motor debido a la restricción del flujo de aire.", "Mejora en la filtración de aire gracias a la mayor velocidad por el filtro."], respuesta_correcta:0, explicacion:"Una TESP de 1.1\" W.C. es más del doble del nominal de 0.5\". Esta restricción excesiva reduce drásticamente el flujo de aire (CFM), causando sobrecarga del motor del soplador y pérdida significativa de capacidad de enfriamiento o calefacción del sistema." },
  { id:"ns_0058", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de doble etapa tiene el compresor de la etapa 1 quemado. ¿Puede operar solo con la etapa 2?", opciones:["No, la lógica de control y el flujo de refrigerante suelen estar interconectados.", "Sí, siempre que se puentee el interruptor de seguridad de la primera etapa.", "Sí, pero la eficiencia bajará y el termostato no podrá alcanzar el set-point.", "No, porque el aceite del sistema se acumularía en el compresor que no opera."], respuesta_correcta:0, explicacion:"En la mayoría de unidades paquete de doble etapa, la lógica de control requiere que la etapa 1 opere antes de activar la etapa 2. Además, si comparten circuito de refrigerante, el compresor dañado puede causar restricciones o migración de refrigerante." },
  { id:"ns_0059", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere aumentar el valor de reventa de su empresa HVAC. ¿Qué métrica es la más atractiva para un comprador?", opciones:["El número de contratos de mantenimiento preventivo activos (Recurring Revenue).", "La cantidad de camionetas nuevas compradas en el último ejercicio fiscal.", "La facturación total bruta anual sin considerar el margen de utilidad neta.", "El número de seguidores en las redes sociales de la empresa de servicios."], respuesta_correcta:0, explicacion:"Los contratos de mantenimiento preventivo generan ingresos recurrentes predecibles (Recurring Revenue), que es la métrica más atractiva para compradores porque garantiza flujo de caja futuro." },
  { id:"ns_0060", categoria:"NATE_SR_RACK", pregunta:"En un rack de refrigeración, ¿cuál es la función primordial de la válvula EPR (Evaporator Pressure Regulator)?", opciones:["Mantener una presión mínima en el evaporador para evitar la congelación del producto.", "Regular el flujo de gas caliente durante el proceso de deshielo de las vitrinas.", "Prevenir que el líquido regrese al compresor durante periodos de baja carga.", "Igualar las presiones entre los diferentes compresores que forman el rack paralelo."], respuesta_correcta:0, explicacion:"La válvula EPR mantiene una presión mínima en el evaporador independientemente de la presión de succión del rack. Esto evita que la temperatura del evaporador baje demasiado y congele productos sensibles como lácteos o vegetales." },
  { id:"ns_0061", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una aproximación (approach) del condensador de 2°F. El Senior concluye que:", opciones:["El condensador está operando con una eficiencia de transferencia de calor excelente.", "Existe una carga excesiva de refrigerante que inunda los tubos del condensador.", "El flujo de agua de la torre es insuficiente y el Delta T es demasiado alto.", "Los tubos del condensador requieren una limpieza mecánica por acumulación de lodo."], respuesta_correcta:0, explicacion:"Un approach de condensador de 2°F (diferencia entre temperatura de saturación del refrigerante y salida del agua) indica una transferencia de calor excelente, con tubos limpios y flujo de agua adecuado." },
  { id:"ns_0062", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema multi-split tiene una unidad interior que no enfría, pero las otras sí. ¿Qué revisaría el Senior?", opciones:["La válvula de expansión electrónica (EEV) dedicada a esa unidad en la exterior.", "La carga total de refrigerante del sistema que podría estar ligeramente baja.", "El sensor de temperatura de la unidad exterior que regula el compresor inverter.", "La comunicación general entre el mando a distancia y el receptor de la unidad."], respuesta_correcta:0, explicacion:"En un multi-split, cada unidad interior tiene su propia válvula de expansión electrónica (EEV). Si solo una no enfría, la EEV dedicada a esa unidad está cerrada o defectuosa." },
  { id:"ns_0063", categoria:"NATE_SR_HVAC", pregunta:"Al realizar un vacío, el sistema se estabiliza en 1500 micrones y no sube más. ¿Qué diagnóstico es correcto?", opciones:["Hay humedad remanente en el sistema que se está evaporando lentamente.", "Existe una fuga pequeña en el sistema que iguala la capacidad de la bomba.", "El aceite de la bomba de vacío está saturado y necesita ser cambiado.", "El vacuómetro está sucio y no puede leer presiones por debajo de ese nivel."], respuesta_correcta:0, explicacion:"Cuando el vacío se estabiliza en 1500 micrones sin subir, indica humedad remanente evaporándose lentamente dentro del sistema. Una fuga haría que la presión suba continuamente, mientras que la humedad mantiene un equilibrio de presión de vapor constante." },
  { id:"ns_0064", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en defrost no derrite el hielo completamente. ¿Qué sensor está mal configurado o fallido?", opciones:["El sensor de temperatura de la tubería del serpentín exterior (Defrost Terminator).", "El sensor de temperatura ambiente exterior que bloquea el ciclo por calor.", "El interruptor de baja presión que detiene el compresor durante el deshielo.", "El termostato de la habitación que no activa las resistencias durante el ciclo."], respuesta_correcta:0, explicacion:"El sensor de temperatura del serpentin exterior (defrost terminator) determina cuando el hielo se ha derretido. Si esta mal calibrado o fallido, termina el ciclo de deshielo prematuramente sin completar el proceso." },
  { id:"ns_0065", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un líder de cuadrilla asigna a dos técnicos a un trabajo de 4 horas. Si tardan 8 horas, ¿qué métrica se afecta más?", opciones:["La eficiencia de la mano de obra y el margen de ganancia de ese proyecto.", "El costo de los materiales utilizados durante las horas adicionales de trabajo.", "La satisfacción del cliente por haber pasado más tiempo revisando el equipo.", "La garantía del fabricante del equipo que se instaló durante ese periodo."], respuesta_correcta:0, explicacion:"Duplicar las horas estimadas significa el doble de costo de mano de obra sin ingresos adicionales. La eficiencia laboral (labor efficiency) impacta directamente el margen de ganancia del proyecto, que es la métrica financiera más sensible." },
  { id:"ns_0066", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete tiene un compresor que arranca pero se apaga por 'Internal Overload'. El voltaje es correcto. ¿Causa?", opciones:["Un sobrecalentamiento excesivo del gas de succión que no enfría el motor.", "Un capacitor de arranque defectuoso que deja el devanado de arranque activo.", "La falta de una trampa de aceite en la línea de succión que sube al techo.", "Un sensor de temperatura de descarga que está desconectado en la placa."], respuesta_correcta:0, explicacion:"El gas de succión enfría el devanado del motor del compresor hermético. Si el sobrecalentamiento es excesivo, el gas llega demasiado caliente y no puede disipar el calor del motor, activando el protector térmico interno (Internal Overload)." },
  { id:"ns_0067", categoria:"NATE_SR_RACK", pregunta:"En un sistema de rack, el receptor de líquido vibra violentamente. ¿Qué problema hidráulico está ocurriendo?", opciones:["Un fenómeno de 'Flash Gas' debido a una caída de presión excesiva en la línea.", "El retorno de aceite está creando turbulencia en la superficie del refrigerante.", "La válvula de alivio está a punto de abrirse por una presión de descarga alta.", "El nivel de líquido es tan alto que no hay espacio para la expansión del gas."], respuesta_correcta:0, explicacion:"La vibración violenta del recibidor indica formación súbita de flash gas dentro del recipiente, causada por una caída de presión excesiva. La ebullición rápida del refrigerante genera ondas de presión que hacen vibrar el recipiente." },
  { id:"ns_0068", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que el 'Account Receivable' tiene facturas de más de 90 días. ¿Cuál es el riesgo de negocio?", opciones:["Una crisis de liquidez que impide pagar la nómina y a los proveedores a tiempo.", "La necesidad de contratar más personal de ventas para cubrir la falta de dinero.", "Un aumento en la carga impositiva sobre ingresos que aún no han sido cobrados.", "La degradación de la imagen de la empresa ante los clientes que no han pagado."], respuesta_correcta:0, explicacion:"Facturas sin cobrar por más de 90 días crean una crisis de liquidez real: la empresa no tiene efectivo para cubrir nómina y proveedores, aunque en papel tenga ingresos altos." },
  { id:"ns_0069", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con evaporador inundado tiene un bajo nivel de refrigerante. ¿Cuál es el síntoma principal?", opciones:["Una temperatura de salida del agua helada más alta que el set-point.", "Un aumento en el sobrecalentamiento del gas de succión del compresor.", "La formación de escarcha en la carcasa del evaporador por baja presión.", "Un consumo de amperaje extremadamente alto en el motor del compresor."], respuesta_correcta:0, explicacion:"En un evaporador inundado, el bajo nivel de refrigerante reduce el área de contacto con los tubos de agua. El resultado directo es que el agua helada sale más caliente que el set-point deseado." },
  { id:"ns_0070", categoria:"NATE_SR_HVAC", pregunta:"Al usar una TXV, el bulbo sensor se suelta de la línea de succión. ¿Qué le sucede al evaporador?", opciones:["Se inunda de líquido refrigerante porque la válvula se abre completamente.", "Se queda sin refrigerante (starving) porque la válvula se cierra por presión.", "La presión de succión baja drásticamente y el compresor se apaga por LPS.", "El sobrecalentamiento aumenta hasta que el compresor falla por alta temperatura."], respuesta_correcta:0, explicacion:"El bulbo sensor de la TXV mide la temperatura de la línea de succión para regular el flujo. Si se suelta, el bulbo sensa la temperatura ambiente (más alta), lo que hace que la válvula interprete que necesita más refrigerante y se abra completamente, inundando el evaporador." },
  { id:"ns_0071", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Customer Acquisition Cost' (CAC). ¿Qué canal es técnicamente más eficiente?", opciones:["El programa de referidos de clientes actuales satisfechos con el servicio.", "La publicidad pagada en televisión local durante las noticias de la tarde.", "La compra de bases de datos de correos electrónicos de clientes potenciales.", "El patrocinio de equipos deportivos locales para aumentar el reconocimiento."], respuesta_correcta:0, explicacion:"Los programas de referidos de clientes satisfechos tienen el CAC más bajo porque aprovechan la confianza existente sin costos significativos de publicidad o marketing." },
  { id:"ns_0072", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema inverter muestra el error 'IPM Intelligent Power Module fault'. ¿Qué prueba física realiza el Senior?", opciones:["Medir la resistencia y continuidad de los terminales U, V, W del compresor.", "Verificar el voltaje de entrada de 240VAC en los terminales L1 y L2 de la placa.", "Cambiar el capacitor de arranque por uno de mayor capacitancia para probar.", "Puentear el sensor de temperatura de descarga para ver si el error desaparece."], respuesta_correcta:0, explicacion:"Ante un error de IPM, el Senior mide resistencia y continuidad en los terminales U, V, W del compresor para descartar un devanado abierto, cortocircuitado o aterrizado que cause sobrecorriente al módulo." },
  { id:"ns_0073", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor geotérmica tiene aire en el lazo cerrado. ¿Cuál es el efecto en la bomba de circulación?", opciones:["Cavitación y pérdida de flujo, resultando en paros por alta o baja presión.", "Un aumento en la presión estática del agua que mejora la transferencia térmica.", "La reducción del consumo eléctrico de la bomba al mover un fluido menos denso.", "El aumento de la temperatura del agua debido a la fricción del aire en los tubos."], respuesta_correcta:0, explicacion:"El aire atrapado en el lazo cerrado causa cavitacion en la bomba de circulacion, reduciendo drasticamente el flujo de agua. Sin flujo adecuado, las presiones del refrigerante se descontrolan causando paros por alta o baja presion." },
  { id:"ns_0074", categoria:"NATE_SR_RACK", pregunta:"En un rack, el controlador indica 'Oil Failure' en tres compresores a la vez. ¿Qué componente central falló?", opciones:["El separador de aceite principal o la válvula de presión diferencial del depósito.", "Los sensores de nivel individuales de cada cárter de los tres compresores.", "La bomba de aceite mecánica de cada uno de los compresores afectados.", "El filtro deshidratador de la línea de líquido que alimenta a las vitrinas."], respuesta_correcta:0, explicacion:"Cuando múltiples compresores reportan falla de aceite simultáneamente, el problema es un componente centralizado del sistema de aceite: el separador principal o la válvula diferencial del depósito, ya que alimentan a todos los compresores." },
  { id:"ns_0075", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior debe decidir entre reparar un equipo de 20 años o vender uno nuevo. ¿Qué factor es decisivo?", opciones:["El costo de la reparación frente al valor residual y la eficiencia operativa.", "La disponibilidad de piezas estéticas como paneles y rejillas originales.", "La preferencia personal del técnico por trabajar con tecnología más antigua.", "El tiempo que tardará en llegar el equipo nuevo desde el almacén central."], respuesta_correcta:0, explicacion:"La decisión reparar vs. reemplazar se basa en análisis costo-beneficio: si el costo de reparación se acerca o supera el valor residual del equipo, y la eficiencia operativa (SEER) es muy inferior a equipos modernos, el reemplazo es la mejor inversión." },
  { id:"ns_0076", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo experimenta una 'caída de presión del evaporador' baja. ¿Cuál es la causa probable?", opciones:["Tubos del evaporador limpios o un flujo de agua superior al diseño nominal.", "Incrustaciones severas en el lado del agua que obstruyen el paso del fluido.", "Falta de refrigerante líquido que no cubre la totalidad de los tubos internos.", "Una válvula de mariposa en la línea de agua que está parcialmente cerrada."], respuesta_correcta:0, explicacion:"Una caída de presión baja en el lado del agua indica poca resistencia al flujo. Tubos limpios o flujo de agua superior al nominal reducen la fricción, resultando en menor caída de presión." },
  { id:"ns_0077", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial con R-410A tiene una presión de succión de 100 PSI y descarga de 300 PSI. ¿Estado?", opciones:["Falta de carga de refrigerante o baja carga térmica en el evaporador.", "Carga correcta de refrigerante operando en condiciones de diseño normales.", "Exceso de carga de refrigerante o restricción en el condensador exterior.", "Compresor con válvulas internas dañadas que no puede bombear eficientemente."], respuesta_correcta:0, explicacion:"Con R-410A, una succión de 100 PSI equivale a aproximadamente 30°F de saturación, lo cual es bajo. La descarga de 300 PSI también es relativamente baja. Esto indica falta de carga de refrigerante o baja carga térmica que impide que las presiones suban a niveles normales." },
  { id:"ns_0078", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete utiliza un motor de soplador accionado por correa. La correa rechina al arrancar. ¿Acción?", opciones:["Ajustar la tensión de la correa y verificar la alineación de las poleas.", "Aplicar lubricante en aerosol sobre la correa para reducir la fricción inicial.", "Reemplazar el motor por uno de mayor caballaje para soportar el arranque.", "Aumentar el diámetro de la polea del motor para reducir la velocidad final."], respuesta_correcta:0, explicacion:"El rechinar de una correa al arranque indica tensión insuficiente (la correa patina sobre la polea) o desalineación entre poleas. Ajustar la tensión y verificar la alineación es el procedimiento correcto antes de considerar reemplazar la correa." },
  { id:"ns_0079", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar la retención de técnicos Senior. ¿Qué estrategia es la más valorada?", opciones:["Un plan de carrera claro con certificaciones pagadas y bonos por desempeño.", "Proporcionar camionetas último modelo con sistemas de sonido premium.", "Aumentar el número de horas extras obligatorias para incrementar sus ingresos.", "Organizar eventos sociales mensuales con asistencia obligatoria fuera de horas."], respuesta_correcta:0, explicacion:"Un plan de carrera claro con certificaciones pagadas y bonos por desempeño demuestra inversión en el crecimiento profesional del técnico, siendo el factor de retención más valorado a largo plazo." },
  { id:"ns_0080", categoria:"NATE_SR_RACK", pregunta:"Se encuentra líquido en el cabezal de succión de un rack de media temperatura. ¿Qué válvula falló?", opciones:["Una válvula de expansión (TXV) de una de las vitrinas está atascada abierta.", "La válvula solenoide de la línea de líquido general no cierra en el paro.", "La válvula de alivio del receptor está permitiendo el paso de gas al rack.", "La válvula diferencial de aceite está inyectando refrigerante al sistema."], respuesta_correcta:0, explicacion:"Una TXV atascada en posición abierta permite el paso descontrolado de refrigerante líquido al evaporador, que no se evapora completamente y llega como líquido al cabezal de succión del rack, poniendo en riesgo los compresores." },
  { id:"ns_0081", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga de aire constante y opera con R-123. ¿Cuál es el riesgo de seguridad química?", opciones:["La formación de ácidos corrosivos dentro del sistema por la mezcla de aire y aceite.", "La liberación de cloro a la atmósfera que daña la capa de ozono directamente.", "El aumento de la inflamabilidad del refrigerante debido a la presión del aire.", "La asfixia del personal en la sala de máquinas por el desplazamiento del oxígeno."], respuesta_correcta:0, explicacion:"Cuando el aire se mezcla con R-123 y aceite a altas temperaturas, se forman ácidos clorhídrico y fluorhídrico que corroen componentes internos del sistema, incluyendo los devanados del motor." },
  { id:"ns_0082", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF reporta 'Communication error' solo cuando el compresor arranca. ¿Diagnóstico?", opciones:["Ruido eléctrico (EMI) que interfiere con la señal por falta de blindaje o tierra.", "La placa de comunicación está dañada y se bloquea por el consumo del motor.", "El compresor está aterrizado y envía voltaje a través del chasis a la placa.", "La longitud de los cables excede los límites y la señal llega muy débil."], respuesta_correcta:0, explicacion:"Cuando el error de comunicación solo ocurre al arrancar el compresor, la causa es ruido electromagnético (EMI) generado por el arranque del motor inverter, que interfiere con la señal de datos por falta de blindaje o tierra." },
  { id:"ns_0083", categoria:"NATE_SR_HVAC", pregunta:"Un sistema de conductos de fibra de vidrio muestra moho interno. ¿Qué factor operativo lo causó?", opciones:["Operar el sistema con baja velocidad de aire permitiendo condensación interna.", "El uso de filtros HEPA que restringen demasiado el flujo de aire del sistema.", "Una carga de refrigerante excesiva que enfría demasiado el serpentín interior.", "La instalación de luces UV después del serpentín en lugar de antes del mismo."], respuesta_correcta:0, explicacion:"Operar con baja velocidad de aire permite que la temperatura del aire dentro del conducto caiga por debajo del punto de rocío, causando condensación en la superficie interior de la fibra de vidrio. Esta humedad persistente crea el ambiente ideal para el crecimiento de moho." },
  { id:"ns_0084", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, la temperatura del aire de suministro en modo calor es de 85°F. ¿Es normal?", opciones:["Sí, las bombas de calor entregan aire a temperaturas más bajas que los hornos.", "No, la temperatura debería estar por encima de los 110°F para ser eficiente.", "Depende de si las resistencias eléctricas de apoyo están activadas o no.", "No, indica que la válvula inversora está fugando gas caliente internamente."], respuesta_correcta:0, explicacion:"Las bombas de calor entregan aire entre 85-95F en modo calor, a diferencia de los hornos de gas que entregan 120-140F. Esto es normal porque la bomba transfiere calor del exterior en vez de generarlo por combustion." },
  { id:"ns_0085", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera la instalación de un rooftop de 50 toneladas. ¿Cuál es el riesgo de seguridad más alto?", opciones:["La maniobra de izaje con grúa y la estabilidad de la estructura del techo.", "La conexión eléctrica de alto voltaje sin el equipo de protección personal.", "La manipulación de cilindros de refrigerante de gran tamaño bajo el sol.", "El riesgo de caídas desde el borde del techo si no hay barandales instalados."], respuesta_correcta:0, explicacion:"El izaje con grúa de un equipo de 50 toneladas involucra cargas extremadamente pesadas suspendidas a gran altura. Una falla en la maniobra puede causar el colapso de la estructura del techo o la caída del equipo, con consecuencias fatales." },
  { id:"ns_0086", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete tiene un economizador. En un día de 50°F exterior, el compresor arranca. ¿Por qué?", opciones:["El sensor de entalpía detectó que el aire exterior está demasiado húmedo.", "El motor del damper está atascado en la posición de aire de retorno 100%.", "El controlador del economizador no tiene energía o el fusible está fundido.", "El termostato de la zona está configurado para ignorar el aire exterior."], respuesta_correcta:0, explicacion:"Aunque 50°F parece ideal para enfriamiento gratuito, si la humedad exterior es alta, la entalpía total del aire excede el umbral. El sensor de entalpía correctamente bloquea el economizador y activa el compresor para evitar introducir aire húmedo." },
  { id:"ns_0087", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-404A. Se sospecha de 'Refrigerant Glide' tras una fuga lenta. ¿Qué debe hacer el Senior?", opciones:["Recuperar todo el refrigerante restante y cargar con refrigerante virgen.", "Simplemente completar la carga hasta que las presiones vuelvan a la normalidad.", "Añadir solo el componente más volátil de la mezcla para equilibrar el gas.", "Cambiar el filtro deshidratador y esperar a que la mezcla se estabilice sola."], respuesta_correcta:0, explicacion:"Aunque el R-404A es casi azeotrópico, tras una fuga lenta la composición puede alterarse. El procedimiento correcto es recuperar toda la carga restante y recargar con refrigerante virgen para garantizar la composición correcta de la mezcla." },
  { id:"ns_0088", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa el 'Return on Investment' (ROI) de una campaña de Google Ads. ¿Qué dato es clave?", opciones:["La conversión de clics en órdenes de trabajo cerradas con margen de utilidad.", "El número total de impresiones de los anuncios en las búsquedas locales.", "El costo por clic (CPC) comparado con el promedio de la industria nacional.", "La cantidad de llamadas telefónicas recibidas, independientemente del resultado."], respuesta_correcta:0, explicacion:"El verdadero ROI de Google Ads se mide por la conversión final: cuántos clics se transformaron en órdenes de trabajo cerradas con margen de utilidad, no solo en impresiones o clics." },
  { id:"ns_0089", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'high discharge temperature'. El condensador es de agua. ¿Qué revisa?", opciones:["El flujo de agua de la torre y la temperatura de entrada al condensador.", "La velocidad del compresor y el ajuste de los álabes de entrada (vanes).", "La carga de refrigerante líquido en el evaporador por el método del visor.", "El estado de la válvula de expansión y el sobrecalentamiento de la succión."], respuesta_correcta:0, explicacion:"En un chiller enfriado por agua con alta temperatura de descarga, lo primero es verificar el flujo y temperatura del agua de la torre, ya que son los factores principales que determinan la presión de condensación." },
  { id:"ns_0090", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 450 PSI con R-410A. ¿Qué indica la descarga?", opciones:["Incondensables en el sistema o un condensador extremadamente sucio.", "Una carga de refrigerante perfecta para un día de alta temperatura ambiental.", "Que el compresor está funcionando al 100% de su capacidad volumétrica.", "Una restricción en la válvula de expansión que eleva la presión de alta."], respuesta_correcta:0, explicacion:"Con R-410A, 450 PSI de descarga es anormalmente alto y equivale a una temperatura de condensación de aproximadamente 130°F. Esto indica incondensables (aire/nitrógeno) atrapados en el sistema o un condensador extremadamente sucio que impide la transferencia de calor." },
  { id:"ns_0091", categoria:"NATE_SR_CEO", pregunta:"Para mejorar el 'First Time Fix Rate', ¿qué acción administrativa es la más efectiva?", opciones:["Asegurar que las camionetas tengan un stock de piezas críticas basado en datos.", "Descontar el tiempo del segundo viaje del salario del técnico responsable.", "Comprar herramientas de diagnóstico más caras para todos los técnicos junior.", "Obligar a los técnicos a llamar a soporte técnico en cada diagnóstico de campo."], respuesta_correcta:0, explicacion:"Mantener un stock de piezas críticas basado en datos históricos de fallas permite al técnico resolver el problema en la primera visita, mejorando el First Time Fix Rate directamente." },
  { id:"ns_0092", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split gotea agua por la unidad interior. El drenaje está limpio. ¿Qué causa técnica es probable?", opciones:["Un bajo nivel de refrigerante que causa escarcha parcial y goteo fuera de la bandeja.", "El ventilador interior está girando demasiado rápido y succiona las gotas de agua.", "La bandeja de condensado está nivelada perfectamente en lugar de tener inclinación.", "El filtro de aire está demasiado limpio y permite que el aire pase con mucha humedad."], respuesta_correcta:0, explicacion:"Con el drenaje limpio, un nivel bajo de refrigerante causa escarcha parcial en el serpentín; al derretirse, el agua cae fuera de la bandeja de condensado porque la distribución de escarcha es irregular." },
  { id:"ns_0093", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor hace un ruido fuerte al terminar el defrost. ¿Qué está ocurriendo físicamente?", opciones:["La válvula inversora cambia de posición y las presiones se igualan bruscamente.", "El compresor está sufriendo un 'slugging' de líquido al volver al modo calor.", "El ventilador exterior golpea el hielo acumulado que no se alcanzó a derretir.", "Las resistencias eléctricas se apagan de golpe causando una contracción térmica."], respuesta_correcta:0, explicacion:"Al terminar el defrost, la valvula inversora cambia de refrigeracion a calefaccion. Este cambio brusco ecualiza las presiones de alta y baja repentinamente, creando un ruido fuerte pero normal en el sistema." },
  { id:"ns_0094", categoria:"NATE_SR_RACK", pregunta:"En un rack, el nivel de aceite en el separador es alto pero bajo en los compresores. ¿Qué revisa?", opciones:["El filtro de la línea de retorno de aceite o la válvula reguladora de nivel.", "La carga de refrigerante líquido que podría estar atrapando el aceite abajo.", "La temperatura de descarga que es demasiado baja para separar el aceite.", "La velocidad de los compresores que no generan suficiente arrastre de gas."], respuesta_correcta:0, explicacion:"Si el separador tiene aceite suficiente pero los compresores no, la obstrucción está en el camino de retorno: un filtro tapado en la línea de aceite o una válvula reguladora de nivel que no abre correctamente impiden el flujo de aceite hacia los cárteres." },
  { id:"ns_0095", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un cliente se queja de un técnico Senior por su actitud. ¿Cómo debe proceder el CEO?", opciones:["Escuchar al cliente, investigar la versión del técnico y tomar medidas justas.", "Despedir al técnico de inmediato para mantener la reputación de la empresa.", "Ignorar al cliente asumiendo que el técnico Senior siempre tiene la razón.", "Ofrecer un descuento del 50% al cliente sin investigar lo que realmente pasó."], respuesta_correcta:0, explicacion:"El liderazgo justo requiere escuchar ambas partes antes de actuar. Investigar los hechos protege tanto la relación con el cliente como los derechos del empleado, y permite tomar decisiones informadas que fortalecen la cultura de la empresa." },
  { id:"ns_0096", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una 'falla de flujo de agua'. La bomba está encendida. ¿Qué debe verificar?", opciones:["El interruptor de flujo (flow switch) o el diferencial de presión en el evaporador.", "El sentido de rotación del motor del compresor centrífugo del sistema.", "La carga de refrigerante que puede estar congelando el agua en los tubos.", "La apertura de las válvulas de expansión del circuito de refrigeración."], respuesta_correcta:0, explicacion:"Con la bomba encendida, una falla de flujo indica un problema con el interruptor de flujo (flow switch) o el diferencial de presión del evaporador, no con el equipo de refrigeración en sí." },
  { id:"ns_0097", categoria:"NATE_SR_HVAC", pregunta:"Un motor de condensador PSC falla. El técnico instala uno nuevo pero gira al revés. ¿Causa?", opciones:["Los cables del capacitor están invertidos o el motor es de rotación incorrecta.", "El voltaje de entrada está en desfase con el capacitor de marcha instalado.", "El ventilador está instalado al revés sobre el eje del motor del condensador.", "La placa de control está enviando una señal de polaridad invertida al motor."], respuesta_correcta:0, explicacion:"En un motor PSC, el capacitor crea el desfase de fase entre los devanados de arranque y marcha para determinar la dirección de rotación. Si los cables del capacitor se conectan invertidos o el motor tiene rotación opuesta al original, el motor girará al revés." },
  { id:"ns_0098", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete industrial no tiene calefacción. El ignitor brilla pero no hay llama. ¿Qué revisa?", opciones:["La válvula de gas o el suministro de presión de gas hacia la unidad.", "El sensor de flama que no está detectando la incandescencia del ignitor.", "El motor del inductor que no está creando el vacío necesario en el switch.", "El termostato de la zona que no está enviando la señal de 24V al terminal W."], respuesta_correcta:0, explicacion:"Si el ignitor brilla, la secuencia de encendido llegó hasta ese punto correctamente (inductor, switch de presión, placa). Si no hay llama, el problema es que no llega gas al quemador: válvula de gas cerrada, defectuosa, o sin presión de suministro." },
  { id:"ns_0099", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC es responsable de la seguridad del empleado. ¿Qué documento es vital ante OSHA?", opciones:["El registro de capacitaciones de seguridad y el manual de procesos de LOTO.", "El contrato de arrendamiento de las oficinas y el almacén de la empresa.", "La lista de precios actualizada que se le entrega a los clientes finales.", "El reporte de mantenimiento preventivo de las camionetas de la flota."], respuesta_correcta:0, explicacion:"OSHA requiere documentación de capacitaciones de seguridad y procedimientos LOTO (Lockout/Tagout) como evidencia de cumplimiento; su ausencia es la causa más común de multas graves." },
  { id:"ns_0100", categoria:"NATE_SR_RACK", pregunta:"En un sistema de rack con CO2, ¿qué sucede si se pierde la energía por mucho tiempo?", opciones:["La presión aumenta por encima de los límites y las válvulas de alivio se abren.", "El refrigerante se congela dentro de las tuberías dañando los evaporadores.", "El aceite se separa del refrigerante y bloquea permanentemente los capilares.", "El sistema entra en un vacío profundo que permite la entrada de humedad externa."], respuesta_correcta:0, explicacion:"El CO2 tiene una presión de saturación muy alta. Sin compresores funcionando, la temperatura del refrigerante sube con el ambiente, la presión aumenta rápidamente y supera los límites del sistema, forzando la apertura de las válvulas de alivio." },
  { id:"ns_0101", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con compresor de tornillo presenta una vibración excesiva solo cuando opera al 25% de carga. ¿Qué debe evaluar el Senior?", opciones:["La alineación de la válvula de corredera (slide valve) y la inyección de aceite.", "El equilibrio estático de los rotores del compresor en condiciones de alta carga.", "La resonancia estructural de la base del equipo con la frecuencia del motor.", "La viscosidad del aceite que se vuelve demasiado baja por la mezcla de gas."], respuesta_correcta:0, explicacion:"A 25% de carga, la válvula de corredera (slide valve) opera en una posición extrema donde la inyección de aceite y la alineación son críticas. Una mala posición causa vibraciones por flujo irregular." },
  { id:"ns_0102", categoria:"NATE_SR_RACK", pregunta:"En un rack de refrigeración, ¿cuál es el propósito de instalar una válvula 'Check' en la línea de descarga de cada compresor?", opciones:["Prevenir la migración de refrigerante líquido desde el condensador al compresor parado.", "Evitar que la presión de succión aumente drásticamente durante el ciclo de deshielo.", "Mantener una presión mínima de aceite en el cárter durante el arranque en frío.", "Reducir las pulsaciones de gas que pueden dañar el separador de aceite principal."], respuesta_correcta:0, explicacion:"La válvula check en la descarga evita que el refrigerante de alta presión y el líquido del condensador migren hacia un compresor apagado. Sin ella, el compresor parado se inundaría de líquido causando golpe de líquido al arrancar." },
  { id:"ns_0103", categoria:"NATE_SR_CEO", pregunta:"Si el margen de contribución de un departamento de instalaciones es del 10%, ¿qué acción estratégica debe tomar el CEO?", opciones:["Analizar los costos de mano de obra indirecta y renegociar precios con proveedores.", "Aumentar el presupuesto de marketing para obtener más volumen de instalaciones.", "Reducir el precio de venta para ganar más cuota de mercado frente a la competencia.", "Eliminar el departamento de inmediato para centrarse solo en el área de servicio."], respuesta_correcta:0, explicacion:"Un margen de contribución del 10% en instalaciones es críticamente bajo; el CEO debe analizar costos indirectos de mano de obra y renegociar con proveedores antes de tomar decisiones drásticas." },
  { id:"ns_0104", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema Multi-split tiene una unidad interior que sopla aire a temperatura ambiente mientras las demás enfrían. ¿Qué indica esto?", opciones:["La bobina de la válvula de expansión electrónica (EEV) de esa unidad está abierta.", "El sensor de temperatura de aire de retorno de esa unidad está fuera de rango.", "El compresor inverter no tiene la capacidad suficiente para alimentar todas las zonas.", "Hay una obstrucción física en el filtro de aire de esa unidad interior específica."], respuesta_correcta:0, explicacion:"Si una unidad interior sopla aire ambiente mientras las demás enfrían, significa que no recibe refrigerante. La bobina de la EEV abierta (sin energía) mantiene la válvula cerrada, bloqueando el flujo a esa unidad." },
  { id:"ns_0105", categoria:"NATE_SR_HVAC", pregunta:"Al realizar una prueba de combustión en un horno de gas, se detecta un exceso de aire del 80%. ¿Qué ajuste técnico es necesario?", opciones:["Reducir la velocidad del inductor o ajustar los obturadores de aire primario.", "Aumentar la presión de gas en el manifold para compensar el exceso de oxígeno.", "Reemplazar los quemadores por unos de menor orificio para reducir la potencia.", "Limpiar el intercambiador de calor para mejorar el tiro natural de la chimenea."], respuesta_correcta:0, explicacion:"Un exceso de aire del 80% significa demasiado oxígeno en la mezcla de combustión, lo que reduce la eficiencia y enfría la llama. La solución es reducir la entrada de aire ajustando los obturadores primarios o la velocidad del inductor para optimizar la relación aire-combustible." },
  { id:"ns_0106", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor presenta escarcha solo en la parte inferior del serpentín exterior en modo calor. ¿Cuál es el diagnóstico?", opciones:["Falta de refrigerante que causa una evaporación incompleta en el serpentín.", "El ventilador exterior está girando demasiado lento debido a un capacitor débil.", "La válvula de expansión exterior está inundando el serpentín con exceso de líquido.", "Es un comportamiento normal debido a la humedad relativa alta en el ambiente."], respuesta_correcta:0, explicacion:"Escarcha solo en la parte inferior del serpentin indica falta de refrigerante. Con carga baja, el refrigerante se evapora antes de llegar a las secciones superiores, dejando solo la parte inferior fria y escarchada." },
  { id:"ns_0107", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior nota que la cuadrilla usa el mismo vacuómetro para sistemas con aceite mineral y POE. ¿Por qué es un error?", opciones:["La contaminación cruzada de aceites puede degradar las propiedades del aceite POE.", "El vacuómetro dará lecturas falsas debido a la diferencia de densidad de los aceites.", "El aceite mineral daña permanentemente el sensor térmico de los vacuómetros digitales.", "Las normativas de la EPA prohíben compartir herramientas de medición entre sistemas."], respuesta_correcta:0, explicacion:"El aceite POE (polioléster) es higroscópico y altamente sensible a contaminantes. Residuos de aceite mineral en el vacuómetro o mangueras pueden contaminar un sistema POE, degradando su lubricación y causando fallas prematuras del compresor." },
  { id:"ns_0108", categoria:"NATE_SR_PACKAGE", pregunta:"En un Rooftop con VFD en el soplador, el motor falla por daño en los rodamientos tras 6 meses. ¿Qué causó esto?", opciones:["Corrientes parásitas (shaft currents) que fluyen a través de los rodamientos a tierra.", "La tensión de la correa era excesiva para la velocidad de operación del variador.", "Falta de lubricación de fábrica en un motor diseñado para operar a bajas RPM.", "El variador de frecuencia está descalibrado y genera un torque excesivo al arranque."], respuesta_correcta:0, explicacion:"Los VFD generan voltajes de modo común en la onda PWM que inducen corrientes parásitas a través del eje del motor hacia los rodamientos. Esto causa erosión eléctrica (fluting) en las pistas, destruyendo los rodamientos prematuramente. Se requieren rodamientos aislados o anillos de puesta a tierra del eje." },
  { id:"ns_0109", categoria:"NATE_SR_RACK", pregunta:"Un rack de media temperatura usa una válvula de bypass de gas caliente para control de capacidad. Si la válvula falla abierta:", opciones:["La presión de succión aumentará y el compresor podría sobrecalentarse rápidamente.", "El sistema se bloqueará por baja presión al no recibir suficiente gas de retorno.", "Las vitrinas se congelarán debido al exceso de refrigerante en los evaporadores.", "El separador de aceite se llenará de líquido causando una falla de lubricación."], respuesta_correcta:0, explicacion:"Una válvula de bypass de gas caliente abierta continuamente inyecta gas de descarga caliente directamente a la succión, elevando la presión y temperatura de succión. El compresor recircula gas caliente sin hacer trabajo útil y se sobrecalienta." },
  { id:"ns_0110", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC quiere implementar 'Tiered Pricing'. ¿Cuál es el objetivo principal de esta estrategia?", opciones:["Ofrecer opciones al cliente para aumentar el valor promedio de cada transacción.", "Reducir el costo operativo al estandarizar los tipos de reparaciones permitidas.", "Eliminar la necesidad de que el técnico explique los beneficios de cada pieza.", "Cumplir con las regulaciones estatales sobre la transparencia de precios de servicios."], respuesta_correcta:0, explicacion:"El Tiered Pricing (Good/Better/Best) ofrece al cliente opciones de diferentes niveles, lo que psicológicamente aumenta el valor promedio de cada transacción al presentar la opción intermedia como ideal." },
  { id:"ns_0111", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo opera en 'free cooling'. ¿Qué condición física permite que este proceso ocurra?", opciones:["La presión del condensador es menor que la del evaporador debido al agua fría.", "El compresor gira a una velocidad mínima para mover solo el refrigerante gaseoso.", "Las bombas de agua helada aumentan su flujo para compensar la falta de compresión.", "El refrigerante se inyecta directamente en la torre de enfriamiento para ser enfriado."], respuesta_correcta:0, explicacion:"El free cooling ocurre cuando el agua de torre está tan fría que la presión del condensador cae por debajo de la del evaporador, permitiendo la circulación natural del refrigerante sin compresión mecánica." },
  { id:"ns_0112", categoria:"NATE_SR_HVAC", pregunta:"Se encuentra una caída de voltaje de 10V entre el contactor y el compresor. ¿Qué debe hacer el Senior?", opciones:["Limpiar o reemplazar los contactos del contactor que presentan una alta resistencia.", "Instalar un capacitor de arranque (Hard Start Kit) para compensar la caída de tensión.", "Reemplazar el cableado por uno de mayor calibre desde el panel eléctrico principal.", "Verificar si la empresa eléctrica está suministrando un voltaje inestable a la casa."], respuesta_correcta:0, explicacion:"Una caída de 10V entre el contactor y el compresor indica alta resistencia en los contactos del contactor, probablemente por picaduras o arco eléctrico. Contactos deteriorados generan calor excesivo y reducen el voltaje entregado al compresor, causando sobrecargas." },
  { id:"ns_0113", categoria:"NATE_SR_CEO", pregunta:"Un CEO detecta que el 'Technician Turnover' es del 40% anual. ¿Cuál es el costo oculto más significativo?", opciones:["La pérdida de conocimiento institucional y la disminución de la lealtad del cliente.", "El gasto directo en anuncios de reclutamiento y uniformes para los nuevos empleados.", "La necesidad de comprar más herramientas básicas para los técnicos que entran.", "El aumento de las primas de seguro por tener conductores nuevos sin experiencia."], respuesta_correcta:0, explicacion:"La rotación del 40% destruye el conocimiento institucional acumulado y debilita la relación técnico-cliente, un costo oculto que supera con creces los gastos visibles de reclutamiento." },
  { id:"ns_0114", categoria:"NATE_SR_MINISPLIT", pregunta:"En un sistema inverter, el puente rectificador falla repetidamente. ¿Qué causa externa debe investigar el técnico?", opciones:["Picos de voltaje transitorios o falta de una conexión a tierra física adecuada.", "Un compresor con un devanado parcialmente cortocircuitado que demanda corriente.", "El uso de un protector de sobrevoltaje que no es compatible con sistemas inverter.", "Una temperatura ambiente excesiva en el compartimento de la placa electrónica."], respuesta_correcta:0, explicacion:"Los picos de voltaje transitorios y la falta de tierra adecuada someten al puente rectificador a sobrevoltajes que exceden su capacidad, causando fallas repetitivas en este componente." },
  { id:"ns_0115", categoria:"NATE_SR_RACK", pregunta:"Un sistema de rack utiliza R-744 (CO2). En el enfriador de gas (gas cooler), el fluido sale a 95°F. ¿Estado del sistema?", opciones:["Operación transcrítica donde el gas no se condensa pero se enfría a alta presión.", "Operación subcrítica normal donde el gas se ha convertido totalmente en líquido.", "Fallo del ventilador del condensador que impide la licuefacción del refrigerante.", "Carga insuficiente de CO2 que impide que el sistema alcance la presión de diseño."], respuesta_correcta:0, explicacion:"A 95°F el CO2 está por encima de su punto crítico (87.8°F), por lo que opera en modo transcrítico. En esta condición el CO2 no se condensa; solo se enfría como gas supercrítico denso en el gas-cooler." },
  { id:"ns_0116", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete tiene un Delta P de aceite bajo. El técnico agrega aceite pero el problema persiste. ¿Qué sigue?", opciones:["Verificar si hay refrigerante líquido diluyendo el aceite en el cárter del compresor.", "Cambiar la bomba de aceite mecánica por una de mayor desplazamiento volumétrico.", "Limpiar el cedazo de succión de aceite que podría estar obstruido por carbonilla.", "Drenar el exceso de aceite agregado para evitar un golpe de líquido en el cilindro."], respuesta_correcta:0, explicacion:"Cuando agregar aceite no resuelve el Delta P bajo, la causa más común es migración de refrigerante líquido al cárter. El refrigerante diluye el aceite, reduce su viscosidad y la bomba no puede generar presión diferencial suficiente para la lubricación." },
  { id:"ns_0117", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior debe entrenar a un Junior en el uso de la tabla P/T. ¿Cuál es el concepto clave a enseñar?", opciones:["La relación entre presión y temperatura solo es válida en un estado de saturación.", "La tabla P/T se usa para determinar el sobrecalentamiento en cualquier punto.", "Siempre se debe restar la presión atmosférica antes de buscar el valor en la tabla.", "Los refrigerantes con glide (mezclas) tienen una sola columna para el punto de burbuja."], respuesta_correcta:0, explicacion:"La tabla P/T refleja la relación presión-temperatura únicamente en estado de saturación (mezcla líquido-vapor). Si el refrigerante está sobrecalentado o subenfriado, la tabla no aplica directamente; entender esto es la base del diagnóstico HVACR." },
  { id:"ns_0118", categoria:"NATE_SR_CHILLERS", pregunta:"Se detecta una fuga en el evaporador de un chiller de baja presión (R-123). ¿Cuál es el síntoma inmediato?", opciones:["La unidad de purga opera con mucha frecuencia para expulsar el aire infiltrado.", "La presión de descarga aumenta debido a la pérdida de masa de refrigerante.", "El agua helada se contamina con aceite y empieza a oler a químico en el edificio.", "El compresor se apaga por alta temperatura de aceite debido a la falta de enfriamiento."], respuesta_correcta:0, explicacion:"El R-123 opera bajo presión atmosférica (vacío). Una fuga en el evaporador permite la entrada de aire, y la unidad de purga trabaja con mayor frecuencia para expulsar el aire infiltrado." },
  { id:"ns_0119", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor utiliza una TXV con orificio de bypass. Si el bypass se bloquea, ¿qué sucede en modo calor?", opciones:["El sistema se bloquea por baja presión ya que no fluye refrigerante al exterior.", "La presión de descarga sube al máximo porque el líquido no puede retornar.", "El compresor empieza a zumbar pero no puede mover el refrigerante en el ciclo.", "La válvula inversora se queda en una posición intermedia por falta de diferencial."], respuesta_correcta:0, explicacion:"En sistemas con TXV y orificio de bypass, el bypass permite el flujo en modo calor. Si se bloquea, no hay flujo al serpentin exterior y la presion baja cae drasticamente hasta activar el switch de baja presion." },
  { id:"ns_0120", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere aumentar el 'Gross Profit Margin'. ¿Cuál de estas acciones impacta más rápido?", opciones:["Mejorar la precisión de los presupuestos para reducir el desperdicio de materiales.", "Contratar a más personal administrativo para gestionar mejor las facturas de cobro.", "Comprar uniformes más económicos para reducir el gasto general de la empresa.", "Aumentar el límite de crédito de los clientes para fomentar compras más grandes."], respuesta_correcta:0, explicacion:"Mejorar la precisión de presupuestos reduce el desperdicio de materiales y el tiempo improductivo, impactando directamente el Gross Profit Margin de forma inmediata y medible." },
  { id:"ns_0121", categoria:"NATE_SR_RACK", pregunta:"En un rack, el sensor de presión de succión falla y marca 0 PSI constantes. ¿Qué acción toma el controlador?", opciones:["Apaga todos los compresores por seguridad para prevenir daños mecánicos graves.", "Arranca todos los compresores al 100% asumiendo una carga máxima de diseño.", "Ignora la lectura y opera basándose en la temperatura de retorno de las vitrinas.", "Activa una alarma pero sigue operando el último compresor que estaba encendido."], respuesta_correcta:0, explicacion:"Cuando el sensor de presión de succión reporta una lectura anormal de 0 PSI, el controlador interpreta una condición peligrosa y apaga todos los compresores como medida de seguridad (fail-safe) para prevenir operación sin control." },
  { id:"ns_0122", categoria:"NATE_SR_MINISPLIT", pregunta:"Al instalar un Mini-split, el técnico nota que el cable de comunicación tiene un empalme. ¿Cuál es la postura del Senior?", opciones:["Prohibir los empalmes, ya que alteran la impedancia y causan errores de datos.", "Permitir el empalme siempre que se use soldadura de estaño y tubo termocontráctil.", "Aceptar el empalme si se realiza dentro de una caja de conexiones accesible.", "Permitirlo solo si el tramo total de cable no excede los 50 pies de longitud."], respuesta_correcta:0, explicacion:"Los empalmes en el cable de comunicación alteran la impedancia de la línea y generan reflexiones de señal, causando errores de datos. El Senior exige un cable continuo sin empalmes." },
  { id:"ns_0123", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta un Delta T de 28°F y baja presión de succión. El flujo de aire parece bajo. ¿Causa?", opciones:["Un evaporador sucio o un filtro de aire con una caída de presión excesiva.", "Falta de refrigerante que provoca un enfriamiento desigual en el serpentín.", "Una válvula de expansión (TXV) que está inyectando demasiado refrigerante.", "El compresor tiene las válvulas de descarga rotas y no succiona correctamente."], respuesta_correcta:0, explicacion:"Un Delta T alto de 28°F con baja succión indica que poco aire pasa por el evaporador. Un evaporador sucio o filtro restrictivo reducen el CFM, lo que causa mayor caída de temperatura del aire que sí pasa y menor absorción total de calor, bajando la presión de succión." },
  { id:"ns_0124", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene tubos de cobre con recubrimiento de polímero. ¿Cuál es la ventaja técnica principal?", opciones:["Prevenir la corrosión galvánica y el fouling biológico en el lado del agua.", "Aumentar la transferencia térmica por encima de la conductividad del cobre puro.", "Permitir que el refrigerante opere a presiones más altas sin riesgo de ruptura.", "Reducir el peso total del intercambiador de calor para facilitar su transporte."], respuesta_correcta:0, explicacion:"El recubrimiento de polímero en tubos de cobre actúa como barrera contra la corrosión galvánica y previene la adhesión de biofilm y fouling biológico en el lado del agua." },
  { id:"ns_0125", categoria:"NATE_SR_CEO", pregunta:"Un CEO analiza el 'Customer Lifetime Value' (CLV). ¿Qué grupo de clientes suele tener el CLV más alto?", opciones:["Clientes con contratos de mantenimiento preventivo y actualizaciones de sistema.", "Clientes que solo llaman para reparaciones de emergencia en días festivos.", "Nuevos propietarios de viviendas que buscan la opción de instalación más barata.", "Empresas constructoras que compran equipos por volumen para edificios nuevos."], respuesta_correcta:0, explicacion:"Los clientes con contratos de mantenimiento preventivo generan ingresos recurrentes durante años y son más propensos a comprar actualizaciones de sistema, maximizando el CLV." },
  { id:"ns_0126", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calefacción, el acumulador de succión de una bomba de calor se llena de escarcha. ¿Qué indica?", opciones:["Operación normal donde el acumulador protege al compresor del líquido frío.", "Una falla total de la válvula inversora que se quedó en modo refrigeración.", "Que el sistema tiene una sobrecarga de refrigerante líquida muy peligrosa.", "El ventilador interior se detuvo y no hay intercambio de calor en la casa."], respuesta_correcta:0, explicacion:"En modo calefaccion, algo de escarcha en el acumulador es normal. El acumulador retiene refrigerante liquido que no se evaporo completamente en el serpentin exterior, protegiendolo de entrar al compresor en estado liquido." },
  { id:"ns_0127", categoria:"NATE_SR_RACK", pregunta:"Un sistema de rack utiliza un 'Subcooler' mecánico. ¿Cuál es el beneficio directo para el Senior?", opciones:["Aumentar la capacidad de enfriamiento de las vitrinas y reducir el flash gas.", "Bajar la presión de descarga de los compresores para ahorrar energía eléctrica.", "Prevenir que el aceite se caliente demasiado antes de entrar al separador.", "Eliminar la necesidad de usar válvulas de expansión térmicas en los servicios."], respuesta_correcta:0, explicacion:"El subcooler enfría el refrigerante líquido por debajo de su temperatura de saturación, reduciendo la formación de flash gas en la válvula de expansión. Esto aumenta directamente la capacidad frigorífica disponible en los evaporadores." },
  { id:"ns_0128", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 10 toneladas tiene dos circuitos independientes. El circuito 1 está muerto. ¿Riesgo?", opciones:["El serpentín del evaporador se congelará parcialmente debido al flujo de aire desigual.", "El compresor del circuito 2 se quemará por trabajar el doble de tiempo nominal.", "El economizador dejará de funcionar porque detecta un desequilibrio térmico.", "La humedad en el edificio aumentará drásticamente al no haber deshumidificación."], respuesta_correcta:0, explicacion:"Con un circuito muerto, la mitad del serpentín del evaporador no tiene refrigerante pero sigue recibiendo flujo de aire. La otra mitad trabaja a carga máxima con todo el flujo, causando temperaturas de evaporación muy bajas que congelan esa sección del serpentín." },
  { id:"ns_0129", categoria:"NATE_SR_MANAGEMENT", pregunta:"Como líder Senior, ¿cuál es la mejor forma de verificar que un sistema está libre de humedad?", opciones:["Realizar una prueba de caída de vacío (standing vacuum test) y llegar a 500 micrones.", "Observar que el visor de líquido (sight glass) cambie de color amarillo a verde.", "Purgar un poco de refrigerante a la atmósfera y verificar si sale vapor de agua.", "Dejar la bomba de vacío encendida durante exactamente 24 horas seguidas."], respuesta_correcta:0, explicacion:"El standing vacuum test a 500 micrones o menos confirma que la humedad fue eliminada. Si el vacío se mantiene estable tras apagar la bomba, el sistema está seco y estanco. El visor de líquido solo detecta humedad después de cargar refrigerante." },
  { id:"ns_0130", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga 'non-condensable' de alta eficiencia. ¿Qué hace con el refrigerante recuperado?", opciones:["Lo separa del aire y lo devuelve automáticamente al evaporador del chiller.", "Lo almacena en un cilindro externo para ser reciclado por el técnico después.", "Lo quema mediante una resistencia eléctrica para evitar su liberación al aire.", "Lo mezcla con el aceite de lubricación para mantener la viscosidad correcta."], respuesta_correcta:0, explicacion:"La purga de alta eficiencia separa el refrigerante del aire mediante condensación, y devuelve automáticamente el refrigerante recuperado al evaporador para minimizar las pérdidas del sistema." },
  { id:"ns_0131", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF tiene una fuga en una de las 10 unidades interiores. ¿Cuál es el procedimiento Senior?", opciones:["Aislar la unidad mediante las válvulas del colector (branch box) y reparar.", "Recuperar el refrigerante de todo el sistema para poder soldar esa unidad.", "Puentear la unidad en el software y dejar que el sistema opere con las otras 9.", "Añadir sellador de fugas líquido al sistema para evitar el paro de las zonas."], respuesta_correcta:0, explicacion:"En sistemas VRF, las válvulas del colector (branch box) permiten aislar una unidad individual sin recuperar todo el refrigerante del sistema, permitiendo reparar la fuga sin afectar las demás zonas." },
  { id:"ns_0132", categoria:"NATE_SR_HVAC", pregunta:"Un compresor hace un ruido de 'clattering' durante el arranque. ¿Qué problema mecánico indica?", opciones:["Arranque inundado (flooded start) con refrigerante líquido en el cárter.", "Un capacitor de marcha que está defectuoso y causa una vibración eléctrica.", "Que el compresor está girando en sentido contrario por una falla de fase.", "Desgaste en los bujes superiores que permite que el rotor golpee el estator."], respuesta_correcta:0, explicacion:"El ruido de 'clattering' al arrancar indica que refrigerante líquido migró al cárter durante el ciclo de apagado. Al arrancar, el aceite espumoso con líquido se succiona violentamente hacia los cilindros, causando golpes mecánicos (slugging) hasta que el líquido se evapora." },
  { id:"ns_0133", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Current Ratio' de la empresa. ¿Qué acción debe priorizar?", opciones:["Convertir activos de inventario obsoleto en efectivo y pagar deudas cortas.", "Pedir un préstamo a 10 años para comprar un nuevo edificio administrativo.", "Aumentar el salario de los técnicos senior para mejorar la productividad.", "Ofrecer descuentos a los clientes que paguen por adelantado sus servicios."], respuesta_correcta:0, explicacion:"Convertir inventario obsoleto en efectivo y pagar deudas a corto plazo mejora directamente el Current Ratio al aumentar activos corrientes líquidos y reducir pasivos corrientes." },
  { id:"ns_0134", categoria:"NATE_SR_RACK", pregunta:"Se observa que una válvula EPR está vibrando y haciendo ruido. ¿Cuál es el ajuste Senior?", opciones:["Ajustar el resorte de la válvula para cambiar su frecuencia natural de oscilación.", "Cerrar la válvula completamente y dejar que el sistema opere por presión de rack.", "Instalar una trampa de aceite justo antes de la válvula para amortiguar el gas.", "Cambiar la válvula por una de menor capacidad para aumentar la velocidad del gas."], respuesta_correcta:0, explicacion:"La vibración de una válvula EPR indica que está operando cerca de su punto de inestabilidad. Ajustar la tensión del resorte cambia su frecuencia natural y elimina la resonancia con el flujo de gas, deteniendo la vibración." },
  { id:"ns_0135", categoria:"NATE_SR_PACKAGE", pregunta:"En un Rooftop, el sensor de 'Mixed Air' falla. ¿Cómo afecta esto al economizador?", opciones:["El damper se moverá a una posición de seguridad (generalmente 100% retorno).", "El economizador se abrirá al 100% para evitar el sobrecalentamiento del equipo.", "Los compresores se apagarán inmediatamente para prevenir la congelación.", "La placa de control ignorará el sensor y operará por tiempo de funcionamiento."], respuesta_correcta:0, explicacion:"El sensor de aire mezclado (Mixed Air) previene la congelación del serpentín al controlar la mezcla de aire exterior y retorno. Si falla, el controlador del economizador entra en modo de seguridad cerrando el damper de aire exterior (100% retorno) para evitar introducir aire frío sin control." },
  { id:"ns_0136", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un approach de evaporador de 0°F. ¿Qué conclusión técnica es correcta?", opciones:["El sensor de temperatura está descalibrado o hay refrigerante líquido en la succión.", "El sistema está operando en su punto máximo de eficiencia termodinámica.", "Los tubos del evaporador han sido limpiados recientemente con ácido fuerte.", "El flujo de agua a través del evaporador es exactamente el doble del nominal."], respuesta_correcta:0, explicacion:"Un approach de 0°F es físicamente improbable en operación normal. Indica un sensor de temperatura descalibrado o presencia de refrigerante líquido en la succión que falsea las lecturas." },
  { id:"ns_0137", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Junior pregunta por qué soldar con nitrógeno. El Senior responde que es para evitar:", opciones:["La formación de escamas de óxido cúprico que tapan las válvulas de expansión.", "Que el cobre se debilite y se vuelva quebradizo por el exceso de calor.", "La entrada de humedad atmosférica al sistema durante el proceso de soldadura.", "Que la soldadura de plata se oxide y pierda sus propiedades de adherencia."], respuesta_correcta:0, explicacion:"Al soldar sin nitrógeno, el oxígeno del aire reacciona con el cobre caliente formando escamas de óxido cúprico (hollín negro) dentro de la tubería. Estas partículas se desprenden y obstruyen filtros, TXVs y orificios, causando fallas del sistema." },
  { id:"ns_0138", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, la temperatura de descarga es de 230°F. ¿Cuál es el límite del Senior?", opciones:["225°F; por encima de esto, el aceite empieza a carbonizarse y fallará.", "250°F; es la temperatura normal de operación para sistemas con R-410A.", "200°F; cualquier valor superior indica una falta de carga de refrigerante.", "275°F; el compresor tiene un protector térmico que actuará en este punto."], respuesta_correcta:0, explicacion:"El limite seguro de temperatura de descarga es aproximadamente 225F. Por encima de este valor, el aceite lubricante comienza a carbonizarse, perdiendo sus propiedades y eventualmente causando falla del compresor." },
  { id:"ns_0139", categoria:"NATE_SR_RACK", pregunta:"Se detecta que el 'Heat Reclaim' de un supermercado no calienta el agua. ¿Qué revisa?", opciones:["La válvula de tres vías que desvía el gas caliente hacia el intercambiador.", "La presión del receptor de líquido que podría estar demasiado alta para el flujo.", "El nivel de aceite en el rack que podría estar bloqueando el intercambio de calor.", "La velocidad de los ventiladores del condensador principal del sistema de rack."], respuesta_correcta:0, explicacion:"El sistema de Heat Reclaim depende de una válvula de tres vías que desvía el gas caliente de descarga hacia el intercambiador de calor del agua. Si esta válvula falla o no abre, el gas caliente va directo al condensador sin calentar el agua." },
  { id:"ns_0140", categoria:"NATE_SR_CEO", pregunta:"Un CEO debe asegurar que todos los técnicos tengan la certificación EPA 608. ¿Por qué?", opciones:["Para evitar multas federales y permitir la compra legal de refrigerantes.", "Porque es un requisito para que la empresa pueda cotizar en la bolsa.", "Para reducir el costo de los seguros de salud de los empleados técnicos.", "Porque los fabricantes no venden equipos a empresas sin técnicos certificados."], respuesta_correcta:0, explicacion:"La certificación EPA 608 es un requisito federal para manejar refrigerantes; sin ella, la empresa enfrenta multas severas y los técnicos no pueden comprar refrigerante legalmente." },
  { id:"ns_0141", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una caída de presión de agua muy alta en el condensador. ¿Causa probable?", opciones:["Obstrucción por escombros o incrustaciones en los tubos del intercambiador.", "La bomba de agua de la torre está girando a una velocidad excesiva.", "El refrigerante está congelando el agua dentro de los tubos del condensador.", "Las válvulas de aislamiento del condensador están completamente abiertas."], respuesta_correcta:0, explicacion:"Una caída de presión de agua muy alta en el condensador indica obstrucción en los tubos por escombros, incrustaciones minerales o lodo que restringen el paso del agua." },
  { id:"ns_0142", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split reporta un código de error de 'DC Voltage Low'. ¿Qué componente revisa?", opciones:["Los capacitores de filtrado en la placa de potencia de la unidad exterior.", "El voltaje de la batería del control remoto inalámbrico de la unidad interior.", "La continuidad de los fusibles térmicos dentro del motor del ventilador.", "El transformador de 24V que alimenta la placa de control principal."], respuesta_correcta:0, explicacion:"El error 'DC Voltage Low' indica que el bus de voltaje DC interno está caído. Los capacitores de filtrado en la placa de potencia son los responsables de mantener ese voltaje estable tras la rectificación." },
  { id:"ns_0143", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene un sobrecalentamiento de 2°F y un subenfriamiento de 20°F. ¿Diagnóstico?", opciones:["Sistema sobrecargado de refrigerante que inunda el evaporador.", "Válvula de expansión (TXV) bloqueada en la posición de cerrado.", "Filtro de aire sucio que reduce la carga térmica en el evaporador.", "El compresor está perdiendo eficiencia y no succiona refrigerante."], respuesta_correcta:0, explicacion:"Un sobrecalentamiento de 2°F indica que el evaporador está casi inundado de líquido, y un subenfriamiento de 20°F indica exceso de líquido acumulado en el condensador. Ambos síntomas juntos confirman una sobrecarga de refrigerante en el sistema." },
  { id:"ns_0144", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete con calefacción eléctrica, un elemento no calienta. ¿Qué revisa?", opciones:["El secuenciador o el contactor que activa ese banco de resistencias.", "El termostato de seguridad de límite de aire que está abierto por calor.", "El interruptor de flujo de aire que detecta una presión estática baja.", "La configuración del ventilador que no está en modo 'G' durante el calor."], respuesta_correcta:0, explicacion:"En calefacción eléctrica, cada banco de resistencias se activa mediante un secuenciador o contactor individual. Si solo un elemento no calienta, el problema está en el componente que controla ese banco específico, no en los controles de seguridad generales." },
  { id:"ns_0145", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere implementar un programa de mantenimiento preventivo. ¿Cuál es el KPI de éxito?", opciones:["El aumento en la tasa de renovación de contratos año tras año.", "La cantidad de filtros de aire comprados mensualmente por la empresa.", "El número de quejas de clientes recibidas a través de la página web.", "La reducción en la cantidad de millas recorridas por las camionetas."], respuesta_correcta:0, explicacion:"La tasa de renovación de contratos mide directamente si los clientes valoran el servicio de mantenimiento preventivo lo suficiente para seguir pagando, siendo el KPI de éxito más relevante." },
  { id:"ns_0146", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor tiene una succión de 50 PSI con R-410A. ¿Problema?", opciones:["Baja absorción de calor en el serpentín exterior por hielo o falla de motor.", "Falla de la válvula inversora que está enviando gas a la descarga directa.", "El termostato interior está configurado a una temperatura muy baja.", "Es una presión normal de funcionamiento cuando hace mucho frío afuera."], respuesta_correcta:0, explicacion:"Con R-410A, una succion de 50 PSI corresponde a aproximadamente 10F de saturacion, lo cual es muy bajo. Indica que el serpentin exterior no absorbe suficiente calor, ya sea por hielo o falla del ventilador exterior." },
  { id:"ns_0147", categoria:"NATE_SR_RACK", pregunta:"En un rack, la mirilla del separador de aceite está vacía durante la carga máxima. ¿Qué hace?", opciones:["Verificar si el aceite está atrapado en los evaporadores o en el condensador.", "Agregar 2 galones de aceite POE de inmediato para proteger los compresores.", "Apagar el rack y esperar a que el aceite regrese por gravedad al sistema.", "Aumentar la presión del recibidor para forzar el aceite hacia los cárteres."], respuesta_correcta:0, explicacion:"Antes de agregar aceite, se debe verificar dónde está el aceite existente. A carga máxima, el aceite puede estar atrapado en evaporadores o condensador por baja velocidad de gas. Agregar aceite sin diagnóstico puede causar exceso cuando el aceite regrese." },
  { id:"ns_0148", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior observa que un ayudante no usa gafas de seguridad al recuperar gas. ¿Por qué?", opciones:["El refrigerante líquido puede causar congelación instantánea y ceguera.", "El aceite del sistema es altamente ácido y puede irritar la piel de la cara.", "La presión del gas puede hacer que la manguera golpee el ojo del técnico.", "Es una regla de la empresa que no tiene un impacto técnico real en la vista."], respuesta_correcta:0, explicacion:"El refrigerante en estado líquido se evapora instantáneamente al contacto con la piel o los ojos, causando quemaduras por congelación severas. Un salpicón en los ojos puede provocar ceguera permanente, por eso las gafas de seguridad son obligatorias." },
  { id:"ns_0149", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo tiene una falla de 'surge' a baja carga. ¿Qué ajuste realiza?", opciones:["Ajustar los álabes de entrada (vanes) o usar un variador de frecuencia.", "Incrementar el set-point de temperatura de salida del agua helada.", "Abrir la válvula de expansión para aumentar la masa de refrigerante.", "Limpiar los tubos del condensador para bajar la presión de descarga."], respuesta_correcta:0, explicacion:"El surge a baja carga se corrige ajustando los álabes de entrada (vanes) para mantener el flujo mínimo de gas, o usando un VFD para reducir la velocidad del compresor y mantener la relación de presiones." },
  { id:"ns_0150", categoria:"NATE_SR_HVAC", pregunta:"Un motor de soplador PSC zumba pero no gira. Si se ayuda con la mano, arranca. ¿Qué falla?", opciones:["El capacitor de marcha está abierto o ha perdido su capacitancia.", "El devanado de trabajo del motor tiene un cortocircuito interno.", "La placa de control no está enviando el voltaje de fase correcto.", "Los rodamientos del motor están secos y requieren lubricación."], respuesta_correcta:0, explicacion:"Un motor PSC necesita el capacitor para crear el desfase de fase necesario entre el devanado de arranque y el de marcha. Si el capacitor está abierto o sin capacitancia, el motor zumba porque recibe corriente pero no puede generar el par de arranque rotacional." },
  { id:"ns_0151", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa el 'Debt-to-Equity Ratio'. Si el valor es de 3.0, ¿qué significa?", opciones:["La empresa tiene mucha deuda en relación con el capital de los socios.", "La empresa es muy rentable y tiene un flujo de caja excelente actualmente.", "Los activos de la empresa son tres veces superiores a sus deudas totales.", "La empresa califica para créditos bancarios con las tasas más bajas."], respuesta_correcta:0, explicacion:"Un Debt-to-Equity Ratio de 3.0 significa que por cada dólar de capital propio, la empresa tiene $3 de deuda, indicando un apalancamiento muy alto y riesgo financiero significativo." },
  { id:"ns_0152", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no modula su velocidad y opera siempre al 100%. ¿Qué revisa?", opciones:["El termistor de temperatura ambiente o la configuración del control remoto.", "La placa de potencia exterior que tiene un transistor IGBT bloqueado.", "La carga de refrigerante que es excesiva y fuerza al compresor al máximo.", "El motor del ventilador interior que no reporta sus RPM a la placa principal."], respuesta_correcta:0, explicacion:"Si el inverter no modula y opera siempre al 100%, el termistor de temperatura ambiente puede estar descalibrado o el control remoto mal configurado, haciendo que el sistema crea que nunca alcanza el setpoint." },
  { id:"ns_0153", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor con R-410A, ¿cuál es el propósito del 'Crancase Heater'?", opciones:["Evitar la migración de refrigerante al aceite durante los periodos de paro.", "Mantener el refrigerante en estado gaseoso para facilitar el arranque rápido.", "Aumentar la temperatura del gas de descarga para mejorar la calefacción.", "Reducir la viscosidad del aceite para que fluya mejor hacia los cojinetes."], respuesta_correcta:0, explicacion:"El calentador de carter (crankcase heater) mantiene el aceite del compresor caliente durante los periodos de paro. Esto evita que el refrigerante liquido migre al carter y diluya el aceite, previniendo slugging al arrancar." },
  { id:"ns_0154", categoria:"NATE_SR_RACK", pregunta:"Un rack paralelo tiene un compresor que vibra mucho más que los otros. ¿Qué revisa?", opciones:["Los soportes antivibratorios de goma o la nivelación del compresor.", "Si ese compresor está retornando más líquido que los demás del grupo.", "La presión de aceite de ese compresor específico comparada con el rack.", "La configuración del variador de frecuencia que controla a ese compresor."], respuesta_correcta:0, explicacion:"Si solo un compresor vibra excesivamente mientras los demás operan normal, la causa más probable es mecánica: soportes antivibratorios (grommets) desgastados o rotos, o una mala nivelación del compresor en la base del rack." },
  { id:"ns_0155", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un cliente pide un descuento porque el técnico Senior tardó 10 minutos. ¿Qué dice el líder?", opciones:["Explica que el cobro es por el conocimiento y la solución, no por el tiempo.", "Acepta el descuento para evitar una mala reseña en las redes sociales.", "Le dice al cliente que el técnico es experto y por eso fue tan rápido.", "Cobra solo la pieza y regala la mano de obra para mantener la relación."], respuesta_correcta:0, explicacion:"El valor del servicio técnico radica en el conocimiento, la experiencia y la solución del problema, no en las horas invertidas. Un diagnóstico rápido refleja años de experiencia y formación, y eso es lo que el cliente paga." },
  { id:"ns_0156", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga manual. ¿Cómo sabe el Senior que hay aire dentro?", opciones:["La presión del condensador es mayor que la presión de saturación del gas.", "La temperatura del agua helada empieza a subir sin razón aparente.", "El compresor hace un ruido metálico debido a la compresión del aire.", "El visor de líquido muestra burbujas constantes a pesar de la carga total."], respuesta_correcta:0, explicacion:"La presencia de gases no condensables (aire) eleva la presión del condensador por encima de la presión de saturación correspondiente a la temperatura del refrigerante. Esta diferencia confirma la presencia de aire." },
  { id:"ns_0157", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 150 PSI y descarga de 350 PSI con R-410A. ¿Cómo está?", opciones:["Presiones normales para un día caluroso con una carga térmica alta.", "Falta de refrigerante que impide que la descarga suba a niveles normales.", "Exceso de refrigerante que eleva la presión de succión por encima del límite.", "Compresor defectuoso que no logra crear el diferencial de presión adecuado."], respuesta_correcta:0, explicacion:"Con R-410A, una succión de 150 PSI equivale a ~48°F de saturación y 350 PSI de descarga equivale a ~100°F de condensación. Estas son presiones normales para un día caluroso con carga térmica alta, indicando operación correcta del sistema." },
  { id:"ns_0158", categoria:"NATE_SR_PACKAGE", pregunta:"En un Rooftop, el damper de alivio barométrico está siempre abierto. ¿Consecuencia?", opciones:["Pérdida de presión positiva en el edificio e infiltración de aire exterior.", "Congelación del serpentín del evaporador por falta de carga térmica.", "Aumento del consumo de gas en el horno durante el ciclo de calefacción.", "Falla del motor del soplador por operar con una presión estática baja."], respuesta_correcta:0, explicacion:"El damper barométrico debe abrir solo cuando la presión del edificio es positiva para aliviar el exceso. Si queda abierto permanentemente, el aire acondicionado del edificio se escapa al exterior, eliminando la presión positiva y permitiendo infiltración descontrolada de aire exterior sin tratar." },
  { id:"ns_0159", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere incentivar a los técnicos a vender más. ¿Cuál es el riesgo de ética?", opciones:["Que los técnicos recomienden reparaciones o equipos innecesarios al cliente.", "Que los técnicos se distraigan y tarden más tiempo en realizar las reparaciones.", "Que los clientes se quejen por sentir una presión de venta durante el servicio.", "Que el inventario de las camionetas se agote más rápido de lo presupuestado."], respuesta_correcta:0, explicacion:"Cuando los técnicos tienen incentivos de venta agresivos, el mayor riesgo ético es que recomienden reparaciones o equipos innecesarios, dañando la confianza del cliente y la reputación." },
  { id:"ns_0160", categoria:"NATE_SR_RACK", pregunta:"Un rack usa descongelación eléctrica. El contactor se quema cada mes. ¿Qué revisa?", opciones:["Si el amperaje de las resistencias excede la capacidad del contactor.", "Si el voltaje de la bobina del contactor es de 120V en lugar de 24V.", "Si el reloj de deshielo está configurado para ciclos demasiado largos.", "Si los cables de alimentación de las resistencias tienen el calibre correcto."], respuesta_correcta:0, explicacion:"Un contactor que se quema repetidamente indica que el amperaje de las resistencias de deshielo excede la capacidad nominal del contactor. Los contactos se sobrecalientan y sueldan, requiriendo un contactor de mayor capacidad o división de circuitos." },
  { id:"ns_0161", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Motor High Temp'. El agua está fría. ¿Qué revisa?", opciones:["La línea de enfriamiento del motor (refrigerante líquido) y su filtro.", "La viscosidad del aceite que podría estar causando fricción en el motor.", "El flujo de agua en el condensador que podría ser insuficiente para enfriar.", "Si el compresor está operando con un voltaje excesivamente alto o bajo."], respuesta_correcta:0, explicacion:"En chillers centrífugos, el motor se enfría con refrigerante líquido. Si la línea de enfriamiento o su filtro están bloqueados, el motor se sobrecalienta aunque el agua del sistema esté fría." },
  { id:"ns_0162", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter muestra el error 'Outdoor Fan Motor error'. ¿Qué prueba?", opciones:["Si el ventilador gira libremente y el voltaje de la placa al motor.", "El capacitor de arranque del motor del ventilador de la unidad exterior.", "La continuidad de los cables de señal del termostato hacia la unidad.", "La carga de refrigerante que podría estar bloqueando el flujo de aire."], respuesta_correcta:0, explicacion:"Ante un error de motor del ventilador exterior, el Senior verifica primero si gira libremente (sin obstrucción mecánica) y luego mide el voltaje que la placa envía al motor para confirmar si es falla mecánica o electrónica." },
  { id:"ns_0163", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una TXV. El sobrecalentamiento es de 25°F y el subenfriamiento de 2°F. ¿Causa?", opciones:["Falta de refrigerante en el sistema (undercharged).", "Válvula de expansión (TXV) bloqueada o fallida.", "Restricción en el filtro deshidratador de la línea de líquido.", "Exceso de flujo de aire a través del serpentín del evaporador."], respuesta_correcta:0, explicacion:"Un sobrecalentamiento alto de 25°F indica que el evaporador no recibe suficiente refrigerante, y un subenfriamiento bajo de 2°F indica que hay poco líquido en el condensador. Ambos síntomas juntos son señal clásica de un sistema con falta de carga (undercharged)." },
  { id:"ns_0164", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el compresor no arranca pero el ventilador sí. ¿Qué revisa?", opciones:["El contactor del compresor y los interruptores de seguridad (HP/LP).", "El fusible de la placa de control que alimenta al motor del soplador.", "El sensor de temperatura de aire de retorno que activa la calefacción.", "La presión de gas de entrada si la unidad es de tipo dual (gas/electric)."], respuesta_correcta:0, explicacion:"Si el ventilador opera pero el compresor no, el circuito de control de baja tensión funciona. El problema está en el circuito del compresor: el contactor puede no estar cerrando, o un interruptor de seguridad de alta o baja presión está abierto bloqueando el arranque." },
  { id:"ns_0165", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota un aumento en el 'Days Sales Outstanding' (DSO). ¿Qué significa?", opciones:["Los clientes están tardando más tiempo en pagar sus facturas a la empresa.", "La empresa está vendiendo más servicios cada día de lo que había planeado.", "Los técnicos están terminando los trabajos más rápido que el mes anterior.", "El costo de ventas ha disminuido gracias a una mejor eficiencia operativa."], respuesta_correcta:0, explicacion:"Un DSO creciente indica que los clientes están tardando más en pagar sus facturas, lo que reduce el efectivo disponible y puede causar problemas de liquidez operativa." },
  { id:"ns_0166", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo refrigeración tiene una presión de alta de 500 PSI. ¿Causa?", opciones:["Condensador exterior sucio o falla del ventilador de la unidad exterior.", "Evaporador interior sucio que reduce la absorción de calor en la casa.", "Válvula inversora que no cambió de posición y sigue en modo calefacción.", "Restricción en la válvula de expansión de la unidad interior del sistema."], respuesta_correcta:0, explicacion:"En modo refrigeracion, el serpentin exterior es el condensador. Una presion de 500 PSI con R-410A indica que el condensador no puede rechazar el calor, tipicamente por suciedad o falla del ventilador exterior." },
  { id:"ns_0167", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué indica una mirilla de aceite con espuma persistente?", opciones:["Presencia de refrigerante líquido diluido en el aceite del cárter.", "Que el aceite está limpio y circulando a la velocidad de diseño correcta.", "Que el separador de aceite está funcionando con una eficiencia del 100%.", "Que el calentador de cárter está funcionando y evaporando el refrigerante."], respuesta_correcta:0, explicacion:"La espuma persistente en la mirilla de aceite indica que hay refrigerante líquido disuelto en el aceite. Al arrancar el compresor, la caída de presión del cárter hace que el refrigerante hierva dentro del aceite, creando espuma." },
  { id:"ns_0168", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior debe explicar el 'GWP' a un cliente. ¿Qué significa?", opciones:["El potencial de calentamiento global del refrigerante usado en el equipo.", "La garantía de piezas y mano de obra que ofrece el fabricante del sistema.", "La eficiencia energética total del equipo en condiciones extremas de calor.", "La presión máxima de trabajo que puede soportar el serpentín de cobre."], respuesta_correcta:0, explicacion:"GWP (Global Warming Potential) mide cuánto contribuye un refrigerante al calentamiento global comparado con el CO2. Es un factor clave en la transición a refrigerantes de bajo impacto ambiental como el R-32 o R-454B." },
  { id:"ns_0169", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga 'smart'. ¿Cuándo decide purgar el sistema?", opciones:["Cuando detecta un diferencial entre la presión real y la de saturación.", "Cada 24 horas de operación continua del compresor para evitar fallos.", "Cuando el operador presiona el botón de purga manual en el panel frontal.", "Cuando la temperatura del refrigerante líquido baja de los 40 grados F."], respuesta_correcta:0, explicacion:"La purga inteligente (smart) compara la presión real del sistema con la presión de saturación teórica a la temperatura medida. Si hay diferencial, indica no condensables y activa la purga automáticamente." },
  { id:"ns_0170", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 120 PSI y el compresor está caliente. ¿Qué falta?", opciones:["Sobrecalentamiento correcto para enfriar el motor del compresor.", "Más refrigerante para subir la presión de succión a 150 PSI nominal.", "Un ventilador de condensador más potente para bajar la temperatura.", "Aceite lubricante en el cárter para reducir la fricción de los pistones."], respuesta_correcta:0, explicacion:"Una succión de 120 PSI con R-410A equivale a ~38°F de saturación. Si el compresor está caliente, es porque no tiene suficiente sobrecalentamiento de gas frío para enfriar el motor interno. El refrigerante que regresa al compresor es lo que enfría los devanados." },
  { id:"ns_0171", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Overhead'. ¿Cuál de estas es una medida directa?", opciones:["Reducir el alquiler de la oficina o el personal administrativo no técnico.", "Bajar el precio de los filtros de aire que se venden a los clientes finales.", "Eliminar el uso de nitrógeno durante las soldaduras de las instalaciones.", "Aumentar la cuota de ventas de los técnicos para generar más ingresos brutos."], respuesta_correcta:0, explicacion:"El Overhead incluye costos indirectos como alquiler y personal administrativo; reducir estos gastos fijos no técnicos es la forma más directa de bajar el Overhead." },
  { id:"ns_0172", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no enciende y no hay códigos de error. ¿Qué revisa?", opciones:["El fusible de la unidad interior y el voltaje de llegada de la línea eléctrica.", "La carga de refrigerante por peso para descartar una fuga total de gas.", "Si el compresor está aterrizado midiendo la resistencia contra la carcasa.", "La placa electrónica de la unidad exterior por si hay rastros de quemaduras."], respuesta_correcta:0, explicacion:"Sin códigos de error, el sistema probablemente no recibe energía. El Senior revisa primero el fusible de la placa interior y confirma que llegan 240VAC, ya que sin alimentación no hay diagnóstico electrónico posible." },
  { id:"ns_0173", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un ruido de soplido constante en la inversora. ¿Causa?", opciones:["Fuga interna de gas de la descarga hacia la succión a través de la válvula.", "El refrigerante líquido está pasando por la válvula a una velocidad alta.", "La bobina de la solenoide está vibrando contra el cuerpo de la válvula.", "Es un sonido normal del flujo de refrigerante en sistemas de alta capacidad."], respuesta_correcta:0, explicacion:"Un ruido de soplido constante en la valvula inversora indica fuga interna. El gas de alta presion (descarga) pasa hacia el lado de baja presion (succion), reduciendo la eficiencia y causando el ruido caracteristico." },
  { id:"ns_0174", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿cuál es la función de la válvula 'Holdback' o de presión de condensación?", opciones:["Mantener una presión mínima en el condensador durante climas muy fríos.", "Evitar que el líquido regrese al separador de aceite durante el deshielo.", "Regular el flujo de refrigerante hacia los evaporadores de baja temperatura.", "Proteger al recibidor de una sobrepresión causada por una falla del ventilador."], respuesta_correcta:0, explicacion:"La válvula holdback mantiene una presión mínima de condensación en climas fríos. Sin ella, la presión de descarga bajaría tanto que las válvulas de expansión no tendrían suficiente diferencial de presión para alimentar líquido a los evaporadores." },
  { id:"ns_0175", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior recibe una llamada de un técnico Junior que está perdido. ¿Acción?", opciones:["Guiarlo paso a paso por teléfono usando un proceso de diagnóstico lógico.", "Decirle que lea el manual y que no lo llame hasta que tenga una solución.", "Ir personalmente al sitio y hacer el trabajo por el Junior para ahorrar tiempo.", "Decirle al cliente que el Junior no sabe y que enviará a otra persona después."], respuesta_correcta:0, explicacion:"Guiar al Junior por teléfono con un proceso lógico de diagnóstico desarrolla sus habilidades mientras resuelve el problema del cliente. Es la mejor combinación de mentoría, eficiencia y servicio profesional." },
  { id:"ns_0176", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un approach de condensador de 15°F. ¿Qué hace el Senior?", opciones:["Programar una limpieza mecánica de los tubos del condensador de inmediato.", "Agregar refrigerante hasta que el approach baje a los 2 grados nominales.", "Aumentar la velocidad de la bomba de agua para mejorar la transferencia.", "Ignorar el valor si la temperatura de salida del agua helada es la correcta."], respuesta_correcta:0, explicacion:"Un approach de condensador de 15°F (normal es 2-5°F) indica tubos sucios con fouling severo que reduce drásticamente la transferencia de calor. Se requiere limpieza mecánica inmediata." },
  { id:"ns_0177", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 100 PSI y descarga de 450 PSI con R-410A. ¿Problema?", opciones:["Restricción en la línea de líquido o condensador extremadamente sucio.", "Falta de refrigerante líquido en el sistema para enfriar el evaporador.", "Válvula de expansión (TXV) bloqueada en la posición de abierta total.", "Compresor perdiendo eficiencia volumétrica por desgaste de los pistones."], respuesta_correcta:0, explicacion:"Succión de 100 PSI (baja) con descarga de 450 PSI (muy alta) indica una restricción en el lado de alta que impide el flujo normal de refrigerante. Esto puede ser una restricción en la línea de líquido o un condensador extremadamente sucio que no disipa el calor." },
  { id:"ns_0178", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el ventilador de condensador no para nunca. ¿Qué revisa?", opciones:["El contactor del ventilador que está pegado mecánicamente o soldado.", "El termostato de la zona que está configurado en modo 'Fan ON' siempre.", "La placa de control que tiene un sensor de temperatura de ambiente roto.", "La carga de refrigerante que es tan alta que mantiene el switch de alta activo."], respuesta_correcta:0, explicacion:"Si el ventilador del condensador no se detiene nunca, la causa directa más probable es un contactor con los contactos soldados (pegados). Esto mantiene el circuito cerrado permanentemente, independientemente de la señal de control." },
  { id:"ns_0179", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere comprar otra empresa HVAC. ¿Qué es lo primero que audita?", opciones:["La rentabilidad real y la calidad de los contratos de servicio existentes.", "El estado físico de las camionetas y las herramientas de los técnicos.", "El diseño del logotipo y la presencia de la marca en los medios locales.", "La cantidad de empleados que tienen más de 5 años trabajando en el sitio."], respuesta_correcta:0, explicacion:"Al adquirir otra empresa HVAC, lo primero que se audita es la rentabilidad real y la calidad de los contratos de servicio existentes, ya que determinan el valor verdadero del negocio." },
  { id:"ns_0180", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Qué precaución toma el Senior al cargar gas?", opciones:["Cargar siempre en estado líquido para evitar el fraccionamiento de la mezcla.", "Cargar en estado gaseoso para no dañar las válvulas de los compresores.", "Utilizar aceite mineral para asegurar que el refrigerante sea miscible.", "No cargar más de 50 libras a la vez para evitar picos de presión alta."], respuesta_correcta:0, explicacion:"El R-448A es una mezcla zeotrópica de múltiples componentes con diferentes puntos de ebullición. Si se carga en fase gaseosa, los componentes más volátiles salen primero del cilindro, alterando la composición. Cargar en líquido mantiene la mezcla intacta." },
  { id:"ns_0181", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Reversal'. ¿Qué sucede si se ignora?", opciones:["El compresor girará al revés y no bombeará aceite ni refrigerante líquido.", "La unidad funcionará al 50% de su capacidad nominal debido al desfase.", "El motor se quemará instantáneamente al intentar vencer la inercia de carga.", "Las válvulas de expansión se cerrarán por seguridad al detectar el error."], respuesta_correcta:0, explicacion:"La inversión de fases causa que el compresor gire al revés, impidiendo el bombeo de aceite a los cojinetes y la circulación de refrigerante. Esto causa daño mecánico inmediato por falta de lubricación." },
  { id:"ns_0182", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["El drenaje tiene una contrapendiente o está parcialmente obstruido arriba.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido.", "La humedad en la habitación es superior al 90% y satura el serpentín."], respuesta_correcta:0, explicacion:"Si el goteo ocurre solo cuando el compresor para, el agua acumulada durante la operación no drena correctamente. Una contrapendiente o obstrucción parcial alta en el tubo de drenaje retiene agua que se libera al cesar la vibración." },
  { id:"ns_0183", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene un 'Static Pressure' de 0.9 en el suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en los conductos de suministro o difusores cerrados.", "Los conductos de retorno son demasiado pequeños para el volumen de aire.", "El filtro de aire está completamente tapado y no deja pasar el flujo.", "El motor del soplador está girando en sentido contrario al de diseño."], respuesta_correcta:0, explicacion:"Una presión estática de 0.9\" en suministro versus solo 0.2\" en retorno indica que la mayor parte de la restricción está en el lado de suministro. Conductos de suministro subdimensionados, aplastados o difusores cerrados causan esta distribución desproporcionada de presión." },
  { id:"ns_0184", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre los 20°F y 30°F.", "Sí, las bombas de calor siempre tienen un diferencial menor que los hornos.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en modo calor es insuficiente. Lo normal es 20-30F. Un diferencial bajo indica problemas como falta de refrigerante, flujo de aire excesivo, o absorcion deficiente de calor exterior." },
  { id:"ns_0185", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar una prueba de acidez del aceite y usar filtros de succión de limpieza.", "Añadir un aditivo sellador de fugas para prevenir fallas futuras en las líneas.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.", "Aumentar la carga de refrigerante un 5% para ayudar a enfriar el motor nuevo."], respuesta_correcta:0, explicacion:"Tras una quemadura de compresor, el aceite se descompone y genera ácidos que contaminan todo el sistema. La prueba de acidez confirma el nivel de contaminación, y los filtros de succión de limpieza atrapan residuos para proteger el compresor nuevo." },
  { id:"ns_0186", categoria:"NATE_SR_PACKAGE", pregunta:"En un Rooftop, el economizador parpadea con un código de 'Enthalpy sensor fault'. ¿Qué hace?", opciones:["El economizador operará basado solo en la temperatura de bulbo seco.", "El economizador se cerrará completamente para evitar aire húmedo fuera.", "Los compresores se bloquearán hasta que el sensor sea reemplazado hoy.", "El sistema usará el sensor de aire de retorno como referencia temporal."], respuesta_correcta:0, explicacion:"La mayoría de controladores de economizador modernos tienen un modo de respaldo (fallback). Cuando el sensor de entalpía falla, el sistema degrada a control por temperatura de bulbo seco solamente, permitiendo operación continua con menor eficiencia pero sin detener el equipo." },
  { id:"ns_0187", categoria:"NATE_SR_RACK", pregunta:"Un rack de baja temperatura tiene una presión de succión muy inestable. ¿Qué revisa?", opciones:["La configuración de los pasos de capacidad de los compresores (steps).", "Si el separador de aceite está retornando aceite de forma intermitente.", "La carga de refrigerante que podría estar en el límite de la burbuja.", "Si las válvulas solenoide de las vitrinas están ciclando por temperatura."], respuesta_correcta:0, explicacion:"Una presión de succión inestable en un rack generalmente indica que los pasos de capacidad (compresores entrando/saliendo) están mal configurados. Un diferencial insuficiente o steps demasiado agresivos causan oscilaciones constantes de presión." },
  { id:"ns_0188", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar la reputación en línea. ¿Qué estrategia es la más orgánica?", opciones:["Pedir a los técnicos que soliciten una reseña al terminar un trabajo exitoso.", "Pagar a una agencia externa para que genere reseñas positivas artificiales.", "Ofrecer un descuento en la factura a cambio de una calificación de 5 estrellas.", "Responder solo a las reseñas negativas para tratar de que el cliente las borre."], respuesta_correcta:0, explicacion:"Pedir reseñas orgánicas a clientes satisfechos al terminar un trabajo exitoso es la estrategia más auténtica y sostenible para mejorar la reputación en línea." },
  { id:"ns_0189", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo usa R-134a. ¿Por qué no necesita unidad de purga?", opciones:["Porque opera a presión positiva y el aire no puede entrar al sistema.", "Porque el R-134a absorbe el aire y lo mezcla con el aceite lubricante.", "Porque el compresor centrífugo destruye las burbujas de aire al girar.", "Porque la temperatura del evaporador nunca baja del punto de congelación."], respuesta_correcta:0, explicacion:"El R-134a opera a presión positiva en todo el sistema (evaporador y condensador). Al no tener presiones de vacío, el aire exterior no puede infiltrarse, eliminando la necesidad de unidad de purga." },
  { id:"ns_0190", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene un sobrecalentamiento de 30°F y subenfriamiento de 15°F. ¿Diagnóstico?", opciones:["Restricción en el dispositivo de expansión o filtro deshidratador sucio.", "Falta de carga de refrigerante que afecta la saturación del evaporador.", "Exceso de carga de refrigerante que inunda el condensador exterior.", "Falla del ventilador interior que reduce la carga térmica en el sistema."], respuesta_correcta:0, explicacion:"Un sobrecalentamiento alto de 30°F indica insuficiente refrigerante en el evaporador, mientras que un subenfriamiento de 15°F es aceptable. La combinación apunta a una restricción en el dispositivo de expansión o filtro deshidratador que impide el paso adecuado de refrigerante líquido." },
  { id:"ns_0191", categoria:"NATE_SR_CEO", pregunta:"Un CEO decide implementar un 'Tool Account' para sus técnicos. ¿Cuál es el beneficio?", opciones:["Asegurar que los técnicos tengan herramientas propias y las cuiden mejor.", "Reducir el gasto de la empresa en herramientas básicas que se pierden.", "Permitir que el técnico compre herramientas de lujo con su propio dinero.", "Deducir el costo de las herramientas de los impuestos corporativos anuales."], respuesta_correcta:0, explicacion:"El Tool Account incentiva al técnico a poseer y mantener sus propias herramientas en buen estado, lo que aumenta su responsabilidad y reduce pérdidas o descuido." },
  { id:"ns_0192", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF tiene un ruido de expansión fuerte en las unidades interiores. ¿Causa?", opciones:["Falta de carga de refrigerante que causa vapor en la línea de líquido.", "La placa de control está moviendo la EEV demasiado rápido entre pasos.", "El aceite del sistema es demasiado espeso y causa fricción en la válvula.", "Es un comportamiento normal cuando el sistema opera a máxima frecuencia."], respuesta_correcta:0, explicacion:"Un ruido de expansión (hissing) fuerte en unidades interiores VRF indica falta de carga de refrigerante, lo que genera burbujas de vapor (flash gas) en la línea de líquido antes de la válvula de expansión." },
  { id:"ns_0193", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor geotérmica tiene una falla de 'High Pressure'. El lazo es abierto. ¿Causa?", opciones:["Incrustaciones de minerales en el intercambiador de calor de agua/gas.", "La bomba del pozo se detuvo o el filtro de sedimentos está obstruido.", "La temperatura del subsuelo ha subido por encima de los 80 grados F.", "Hay una fuga de refrigerante hacia el agua del pozo por una ruptura."], respuesta_correcta:0, explicacion:"En un sistema geotermico de lazo abierto, las incrustaciones minerales del agua del pozo reducen la transferencia de calor en el intercambiador, elevando la presion de descarga hasta disparar el switch de alta presion." },
  { id:"ns_0194", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si la válvula diferencial de aceite está mal ajustada (muy alta)?", opciones:["Se inyecta demasiado aceite al cárter y puede causar daños mecánicos.", "No habrá suficiente presión para que el aceite regrese a los compresores.", "El separador de aceite se desbordará hacia la línea de descarga del rack.", "La temperatura del aceite bajará por debajo del punto de lubricación."], respuesta_correcta:0, explicacion:"Una válvula diferencial ajustada muy alta permite un flujo excesivo de aceite hacia los cárteres. El exceso de aceite puede causar golpe de líquido hidráulico, daño en las válvulas de plato, y problemas mecánicos en los compresores." },
  { id:"ns_0195", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior detecta un error de diseño en un plano de conductos. ¿Qué hace?", opciones:["Notificar al ingeniero de diseño y sugerir una corrección basada en campo.", "Instalar el sistema como dice el plano para no tener responsabilidad legal.", "Corregir el diseño por su cuenta sin avisar a nadie para terminar rápido.", "Decirle al cliente que el ingeniero no sabe nada y que él lo hará mejor."], respuesta_correcta:0, explicacion:"Notificar al ingeniero mantiene la comunicación profesional y la cadena de responsabilidad. El técnico Senior aporta experiencia de campo valiosa, pero los cambios de diseño deben ser aprobados por el ingeniero responsable del proyecto." },
  { id:"ns_0196", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que expulsa refrigerante líquido. ¿Qué componente falló?", opciones:["La válvula de flotador o el orificio de separación de la unidad de purga.", "El compresor centrífugo que está enviando líquido hacia el condensador.", "El sensor de presión de la purga que está enviando una señal errónea.", "El calentador de la purga que no está evaporando el líquido recolectado."], respuesta_correcta:0, explicacion:"La válvula de flotador de la purga controla la separación entre líquido y gas. Si falla, permite que refrigerante líquido pase directamente a la salida de la purga en vez de solo gases." },
  { id:"ns_0197", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 115 PSI y descarga de 320 PSI con R-410A. ¿Cómo está?", opciones:["Funcionamiento normal para un día con temperatura exterior moderada.", "Falta de refrigerante líquido que impide que la descarga suba más.", "Evaporador sucio que reduce la presión de succión por debajo de 120.", "Compresor con desgaste moderado que aún mantiene el diferencial útil."], respuesta_correcta:0, explicacion:"Con R-410A, succión de 115 PSI (~36°F sat.) y descarga de 320 PSI (~90°F sat.) son valores normales para un día con temperatura exterior moderada (alrededor de 75-80°F). El diferencial de presión es adecuado y el sistema opera dentro de parámetros de diseño." },
  { id:"ns_0198", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el serpentín del evaporador se congela. El filtro está limpio. ¿Qué sigue?", opciones:["Verificar la velocidad del motor del soplador y la carga de refrigerante.", "Reemplazar la válvula de expansión térmica (TXV) por una nueva hoy.", "Instalar un termostato de descongelación para que pare el compresor.", "Agregar refrigerante hasta que la presión de succión suba a 130 PSI."], respuesta_correcta:0, explicacion:"Con filtro limpio, la congelación del evaporador se debe a flujo de aire insuficiente (motor lento, correa floja) o carga de refrigerante baja que reduce la presión/temperatura de evaporación por debajo de 32°F. Ambas causas deben verificarse antes de reemplazar componentes." },
  { id:"ns_0199", categoria:"NATE_SR_CEO", pregunta:"Un CEO debe cumplir con la ley FLSA (Fair Labor Standards Act). ¿Qué regula?", opciones:["El pago de horas extras y el salario mínimo para los empleados técnicos.", "La seguridad de los técnicos en el sitio de trabajo y el uso de EPP.", "La certificación de los equipos HVAC según su eficiencia energética.", "El manejo y disposición final de los refrigerantes usados en el campo."], respuesta_correcta:0, explicacion:"La FLSA (Fair Labor Standards Act) regula el pago de salario mínimo y horas extras obligatorias; su incumplimiento expone a la empresa a demandas colectivas costosas." },
  { id:"ns_0200", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-407A. El técnico mezcla con R-404A por error. ¿Consecuencia?", opciones:["La relación presión/temperatura será impredecible y el sistema fallará.", "El sistema funcionará bien ya que ambos refrigerantes son del tipo HFC.", "La eficiencia aumentará un 5% pero el compresor hará un poco más de ruido.", "El aceite se separará del refrigerante y los compresores se bloquearán."], respuesta_correcta:0, explicacion:"Mezclar dos refrigerantes diferentes crea una mezcla desconocida con propiedades termodinámicas impredecibles. La relación presión/temperatura cambia, los controles no pueden calibrarse, y el sistema opera de forma errática y eventualmente falla." },
  { id:"ns_0201", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta una caída de presión excesiva en el evaporador, pero el flujo de agua es nominal. ¿Cuál es la sospecha del Senior?", opciones:["Obstrucción parcial en el cedazo (strainer) de entrada o tubos con lodo.", "La bomba de agua helada está girando a más RPM de las que indica la placa.", "El refrigerante está inundando los tubos superiores del intercambiador.", "Las válvulas de mariposa de aislamiento están vibrando por turbulencia."], respuesta_correcta:0, explicacion:"Con flujo de agua nominal, una caída de presión excesiva en el evaporador indica obstrucción parcial en el cedazo (strainer) de entrada o acumulación de lodo en los tubos del intercambiador." },
  { id:"ns_0202", categoria:"NATE_SR_RACK", pregunta:"En un sistema de rack paralelo, ¿qué fenómeno ocurre si la presión del recibidor cae por debajo de la presión de diseño del líquido?", opciones:["Formación de gas flash en la línea de líquido que afecta a las vitrinas.", "Aumento súbito del nivel de aceite en el separador de descarga principal.", "Cierre automático de todas las válvulas de expansión por falta de flujo.", "El subenfriamiento aumenta drásticamente para compensar la baja presión."], respuesta_correcta:0, explicacion:"Cuando la presión del recibidor baja demasiado, el refrigerante líquido pierde subenfriamiento y se forma gas flash en la línea de líquido. Esto reduce el flujo efectivo de líquido a las vitrinas y causa problemas de alimentación en las TXV." },
  { id:"ns_0203", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC analiza el 'Break-Even Point'. Si los costos fijos suben, ¿qué debe suceder para mantener la misma utilidad?", opciones:["El volumen de ventas debe aumentar o el margen de contribución subir.", "El costo de la mano de obra directa debe incrementarse proporcionalmente.", "La empresa debe reducir el precio de sus servicios para ser más competitiva.", "Los activos fijos deben venderse para capitalizar la operación de campo."], respuesta_correcta:0, explicacion:"Si los costos fijos suben, la empresa necesita vender más unidades o aumentar el margen de contribución por unidad para alcanzar y superar el punto de equilibrio." },
  { id:"ns_0204", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF muestra un error de 'Suction Pipe Thermistor'. El sensor mide 10k Ohms a 77°F. ¿Cuál es la conclusión?", opciones:["El sensor está en buen estado; el problema reside en la placa o el cableado.", "El sensor está fuera de rango y debe reemplazarse por uno de 50k Ohms.", "Existe una fuga de refrigerante que está enfriando el sensor erráticamente.", "La unidad exterior está enviando un voltaje incorrecto al bus de sensores."], respuesta_correcta:0, explicacion:"Un termistor típico de 10k Ohms a 77°F (25°C) está dentro del rango normal. Si el sistema reporta error con un sensor en buen estado, el problema está en la placa de control o en el cableado entre el sensor y la placa." },
  { id:"ns_0205", categoria:"NATE_SR_HVAC", pregunta:"En un sistema con conductos, un valor de 'Static Pressure' de retorno de 0.8 pulg. W.C. indica generalmente que:", opciones:["El sistema de filtración es insuficiente o los conductos están mal diseñados.", "El motor del soplador tiene demasiada fuerza y está succionando aire de más.", "Las rejillas de suministro están cerradas y el aire rebota hacia el retorno.", "El serpentín del evaporador está limpio y permite un flujo de aire libre."], respuesta_correcta:0, explicacion:"Una presión estática de retorno de 0.8\" W.C. es excesivamente alta y señala restricciones significativas en el lado de retorno. Filtros insuficientes, conductos de retorno subdimensionados o mal diseñados crean esta restricción que reduce el flujo total de aire del sistema." },
  { id:"ns_0206", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor activa las resistencias de apoyo innecesariamente. ¿Qué ajuste Senior es el primero?", opciones:["Verificar el 'Outdoor Ambient Lockout' y el diferencial del termostato.", "Cambiar el contactor de las resistencias por uno de menor amperaje total.", "Aumentar la carga de refrigerante para que el compresor genere más calor.", "Desconectar físicamente el cable 'W' del termostato durante el invierno."], respuesta_correcta:0, explicacion:"El outdoor ambient lockout impide que las resistencias se activen por encima de cierta temperatura exterior. Si esta mal configurado, las resistencias se encienden innecesariamente, desperdiciando energia." },
  { id:"ns_0207", categoria:"NATE_SR_MANAGEMENT", pregunta:"Al supervisar una instalación, nota que no usan un torque de apriete específico en las tuercas flare. ¿Cuál es el riesgo?", opciones:["Fugas de refrigerante por deformación del cobre o por falta de sello.", "Aumento del ruido por vibración mecánica en las líneas de interconexión.", "Pérdida de la garantía del fabricante solo si el equipo deja de enfriar.", "Dificultad para remover la unidad en el futuro si se requiere un servicio."], respuesta_correcta:0, explicacion:"Un torque insuficiente no sella correctamente la conexión flare, causando fugas lentas. Un torque excesivo deforma el cobre y rompe el sello. Usar torquímetro con las especificaciones del fabricante garantiza conexiones herméticas." },
  { id:"ns_0208", categoria:"NATE_SR_PACKAGE", pregunta:"Un Rooftop de 25 toneladas tiene un motor de soplador que quema fusibles al arrancar. ¿Qué prueba mecánica hace?", opciones:["Verificar la tensión de las correas y el estado de los rodamientos del eje.", "Cambiar el capacitor de arranque aunque el motor sea del tipo trifásico.", "Aumentar el tamaño de los fusibles para permitir el pico de corriente inicial.", "Medir el voltaje en el secundario del transformador de control de 24V."], respuesta_correcta:0, explicacion:"Un motor que quema fusibles al arrancar indica excesiva corriente de rotor bloqueado. La causa mecánica más común es una correa demasiado tensa o rodamientos del eje dañados que impiden el giro libre del motor, aumentando el amperaje de arranque más allá del límite del fusible." },
  { id:"ns_0209", categoria:"NATE_SR_RACK", pregunta:"En un rack con CO2 transcrítico, ¿cuál es la función de la válvula 'Flash Gas Bypass'?", opciones:["Controlar la presión del recibidor enviando el exceso de gas a la succión.", "Inyectar refrigerante líquido en la descarga para bajar la temperatura total.", "Evacuar el aceite atrapado en el gas-cooler hacia el cárter de los compresores.", "Regular el flujo de gas hacia las vitrinas de baja temperatura en el sistema."], respuesta_correcta:0, explicacion:"En un sistema CO2 transcrítico, al expandir el fluido supercrítico se genera gas flash en el recibidor. La válvula de flash gas bypass envía ese exceso de gas a la succión, controlando la presión del recibidor y mejorando la eficiencia." },
  { id:"ns_0210", categoria:"NATE_SR_CEO", pregunta:"Un CEO implementa un sistema de 'Flat Rate Pricing'. ¿Cuál es el beneficio para el cliente final?", opciones:["Conocer el costo total del servicio antes de que se realice cualquier reparación.", "Pagar menos por hora de trabajo si el técnico es más lento que el promedio.", "Garantizar que solo se utilicen piezas de la marca original en su equipo HVAC.", "Recibir una auditoría de eficiencia energética gratuita con cada llamada de servicio."], respuesta_correcta:0, explicacion:"El Flat Rate Pricing permite al cliente conocer el costo total antes de aprobar la reparación, eliminando la incertidumbre y generando confianza en la transparencia del servicio." },
  { id:"ns_0211", categoria:"NATE_SR_CHILLERS", pregunta:"Se detecta presencia de agua en el refrigerante de un chiller. ¿Cuál es la consecuencia química?", opciones:["Formación de ácidos corrosivos que atacan el barniz de los devanados del motor.", "Aumento de la capacidad frigorífica debido a la mayor densidad de la mezcla.", "Reducción de la presión de condensación por el efecto de enfriamiento del agua.", "Mejora en la lubricación de los cojinetes al reducir la viscosidad del aceite."], respuesta_correcta:0, explicacion:"El agua en el refrigerante reacciona con el aceite y el refrigerante a altas temperaturas, formando ácidos corrosivos (HCl, HF) que atacan el barniz aislante de los devanados del motor del compresor." },
  { id:"ns_0212", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial con TXV presenta 'hunting' (oscilación de presión). ¿Cuál es el ajuste Senior?", opciones:["Verificar la ubicación y el aislamiento térmico del bulbo sensor de la válvula.", "Cerrar la válvula de expansión dos vueltas para reducir el flujo de líquido.", "Cambiar el filtro de aire por uno de mayor restricción para estabilizar la carga.", "Purgar un poco de refrigerante para reducir la presión en el lado de alta."], respuesta_correcta:0, explicacion:"El 'hunting' de una TXV generalmente se debe a una mala ubicación o falta de aislamiento del bulbo sensor. Si el bulbo no hace buen contacto con la línea de succión o está expuesto a temperaturas ambientales, lee señales erráticas que causan la oscilación de apertura/cierre." },
  { id:"ns_0213", categoria:"NATE_SR_CEO", pregunta:"Para reducir los accidentes laborales, un CEO debe enfocarse en:", opciones:["La cultura de seguridad proactiva y el entrenamiento constante en procesos.", "Sancionar económicamente a cada técnico que sufra un percance en el campo.", "Comprar solo herramientas manuales para evitar el uso de electricidad en obra.", "Reducir las horas de trabajo para que los técnicos no sufran de fatiga crónica."], respuesta_correcta:0, explicacion:"Una cultura de seguridad proactiva con entrenamiento constante previene accidentes desde la raíz; las sanciones solo generan ocultamiento de incidentes sin resolver el problema." },
  { id:"ns_0214", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema Multi-split tiene una fuga de aceite en una tuerca flare, pero no hay fuga de gas. ¿Es posible?", opciones:["No, si hay fuga de aceite, la presión del refrigerante forzosamente escapará.", "Sí, es una señal de que el sistema tiene un exceso de lubricante acumulado.", "Sí, ocurre cuando el sistema está apagado y el aceite se asienta en la junta.", "No, el aceite solo sale si el refrigerante actúa como vehículo de transporte."], respuesta_correcta:0, explicacion:"Si hay fuga de aceite en una tuerca flare, el refrigerante presurizado también escapará ya que el aceite viaja mezclado con el gas. No puede haber fuga de aceite sin fuga de refrigerante en un sistema presurizado." },
  { id:"ns_0215", categoria:"NATE_SR_RACK", pregunta:"En un rack con descongelación por aire (Off-cycle), ¿cuál es el parámetro crítico para el Senior?", opciones:["La duración del ciclo debe ser suficiente para derretir el hielo por aire ambiente.", "La presión de descarga debe subir para calentar indirectamente los evaporadores.", "Los ventiladores del evaporador deben apagarse para evitar el choque térmico.", "La válvula de expansión debe permanecer abierta para mantener el flujo interno."], respuesta_correcta:0, explicacion:"En descongelación off-cycle, el evaporador se apaga y el hielo se derrite con el aire ambiente de la vitrina. El parámetro crítico es que la duración del ciclo sea suficiente para completar el deshielo antes de que la temperatura del producto suba demasiado." },
  { id:"ns_0216", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 5 toneladas muestra un sobrecalentamiento de 45°F. ¿Qué indica?", opciones:["Una falta severa de refrigerante o una restricción en el dispositivo de expansión.", "Que el serpentín del evaporador está inundado de líquido y no hay intercambio.", "Un exceso de carga de refrigerante que está regresando al compresor sin gas.", "Que el motor del ventilador del condensador está girando a demasiadas RPM."], respuesta_correcta:0, explicacion:"Un sobrecalentamiento de 45°F (normal es 8-14°F) significa que el refrigerante se evaporó mucho antes de llegar al final del serpentín. Esto indica falta severa de refrigerante (fuga) o una restricción en la TXV/pistón que no permite suficiente flujo de líquido al evaporador." },
  { id:"ns_0217", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Junior rompe una pieza costosa por descuido. ¿Cómo debe manejarlo el Senior?", opciones:["Explicar el error, mostrar la forma correcta y documentar para capacitación futura.", "Obligar al Junior a pagar la pieza con su salario para que aprenda la lección.", "Ocultar el error al cliente y a la gerencia para proteger al equipo de trabajo.", "Hacer que el Junior trabaje horas extra sin pago hasta compensar el costo real."], respuesta_correcta:0, explicacion:"El liderazgo efectivo transforma errores en oportunidades de aprendizaje. Explicar qué salió mal, mostrar la técnica correcta y documentar el incidente mejora las habilidades del equipo y previene que el error se repita." },
  { id:"ns_0218", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller enfriado por agua, el approach del evaporador sube de 2°F a 10°F. ¿Qué hace?", opciones:["Realizar una limpieza química o mecánica de los tubos del evaporador de inmediato.", "Agregar más refrigerante líquido para cubrir más superficie de tubos internos.", "Aumentar el flujo de agua helada mediante el ajuste del variador de la bomba.", "Reducir el set-point de temperatura para forzar una mayor transferencia térmica."], respuesta_correcta:0, explicacion:"Un aumento del approach del evaporador de 2°F a 10°F indica fouling significativo en los tubos que reduce la transferencia térmica. Se requiere limpieza química o mecánica inmediata." },
  { id:"ns_0219", categoria:"NATE_SR_HEATPUMP", pregunta:"Un sistema de bomba de calor tiene un acumulador de succión. ¿Cuándo es más probable que actúe?", opciones:["Al final del ciclo de deshielo cuando el líquido regresa bruscamente al compresor.", "Durante los días más calurosos del verano cuando la presión de alta es máxima.", "Cuando el termostato cambia de modo calor a modo frío en menos de un minuto.", "Cuando las resistencias eléctricas se activan para ayudar al compresor en carga."], respuesta_correcta:0, explicacion:"El acumulador actua principalmente al terminar el defrost, cuando la valvula inversora cambia de refrigeracion a calefaccion. En ese momento, el refrigerante liquido puede regresar bruscamente hacia el compresor." },
  { id:"ns_0220", categoria:"NATE_SR_CEO", pregunta:"Para maximizar el 'Net Profit', un CEO debe priorizar:", opciones:["La eficiencia operativa y la reducción de callbacks o re-visitas técnicas.", "La compra de las camionetas más lujosas para proyectar una imagen de éxito.", "Aumentar el número de empleados sin importar la carga de trabajo actual.", "Reducir drásticamente los precios para eliminar a todos los competidores locales."], respuesta_correcta:0, explicacion:"La eficiencia operativa y la eliminación de callbacks reducen costos directos sin sacrificar ingresos, siendo la vía más sólida para maximizar el Net Profit de la empresa." },
  { id:"ns_0221", categoria:"NATE_SR_RACK", pregunta:"Se observa aceite en el visor de la línea de succión de un rack. ¿Qué indica al Senior?", opciones:["Velocidad de gas adecuada para el retorno de aceite desde los evaporadores.", "Falla en el separador de aceite que permite el paso hacia el lado de baja.", "Nivel excesivo de aceite en el cárter del compresor de la etapa de alta.", "Obstrucción en el cedazo de la línea de retorno de aceite hacia el depósito."], respuesta_correcta:0, explicacion:"Ver aceite fluyendo en la mirilla de succión indica que la velocidad del gas es suficiente para arrastrar el aceite de regreso desde los evaporadores. Es una señal positiva de que el retorno de aceite está funcionando correctamente." },
  { id:"ns_0222", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema inverter reporta error de comunicación (E6/U4). ¿Qué voltaje busca entre S2 y S3?", opciones:["Un voltaje DC pulsante que fluctúa rápidamente entre 0V y 24V (aprox).", "Un voltaje AC constante de 24V proveniente del transformador de control.", "Un voltaje DC estable de exactamente 5V para alimentar los microchips.", "Cero voltios, ya que la comunicación es por frecuencia y no por voltaje."], respuesta_correcta:0, explicacion:"La comunicación entre unidades en sistemas inverter utiliza señales DC pulsantes que fluctúan rápidamente entre 0V y ~24V para transmitir datos. Un voltaje constante indicaría fallo de comunicación." },
  { id:"ns_0223", categoria:"NATE_SR_HVAC", pregunta:"Un motor de soplador ECM está 'haciendo hunting' (sube y baja RPM). ¿Cuál es la causa?", opciones:["Alta presión estática o restricciones severas en el sistema de conductos.", "El termostato está enviando señales contradictorias de velocidad a la placa.", "El capacitor de marcha está fallando y no mantiene el torque del motor.", "La humedad en el aire está afectando los sensores magnéticos internos del ECM."], respuesta_correcta:0, explicacion:"Los motores ECM están diseñados para mantener un flujo de aire constante (CFM). Cuando la presión estática es alta, el ECM aumenta sus RPM para compensar, pero al alcanzar su límite y no poder mantener el flujo, comienza a oscilar entre diferentes velocidades (hunting)." },
  { id:"ns_0224", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con R-134a tiene una presión de succión de 35 PSI. ¿Cuál es el riesgo?", opciones:["Congelación de los tubos del evaporador ya que la saturación está bajo 32°F.", "Sobrecalentamiento del motor por falta de masa de refrigerante para enfriarlo.", "Falla mecánica por falta de lubricación al no haber suficiente arrastre de aceite.", "Aumento excesivo del consumo eléctrico al intentar comprimir gas muy ralo."], respuesta_correcta:0, explicacion:"A 35 PSI de succión, la temperatura de saturación del R-134a está por debajo de 32°F (punto de congelación del agua), creando riesgo de congelación de los tubos del evaporador." },
  { id:"ns_0225", categoria:"NATE_SR_CEO", pregunta:"Al analizar el 'Cost Per Lead' (CPL), un CEO nota que las redes sociales son baratas pero no cierran ventas. ¿Acción?", opciones:["Reevaluar el 'Targeting' o mejorar el proceso de calificación de prospectos.", "Triplicar la inversión en redes sociales para forzar estadísticamente una venta.", "Cerrar todas las cuentas de redes sociales y volver a los anuncios impresos.", "Culpar al departamento de ventas por no saber convencer a los seguidores."], respuesta_correcta:0, explicacion:"Si las redes sociales generan leads baratos pero no cierran ventas, el problema está en el targeting o en el proceso de calificación de prospectos, no en el canal en sí." },
  { id:"ns_0226", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calefacción, una bomba de calor tiene un subenfriamiento de 30°F. ¿Qué indica?", opciones:["Sobrecarga de refrigerante o una restricción en la válvula de expansión interior.", "Falta de refrigerante que impide que el líquido se acumule en el condensador.", "Funcionamiento óptimo considerando las bajas temperaturas del aire exterior.", "Que la válvula inversora está desviando gas caliente directamente a la succión."], respuesta_correcta:0, explicacion:"Un subenfriamiento de 30F es excesivamente alto (lo normal es 8-15F). Indica sobrecarga de refrigerante que acumula demasiado liquido en el condensador, o una restriccion en la TXV que impide el flujo normal." },
  { id:"ns_0227", categoria:"NATE_SR_RACK", pregunta:"Un rack usa un controlador electrónico de aceite. Si el LED parpadea en rojo, ¿qué significa?", opciones:["Falla de lubricación detectada; el compresor será bloqueado por seguridad.", "El nivel de aceite está en el punto ideal y el sistema está en espera.", "El sistema está inyectando aceite activamente para recuperar el nivel nominal.", "El sensor de nivel está sucio y requiere limpieza manual con solvente POE."], respuesta_correcta:0, explicacion:"En controladores electrónicos de aceite, un LED rojo parpadeante indica una condición de falla de lubricación (oil failure). El controlador bloqueará el compresor después del tiempo de retardo programado para proteger los cojinetes y partes móviles." },
  { id:"ns_0228", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete industrial de 50 toneladas tiene un economizador que no abre. ¿Qué revisa?", opciones:["La señal de entalpía y el ajuste del set-point del controlador de aire exterior.", "La carga de refrigerante del circuito número uno que activa los dampers.", "La tensión de la correa del motor del soplador que genera la presión estática.", "El sensor de temperatura de descarga del compresor que bloquea el aire frío."], respuesta_correcta:0, explicacion:"Si el economizador no abre, lo primero es verificar la señal que recibe del sensor de entalpía exterior y el set-point del controlador. Si el sensor está mal calibrado o el set-point es demasiado bajo, el controlador nunca dará la orden de abrir el damper de aire exterior." },
  { id:"ns_0229", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un cliente afirma que el sistema nuevo gasta más luz que el viejo de hace 20 años. ¿Qué hace?", opciones:["Auditar el consumo real, revisar configuraciones y verificar el sellado de ductos.", "Decirle al cliente que es imposible y que su medidor de luz debe estar fallando.", "Cambiar el equipo por otro modelo sin realizar pruebas previas de diagnóstico.", "Explicar que los equipos modernos tardan más tiempo en enfriar por diseño SEER."], respuesta_correcta:0, explicacion:"Un equipo nuevo con SEER alto debería consumir menos. Si el cliente reporta lo contrario, hay que investigar: ductos con fugas, configuración incorrecta del termostato, problemas de carga, o carga térmica aumentada. La auditoría revela la causa real." },
  { id:"ns_0230", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo vibra violentamente al apagar. ¿Qué componente técnico previene daños graves por rotación inversa?", opciones:["La válvula de retención de descarga y el sistema de lubricación por inercia.", "El freno electromagnético integrado en el estator del motor del compresor.", "Los álabes de entrada que se cierran herméticamente al detectar el paro.", "El bypass de gas caliente que iguala las presiones de forma instantánea."], respuesta_correcta:0, explicacion:"La válvula de retención de descarga previene la rotación inversa del impulsor al apagar el chiller, mientras el sistema de lubricación por inercia mantiene aceite en los cojinetes durante la desaceleración." },
  { id:"ns_0231", categoria:"NATE_SR_RACK", pregunta:"En un rack, la válvula de presión diferencial de aceite está ajustada a 20 PSI, pero el compresor se apaga por 'Oil Trip'. ¿Qué revisa?", opciones:["La caída de presión en el filtro de aceite y la espuma en el cárter.", "El voltaje de alimentación del solenoide que inyecta aceite al sistema.", "Si el separador de aceite tiene el flotador perforado y se encuentra hundido.", "La calibración del transductor de presión de descarga del rack paralelo."], respuesta_correcta:0, explicacion:"Si el diferencial está bien ajustado pero hay oil trip, la presión neta de aceite se pierde por otro motivo. Un filtro de aceite tapado crea una caída de presión que reduce el diferencial efectivo, y espuma en el cárter (refrigerante disuelto) impide la lubricación correcta." },
  { id:"ns_0232", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC observa que el 'Gross Margin' es alto, pero el 'Net Profit' es negativo. ¿Dónde reside el problema?", opciones:["En los costos indirectos excesivos, como renta, administración o deudas.", "En que los técnicos están cobrando muy poco por las piezas de repuesto.", "En que el costo de los materiales ha subido drásticamente este trimestre.", "En que la empresa no está realizando suficientes llamadas de servicio."], respuesta_correcta:0, explicacion:"Si el Gross Margin es alto pero el Net Profit es negativo, los costos indirectos (renta, administración, intereses de deuda) están consumiendo toda la utilidad bruta." },
  { id:"ns_0233", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split presenta un error de 'Overcurrent' intermitente solo en días de calor extremo. ¿Qué causa Senior es probable?", opciones:["Aletas del condensador dobladas o sucias que elevan la presión de descarga.", "Una placa electrónica defectuosa que no modula la frecuencia correctamente.", "Cables de alimentación con un calibre inferior al requerido por la carga.", "Un compresor que tiene un desgaste mecánico interno en los rodamientos."], respuesta_correcta:0, explicacion:"En días de calor extremo, las aletas del condensador sucias o dobladas impiden la disipación de calor, elevando la presión de descarga y forzando al compresor a consumir más corriente, disparando la protección de sobrecorriente." },
  { id:"ns_0234", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial usa R-410A y tiene una succión de 160 PSI con 0°F de sobrecalentamiento. ¿Qué está ocurriendo?", opciones:["Inundación del evaporador por refrigerante líquido regresando al compresor.", "Una falta de carga que impide que el refrigerante se evapore totalmente.", "El motor del ventilador interior está girando a una velocidad excesiva.", "La válvula de expansión está bloqueada y no permite el paso de líquido."], respuesta_correcta:0, explicacion:"Una succión de 160 PSI con R-410A es alta (~52°F sat.) y un sobrecalentamiento de 0°F significa que no hay absorción de calor adicional después del evaporador. Esto indica que refrigerante líquido está regresando al compresor (flood-back), riesgo de daño mecánico por slugging." },
  { id:"ns_0235", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, la válvula inversora no cambia a modo calor. El técnico mide 24V en la solenoide. ¿Qué sigue?", opciones:["Verificar el diferencial de presión entre alta y baja para mover el pistón.", "Reemplazar el termostato asumiendo que la señal de 24V es de bajo amperaje.", "Golpear la válvula con un martillo para liberar el pistón interno trabado.", "Cambiar la placa de control exterior que activa el relé de la inversora."], respuesta_correcta:0, explicacion:"Si hay 24V en la solenoide pero la valvula no cambia, el problema es mecanico. Se debe verificar que exista suficiente diferencial de presion entre alta y baja para que la presion piloto mueva el piston principal." },
  { id:"ns_0236", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un líder nota que sus técnicos no están pesando la carga de refrigerante en sistemas críticos. ¿Cuál es la consecuencia?", opciones:["Baja eficiencia y posible daño al compresor por sobrecarga o falta de gas.", "Aumento en el tiempo de servicio sin una mejora real en el diagnóstico.", "Multas inmediatas por parte de la EPA al no usar básculas certificadas.", "Pérdida de la certificación NATE de los técnicos por malas prácticas."], respuesta_correcta:0, explicacion:"Los sistemas de carga crítica requieren la cantidad exacta de refrigerante especificada por el fabricante. Sobrecarga causa alta presión de descarga y daño al compresor; falta de gas causa sobrecalentamiento excesivo y lubricación deficiente." },
  { id:"ns_0237", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete industrial de 30 toneladas tiene compresores 'Tandem'. Si uno falla eléctricamente, ¿qué hace?", opciones:["Aislar el compresor fallido y verificar el nivel de aceite en el restante.", "Puentear el contactor para que ambos arranquen al mismo tiempo siempre.", "Cambiar ambos compresores ya que los circuitos de aceite están unidos.", "Reducir el flujo de aire del soplador para compensar la falta de capacidad."], respuesta_correcta:0, explicacion:"En compresores tandem que comparten circuito de aceite, cuando uno falla eléctricamente, se debe aislar para evitar que contamine al otro. Es crítico verificar el nivel de aceite del compresor operativo, ya que con un solo compresor funcionando la distribución de aceite cambia." },
  { id:"ns_0238", categoria:"NATE_SR_RACK", pregunta:"Se encuentra líquido en el cabezal de succión de un rack tras un deshielo. ¿Qué ajuste de control es necesario?", opciones:["Aumentar el tiempo de 'Pump Down' o de goteo antes de abrir la succión.", "Cerrar las válvulas de expansión de todas las vitrinas durante el defrost.", "Instalar un acumulador de succión tres veces más grande que el actual.", "Bajar el set-point de presión de succión del rack para evaporar el líquido."], respuesta_correcta:0, explicacion:"Tras un deshielo, el refrigerante condensado en el evaporador puede regresar como líquido. Aumentar el tiempo de pump-down o goteo (drip time) permite que el líquido se evapore dentro del evaporador antes de abrir la succión al rack." },
  { id:"ns_0239", categoria:"NATE_SR_CEO", pregunta:"Un CEO decide tercerizar el mantenimiento de la flota de vehículos. ¿Cuál es el objetivo estratégico?", opciones:["Eliminar costos fijos de taller y enfocar recursos en la actividad principal.", "Reducir el costo del combustible mediante el uso de aditivos especializados.", "Evitar que los técnicos pierdan tiempo limpiando sus propias camionetas.", "Incrementar el valor de reventa de los vehículos al tener sellos de agencia."], respuesta_correcta:0, explicacion:"Tercerizar el mantenimiento de flota elimina costos fijos de taller propio y permite que la empresa se enfoque en su actividad principal: servicios HVAC." },
  { id:"ns_0240", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una aproximación (approach) negativa del evaporador. ¿Cómo interpreta esto el Senior?", opciones:["Error de calibración en los sensores de temperatura o presión del sistema.", "Eficiencia de transferencia de calor superior a los límites físicos teóricos.", "El flujo de agua es tan alto que el sensor no alcanza a leer la realidad.", "El refrigerante está saliendo sobrecalentado antes de entrar al compresor."], respuesta_correcta:0, explicacion:"Un approach negativo del evaporador es físicamente imposible en condiciones normales. Esto siempre indica un error de calibración en los sensores de temperatura o presión del sistema." },
  { id:"ns_0241", categoria:"NATE_SR_HVAC", pregunta:"Se detecta un 'Voltage Imbalance' del 5% en un motor trifásico. ¿Cuál es el impacto técnico?", opciones:["Aumento drástico en la temperatura de los devanados y reducción de vida.", "El motor girará más rápido pero con un torque de arranque muy inferior.", "Los fusibles de una fase se quemarán constantemente por el bajo voltaje.", "El motor consumirá menos amperaje total al estar las fases desequilibradas."], respuesta_correcta:0, explicacion:"Un desbalance de voltaje del 5% en un motor trifásico causa un aumento de temperatura en los devanados de aproximadamente el 50% sobre lo normal. Este calor excesivo degrada rápidamente el aislamiento del motor, reduciendo dramáticamente su vida útil." },
  { id:"ns_0242", categoria:"NATE_SR_CEO", pregunta:"Al realizar trabajos en altura, un CEO debe asegurar que se use el sistema de protección contra caídas. ¿Cuándo es obligatorio?", opciones:["En cualquier borde no protegido que esté a 6 pies o más del nivel inferior.", "Solo cuando el técnico está trabajando directamente sobre una escalera.", "Cuando la velocidad del viento en el techo excede las 20 millas por hora.", "Únicamente si el cliente lo solicita explícitamente en el contrato de obra."], respuesta_correcta:0, explicacion:"OSHA exige protección contra caídas en cualquier borde no protegido a 6 pies (1.83m) o más del nivel inferior, siendo una de las normativas más estrictas en construcción." },
  { id:"ns_0243", categoria:"NATE_SR_MINISPLIT", pregunta:"Un VRF tiene una fuga de refrigerante y el sistema se bloquea. ¿Por qué no se debe usar detector de fugas de tinte?", opciones:["Puede dañar las válvulas de expansión electrónica y alterar el aceite POE.", "El tinte es invisible bajo las luces LED que usan los técnicos modernos.", "El costo del tinte es superior al costo de recuperar y recargar el sistema.", "Las normativas de la EPA prohíben el uso de tintes en sistemas Inverter."], respuesta_correcta:0, explicacion:"El tinte detector de fugas puede dañar las válvulas de expansión electrónica (EEV) de precisión y contaminar el aceite POE del sistema VRF, comprometiendo la lubricación del compresor." },
  { id:"ns_0244", categoria:"NATE_SR_RACK", pregunta:"Un rack de baja temperatura usa R-404A. Durante el servicio, el técnico encuentra un 'glide' significativo. ¿Qué hace?", opciones:["Recuperar la carga completa y cargar con refrigerante virgen en líquido.", "Completar la carga con R-404A en fase gaseosa para equilibrar la mezcla.", "Añadir solo R-125 al sistema para compensar la pérdida de presión alta.", "No hacer nada, ya que el glide es despreciable en sistemas de rack paralelo."], respuesta_correcta:0, explicacion:"Un glide significativo en R-404A indica fraccionamiento de la mezcla por fuga. La única solución correcta es recuperar toda la carga contaminada y recargar con refrigerante virgen en fase líquida para restaurar la composición original de la mezcla." },
  { id:"ns_0245", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete con gas, el inductor arranca pero no hay ignición. El switch de presión está cerrado. ¿Qué sigue?", opciones:["Verificar el ignitor y la placa de control para ver si envía los 120V.", "Reemplazar el motor del inductor asumiendo que no tiene suficiente fuerza.", "Limpiar el sensor de flama con una lija metálica de grano muy fino.", "Cerrar la llave de gas para evitar una acumulación peligrosa de combustible."], respuesta_correcta:0, explicacion:"Con el inductor funcionando y el switch de presión cerrado, la secuencia de ignición avanza al ignitor. Si no hay ignición, se debe verificar que la placa de control envía 120V al ignitor y que el ignitor no está fracturado o con alta resistencia. Sin ignitor funcional, la válvula de gas no abrirá." },
  { id:"ns_0246", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un sistema donde el cliente instaló su propio termostato 'Smart'. El sistema no enciende. ¿Causa?", opciones:["Falta del cable común (C) o daño en el fusible de 3A de la placa de control.", "Incompatibilidad del Wi-Fi de la casa con la frecuencia del compresor AC.", "El termostato requiere una actualización de software para leer los 24V.", "El cliente puenteó los terminales R y C quemando el transformador de 24V."], respuesta_correcta:0, explicacion:"Los termostatos inteligentes requieren el cable C (común) para alimentación continua. Sin este cable, el termostato no tiene suficiente energía. Además, una conexión incorrecta frecuentemente quema el fusible de 3A en la placa de control del equipo." },
  { id:"ns_0247", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Low Water Flow'. Se purga aire de la bomba y el flujo vuelve. ¿Qué causó el aire?", opciones:["Fuga en el sello de la bomba o nivel bajo en el tanque de expansión.", "El refrigerante se evaporó dentro de los tubos por una baja presión.", "La torre de enfriamiento está operando con una temperatura muy alta.", "La válvula de expansión está inyectando gas en lugar de líquido al sistema."], respuesta_correcta:0, explicacion:"El aire en el sistema de agua proviene de fugas en el sello de la bomba (que aspira aire al parar) o de un nivel bajo en el tanque de expansión que permite la entrada de aire al circuito." },
  { id:"ns_0248", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor geotérmica muestra baja presión de succión en modo frío. ¿Qué revisa en el lazo de agua?", opciones:["El flujo de agua de la bomba de circulación y la limpieza del filtro.", "La temperatura del aire de retorno en la manejadora de aire interior.", "Si el anticongelante (glicol) está degradado y ha perdido su viscosidad.", "La presión de nitrógeno en el tanque de expansión hidroneumático."], respuesta_correcta:0, explicacion:"En modo frio de una geotermica, baja succion indica mala absorcion de calor en el intercambiador agua-refrigerante. Lo primero es verificar el flujo de la bomba de circulacion y la limpieza del filtro de agua." },
  { id:"ns_0249", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Customer Churn'. ¿Qué métrica de servicio debe monitorear más?", opciones:["El tiempo de respuesta a emergencias y el índice de satisfacción (NPS).", "La cantidad de anuncios impresos en las revistas locales de decoración.", "El margen de ganancia por cada filtro de aire vendido en los contratos.", "La edad promedio de la flota de vehículos que visitan a los clientes."], respuesta_correcta:0, explicacion:"El tiempo de respuesta a emergencias y el NPS (Net Promoter Score) son indicadores directos de la satisfacción del cliente, y su deterioro es la causa principal del churn." },
  { id:"ns_0250", categoria:"NATE_SR_RACK", pregunta:"Se observa que un rack paralelo tiene una presión de descarga muy baja en invierno. ¿Por qué es un problema?", opciones:["Las válvulas de expansión no tendrán suficiente diferencial para alimentar líquido.", "El aceite se enfriará demasiado y se volverá sólido dentro del separador.", "Los compresores consumirán más energía al intentar subir la presión artificialmente.", "El recibidor de líquido se vaciará debido a la contracción del refrigerante."], respuesta_correcta:0, explicacion:"Una presión de descarga baja reduce el diferencial de presión disponible en las válvulas de expansión (TXV). Sin suficiente diferencial, las válvulas no pueden alimentar líquido adecuadamente a los evaporadores y las vitrinas pierden capacidad." },
  { id:"ns_0251", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller de tornillo tiene una falla de 'High Discharge Temp'. El aceite está negro. ¿Qué concluye el Senior?", opciones:["El aceite se ha carbonizado debido a temperaturas excesivas y falta de flujo.", "Es normal que el aceite POE cambie a color negro tras un año de operación.", "El filtro deshidratador está soltando partículas de carbón activado al sistema.", "El motor del compresor se quemó y el hollín contaminó todo el lubricante."], respuesta_correcta:0, explicacion:"El aceite negro indica carbonización por temperaturas excesivas y degradación térmica. Combinado con alta temperatura de descarga, confirma que el aceite ha sufrido descomposición química severa." },
  { id:"ns_0252", categoria:"NATE_SR_HVAC", pregunta:"Un técnico mide un 'Capacitor' de 35/5 MFD y obtiene 31/4. ¿Cuál es la decisión Senior?", opciones:["Reemplazarlo inmediatamente, ya que está fuera del 6% de tolerancia estándar.", "Dejarlo instalado hasta que el motor del compresor falle por completo.", "Añadir un capacitor de arranque en paralelo para compensar la pérdida.", "Limpiar los terminales del capacitor para ver si la lectura mejora."], respuesta_correcta:0, explicacion:"Un capacitor de 35 MFD que mide 31 MFD ha perdido más del 11% de su capacitancia, muy por encima del 6% de tolerancia estándar. Un capacitor débil causa bajo torque, sobrecalentamiento del motor y eventual falla. Debe reemplazarse preventivamente." },
  { id:"ns_0253", categoria:"NATE_SR_CEO", pregunta:"Un CEO decide implementar 'Flat Rate'. ¿Cuál es el impacto en la productividad del técnico?", opciones:["Aumenta la velocidad al eliminar la necesidad de calcular precios en el sitio.", "Reduce la calidad del trabajo porque los técnicos intentan terminar más rápido.", "Disminuye la productividad al requerir más papeleo administrativo por visita.", "No tiene impacto, ya que el técnico sigue trabajando a su propio ritmo habitual."], respuesta_correcta:0, explicacion:"El Flat Rate elimina la necesidad de calcular precios en el sitio, permitiendo al técnico enfocarse en el diagnóstico y la presentación de opciones, lo que acelera cada visita." },
  { id:"ns_0254", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no responde al control remoto. El técnico prueba con uno nuevo y sigue igual. ¿Qué sigue?", opciones:["Verificar la placa receptora de la unidad interior y el cableado de señal.", "Cambiar la placa principal exterior asumiendo que bloquea el receptor.", "Sustituir las baterías del control remoto aunque parezcan estar nuevas.", "Resetear el breaker de la unidad durante 10 minutos para borrar el error."], respuesta_correcta:0, explicacion:"Si un control remoto nuevo tampoco funciona, el problema no es el emisor sino el receptor. El Senior verifica la placa receptora de infrarrojos de la unidad interior y el cableado de señal hacia la placa principal." },
  { id:"ns_0255", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calefacción, una bomba de calor tiene una presión de succión de 100 PSI y descarga de 400 PSI con R-410A a 40°F exterior. ¿Estado?", opciones:["Funcionamiento normal considerando las presiones de saturación en modo calor.", "Falta de refrigerante que impide que la descarga suba a los 600 PSI ideales.", "Exceso de carga que está elevando la succión por encima de los 80 PSI.", "Válvula inversora dañada que está permitiendo un bypass interno de gas."], respuesta_correcta:0, explicacion:"Con R-410A a 40F exterior, una succion de 100 PSI y descarga de 400 PSI son valores normales para modo calefaccion. Corresponden a temperaturas de saturacion adecuadas para las condiciones de operacion." },
  { id:"ns_0256", categoria:"NATE_SR_RACK", pregunta:"Un rack usa 'Hot Gas Defrost'. Una vitrina se queda con hielo tras el ciclo. ¿Qué revisa?", opciones:["La válvula solenoide de gas caliente y el cheque de la línea de líquido.", "El ventilador del evaporador que debe estar apagado durante el deshielo.", "La presión del recibidor que podría estar demasiado baja para el empuje.", "Si el reloj de deshielo tiene configurado un tiempo de goteo muy largo."], respuesta_correcta:0, explicacion:"Si una vitrina específica no descongela con gas caliente, la solenoide de gas caliente puede no estar abriendo, o la válvula check de la línea de líquido puede estar impidiendo el flujo inverso necesario para que el gas caliente circule por el evaporador." },
  { id:"ns_0257", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Junior usa una antorcha de acetileno sin nitrógeno. El Senior lo detiene por:", opciones:["La oxidación interna que creará hollín y tapará los filtros y válvulas.", "El riesgo de incendio al no haber un gas inerte que desplace el oxígeno.", "La deformación del tubo de cobre por el calor excesivo de la llama pura.", "La pérdida de las propiedades de la soldadura de plata al oxidarse el cobre."], respuesta_correcta:0, explicacion:"Sin purga de nitrógeno, el oxígeno dentro de la tubería reacciona con el cobre a altas temperaturas formando óxido cúprico (hollín negro). Estas escamas se desprenden y obstruyen filtros deshidratadores, TXVs y orificios del sistema." },
  { id:"ns_0258", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una caída de presión de agua de 15 PSI en el evaporador. ¿Cómo verifica el flujo?", opciones:["Consultando la curva de la bomba y la tabla de diseño del fabricante.", "Midiendo la temperatura de salida del agua con un termómetro láser.", "Observando el movimiento del agua en el tanque de expansión abierto.", "Contando las revoluciones por minuto del motor de la bomba de agua helada."], respuesta_correcta:0, explicacion:"La caída de presión de agua se correlaciona con el flujo según las curvas del fabricante. Consultando la curva de la bomba y la tabla de diseño, se puede verificar si el flujo corresponde al diferencial medido." },
  { id:"ns_0259", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta ruidos de 'Water Hammering' en las líneas de refrigerante. ¿Causa?", opciones:["Líquido refrigerante regresando al compresor o falta de soportes en tubería.", "Aire atrapado en el sistema que no fue evacuado durante el proceso de vacío.", "Una válvula de expansión que abre y cierra violentamente por falta de carga.", "El uso de tubería de succión con un diámetro mayor al especificado por diseño."], respuesta_correcta:0, explicacion:"El 'water hammering' en líneas de refrigerante se produce cuando refrigerante líquido viaja a alta velocidad y golpea contra curvas o componentes, o cuando la tubería vibra por falta de soportes adecuados. El líquido regresando al compresor es la causa más común y peligrosa." },
  { id:"ns_0260", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar la retención de clientes. ¿Cuál es el impacto de un programa de mantenimiento?", opciones:["Aumenta la lealtad, reduce las emergencias y genera ingresos recurrentes.", "Permite cobrar más caro por las reparaciones de emergencia al cliente fiel.", "Reduce la necesidad de tener técnicos Senior, ya que el equipo estará nuevo.", "Elimina la competencia al obligar al cliente a firmar un contrato de exclusividad."], respuesta_correcta:0, explicacion:"Un programa de mantenimiento preventivo aumenta la lealtad del cliente, reduce emergencias costosas y genera ingresos recurrentes predecibles para la empresa." },
  { id:"ns_0261", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se prefiere un condensador remoto con ventiladores VFD?", opciones:["Mantiene una presión de descarga estable y reduce el consumo eléctrico.", "Permite que el rack funcione sin necesidad de un separador de aceite.", "Elimina el ruido en el área de ventas al alejar los motores del edificio.", "Facilita la carga de refrigerante al no depender de la temperatura ambiente."], respuesta_correcta:0, explicacion:"Los ventiladores con VFD (variador de frecuencia) modulan su velocidad según la presión de descarga, manteniendo una presión estable en todas las condiciones ambientales. Además, a velocidades reducidas consumen significativamente menos energía eléctrica." },
  { id:"ns_0262", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Surge'. El Senior nota que la temperatura del agua de la torre es de 45°F. ¿Causa?", opciones:["La temperatura del agua es demasiado baja, causando baja presión de condensación.", "El agua está demasiado fría y está congelando el refrigerante en los tubos.", "La torre está enviando agua con aire hacia el condensador del chiller.", "Los ventiladores de la torre están girando en sentido contrario al diseño."], respuesta_correcta:0, explicacion:"Agua de torre a 45°F es demasiado fría, causando baja presión de condensación. La diferencia de presión entre condensador y evaporador se reduce al punto donde el impulsor centrífugo entra en surge." },
  { id:"ns_0263", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter muestra el error 'P4' (Inverter Fin Temp Error). ¿Qué hace?", opciones:["Limpiar el disipador de calor de la placa exterior y revisar la pasta térmica.", "Cambiar el motor del ventilador interior por uno de mayor flujo de aire.", "Sustituir el compresor asumiendo que el bobinado está sobrecalentado.", "Puentear el sensor de temperatura del disipador para que la placa opere."], respuesta_correcta:0, explicacion:"El error P4 (IPM Overheat) indica sobrecalentamiento del módulo de potencia. Limpiar el disipador de calor y revisar/reemplazar la pasta térmica restablece la transferencia de calor adecuada del IPM." },
  { id:"ns_0264", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor tiene la línea de líquido caliente y la succión escarchada. ¿Qué revisa?", opciones:["El flujo de aire exterior y si el serpentín exterior está bloqueado por suciedad.", "La válvula inversora que podría estar parcialmente movida hacia refrigeración.", "Si el filtro de aire interior está sucio, reduciendo la transferencia de calor.", "La carga de refrigerante que probablemente es excesiva para el modo calor."], respuesta_correcta:0, explicacion:"La linea de liquido caliente indica que el condensador interior funciona. La succion escarchada indica que el serpentin exterior no absorbe suficiente calor, por suciedad o bloqueo del flujo de aire exterior." },
  { id:"ns_0265", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa el 'Average Ticket'. ¿Cómo puede subir este valor sin subir precios?", opciones:["Capacitando a los técnicos en la identificación de accesorios y mejoras.", "Obligando a los técnicos a tardar más tiempo en cada llamada de servicio.", "Cargando una tarifa extra por el uso de herramientas especializadas en sitio.", "Eliminando los descuentos por pronto pago que se ofrecen a los clientes."], respuesta_correcta:0, explicacion:"Capacitar a los técnicos para identificar oportunidades de mejora (filtros UV, termostatos inteligentes, protectores de voltaje) sube el Average Ticket sin aumentar los precios base." },
  { id:"ns_0266", categoria:"NATE_SR_RACK", pregunta:"Un rack de media temperatura usa R-22. El cliente quiere convertirlo a R-407A. ¿Qué es crítico?", opciones:["Cambiar el aceite mineral por POE y sustituir todos los sellos de elastómero.", "Reemplazar todos los compresores ya que el R-407A dañará los pistones.", "Simplemente vaciar el R-22 y cargar el R-407A sin hacer cambios físicos.", "Instalar un condensador dos veces más grande para manejar la nueva presión."], respuesta_correcta:0, explicacion:"El R-407A requiere aceite POE (poliol éster) que es compatible con HFC, a diferencia del aceite mineral usado con R-22. Además, los sellos de elastómero deben cambiarse porque el R-407A puede deteriorar los materiales diseñados para R-22." },
  { id:"ns_0267", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que una unidad nueva tiene un serpentín con fuga de fábrica. ¿Qué hace el Senior?", opciones:["Documentar con fotos, procesar la garantía y pedir el reemplazo al proveedor.", "Reparar la fuga con soldadura de plata para no perder tiempo en la obra.", "Decirle al cliente que el equipo es de mala calidad y que compre otra marca.", "Cargar el sistema con un sellador de fugas para que el cliente no se dé cuenta."], respuesta_correcta:0, explicacion:"Un defecto de fábrica debe procesarse como garantía. Documentar con fotos protege a la empresa y al cliente, asegura el reemplazo sin costo, y mantiene la integridad del equipo nuevo sin reparaciones que podrían comprometer su vida útil." },
  { id:"ns_0268", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con evaporador de placas presenta una falla de 'Freeze Protection'. ¿Causa?", opciones:["Bajo flujo de agua o set-point de presión de succión demasiado bajo.", "Carga de refrigerante excesiva que enfría demasiado el agua del proceso.", "Válvula de expansión electrónica bloqueada en la posición de abierta total.", "El sensor de temperatura de salida del agua está tocando la tubería caliente."], respuesta_correcta:0, explicacion:"En evaporadores de placas, el espacio es reducido y el riesgo de congelación es alto. Un bajo flujo de agua o set-point de succión muy bajo causa que el refrigerante enfríe el agua por debajo de 32°F." },
  { id:"ns_0269", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga que oscila rítmicamente. ¿Qué revisa?", opciones:["Aire en el sistema o una válvula de expansión con el bulbo mal ubicado.", "El capacitor de marcha del compresor que está perdiendo fuerza motriz.", "Si el motor del ventilador del condensador está ciclando por temperatura.", "La estabilidad del voltaje que suministra la empresa eléctrica local."], respuesta_correcta:0, explicacion:"Una descarga que oscila rítmicamente indica aire (incondensables) atrapado en el sistema que se comprime y expande, o una TXV con el bulbo mal ubicado que causa ciclos repetitivos de apertura y cierre. Ambos producen fluctuaciones predecibles en la presión de descarga." },
  { id:"ns_0270", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 10 toneladas tiene un Delta T de aire de 30°F. ¿Qué indica?", opciones:["Bajo flujo de aire a través del evaporador debido a filtros o conductos.", "Funcionamiento excepcional del sistema con una capacidad de enfriamiento alta.", "Falta de refrigerante que causa que el aire se enfríe de forma desigual.", "Exceso de velocidad del ventilador del soplador que genera turbulencia."], respuesta_correcta:0, explicacion:"Un Delta T de 30°F (normal es 18-22°F) indica que el aire permanece demasiado tiempo en contacto con el serpentín por bajo flujo de aire. Menos CFM sobre el evaporador = mayor caída de temperatura por unidad de aire, causado típicamente por filtros sucios, conductos restringidos o soplador lento." },
  { id:"ns_0271", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Cash Flow'. ¿Cuál es la medida más efectiva?", opciones:["Cobrar en el momento del servicio y reducir los términos de crédito a 30 días.", "Pedir un préstamo bancario a largo plazo para cubrir los gastos operativos.", "Aumentar el inventario de piezas en las camionetas para no ir a la tienda.", "Reducir el salario de los técnicos junior para ahorrar en la nómina semanal."], respuesta_correcta:0, explicacion:"Cobrar en el momento del servicio y reducir los términos de crédito a 30 días máximo acelera la entrada de efectivo, mejorando directamente el flujo de caja operativo." },
  { id:"ns_0272", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿cuál es la función del 'Oil Reservoir' o depósito de aceite?", opciones:["Almacenar el aceite separado del gas para distribuirlo según la demanda.", "Enfriar el aceite mediante un intercambiador de placas antes de los motores.", "Separar el refrigerante líquido que pudo haberse mezclado con el lubricante.", "Mantener la presión de descarga constante para el retorno de aceite al rack."], respuesta_correcta:0, explicacion:"El depósito de aceite (oil reservoir) almacena el aceite recuperado por el separador y lo distribuye a los compresores según la demanda, mediante válvulas reguladoras de nivel. Actúa como reserva centralizada para todo el rack paralelo." },
  { id:"ns_0273", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un approach de condensador de 1°F. ¿Qué concluye el Senior?", opciones:["Transferencia de calor excelente; el condensador está perfectamente limpio.", "Falta de refrigerante líquido; no hay suficiente masa para el intercambio.", "Flujo de agua excesivo que está falseando la lectura del sensor térmico.", "El sensor de temperatura de salida del agua está defectuoso o mal puesto."], respuesta_correcta:0, explicacion:"Un approach de condensador de 1°F indica una excelente transferencia de calor, con tubos perfectamente limpios y una diferencia mínima entre la temperatura de saturación y la salida del agua." },
  { id:"ns_0274", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter muestra el error 'High Pressure Protection' en calefacción. ¿Causa?", opciones:["Filtro de aire interior sucio o ventilador interior a baja velocidad.", "Condensador exterior bloqueado por hojas o suciedad del ambiente.", "Carga de refrigerante insuficiente para alcanzar la presión de diseño.", "Válvula de expansión electrónica (EEV) bloqueada en posición cerrada."], respuesta_correcta:0, explicacion:"En modo calefacción, el serpentín interior actúa como condensador. Un filtro sucio o ventilador lento reduce el flujo de aire, la presión de condensación sube excesivamente y activa la protección de alta presión." },
  { id:"ns_0275", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿por qué el compresor se apaga durante el ciclo de deshielo?", opciones:["No se apaga; el compresor sigue operando para calentar el serpentín exterior.", "Se apaga por seguridad para evitar un golpe de líquido al revertir la válvula.", "Para ahorrar energía ya que las resistencias eléctricas están encendidas.", "Para permitir que el hielo se derrita por la temperatura del aire ambiente."], respuesta_correcta:0, explicacion:"Durante el defrost, el compresor NO se apaga. Continua operando para bombear gas caliente de descarga al serpentin exterior, derritiendo el hielo acumulado. El sistema opera en modo refrigeracion temporalmente." },
  { id:"ns_0276", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Junior instala una unidad y no conecta la tierra física. El Senior le advierte que:", opciones:["Es un riesgo mortal de descarga eléctrica y puede dañar las placas electrónicas.", "El compresor consumirá más amperaje al no tener una referencia de neutro.", "La garantía del fabricante se anula si no hay una conexión a tierra certificada.", "El equipo hará más ruido debido a la falta de masa para las vibraciones."], respuesta_correcta:0, explicacion:"La tierra física proporciona un camino seguro para corrientes de fuga, protegiendo a las personas de descargas eléctricas letales. Sin tierra, el chasis del equipo puede quedar energizado. Además, las placas electrónicas son vulnerables a daños por descargas estáticas." },
  { id:"ns_0277", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo usa un variador de frecuencia (VFD). ¿Cuál es el beneficio a baja carga?", opciones:["Prevenir el surge bajando la velocidad del motor y ajustando los vanes.", "Aumentar la presión de descarga para mejorar la eficiencia del condensador.", "Eliminar la necesidad de usar una unidad de purga en sistemas de baja presión.", "Reducir el flujo de agua helada para mantener la temperatura de salida constante."], respuesta_correcta:0, explicacion:"El VFD permite reducir la velocidad del compresor a baja carga, previniendo el surge al mantener una velocidad de gas adecuada en el impulsor mientras se ajustan los vanes de entrada." },
  { id:"ns_0278", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial tiene una succión de 110 PSI y descarga de 350 PSI. El subenfriamiento es 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido en el sistema (undercharged).", "Válvula de expansión (TXV) fallida en posición abierta total.", "Condensador exterior sucio que no permite el subenfriamiento.", "Evaporador interior congelado que bloquea el flujo de calor."], respuesta_correcta:0, explicacion:"Un subenfriamiento de 0°F significa que no hay líquido subenfriado saliendo del condensador, solo vapor o mezcla bifásica. Con presiones que no son extremas, esto indica claramente que el sistema no tiene suficiente refrigerante para llenar el condensador con líquido (undercharged)." },
  { id:"ns_0279", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración.", "Personal experto en la instalación de conductos de lámina galvanizada.", "Instaladores de paneles solares con certificación eléctrica industrial.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos."], respuesta_correcta:0, explicacion:"El mercado de Smart Homes requiere técnicos que dominen redes Wi-Fi, protocolos IoT (Zigbee, Z-Wave) e integración de dispositivos, habilidades que van más allá del HVAC tradicional." },
  { id:"ns_0280", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué indica una temperatura de succión muy alta en el cabezal?", opciones:["Sobrecalentamiento excesivo que puede dañar la lubricación de los compresores.", "Que el sistema está operando a su máxima eficiencia de evaporación.", "Falta de refrigerante líquido en el recibidor principal del rack paralelo.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura."], respuesta_correcta:0, explicacion:"Una temperatura de succión muy alta indica sobrecalentamiento excesivo del gas de retorno. Esto reduce la capacidad de enfriamiento del motor del compresor y degrada las propiedades del aceite lubricante, acelerando el desgaste mecánico." },
  { id:"ns_0281", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Loss'. ¿Qué componente eléctrico protege al motor?", opciones:["El monitor de fase o el relé de sobrecarga de estado sólido del sistema.", "Los fusibles de retardo de tiempo instalados en la desconexión principal.", "El interruptor termomagnético de la placa de control de 120 voltios.", "El contactor magnético que se abrirá por falta de voltaje en la bobina."], respuesta_correcta:0, explicacion:"El monitor de fase o relé de sobrecarga de estado sólido detecta la pérdida de fase y desconecta el motor antes de que sufra daño. Los fusibles solo protegen contra cortocircuitos, no pérdida de fase." },
  { id:"ns_0282", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter tiene una fuga en el serpentín interior. El cliente pide repararlo. ¿Qué dice el Senior?", opciones:["Es mejor reemplazar el serpentín completo debido a la complejidad de soldar aluminio.", "Se puede reparar con epóxico especial para refrigeración sin retirar la unidad.", "La soldadura de plata funcionará perfectamente si se usa el fundente adecuado.", "No es reparable; el sistema completo debe ser desechado por normativas ambientales."], respuesta_correcta:0, explicacion:"Los serpentines interiores de mini-split suelen ser de aluminio, un material difícil de soldar en campo. Es más confiable y seguro reemplazar el serpentín completo que intentar una reparación de soldadura." },
  { id:"ns_0283", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática total de 1.2 pulg. W.C. ¿Qué le sucede al motor ECM?", opciones:["Intentará subir las RPM para mantener el flujo de aire, aumentando el consumo y ruido.", "Se apagará por seguridad para evitar que el exceso de presión rompa los conductos.", "Bajará la velocidad automáticamente para proteger los rodamientos del motor.", "No le sucede nada, ya que los motores ECM están diseñados para cualquier presión."], respuesta_correcta:0, explicacion:"Los motores ECM son de velocidad variable y están programados para entregar un CFM constante. Ante alta presión estática, el ECM aumenta automáticamente las RPM para mantener el flujo objetivo, lo que incrementa el consumo eléctrico y genera más ruido en el sistema." },
  { id:"ns_0284", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿cuál es la función del 'Defrost Control Board'?", opciones:["Monitorear tiempo y temperatura para revertir la válvula y quitar el hielo.", "Encender las resistencias eléctricas cuando la temperatura exterior baja de 30°F.", "Asegurar que el compresor no arranque si la presión de alta es muy elevada.", "Regular la velocidad del ventilador interior según la demanda de calefacción."], respuesta_correcta:0, explicacion:"La placa de defrost monitorea tiempo acumulado de operacion y temperatura del serpentin exterior. Cuando ambas condiciones se cumplen, inicia el deshielo revirtiendo la valvula inversora a modo refrigeracion." },
  { id:"ns_0285", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un equipo de 10 técnicos. Nota que el inventario de gas desaparece. ¿Acción?", opciones:["Implementar un registro de peso de cilindros al inicio y final de cada día.", "Descontar el costo del refrigerante faltante de forma equitativa a todos.", "Cerrar con llave el almacén de gas y solo el Senior puede entregar cilindros.", "Instalar cámaras en todas las camionetas para ver qué hacen los técnicos."], respuesta_correcta:0, explicacion:"Un registro diario de peso de cilindros es una medida de control de inventario precisa y justa. Permite identificar discrepancias, rastrear el consumo por técnico y trabajo, y detectar pérdidas sin acusar injustamente a nadie." },
  { id:"ns_0286", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. ¿Estado?", opciones:["Funcionamiento correcto; la purga está separando los no condensables.", "Falla en el serpentín de condensación interno de la unidad de purga.", "El sistema tiene una fuga masiva de agua hacia el lado del refrigerante.", "La temperatura del evaporador es demasiado alta para que la purga trabaje."], respuesta_correcta:0, explicacion:"Una purga que expulsa mucho aire pero poco refrigerante está funcionando correctamente, ya que su diseño separa los gases no condensables del refrigerante y solo expulsa el aire." },
  { id:"ns_0287", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si el 'Oil Separator' se queda pegado en posición abierta?", opciones:["Gas caliente de descarga pasará directamente al depósito de aceite y la succión.", "El rack se quedará sin aceite en pocos minutos al no poder separarlo del gas.", "Los compresores se apagarán por alta presión al bloquearse el flujo de gas.", "El nivel de aceite en los cárteres subirá tanto que dañará los pistones."], respuesta_correcta:0, explicacion:"Si el flotador del separador se queda abierto, gas caliente de descarga a alta presión pasa directamente al depósito de aceite y puede llegar a la succión. Esto crea un bypass que reduce la capacidad del sistema y sobrecalienta los compresores." },
  { id:"ns_0288", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. ¿Qué KPI usa?", opciones:["El número de llamadas de nuevos clientes que mencionan haber visto la unidad.", "La cantidad de millas recorridas por cada vehículo en zonas residenciales.", "El costo total del diseño y la instalación del rótulo dividido entre 12 meses.", "El aumento en la velocidad promedio de los técnicos al conducir camionetas nuevas."], respuesta_correcta:0, explicacion:"El KPI más directo para medir la efectividad de camionetas rotuladas es el número de llamadas de nuevos clientes que mencionan haber visto la unidad en su vecindario." },
  { id:"ns_0289", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador de agua tiene 'High Condensing Pressure'. ¿Qué revisa primero?", opciones:["La temperatura del agua de la torre y si la bomba de condensador funciona.", "La carga de refrigerante líquido basándose en el visor del evaporador.", "Si la válvula de expansión está inyectando demasiado líquido al sistema.", "El estado de los filtros de aire de la manejadora de aire del edificio."], respuesta_correcta:0, explicacion:"En un condensador enfriado por agua, la alta presión de condensación se relaciona directamente con la temperatura del agua de torre y el funcionamiento de la bomba de condensador como primer punto de diagnóstico." },
  { id:"ns_0290", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 125 PSI y descarga de 400 PSI con R-410A. El aire sale a 60°F. ¿Estado?", opciones:["Funcionamiento normal bajo condiciones de carga térmica estándar.", "Falta de refrigerante que impide que la temperatura del aire baje a 55°F.", "Exceso de carga que está elevando la presión de descarga innecesariamente.", "Compresor con eficiencia reducida que no logra enfriar el aire correctamente."], respuesta_correcta:0, explicacion:"Con R-410A, succión de 125 PSI (~40°F sat.) y descarga de 400 PSI (~109°F sat.) son valores normales. Una temperatura de suministro de 60°F indica un Delta T adecuado de ~15-20°F sobre la saturación del evaporador, confirmando operación normal." },
  { id:"ns_0291", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. ¿Qué estrategia lanza?", opciones:["Un programa de membresías de mantenimiento para convertir clientes en recurrentes.", "Aumentar el precio de la primera visita para maximizar la ganancia inmediata.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos.", "Despedir a los técnicos que no logren vender un sistema nuevo en cada visita."], respuesta_correcta:0, explicacion:"Un programa de membresías de mantenimiento convierte clientes de una sola vez en recurrentes, generando ingresos predecibles y aumentando el Customer Lifetime Value." },
  { id:"ns_0292", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una restricción en la válvula de expansión.", "Si el ventilador interior está sucio y no sopla suficiente aire frío.", "El voltaje de la línea eléctrica que podría estar por debajo de los 200V.", "Si el control remoto está configurado en una temperatura demasiado baja."], respuesta_correcta:0, explicacion:"Una carga baja de refrigerante o una restricción en la EEV causa sobrecalentamiento excesivo del gas de descarga del compresor, activando la protección de temperatura de descarga." },
  { id:"ns_0293", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si la válvula de retención del condensador falla abierta?", opciones:["El refrigerante hará bypass a la TXV en modo calor, impidiendo el calentamiento.", "El sistema funcionará mejor al haber menos restricción al flujo de líquido.", "La presión de descarga subirá hasta que el switch de alta apague el equipo.", "El compresor se quemará por el retorno de líquido masivo durante el arranque."], respuesta_correcta:0, explicacion:"La check valve esta en paralelo con la TXV. Si falla abierta, en modo calor el refrigerante hace bypass por la check valve en vez de pasar por la TXV, sin restriccion ni calentamiento adecuado." },
  { id:"ns_0294", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o de inyección de líquido?", opciones:["Para enfriar el gas de succión y evitar que la descarga dañe el aceite.", "Para aumentar la presión de succión cuando la carga en las vitrinas es baja.", "Para limpiar el interior de los compresores de acumulaciones de carbonilla.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos."], respuesta_correcta:0, explicacion:"La válvula Quench inyecta una pequeña cantidad de refrigerante líquido en la succión o descarga para enfriar el gas y reducir la temperatura de descarga. Esto protege el aceite lubricante de la degradación térmica por temperaturas excesivas." },
  { id:"ns_0295", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior debe decidir si usar una aspiradora de agua o una bomba para un drenaje. ¿Criterio?", opciones:["El volumen de agua y la accesibilidad para la eliminación segura del fluido.", "Cuál de las dos herramientas es más nueva y hace menos ruido al operar.", "La preferencia del cliente sobre qué herramienta quiere ver en su casa.", "Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo."], respuesta_correcta:0, explicacion:"La selección de herramienta debe basarse en factores técnicos: el volumen de agua a remover determina la capacidad necesaria, y la accesibilidad del drenaje determina qué equipo puede llegar al punto de acumulación para una eliminación segura." },
  { id:"ns_0296", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar una prueba de presión a los tubos del evaporador para buscar rupturas.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema.", "Aumentar la temperatura del agua helada para evitar que el vapor se condense.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo secante."], respuesta_correcta:0, explicacion:"La detección de agua por la purga indica una posible ruptura en los tubos del evaporador. Se requiere una prueba de presión urgente para localizar la fuga y evitar contaminación del refrigerante." },
  { id:"ns_0297", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 130 PSI y descarga de 380 PSI. El subenfriamiento es 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango.", "Falta de refrigerante líquido; el subenfriamiento debería ser de 15°F mínimo.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno.", "Compresor fallando; la diferencia de presión entre succión y descarga es baja."], respuesta_correcta:0, explicacion:"Con R-410A, succión de 130 PSI (~42°F sat.) y descarga de 380 PSI (~104°F sat.) son normales. Un subenfriamiento de 12°F está dentro del rango típico de 10-15°F para sistemas con TXV, confirmando una carga de refrigerante correcta y operación óptima." },
  { id:"ns_0298", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el contactor del compresor zumba pero no cierra. ¿Qué revisa?", opciones:["El voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo.", "Si los contactos principales están quemados o soldados entre sí.", "El capacitor de arranque del compresor que podría estar descargado.", "La continuidad de los fusibles de potencia de la línea de 240 voltios."], respuesta_correcta:0, explicacion:"Un contactor que zumba sin cerrar indica que la bobina recibe voltaje insuficiente para generar la fuerza magnética necesaria, o que el núcleo tiene suciedad/óxido que impide el cierre mecánico. Verificar el voltaje de la bobina y la limpieza del núcleo es el primer paso diagnóstico." },
  { id:"ns_0299", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico está cobrando 'por fuera' a los clientes. ¿Acción?", opciones:["Despido inmediato y posible acción legal según el contrato de trabajo.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras.", "Ignorar la situación si el técnico es el que más dinero genera a la empresa.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas de trabajo."], respuesta_correcta:0, explicacion:"Cobrar por fuera es fraude contra la empresa; el despido inmediato y la acción legal protegen la integridad del negocio y envían un mensaje claro de tolerancia cero." },
  { id:"ns_0300", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en el recibidor?", opciones:["Para evitar el fraccionamiento de la mezcla y asegurar la composición correcta.", "Para que el refrigerante se mezcle más rápido con el aceite POE del rack.", "Para prevenir que las válvulas de descarga de los compresores se calienten.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."], respuesta_correcta:0, explicacion:"El R-448A es una mezcla zeotrópica; si se carga en fase gaseosa, los componentes más volátiles se evaporan primero y la composición del cilindro cambia. Cargar en fase líquida garantiza que todos los componentes entren al sistema en la proporción correcta." },
  { id:"ns_0301", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo opera con una presión de condensación que fluctúa rítmicamente. El flujo de agua es estable. ¿Qué diagnóstico Senior aplica?", opciones:["Presencia de gases incondensables o una carga de refrigerante excesiva.", "Descalibración del sensor de temperatura de aproximación del evaporador.", "Falla en el rodamiento de empuje (thrust bearing) del eje principal.", "Efecto de cavitación en la bomba de agua de la torre de enfriamiento."], respuesta_correcta:0, explicacion:"Fluctuaciones rítmicas en la presión de condensación, con flujo de agua estable, indican gases no condensables que se comprimen y expanden, o una sobrecarga de refrigerante que causa inundación intermitente." },
  { id:"ns_0302", categoria:"NATE_SR_RACK", pregunta:"En un rack de refrigeración, ¿cuál es el síntoma principal de una válvula reguladora de presión de cárter (CPR) mal ajustada (muy alta)?", opciones:["Sobrecarga del motor del compresor durante el arranque tras un deshielo.", "Reducción de la capacidad de enfriamiento en todas las vitrinas conectadas.", "Aumento del retorno de aceite líquido directamente al cabezal de succión.", "Ciclos cortos por baja presión de succión debido a la restricción de gas."], respuesta_correcta:0, explicacion:"La CPR limita la presión máxima de succión que llega al compresor para proteger el motor. Si está ajustada muy alta, permite el paso de demasiado gas durante el pull-down post-deshielo, sobrecargando el motor del compresor." },
  { id:"ns_0303", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa el 'Labor Burden'. ¿Qué elementos deben incluirse para un cálculo real de costo por hora técnica?", opciones:["Impuestos sobre nómina, seguros, beneficios, uniformes y tiempo no facturable.", "Únicamente el salario base por hora multiplicado por las horas de la jornada.", "El costo de las herramientas manuales y el combustible usado en la camioneta.", "La comisión por ventas y el bono de productividad trimestral del empleado."], respuesta_correcta:0, explicacion:"El Labor Burden real incluye impuestos sobre nómina, seguros, beneficios, uniformes y tiempo no facturable; usar solo el salario base subestima gravemente el costo por hora." },
  { id:"ns_0304", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF presenta un error de 'Inverter DC Link Overvoltage'. ¿Qué factor eléctrico externo es el culpable más probable?", opciones:["Una pérdida del neutro o un desequilibrio severo en las fases de entrada.", "Un compresor con los devanados parcialmente quemados que genera retorno.", "El uso de un generador eléctrico con una frecuencia de salida inestable.", "Un ventilador de condensador bloqueado que eleva la carga del compresor."], respuesta_correcta:0, explicacion:"La pérdida del neutro o un desequilibrio severo de fases causa picos de voltaje en el bus DC del inverter que exceden el límite del circuito, disparando el error de sobrevoltaje DC Link." },
  { id:"ns_0305", categoria:"NATE_SR_HVAC", pregunta:"Al realizar un balanceo de aire, se encuentra que una habitación tiene presión positiva excesiva. ¿Cuál es la corrección técnica?", opciones:["Aumentar el tamaño del conducto de retorno o instalar una rejilla de transferencia.", "Reducir el diámetro del conducto de suministro para bajar el volumen de CFM.", "Instalar un damper motorizado que cierre al detectar presión en la habitación.", "Aumentar la velocidad del soplador para forzar la salida del aire por las puertas."], respuesta_correcta:0, explicacion:"Presión positiva en una habitación significa que entra más aire del que sale. La solución es agregar un camino de retorno adecuado, ya sea aumentando el conducto de retorno o instalando una rejilla de transferencia, para que el aire pueda circular de vuelta al sistema." },
  { id:"ns_0306", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor presenta una temperatura de descarga de 240°F con R-410A. ¿Qué acción es prioritaria?", opciones:["Verificar falta de refrigerante o una restricción en la TXV exterior.", "Instalar un enfriador de aceite externo para proteger los rodamientos.", "Reducir el flujo de aire interior para aumentar la presión de condensación.", "Ignorar el valor si el sobrecalentamiento de succión es menor a 15°F."], respuesta_correcta:0, explicacion:"Una temperatura de descarga de 240F con R-410A es peligrosamente alta (limite 225F). La prioridad es verificar falta de refrigerante o una restriccion en la TXV que limita el flujo y reduce el enfriamiento del gas." },
  { id:"ns_0307", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior observa que su equipo recupera refrigerante en cilindros llenos al 95%. ¿Cuál es el riesgo de seguridad?", opciones:["Explosión por expansión hidrostática si la temperatura ambiente aumenta.", "Contaminación del refrigerante recuperado por falta de espacio gaseoso.", "Daño mecánico a la máquina recuperadora por exceso de contrapresión.", "Multas de la EPA por exceder el límite legal de transporte de materiales."], respuesta_correcta:0, explicacion:"Los cilindros de recuperación no deben llenarse más del 80% de su capacidad. Si la temperatura sube, el líquido se expande y sin espacio gaseoso de seguridad, la presión hidrostática puede causar una explosión catastrófica del cilindro." },
  { id:"ns_0308", categoria:"NATE_SR_PACKAGE", pregunta:"Un Rooftop tiene un economizador con control de 'Diferencial de Entalpía'. ¿Qué comparan los sensores?", opciones:["La energía total (calor + humedad) del aire exterior vs. el aire de retorno.", "La temperatura de bulbo seco exterior vs. la temperatura de bulbo húmedo.", "La humedad relativa de la zona vs. el punto de rocío del serpentín interior.", "La presión estática del suministro vs. la presión barométrica del exterior."], respuesta_correcta:0, explicacion:"El control de diferencial de entalpía compara la energía total (calor sensible + calor latente por humedad) del aire exterior contra el aire de retorno. Solo abre el economizador cuando la entalpía exterior es menor, garantizando un ahorro energético real incluyendo el efecto de la humedad." },
  { id:"ns_0309", categoria:"NATE_SR_RACK", pregunta:"En un sistema de rack paralelo, el 'Master Controller' falla. ¿Qué modo de operación deben tener los compresores?", opciones:["Operación manual mediante presostatos mecánicos de respaldo (fail-safe).", "Apagado total para evitar que los compresores operen sin control de aceite.", "Ciclo de tiempo fijo (5 minutos encendido, 5 apagado) para mantener frío.", "Arranque simultáneo de todos los compresores para proteger la mercancía."], respuesta_correcta:0, explicacion:"Los racks bien diseñados tienen presostatos mecánicos de respaldo (fail-safe) que operan los compresores por presión de succión cuando el controlador electrónico falla. Esto mantiene la refrigeración activa hasta que se repare el controlador." },
  { id:"ns_0310", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar la 'Eficiencia de Ruta'. ¿Qué tecnología impacta más directamente en el costo de combustible?", opciones:["Software de optimización de rutas con GPS y despacho en tiempo real.", "Camionetas con motores híbridos o de cuatro cilindros de alta eficiencia.", "Tarjetas de crédito corporativas que ofrecen reembolsos en gasolineras.", "Capacitación de técnicos en técnicas de conducción defensiva e inercia."], respuesta_correcta:0, explicacion:"El software de optimización de rutas con GPS reduce las millas innecesarias entre llamadas, impactando directamente el costo de combustible y el tiempo no facturable." },
  { id:"ns_0311", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con evaporador inundado presenta burbujas en la mirilla de líquido, pero el subenfriamiento es de 12°F. ¿Qué indica?", opciones:["Restricción en el filtro deshidratador o en la línea de líquido previa.", "Falta de refrigerante líquido para llenar el volumen total del sistema.", "Gases incondensables que están atrapados en la parte superior del visor.", "Operación normal debido a la alta velocidad del flujo de refrigerante."], respuesta_correcta:0, explicacion:"Burbujas en el visor con subenfriamiento adecuado de 12°F indican una restricción (filtro deshidratador o línea de líquido) que causa una caída de presión antes del visor, no falta de carga." },
  { id:"ns_0312", categoria:"NATE_SR_HVAC", pregunta:"Al analizar un gráfico psicrométrico, si aumentamos solo la temperatura de bulbo seco sin añadir humedad, ¿qué sucede?", opciones:["La humedad relativa disminuye mientras que la humedad absoluta permanece constante.", "El punto de rocío sube proporcionalmente al incremento de la temperatura seca.", "La entalpía del aire disminuye debido a la expansión de las moléculas de vapor.", "La capacidad de enfriamiento del serpentín aumenta al haber mayor diferencial."], respuesta_correcta:0, explicacion:"Al aumentar solo la temperatura de bulbo seco sin añadir humedad, la cantidad de agua en el aire (humedad absoluta) no cambia. Sin embargo, el aire más caliente puede contener más humedad, por lo que el porcentaje de saturación (humedad relativa) disminuye." },
  { id:"ns_0313", categoria:"NATE_SR_CEO", pregunta:"Un CEO debe responder ante una demanda por 'Mold Growth' en un edificio. ¿Qué registro técnico es su mejor defensa?", opciones:["Reportes de mantenimiento que prueben que la humedad relativa se mantuvo bajo el 60%.", "Facturas de compra de los filtros de aire de alta eficiencia instalados en el sitio.", "Certificaciones NATE vigentes de todos los técnicos que visitaron la propiedad.", "El contrato de instalación donde se especifica que el moho es riesgo del cliente."], respuesta_correcta:0, explicacion:"Los reportes de mantenimiento que documentan la humedad relativa bajo control (menos del 60%) son la mejor defensa legal, ya que prueban que la empresa mantuvo condiciones correctas." },
  { id:"ns_0314", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema Multi-split tiene todas las unidades interiores encendidas, pero solo una enfría. ¿Cuál es el fallo lógico?", opciones:["Las válvulas de expansión electrónica (EEV) de las otras unidades están cerradas.", "El compresor inverter está operando a su frecuencia mínima por un error de placa.", "La carga de refrigerante es insuficiente para alimentar más de un evaporador.", "Hay una inversión de cables de comunicación entre las unidades que no enfrían."], respuesta_correcta:0, explicacion:"Si solo una unidad enfría y las demás no, las válvulas de expansión electrónica (EEV) de las unidades que no enfrían están cerradas, bloqueando el flujo de refrigerante a esos evaporadores." },
  { id:"ns_0315", categoria:"NATE_SR_RACK", pregunta:"En un sistema de rack, el separador de aceite está frío al tacto durante la operación. ¿Qué significa?", opciones:["No hay flujo de gas de descarga a través del separador o está puenteado.", "El sistema de refrigeración del aceite está funcionando con máxima eficiencia.", "El refrigerante líquido está inundando el separador por una falla en la TXV.", "El nivel de aceite es tan alto que actúa como un aislante térmico interno."], respuesta_correcta:0, explicacion:"El separador de aceite está en la línea de descarga y debería estar caliente durante la operación normal. Si está frío, no hay flujo de gas de descarga pasando a través de él, indicando que está puenteado o la conexión está obstruida." },
  { id:"ns_0316", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 15 toneladas presenta ciclos cortos por el interruptor de alta presión. El condensador está limpio. ¿Qué sigue?", opciones:["Verificar la rotación de los ventiladores del condensador y el subenfriamiento.", "Purgar refrigerante asumiendo que el sistema tiene una sobrecarga de fábrica.", "Puentear el switch de alta presión para verificar si el compresor sigue operando.", "Cambiar el filtro de aire interior para reducir la carga térmica en el sistema."], respuesta_correcta:0, explicacion:"Con el condensador limpio pero alta presión, se debe verificar la rotación correcta de los ventiladores (giro inverso mueve poco aire) y medir el subenfriamiento. Un subenfriamiento alto con alta presión puede indicar sobrecarga de refrigerante; un subenfriamiento bajo indica falta de rechazo de calor." },
  { id:"ns_0317", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior detecta que el voltaje de control de 24V cae a 18V cuando el contactor cierra. ¿Diagnóstico?", opciones:["Transformador de control infradimensionado (VA insuficientes) o bobina en corto.", "Caída de voltaje en la línea principal de 240V que afecta al transformador.", "Uso de cables de control de calibre 22 en una distancia mayor a 100 pies.", "El termostato digital está consumiendo demasiada corriente para el circuito."], respuesta_correcta:0, explicacion:"Una caída de 24V a 18V al cerrar el contactor indica que el transformador no tiene suficientes VA para la carga, o que la bobina del contactor tiene un cortocircuito parcial que consume excesiva corriente. Ambos causan caída de voltaje de control." },
  { id:"ns_0318", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con R-123 (baja presión) tiene una presión de evaporador por encima de la atmosférica en reposo. ¿Qué indica?", opciones:["Que la temperatura de la sala de máquinas es superior al punto de ebullición del gas.", "Existe una fuga masiva que ha igualado las presiones con el aire exterior.", "El calentador del evaporador está fallando y no mantiene la presión de seguridad.", "Es una condición normal ya que el R-123 siempre opera a presiones positivas."], respuesta_correcta:0, explicacion:"El R-123 tiene un punto de ebullición de ~80°F a presión atmosférica. Si la sala de máquinas está por encima de esa temperatura, el refrigerante se vaporiza y la presión del evaporador supera la atmosférica." },
  { id:"ns_0319", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor tiene una succión de 140 PSI y descarga de 350 PSI con R-410A. ¿Qué concluye el Senior?", opciones:["La válvula inversora está fugando internamente (bypass de gas caliente).", "El sistema está operando perfectamente considerando un día templado exterior.", "Falta de refrigerante líquido que impide que la descarga suba a 500 PSI.", "El compresor tiene las válvulas de descarga dañadas y no puede bombear."], respuesta_correcta:0, explicacion:"Succion alta (140 PSI) y descarga baja (350 PSI) con ratio de compresion reducido es sintoma clasico de fuga interna en la valvula inversora. El gas de descarga se recircula a la succion sin hacer trabajo util." },
  { id:"ns_0320", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere incentivar a los técnicos a través de 'Revenue Sharing'. ¿Cuál es el mayor riesgo operativo?", opciones:["Priorización de ventas sobre la calidad técnica y reparaciones necesarias.", "Aumento en el costo de la nómina que reduce el margen de utilidad neta.", "Descontento entre los técnicos que realizan instalaciones vs. los de servicio.", "Necesidad de contratar más contadores para calcular las comisiones exactas."], respuesta_correcta:0, explicacion:"El Revenue Sharing puede hacer que los técnicos prioricen la venta de equipos nuevos sobre la reparación técnicamente correcta, comprometiendo la calidad y la ética del servicio." },
  { id:"ns_0321", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, se observa que el nivel de aceite en todos los compresores baja simultáneamente. ¿Causa raíz?", opciones:["Baja velocidad del gas en las líneas de succión que impide el retorno de aceite.", "Falla en la válvula diferencial de presión que alimenta el depósito de aceite.", "El separador de aceite principal tiene el filtro de malla metálica roto.", "Todos los compresores tienen desgaste en los anillos y consumen más aceite."], respuesta_correcta:0, explicacion:"Cuando todos los compresores pierden aceite simultáneamente, el aceite se está acumulando en el sistema (evaporadores, condensador). La causa más común es baja velocidad del gas en las líneas de succión que no puede arrastrar el aceite de vuelta." },
  { id:"ns_0322", categoria:"NATE_SR_HVAC", pregunta:"Un motor de soplador PSC tiene un capacitor de 5 MFD. Si el técnico instala uno de 10 MFD, ¿qué sucede?", opciones:["El motor se sobrecalentará debido al aumento excesivo del flujo de corriente.", "El motor tendrá más torque de arranque y consumirá menos energía eléctrica.", "Las RPM del motor aumentarán un 20% mejorando el flujo de aire del sistema.", "El motor funcionará de manera más silenciosa al tener un campo magnético fuerte."], respuesta_correcta:0, explicacion:"Instalar un capacitor del doble del valor especificado (10 MFD vs 5 MFD) genera un flujo de corriente excesivo en el devanado de arranque del motor. Esta sobrecorriente produce calor adicional que deteriora el aislamiento y causa sobrecalentamiento y falla prematura." },
  { id:"ns_0323", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una caída de temperatura (Delta T) de agua helada de solo 4°F (Diseño es 10°F). ¿Qué indica?", opciones:["Flujo de agua excesivo a través del evaporador o baja carga térmica.", "Falta de refrigerante en el chiller que impide el enfriamiento del agua.", "Incrustaciones severas en los tubos que bloquean la transferencia térmica.", "La bomba de agua helada tiene el impulsor desgastado y mueve poco flujo."], respuesta_correcta:0, explicacion:"Un Delta T de 4°F vs. diseño de 10°F indica flujo de agua excesivo (el agua pasa demasiado rápido para enfriarse) o baja carga térmica en el edificio que demanda menos enfriamiento." },
  { id:"ns_0324", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter muestra el error 'Outdoor Coil Sensor Open'. ¿Cómo afecta la operación?", opciones:["El sistema no entrará en modo de deshielo o lo hará de forma errática.", "El compresor se bloqueará inmediatamente por protección de sobrecalentamiento.", "La unidad solo funcionará en modo de ventilación hasta que se repare el sensor.", "El ventilador exterior girará a la máxima velocidad sin importar la carga."], respuesta_correcta:0, explicacion:"El sensor del serpentín exterior es esencial para detectar la formación de escarcha y activar el ciclo de deshielo. Sin este sensor, el sistema no podrá iniciar el deshielo correctamente." },
  { id:"ns_0325", categoria:"NATE_SR_CEO", pregunta:"Un CEO decide expandir su empresa a 'Commercial Kitchen Refrigeration'. ¿Cuál es el desafío principal?", opciones:["La necesidad de técnicos disponibles 24/7 y stock de piezas multimarca.", "El cumplimiento de normativas de salud relacionadas con el moho en paredes.", "La baja rentabilidad de los equipos de cocina comparado con chillers industriales.", "La dificultad para encontrar refrigerantes específicos para máquinas de hielo."], respuesta_correcta:0, explicacion:"La refrigeración comercial de cocinas opera 24/7 y requiere técnicos disponibles en todo momento con stock de piezas multimarca, ya que el tiempo de inactividad causa pérdidas de producto." },
  { id:"ns_0326", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calefacción, una bomba de calor tiene un Delta T de 40°F. ¿Qué concluye el Senior?", opciones:["Flujo de aire interior insuficiente (filtros sucios o motor a baja velocidad).", "Operación perfecta; un Delta T alto indica una gran transferencia de calor.", "Exceso de refrigerante que está inundando el serpentín de la unidad interior.", "Las resistencias eléctricas están encendidas simultáneamente con el compresor."], respuesta_correcta:0, explicacion:"Un Delta T de 40F en modo calor es excesivamente alto. Indica flujo de aire insuficiente (filtros sucios o motor de soplador a baja velocidad), haciendo que el aire se caliente en exceso sobre el serpentin." },
  { id:"ns_0327", categoria:"NATE_SR_RACK", pregunta:"Se detecta presencia de aire en un sistema de rack con R-448A. ¿Qué parámetro se altera primero?", opciones:["La presión de descarga será más alta que la presión de saturación del gas.", "La temperatura de succión bajará debido a la expansión del aire en el rack.", "El aceite se volverá espumoso y el nivel en los compresores subirá de golpe.", "El consumo eléctrico del rack bajará al haber menos masa de refrigerante."], respuesta_correcta:0, explicacion:"El aire es un gas no condensable que se acumula en el condensador, sumando su presión parcial a la del refrigerante. Esto eleva la presión de descarga por encima de la presión de saturación esperada para la temperatura del condensador." },
  { id:"ns_0328", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete con gas tiene una llama amarilla y ondulante. ¿Qué peligro Senior existe?", opciones:["Producción de monóxido de carbono (CO) por combustión incompleta de gas.", "Baja eficiencia térmica que aumentará la factura de gas del cliente final.", "Desgaste prematuro de los quemadores por exceso de temperatura localizada.", "Acumulación de hollín en el sensor de flama que bloqueará la ignición."], respuesta_correcta:0, explicacion:"Una llama amarilla y ondulante indica combustión incompleta por falta de aire primario o exceso de gas. La combustión incompleta produce monóxido de carbono (CO), un gas letal inodoro. Este es el peligro más grave y la prioridad absoluta para un Senior." },
  { id:"ns_0329", categoria:"NATE_SR_MANAGEMENT", pregunta:"Al realizar un retrofit de R-22 a R-407C, el Senior insiste en cambiar el aceite. ¿Por qué?", opciones:["El aceite mineral no es miscible con HFC y causará fallas de retorno de aceite.", "El R-407C descompone químicamente el aceite mineral en pocos días de uso.", "El aceite POE es necesario para aumentar la presión de descarga del sistema.", "Las válvulas de expansión térmicas solo funcionan con aceite de polioléster."], respuesta_correcta:0, explicacion:"Los refrigerantes HFC como el R-407C no son miscibles con aceite mineral. Sin miscibilidad, el aceite no retorna al compresor y se acumula en el evaporador, causando falla de lubricación y eventual destrucción del compresor. Se requiere aceite POE o AB." },
  { id:"ns_0330", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga automática que expulsa refrigerante líquido constantemente. ¿Causa?", opciones:["Falla en la válvula de flotador de la purga o sensor de nivel defectuoso.", "La presión del condensador es tan alta que vence la capacidad de la purga.", "Infiltración masiva de aire que impide la separación correcta del gas.", "El calentador de la unidad de purga está quemado y no evapora el líquido."], respuesta_correcta:0, explicacion:"Una purga automática que expulsa refrigerante líquido constantemente indica falla en la válvula de flotador que controla el nivel, o un sensor de nivel defectuoso que no separa correctamente líquido de gas." },
  { id:"ns_0331", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Callbacks Rate'. ¿Qué inversión técnica es más efectiva?", opciones:["Programas de capacitación técnica continua y procesos de verificación en campo.", "Comprar herramientas de diagnóstico de marca premium para todos los técnicos.", "Aumentar el salario de los técnicos para que trabajen con más motivación.", "Contratar a un supervisor que revise físicamente cada trabajo terminado."], respuesta_correcta:0, explicacion:"La capacitación técnica continua y los procesos de verificación en campo atacan la causa raíz de los callbacks: falta de conocimiento o de un procedimiento estandarizado." },
  { id:"ns_0332", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 105 PSI y descarga de 480 PSI con R-410A. El subenfriamiento es 25°F. ¿Estado?", opciones:["Restricción en el dispositivo de expansión o en el filtro deshidratador.", "Exceso de carga de refrigerante que inunda el condensador del sistema.", "Falta de refrigerante que impide que la succión suba a niveles de diseño.", "Falla del ventilador del condensador que eleva la presión de descarga."], respuesta_correcta:0, explicacion:"Succión baja (105 PSI) con descarga muy alta (480 PSI) y subenfriamiento elevado (25°F) indica una restricción que acumula líquido antes del dispositivo de expansión. El filtro deshidratador tapado o la TXV restringida impiden el flujo, creando este patrón de presiones." },
  { id:"ns_0333", categoria:"NATE_SR_MINISPLIT", pregunta:"Un VRF tiene un error de 'Master/Slave Address Conflict'. ¿Cómo lo resuelve el Senior?", opciones:["Reiniciando los dip-switches de direccionamiento según el manual de fábrica.", "Cambiando el cable de comunicación por uno blindado en todas las unidades.", "Puenteando los terminales de comunicación en la unidad exterior temporalmente.", "Reemplazando la placa electrónica de la unidad que reporta el conflicto."], respuesta_correcta:0, explicacion:"El conflicto de direcciones Master/Slave se resuelve reiniciando los dip-switches de direccionamiento en cada unidad interior siguiendo el esquema del manual de fábrica para asignar direcciones únicas." },
  { id:"ns_0334", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo refrigeración, una bomba de calor tiene un sobrecalentamiento de 30°F. ¿Qué indica?", opciones:["Baja carga de refrigerante o una TXV que está fallando hacia cerrado.", "Exceso de carga de refrigerante que inunda el serpentín del evaporador.", "Operación normal para un día con carga térmica alta dentro del edificio.", "Que la válvula inversora está permitiendo un bypass interno de gas frío."], respuesta_correcta:0, explicacion:"Un sobrecalentamiento de 30F es muy alto (lo normal es 8-14F). Indica que el refrigerante se evapora demasiado pronto, tipicamente por falta de carga o una TXV que no abre lo suficiente." },
  { id:"ns_0335", categoria:"NATE_SR_RACK", pregunta:"Un rack de CO2 transcrítico tiene una presión de salida del gas cooler de 1400 PSI. ¿Es seguro?", opciones:["Sí, es una presión operativa estándar para sistemas de CO2 transcrítico.", "No, el switch de alta presión debería haber cortado el sistema a 1200 PSI.", "Depende de si el refrigerante se encuentra por encima del punto crítico.", "Solo si la temperatura del gas a la salida es inferior a los 80 grados F."], respuesta_correcta:0, explicacion:"Los sistemas de CO2 transcrítico operan normalmente con presiones de descarga entre 1100-1450 PSI. Los componentes están diseñados para estas presiones extremas, por lo que 1400 PSI está dentro del rango operativo estándar." },
  { id:"ns_0336", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un approach de evaporador de 8°F (nominal es 2°F). El Senior concluye:", opciones:["Tubos del evaporador sucios que requieren limpieza mecánica o química.", "El chiller tiene una sobrecarga de refrigerante que inunda el sistema.", "El flujo de agua es demasiado bajo para permitir una transferencia eficiente.", "Los sensores de temperatura están descalibrados y marcan valores altos."], respuesta_correcta:0, explicacion:"Un approach de evaporador de 8°F vs. nominal de 2°F indica fouling en los tubos que actúa como aislante térmico, reduciendo la transferencia de calor entre el refrigerante y el agua." },
  { id:"ns_0337", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que no puede hacer vacío porque la bomba tira humo. ¿Qué le dice el Senior?", opciones:["Es vapor de agua siendo evacuado; el aceite de la bomba debe cambiarse.", "La bomba se está quemando y debe ser apagada inmediatamente por seguridad.", "El sistema tiene una fuga masiva que permite la entrada de aire atmosférico.", "El humo es normal cuando se evacúan sistemas que usaron refrigerante R-22."], respuesta_correcta:0, explicacion:"El 'humo' de la bomba de vacío es vapor de agua que fue evacuado del sistema y contamina el aceite de la bomba. La solución es cambiar el aceite de la bomba (puede requerirse varias veces en sistemas muy húmedos) para restaurar su eficiencia." },
  { id:"ns_0338", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que el 'Account Receivable' es muy alto a más de 90 días. ¿Qué riesgo hay?", opciones:["Problemas de liquidez para pagar nóminas y falta de capital de trabajo.", "Necesidad de aumentar los precios para compensar el dinero no cobrado.", "Mejora en la relación con los clientes al darles plazos largos de pago.", "Aumento en el valor de la empresa al tener más facturación pendiente."], respuesta_correcta:0, explicacion:"Las cuentas por cobrar a más de 90 días representan un riesgo serio de liquidez; ese dinero no está disponible para nóminas ni capital de trabajo operativo." },
  { id:"ns_0339", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial tiene un Delta T de 12°F y alta succión. El compresor suena suave. ¿Causa?", opciones:["Compresor con eficiencia volumétrica baja (válvulas internas dañadas).", "Falta de refrigerante líquido que no permite el enfriamiento del aire.", "Exceso de flujo de aire a través del evaporador por un motor ECM.", "Válvula de expansión (TXV) bloqueada en la posición de cerrado total."], respuesta_correcta:0, explicacion:"Un Delta T bajo de 12°F con succión alta y compresor silencioso indica que el compresor no puede crear suficiente diferencial de presión. Las válvulas internas dañadas permiten que el gas recircule internamente, reduciendo la eficiencia volumétrica sin ruidos mecánicos evidentes." },
  { id:"ns_0340", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 20 toneladas tiene un Delta P de aceite bajo. ¿Qué revisa el Senior?", opciones:["Presencia de refrigerante líquido en el cárter que diluye el lubricante.", "Si el separador de aceite está retornando aceite al compresor equivocado.", "La presión de descarga del rack paralelo que alimenta a la unidad paquete.", "El ajuste de la válvula EPR que podría estar restringiendo el retorno de gas."], respuesta_correcta:0, explicacion:"La causa más común de Delta P de aceite bajo es la dilución del aceite por refrigerante líquido migrado al cárter. El refrigerante líquido reduce la viscosidad del aceite, impidiendo que la bomba genere la presión diferencial necesaria para lubricar los cojinetes del compresor." },
  { id:"ns_0341", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller centrífugo, ¿cuál es la función de la válvula de 'Economizador'?", opciones:["Mejorar la eficiencia mediante el enfriamiento del líquido por flash gas.", "Reducir el consumo eléctrico al apagar los ventiladores del condensador.", "Permitir que el compresor opere a velocidades más bajas sin entrar en surge.", "Controlar el flujo de agua helada que entra al intercambiador de calor."], respuesta_correcta:0, explicacion:"El economizador enfría el refrigerante líquido mediante flash gas a una presión intermedia, inyectando este gas al compresor en una etapa intermedia para mejorar la eficiencia del ciclo." },
  { id:"ns_0342", categoria:"NATE_SR_CEO", pregunta:"Un CEO busca implementar 'Dynamic Pricing' (Precios Dinámicos). ¿Cuál es la lógica?", opciones:["Ajustar los precios según la oferta, demanda y estacionalidad del mercado.", "Cobrar lo mismo a todos los clientes para mantener la equidad del negocio.", "Reducir los precios cada vez que un competidor lanza una oferta especial.", "Establecer precios fijos por contrato para asegurar ingresos a largo plazo."], respuesta_correcta:0, explicacion:"El Dynamic Pricing ajusta los precios según la oferta, la demanda y la estacionalidad, permitiendo maximizar ingresos en temporada alta y mantener volumen en temporada baja." },
  { id:"ns_0343", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Communication Error'. Los voltajes son correctos. ¿Qué revisa?", opciones:["Ruido electromagnético (EMI) causado por falta de tierra o cables de fuerza.", "La carga de refrigerante que podría estar afectando la placa electrónica.", "Si el control remoto tiene las baterías bajas y no envía la señal Wi-Fi.", "El capacitor de marcha del compresor que está interfiriendo con la señal."], respuesta_correcta:0, explicacion:"Si los voltajes de comunicación son correctos pero persiste el error, el ruido electromagnético (EMI) por falta de tierra o proximidad a cables de fuerza es la causa más probable de corrupción de la señal." },
  { id:"ns_0344", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor presenta una descarga de 550 PSI con R-410A. ¿Qué revisa?", opciones:["Filtro de aire interior sucio o flujo de aire de la manejadora muy bajo.", "Condensador exterior bloqueado por hielo o falla del ciclo de deshielo.", "Carga de refrigerante excesiva que está inundando el serpentín exterior.", "Válvula inversora que no logró cambiar completamente a la posición de calor."], respuesta_correcta:0, explicacion:"En modo calor, el serpentin interior es el condensador. Una descarga de 550 PSI indica que el condensador no puede rechazar el calor. Con filtro sucio o bajo flujo de aire interior, la presion de condensacion se eleva peligrosamente." },
  { id:"ns_0345", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué sucede si la válvula de retención de la descarga de un compresor falla?", opciones:["El refrigerante migrará al compresor parado, causando arranques inundados.", "La presión de succión aumentará en todo el sistema del rack de refrigeración.", "El aceite se quedará atrapado en el condensador y no regresará al rack.", "El compresor consumirá el doble de amperaje al intentar arrancar con carga."], respuesta_correcta:0, explicacion:"Sin la válvula de retención, el gas de alta presión del cabezal de descarga y el refrigerante del condensador migran hacia el compresor apagado. Al arrancar, el compresor intenta comprimir líquido, causando golpe de líquido (slugging)." },
  { id:"ns_0346", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Junior quiere usar sellador de fugas en un chiller de 500 toneladas. ¿Qué dice el Senior?", opciones:["Prohibido; el sellador puede obstruir los canales de aceite y dañar cojinetes.", "Adelante, siempre que sea una marca certificada por el fabricante del chiller.", "Solo si la fuga es menor a 5 libras por año según las normativas de la EPA.", "Se debe usar el doble de la dosis recomendada debido al volumen del sistema."], respuesta_correcta:0, explicacion:"En equipos de gran tonelaje como chillers, el sellador puede obstruir los canales de lubricación internos, los intercambiadores de calor y dañar los cojinetes del compresor. La fuga debe localizarse y repararse mecánicamente de forma profesional." },
  { id:"ns_0347", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Low Oil Pressure'. El nivel de aceite es normal. ¿Qué componente revisa?", opciones:["La bomba de aceite mecánica o el sensor diferencial de presión de aceite.", "El calentador de cárter que no está evaporando el refrigerante del aceite.", "El filtro de succión de refrigerante que tiene una caída de presión alta.", "La válvula de expansión que está alimentando líquido al cárter del motor."], respuesta_correcta:0, explicacion:"Con nivel de aceite normal, una baja presión de aceite apunta a la bomba de aceite mecánica que no genera presión suficiente, o al sensor diferencial de presión que está enviando lecturas erróneas." },
  { id:"ns_0348", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial tiene un 'Static Pressure' de 1.1 pulg. W.C. ¿Qué le sucede al motor PSC?", opciones:["Bajará sus RPM, reducirá el flujo de aire y el amperaje de consumo bajará.", "Aumentará la velocidad para compensar la presión estática del sistema.", "Se quemará instantáneamente debido al esfuerzo mecánico de la turbina.", "Consumirá más energía eléctrica para intentar mover el aire restringido."], respuesta_correcta:0, explicacion:"Los motores PSC son de velocidad fija determinada por la carga mecánica. Ante alta presión estática (restricción), la carga sobre el motor disminuye, haciendo que las RPM bajen, el flujo de aire se reduzca y el amperaje disminuya, opuesto al comportamiento de un ECM." },
  { id:"ns_0349", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir el 'Customer Satisfaction'. ¿Qué herramienta es la más estándar?", opciones:["Net Promoter Score (NPS) enviado tras finalizar cada orden de servicio.", "Contar el número de me gusta en las publicaciones de Facebook de la empresa.", "Verificar cuántas veces el cliente llamó para quejarse durante el último año.", "El margen de utilidad de cada contrato de mantenimiento preventivo vendido."], respuesta_correcta:0, explicacion:"El Net Promoter Score (NPS) enviado después de cada servicio es el estándar de la industria para medir satisfacción del cliente de forma cuantificable y comparable." },
  { id:"ns_0350", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-404A y las mirillas de las vitrinas tienen burbujas. El subenfriamiento es de 15°F. ¿Causa?", opciones:["Restricción en el filtro de la línea de líquido o antes de la mirilla.", "Falta de refrigerante líquido en el recibidor principal del sistema de rack.", "El ventilador del condensador está girando demasiado lento por un capacitor.", "Operación normal para sistemas de rack que usan tuberías de gran longitud."], respuesta_correcta:0, explicacion:"Con 15°F de subenfriamiento, hay suficiente líquido en el sistema. Las burbujas indican una caída de presión localizada antes de la mirilla, típicamente causada por un filtro deshidratador saturado que genera flash gas en ese punto." },
  { id:"ns_0351", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una caída de presión de agua baja en el evaporador. ¿Cómo afecta la capacidad?", opciones:["La capacidad disminuye debido a la baja transferencia térmica por falta de flujo.", "La capacidad aumenta ya que el refrigerante tiene más tiempo para enfriar.", "No afecta la capacidad, pero el compresor consumirá más energía eléctrica.", "El chiller entrará en modo de ahorro de energía automáticamente por control."], respuesta_correcta:0, explicacion:"Una baja caída de presión de agua indica bajo flujo, lo que reduce la velocidad del agua y la transferencia térmica. Con menos intercambio de calor, la capacidad de enfriamiento del chiller disminuye." },
  { id:"ns_0352", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no arranca y el LED parpadea 5 veces. ¿Qué hace el Senior?", opciones:["Consultar el manual técnico para descodificar el error específico del fabricante.", "Resetear el breaker y esperar a que el sistema se repare solo con el tiempo.", "Cambiar la placa exterior asumiendo que es una falla de comunicación común.", "Agregar 1 libra de refrigerante para ver si el error desaparece por presión."], respuesta_correcta:0, explicacion:"Los patrones de parpadeo del LED son códigos de diagnóstico específicos de cada fabricante. El Senior debe consultar el manual técnico para decodificar el error exacto antes de realizar cualquier reparación." },
  { id:"ns_0353", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene un Delta T de 25°F. El Senior sospecha de bajo flujo de aire. ¿Qué mide?", opciones:["La presión estática total externa (TESP) y el amperaje del motor del soplador.", "La temperatura de la línea de succión y el sobrecalentamiento del sistema.", "El subenfriamiento a la salida del condensador y la presión de descarga.", "La caída de voltaje entre los terminales L1 y L2 del contactor del compresor."], respuesta_correcta:0, explicacion:"La TESP (presión estática total externa) confirma directamente si hay restricciones en el sistema de conductos, y el amperaje del motor indica si está trabajando dentro de sus parámetros. Juntas, estas dos mediciones diagnostican problemas de flujo de aire de manera precisa." },
  { id:"ns_0354", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir la rotación de técnicos. ¿Cuál es el factor no económico más valorado?", opciones:["Equilibrio entre vida laboral y personal (horarios predecibles y guardias justas).", "Tener camionetas nuevas cada dos años con logotipos de diseño profesional.", "Organizar fiestas trimestrales para los empleados con asistencia obligatoria.", "Recibir uniformes de marca premium con bordados personalizados cada temporada."], respuesta_correcta:0, explicacion:"El equilibrio entre vida laboral y personal (horarios predecibles y guardias justas) es el factor no económico más valorado por los técnicos, por encima de beneficios materiales." },
  { id:"ns_0355", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿por qué la TXV exterior tiene una válvula de retención?", opciones:["Para permitir el flujo libre de refrigerante en modo refrigeración sin restricción.", "Para evitar que el aceite regrese al compresor cuando el sistema está apagado.", "Para proteger a la válvula de expansión de las presiones altas del modo calor.", "Para asegurar que el refrigerante líquido solo fluya en una dirección siempre."], respuesta_correcta:0, explicacion:"La check valve en paralelo con la TXV exterior permite que el refrigerante fluya libremente en modo refrigeracion (bypass a la TXV exterior), ya que en ese modo la expansion ocurre en la TXV interior." },
  { id:"ns_0356", categoria:"NATE_SR_RACK", pregunta:"Un rack tiene una presión de succión de 15 PSI con R-404A. Las vitrinas están a 40°F. ¿Problema?", opciones:["Presión de succión demasiado baja para vitrinas de media temperatura (media etapa).", "Funcionamiento correcto; la presión corresponde a la temperatura del producto.", "Falta de refrigerante líquido que impide que la presión de succión suba más.", "Válvulas de expansión de las vitrinas que están inyectando demasiado líquido."], respuesta_correcta:0, explicacion:"Con R-404A, 15 PSI corresponde a una temperatura de evaporación de aproximadamente -15°F, demasiado baja para vitrinas de media temperatura a 40°F. La presión de succión debería estar alrededor de 45-55 PSI para esa aplicación." },
  { id:"ns_0357", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un equipo en una obra grande. Nota que no usan arneses a 10 pies. ¿Acción?", opciones:["Detener el trabajo inmediatamente, colocar los arneses y dar una plática de seguridad.", "Anotar los nombres de los técnicos y reportarlos a la oficina al final del día.", "Pedirles que tengan cuidado y que se aseguren de terminar el trabajo rápido.", "Ignorar la situación si el cliente no está presente en el sitio de la obra hoy."], respuesta_correcta:0, explicacion:"OSHA requiere protección contra caídas a partir de 6 pies en construcción. A 10 pies, el incumplimiento es una violación grave. El líder debe detener el trabajo inmediatamente (stop work authority), corregir la situación y reforzar la seguridad." },
  { id:"ns_0358", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador de aire tiene un ventilador que vibra. ¿Qué daño Senior previene?", opciones:["Falla por fatiga del serpentín de aluminio y pérdida de refrigerante masiva.", "Aumento en el consumo eléctrico del motor del ventilador por desequilibrio.", "Reducción de la vida útil de los rodamientos del compresor de tornillo.", "Falsas alarmas de alta presión de condensación en el controlador central."], respuesta_correcta:0, explicacion:"La vibración de un ventilador del condensador enfriado por aire puede causar fatiga mecánica en las conexiones del serpentín de aluminio, resultando en grietas y pérdida masiva de refrigerante." },
  { id:"ns_0359", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial tiene una succión de 115 PSI y descarga de 450 PSI con R-410A. ¿Cómo está?", opciones:["Restricción en el lado de alta o condensador extremadamente sucio.", "Funcionamiento normal para un día caluroso con carga térmica estándar.", "Falta de refrigerante líquido que impide que la descarga baje a 300.", "Compresor con eficiencia reducida que no puede bombear correctamente."], respuesta_correcta:0, explicacion:"Con R-410A, succión de 115 PSI (~36°F sat.) con descarga de 450 PSI (~120°F sat.) muestra una descarga anormalmente alta. Esto indica una restricción en el lado de alta, como un condensador sucio que no disipa calor, elevando la presión de descarga." },
  { id:"ns_0360", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere aumentar el 'Customer Lifetime Value'. ¿Qué estrategia lanza?", opciones:["Contratos de mantenimiento preventivo con beneficios exclusivos y descuentos.", "Aumentar los precios de instalación para maximizar la ganancia del primer día.", "Eliminar el departamento de servicio para enfocarse solo en ventas de equipos.", "Reducir la garantía de mano de obra a 30 días para evitar gastos futuros."], respuesta_correcta:0, explicacion:"Los contratos de mantenimiento preventivo con beneficios exclusivos retienen al cliente por años, generando múltiples transacciones y maximizando el Customer Lifetime Value." },
  { id:"ns_0361", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se instalan válvulas solenoide en la línea de líquido de cada vitrina?", opciones:["Para controlar la temperatura de la vitrina mediante el corte del flujo de líquido.", "Para evitar que el aceite se acumule en el evaporador durante el funcionamiento.", "Para aumentar el subenfriamiento del refrigerante antes de entrar a la TXV.", "Para proteger al compresor de un posible retorno de líquido en el arranque."], respuesta_correcta:0, explicacion:"La válvula solenoide de líquido permite controlar la temperatura de cada vitrina individualmente. Cuando la vitrina alcanza la temperatura deseada, la solenoide corta el flujo de refrigerante, implementando un control por pump-down del circuito." },
  { id:"ns_0362", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Low Evaporator Temp' constante. ¿Qué revisa el Senior?", opciones:["Flujo de agua helada insuficiente o sensor de temperatura mal ubicado.", "Carga de refrigerante excesiva que está inundando el intercambiador.", "Válvula de expansión electrónica bloqueada en la posición de abierta total.", "Si la torre de enfriamiento está enviando agua demasiado fría al condensador."], respuesta_correcta:0, explicacion:"Una falla constante de baja temperatura del evaporador indica flujo de agua insuficiente (el agua se enfría demasiado) o un sensor de temperatura mal ubicado que lee valores incorrectos." },
  { id:"ns_0363", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter muestra el error 'H6' (Indoor Fan Motor error). ¿Qué prueba?", opciones:["Si el ventilador gira libremente y la señal de voltaje de la placa interior.", "El capacitor de arranque del motor del ventilador de la unidad exterior.", "La carga de refrigerante que podría estar bloqueando el flujo de aire interior.", "La continuidad de los cables de comunicación entre la unidad interior y exterior."], respuesta_correcta:0, explicacion:"El error H6 indica fallo del motor del ventilador interior. El Senior verifica que el ventilador gire libremente (sin obstrucción) y mide el voltaje que la placa interior envía al motor DC." },
  { id:"ns_0364", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, el ciclo de deshielo dura el tiempo máximo y no quita el hielo. ¿Causa?", opciones:["El ventilador exterior no se detuvo o la válvula inversora no cambió a frío.", "La carga de refrigerante es demasiado alta y el serpentín no se calienta.", "Las resistencias eléctricas no encendieron durante el proceso de descongelado.", "El sensor de temperatura de deshielo está ubicado en la línea de succión."], respuesta_correcta:0, explicacion:"Para un deshielo efectivo, el ventilador exterior debe detenerse y la valvula inversora debe cambiar a modo refrigeracion para enviar gas caliente al serpentin exterior. Si alguno falla, el hielo no se derrite." },
  { id:"ns_0365", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que el 'Direct Labor Cost' es el 40% de los ingresos. ¿Cómo lo interpreta?", opciones:["Es un costo alto que indica ineficiencia operativa o falta de facturación.", "Es un porcentaje excelente que asegura una rentabilidad neta superior al 20%.", "Indica que los técnicos están vendiendo muchos accesorios y planes de servicio.", "Es un valor irrelevante si el margen bruto de los materiales es superior al 50%."], respuesta_correcta:0, explicacion:"Un Direct Labor Cost del 40% es alto para la industria HVAC (ideal: 25-30%); indica que los técnicos están poco ocupados o que los precios de venta son insuficientes." },
  { id:"ns_0366", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-404A. Se detecta una fuga ácida. ¿Qué acción técnica es mandatoria?", opciones:["Cambiar el aceite, instalar filtros de succión de limpieza y neutralizadores.", "Simplemente reparar la fuga y completar la carga con refrigerante virgen.", "Drenar el refrigerante y cargarlo de nuevo tras hacer un vacío de 24 horas.", "Agregar un aditivo sellador de fugas que también neutralice la acidez del POE."], respuesta_correcta:0, explicacion:"La acidez en el sistema indica descomposición del aceite o contaminación. Es mandatorio cambiar el aceite contaminado, instalar filtros de succión de limpieza (burnout filters) y neutralizadores de ácido para remover los contaminantes y proteger los compresores." },
  { id:"ns_0367", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que no tiene la herramienta para medir micrones. ¿Qué hace el Senior?", opciones:["Prohibir que termine el vacío y enviarle un vacuómetro digital de inmediato.", "Decirle que deje la bomba encendida por 4 horas y asuma que está a 500.", "Pedirle que use el manómetro analógico y vea si la aguja baja del cero.", "Sugiere que use un poco de refrigerante para barrer la humedad del sistema."], respuesta_correcta:0, explicacion:"Sin un vacuómetro digital (micron gauge) es imposible verificar que el sistema alcanzó 500 micrones o menos. Asumir el vacío sin medirlo es una práctica irresponsable que puede dejar humedad en el sistema y causar fallas prematuras." },
  { id:"ns_0368", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una aproximación de evaporador de 0°F. ¿Qué sospecha el Senior?", opciones:["Falla de calibración del transductor de presión o del sensor de temperatura.", "El chiller está operando en el punto de diseño perfecto del fabricante.", "El flujo de agua es tan alto que no permite que el refrigerante se evapore.", "El compresor centrífugo está operando a su máxima velocidad de rotación."], respuesta_correcta:0, explicacion:"Un approach de evaporador de 0°F es termodinámicamente improbable. Indica falla de calibración en el transductor de presión o sensor de temperatura que genera lecturas inconsistentes." },
  { id:"ns_0369", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 125 PSI y descarga de 380 PSI con R-410A. El subenfriamiento es 5°F. ¿Causa?", opciones:["Falta de refrigerante líquido en el sistema (undercharged).", "Válvula de expansión (TXV) fallida en la posición de abierta total.", "Condensador exterior sucio que no permite el intercambio térmico.", "Evaporador interior congelado que restringe la absorción de calor."], respuesta_correcta:0, explicacion:"Un subenfriamiento de solo 5°F con R-410A indica que el condensador no tiene suficiente líquido para subenfriarlo adecuadamente. Esto es señal clásica de falta de carga (undercharged), donde no hay suficiente refrigerante para llenar completamente el condensador." },
  { id:"ns_0370", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el serpentín del evaporador se congela. El ventilador funciona bien. ¿Siguiente paso?", opciones:["Verificar la carga de refrigerante y si la TXV está operando correctamente.", "Instalar un termostato de descongelación para que pare el compresor.", "Reemplazar el motor del soplador por uno de mayor caballaje total.", "Agregar refrigerante hasta que la presión de succión suba a 140 PSI."], respuesta_correcta:0, explicacion:"Con el ventilador funcionando correctamente, la congelación se debe a una temperatura de evaporación demasiado baja. Esto ocurre por carga baja de refrigerante o una TXV que restringe el flujo. Verificar ambas condiciones permite identificar la causa raíz antes de actuar." },
  { id:"ns_0371", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la 'Productividad Técnica'. ¿Cuál es la fórmula correcta?", opciones:["Horas facturadas al cliente divididas entre las horas totales pagadas al técnico.", "Ingresos totales del mes divididos entre el número de técnicos en la nómina.", "Cantidad de reparaciones terminadas dividida entre el costo de los materiales.", "Número de millas recorridas divididas entre el número de llamadas de servicio."], respuesta_correcta:0, explicacion:"La Productividad Técnica se calcula dividiendo las horas facturadas al cliente entre las horas totales pagadas, mostrando qué porcentaje del tiempo genera ingresos directos." },
  { id:"ns_0372", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si la válvula de bypass de gas caliente falla abierta?", opciones:["La presión de succión subirá y los compresores se sobrecalentarán rápido.", "El rack se bloqueará por baja presión al no retornar gas a la succión.", "El nivel de aceite en el separador bajará drásticamente de forma continua.", "Las vitrinas se congelarán debido al exceso de calor en el evaporador."], respuesta_correcta:0, explicacion:"Con la válvula de bypass abierta permanentemente, gas caliente de descarga recircula directamente a la succión, elevando la presión y temperatura. Los compresores trabajan recirculando gas caliente sin enfriar, sobrecalentándose rápidamente." },
  { id:"ns_0373", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un approach de condensador de 15°F. ¿Qué acción toma el Senior?", opciones:["Limpieza de tubos del condensador y verificar el tratamiento de agua de torre.", "Agregar más refrigerante líquido para bajar la temperatura de aproximación.", "Aumentar el set-point de la temperatura del agua de la torre a 90 grados.", "Reducir la velocidad de la bomba de condensador para estabilizar el flujo."], respuesta_correcta:0, explicacion:"Un approach de condensador de 15°F indica fouling severo en los tubos. La limpieza mecánica y la verificación del tratamiento químico del agua de torre son las acciones correctivas prioritarias." },
  { id:"ns_0374", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no enfría. Al medir voltaje entre S1 y S2 hay 240VAC. ¿Conclusión?", opciones:["La alimentación eléctrica de la unidad exterior es correcta.", "Hay una falla de comunicación masiva entre las dos unidades.", "El fusible de la placa electrónica exterior está fundido.", "El compresor inverter está aterrizado y consume voltaje."], respuesta_correcta:0, explicacion:"Un voltaje de 240VAC entre S1 y S2 confirma que la alimentación eléctrica llega correctamente a la unidad exterior. El problema de enfriamiento debe buscarse en otra parte del sistema." },
  { id:"ns_0375", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿cuál es el propósito del 'Accumulator'?", opciones:["Evitar que el refrigerante líquido entre al compresor y lo dañe mecánicamente.", "Almacenar el exceso de aceite del sistema durante el modo de calefacción.", "Aumentar la presión de succión mediante el recalentamiento del gas frío.", "Separar los incondensables del refrigerante antes de entrar a la descarga."], respuesta_correcta:0, explicacion:"El acumulador de succion es un tanque antes del compresor que atrapa refrigerante liquido, permitiendo que solo vapor entre al compresor. Protege contra slugging (golpe de liquido) que danaria las valvulas o scrolls." },
  { id:"ns_0376", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un cliente se queja de un olor a quemado tras un mantenimiento. ¿Qué debe hacer el Senior?", opciones:["Regresar al sitio inmediatamente, inspeccionar cables y motores por seguridad.", "Decirle al cliente que es normal que los aceites de limpieza huelan así.", "Pedirle al cliente que apague el sistema y que llame en 24 horas si sigue el olor.", "Preguntar al técnico que realizó el trabajo si dejó algo mal conectado ayer."], respuesta_correcta:0, explicacion:"Un olor a quemado después de un mantenimiento puede indicar un cable suelto, un motor trabado o un componente eléctrico fallando. Es una emergencia potencial que requiere inspección inmediata para prevenir incendios o daños mayores." },
  { id:"ns_0377", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Pumping' o 'Surge'. ¿Cómo se ajusta operativamente?", opciones:["Bajando la presión de descarga o aumentando el flujo de gas por el impulsor.", "Incrementando la velocidad de la bomba de agua helada del edificio.", "Cerrando la válvula de expansión para reducir la masa de refrigerante.", "Aumentando la temperatura del agua de la torre para subir la descarga."], respuesta_correcta:0, explicacion:"El surge se corrige reduciendo la relación de presiones (lift). Bajar la presión de descarga (limpiar condensador, mejorar agua de torre) o aumentar el flujo de gas por el impulsor estabiliza la operación." },
  { id:"ns_0378", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial tiene una succión de 145 PSI y descarga de 380 PSI. El sobrecalentamiento es 0°F. ¿Causa?", opciones:["Válvula de expansión (TXV) fallida en la posición de abierta total.", "Falta de refrigerante líquido que impide que la descarga suba más.", "Evaporador interior con flujo de aire extremadamente alto (motor ECM).", "Compresor perdiendo eficiencia volumétrica por desgaste de pistones."], respuesta_correcta:0, explicacion:"Succión alta de 145 PSI con sobrecalentamiento de 0°F significa que el evaporador está completamente inundado de líquido y el refrigerante no se evapora totalmente. Una TXV fallida en posición abierta permite el paso descontrolado de líquido, causando flood-back al compresor." },
  { id:"ns_0379", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere expandirse a 'Industrial Chillers'. ¿Qué inversión es la más crítica?", opciones:["Equipos de izaje pesados, herramientas láser de alineación y técnicos Senior.", "Comprar una flota de camionetas pequeñas para facilitar el estacionamiento.", "Invertir en publicidad en redes sociales enfocada en clientes residenciales.", "Contratar a más personal de ventas para vender planes de mantenimiento básicos."], respuesta_correcta:0, explicacion:"Los chillers industriales requieren equipos de izaje pesado, herramientas de alineación láser y técnicos Senior con experiencia en sistemas de alta capacidad y complejidad." },
  { id:"ns_0380", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué sucede si la válvula de retención del separador de aceite falla abierta?", opciones:["El aceite y gas de descarga regresarán a los compresores durante el paro.", "La presión de succión bajará tanto que el rack se bloqueará por seguridad.", "El nivel de aceite en el depósito subirá por encima de la mirilla superior.", "Las vitrinas dejarán de enfriar debido a la falta de diferencial de presión."], respuesta_correcta:0, explicacion:"La válvula check del separador evita el flujo inverso durante el paro. Si falla abierta, el gas de alta presión y el aceite del depósito pueden regresar hacia los compresores, causando migración de refrigerante e inundación de los cárteres." },
  { id:"ns_0381", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Unbalance' del 4%. ¿Qué riesgo técnico existe?", opciones:["Sobrecalentamiento excesivo del motor del compresor y fallo prematuro.", "El chiller funcionará al 96% de su capacidad nominal sin riesgo alguno.", "La unidad de purga empezará a operar para compensar el desequilibrio.", "La válvula de expansión se cerrará para proteger el circuito eléctrico."], respuesta_correcta:0, explicacion:"Un desbalance de voltaje del 4% puede causar un aumento de corriente de hasta 25% en una fase del motor, generando sobrecalentamiento excesivo y reducción drástica de la vida útil del motor." },
  { id:"ns_0382", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua por la unidad interior. El drenaje está libre. ¿Causa?", opciones:["Carga de refrigerante baja que causa escarcha parcial y goteo fuera de bandeja.", "La bomba de condensado integrada tiene el flotador pegado en posición alta.", "El ventilador interior está girando tan rápido que succiona el agua del serpentín.", "La humedad relativa de la habitación es superior al 95% y condensa en chasis."], respuesta_correcta:0, explicacion:"Con el drenaje libre, una carga baja de refrigerante causa escarcha parcial e irregular en el serpentín. Al derretirse, el agua cae fuera de la bandeja de condensado, goteando dentro de la habitación." },
  { id:"ns_0383", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de retorno de 0.6 pulg. W.C. El diseño es 0.2. ¿Consecuencia?", opciones:["Ruido excesivo, bajo flujo de aire y posible falla del motor del soplador.", "Aumento en la eficiencia del intercambio de calor por la velocidad del aire.", "Menor consumo eléctrico del motor al tener una restricción en la succión.", "Mejora en la deshumidificación del ambiente al pasar el aire más lento."], respuesta_correcta:0, explicacion:"Una presión estática de retorno de 0.6\" W.C. cuando el diseño es 0.2\" representa el triple de la restricción permitida. Esto causa ruido por turbulencia, reducción severa del flujo de aire, y estrés mecánico y eléctrico sobre el motor del soplador que puede provocar su falla." },
  { id:"ns_0384", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Check Valve' de la unidad interior falla abierta?", opciones:["En modo refrigeración, el refrigerante hará bypass a la TXV y no enfriará.", "En modo calefacción, el sistema se bloqueará por alta presión de descarga.", "El aceite se quedará atrapado en el evaporador y el compresor fallará.", "La válvula inversora no podrá cambiar de posición por falta de diferencial."], respuesta_correcta:0, explicacion:"La check valve interior esta en paralelo con la TXV interior. Si falla abierta, en modo refrigeracion el refrigerante hace bypass a la TXV y fluye sin restriccion, eliminando la caida de presion necesaria para enfriar." },
  { id:"ns_0385", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior observa que un Junior no usa 'Brazing Shield' al soldar. ¿Riesgo?", opciones:["Daño térmico a componentes sensibles como válvulas o aislamiento de cables.", "Que la soldadura de plata no se adhiera correctamente por falta de calor.", "Aumento del consumo de oxígeno y acetileno durante el proceso de soldadura.", "La formación de óxido en la superficie externa de la tubería de cobre."], respuesta_correcta:0, explicacion:"El brazing shield protege componentes cercanos del calor radiante de la antorcha. Sin él, válvulas, aislamiento de cables eléctricos y otros componentes sensibles al calor pueden dañarse irreversiblemente durante la soldadura." },
  { id:"ns_0386", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de temperatura de 'Leaving Water' descalibrado (marca menos). ¿Riesgo?", opciones:["Congelación de los tubos del evaporador debido a un set-point real bajo.", "El compresor se apagará por alta presión antes de alcanzar la temperatura.", "La unidad de purga operará innecesariamente expulsando gas al ambiente.", "Aumento en el consumo de energía eléctrica por ciclos de carga excesivos."], respuesta_correcta:0, explicacion:"Si el sensor de leaving water marca menos de lo real, el controlador cree que el agua está más fría y sigue enfriando. Esto baja la temperatura real por debajo del diseño, arriesgando congelación de tubos." },
  { id:"ns_0387", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué indica una temperatura de descarga de 250°F constante?", opciones:["Problema grave de sobrecalentamiento de succión o falla interna del compresor.", "Operación normal para un rack que usa R-404A en condiciones de carga alta.", "Que el enfriador de aceite del rack paralelo está funcionando perfectamente.", "Falta de refrigerante líquido en el recibidor que impide el enfriamiento."], respuesta_correcta:0, explicacion:"Para R-404A, la temperatura de descarga normal es de 150-200°F. Una temperatura constante de 250°F indica un sobrecalentamiento de succión severo o válvulas de plato dañadas en el compresor, requiriendo atención inmediata." },
  { id:"ns_0388", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere aumentar el 'Referral Rate'. ¿Qué acción es la más efectiva?", opciones:["Ofrecer una recompensa o descuento tanto al que refiere como al nuevo cliente.", "Pagar por anuncios en el periódico local para que la gente conozca la marca.", "Reducir el precio de todos los servicios para que los clientes hablen bien.", "Contratar a un vendedor de puerta en puerta para buscar clientes referidos."], respuesta_correcta:0, explicacion:"Un programa de referidos que recompensa tanto al cliente que refiere como al nuevo cliente crea un incentivo bilateral que multiplica las recomendaciones de forma orgánica." },
  { id:"ns_0389", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta una vibración en la frecuencia de paso de álabes. ¿Causa?", opciones:["Alineación incorrecta del impulsor o flujo de gas turbulento en la entrada.", "Desgaste natural de los cojinetes de rodillos del motor de alta velocidad.", "Falta de aceite en el sistema de lubricación por inyección del compresor.", "El variador de frecuencia está generando armónicos que afectan al motor."], respuesta_correcta:0, explicacion:"La vibración en la frecuencia de paso de álabes (blade pass frequency) indica una alineación incorrecta del impulsor o flujo turbulento en la entrada que genera pulsaciones a la frecuencia de los álabes." },
  { id:"ns_0390", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 420 PSI. El aire sale a 65°F. ¿Problema?", opciones:["Bajo flujo de aire o carga de refrigerante ligeramente baja.", "Funcionamiento normal considerando la temperatura exterior de 100 grados.", "Exceso de carga de refrigerante que inunda el serpentín del condensador.", "Compresor con válvulas dañadas que no logran enfriar el aire de suministro."], respuesta_correcta:0, explicacion:"Temperatura de suministro de 65°F es alta (debería ser ~55°F), y la descarga de 420 PSI es elevada con succión de 110 PSI. Bajo flujo de aire o falta leve de carga explican por qué el evaporador no enfría el aire suficientemente mientras la descarga está elevada." },
  { id:"ns_0391", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Profit Margin' de las reparaciones. ¿Qué debe auditar?", opciones:["El 'Mark-up' aplicado a las piezas de repuesto y el tiempo de mano de obra.", "El costo del alquiler de la oficina administrativa central de la empresa.", "La cantidad de uniformes que se compran para los técnicos nuevos cada año.", "El número de seguidores que interactúan con la marca en redes sociales."], respuesta_correcta:0, explicacion:"Para mejorar el margen de reparaciones, el CEO debe auditar el mark-up aplicado a piezas y el tiempo de mano de obra cobrado, ya que son los dos componentes directos del precio." },
  { id:"ns_0392", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no enfría. El compresor exterior no arranca pero el ventilador sí. ¿Prueba?", opciones:["Medir resistencia de las bobinas del compresor y voltaje DC de la placa.", "Cambiar el capacitor de arranque por uno de mayor capacidad inmediatamente.", "Puentear el interruptor de alta presión para ver si el compresor enciende.", "Agregar 2 libras de refrigerante R-410A para descartar una fuga total."], respuesta_correcta:0, explicacion:"Cuando el ventilador exterior funciona pero el compresor no arranca, el Senior mide la resistencia de las bobinas U, V, W del compresor y el voltaje DC que la placa IPM envía al motor para aislar la falla." },
  { id:"ns_0393", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el sensor de temperatura exterior falla en corto?", opciones:["El sistema podría bloquear la calefacción auxiliar o el ciclo de deshielo.", "El compresor se quemará debido a la falta de control de sobrecalentamiento.", "La unidad operará solo en modo refrigeración permanentemente por seguridad.", "El ventilador exterior girará en sentido contrario para proteger el serpentín."], respuesta_correcta:0, explicacion:"Si el sensor de temperatura exterior falla en corto (lee como muy caliente), el sistema podria bloquear la calefaccion auxiliar y no iniciar el defrost, creyendo que no hay condiciones de congelamiento." },
  { id:"ns_0394", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿por qué se usa una válvula 'Check' en la succión de cada compresor?", opciones:["Para evitar que el aceite y refrigerante migren al compresor que está apagado.", "Para aumentar la presión de succión y mejorar la eficiencia del sistema total.", "Para permitir que los compresores arranquen sin carga durante los deshielos.", "Para proteger al separador de aceite de las pulsaciones de gas de la succión."], respuesta_correcta:0, explicacion:"La válvula check en la succión previene la migración de aceite y refrigerante hacia un compresor apagado a través del cabezal de succión común. Sin ella, el refrigerante se condensa en el cárter frío del compresor parado." },
  { id:"ns_0395", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un plano donde el retorno de aire está en la cocina. ¿Qué hace?", opciones:["Solicita el cambio de ubicación del retorno para evitar olores y grasa en el equipo.", "Instala el retorno en la cocina pero añade un filtro de carbón activado extra.", "Sigue el plano del arquitecto para no tener problemas de diseño legal después.", "No hace nada, ya que la cocina es el lugar donde más calor se genera siempre."], respuesta_correcta:0, explicacion:"Un retorno de aire en la cocina absorbe grasa, olores y humedad que contaminarán el serpentín del evaporador y se distribuirán por toda la casa. Es un error de diseño grave que debe corregirse reubicando el retorno." },
  { id:"ns_0396", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Water Flow' intermitente. El filtro está limpio. ¿Qué revisa?", opciones:["El interruptor de flujo (Paddle switch) o el transductor diferencial de presión.", "La velocidad del motor del compresor centrífugo en el panel de control.", "Si la válvula de expansión electrónica está inyectando líquido al sistema.", "La carga de refrigerante líquido basándose en la mirilla del evaporador."], respuesta_correcta:0, explicacion:"Una falla intermitente de flujo de agua con filtro limpio apunta al interruptor de flujo (paddle switch) desgastado o al transductor diferencial de presión descalibrado que genera falsas alarmas." },
  { id:"ns_0397", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 120 PSI y descarga de 410 PSI. El subenfriamiento es 10°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y subenfriamiento son los correctos.", "Falta de refrigerante líquido; el subenfriamiento debería ser de 15 grados.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno.", "Compresor fallando; el diferencial de presión es insuficiente para enfriar."], respuesta_correcta:0, explicacion:"Con R-410A, succión de 120 PSI (~38°F sat.), descarga de 410 PSI (~112°F sat.) y subenfriamiento de 10°F están dentro de rangos aceptables para operación en un día moderadamente caluroso. El sistema funciona correctamente con carga de refrigerante adecuada." },
  { id:"ns_0398", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el motor del soplador consume más amperaje del de placa. ¿Causa?", opciones:["Presión estática del sistema muy baja (conductos abiertos o filtros faltantes).", "Filtros de aire extremadamente sucios que restringen el flujo de aire total.", "El motor es del tipo ECM y está compensando la suciedad del serpentín.", "Las rejillas de suministro están cerradas, aumentando la contrapresión interna."], respuesta_correcta:0, explicacion:"Un motor PSC consume más amperaje con menor restricción (presión estática baja). Sin filtros o con conductos abiertos/desconectados, el motor mueve más aire del diseñado, lo que aumenta la carga en el eje y el consumo eléctrico por encima del amperaje de placa." },
  { id:"ns_0399", categoria:"NATE_SR_CEO", pregunta:"Un CEO debe asegurar que su empresa cumpla con la ley OSHA 1910.1200. ¿Qué regula?", opciones:["La comunicación de peligros y el manejo de hojas de datos de seguridad (SDS).", "El pago de horas extras y beneficios sociales a los empleados de campo.", "La certificación de los recipientes de recuperación de gas refrigerante.", "El uso obligatorio de uniformes ignífugos en todas las instalaciones HVAC."], respuesta_correcta:0, explicacion:"OSHA 1910.1200 (HazCom) regula la comunicación de peligros químicos y exige que la empresa tenga hojas de datos de seguridad (SDS) accesibles para todos los empleados." },
  { id:"ns_0400", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-407A y tiene una fuga en la línea de líquido. El técnico quiere completar carga. ¿Riesgo?", opciones:["Fraccionamiento de la mezcla; la eficiencia y presiones serán incorrectas.", "El refrigerante se volverá inflamable al perder uno de sus componentes gaseosos.", "El aceite se separará del refrigerante y los compresores se bloquearán pronto.", "No hay riesgo; el R-407A es una mezcla azeotrópica que no se fracciona."], respuesta_correcta:0, explicacion:"El R-407A es una mezcla zeotrópica (no azeotrópica) con un glide significativo. Durante una fuga, los componentes más volátiles escapan primero, alterando la composición. Completar la carga no restaura la proporción original; se debe recuperar y recargar." },
  { id:"ns_0401", categoria:"NATE_SR_PACKAGE", pregunta:"En un sistema de enfriamiento para Data Center (CRAC), se observa que el calor sensible es muy alto pero la humedad relativa cae al 20%. ¿Qué acción debe tomar el Senior?", opciones:["Activar el sistema de humidificación y verificar el sellado del piso falso.", "Aumentar el flujo de aire del soplador para reducir la temperatura de salida.", "Reducir la carga de refrigerante para permitir que el serpentín deshumidifique menos.", "Instalar un variador de frecuencia en el compresor para modular la capacidad térmica."], respuesta_correcta:0, explicacion:"En Data Centers, la humedad relativa baja (20%) crea riesgo de descarga electrostática que puede dañar servidores. Se debe activar la humidificación integrada del CRAC y verificar el sellado del piso falso, ya que fugas de aire permiten la pérdida de humedad controlada." },
  { id:"ns_0402", categoria:"NATE_SR_RACK", pregunta:"Se detecta que un rack paralelo tiene una presión de succión superior a la de saturación de todas las vitrinas conectadas. ¿Qué indica este fenómeno?", opciones:["Falla en el controlador del rack o compresores insuficientes para la carga actual.", "Las válvulas EPR están todas cerradas bloqueando el retorno de gas al cabezal.", "Existe una fuga masiva de refrigerante en el lado de alta presión del sistema.", "El separador de aceite está inundado y devuelve líquido a la línea de succión."], respuesta_correcta:0, explicacion:"Si la presión de succión es más alta que la saturación de las vitrinas, los compresores no están removiendo suficiente gas. Esto indica que el controlador no está activando suficientes compresores, o los compresores no tienen capacidad para manejar la carga térmica." },
  { id:"ns_0403", categoria:"NATE_SR_CEO", pregunta:"Durante una ola de calor, el 30% de la flota de la empresa falla mecánicamente. Desde la posición de CEO, ¿cuál es la prioridad inmediata?", opciones:["Alquilar unidades temporales y priorizar llamadas de emergencia sobre mantenimientos.", "Sancionar al jefe de taller por la falta de mantenimiento preventivo en los vehículos.", "Cancelar todas las citas y esperar a que las camionetas sean reparadas por la agencia.", "Aumentar los precios de emergencia para compensar el costo del alquiler de transporte."], respuesta_correcta:0, explicacion:"En una crisis de flota durante temporada alta, la prioridad es alquilar unidades temporales y priorizar emergencias sobre mantenimientos para no perder ingresos críticos." },
  { id:"ns_0404", categoria:"NATE_SR_MINISPLIT", pregunta:"Al trabajar con refrigerantes A2L (como R-454B o R-32), ¿qué herramienta es técnicamente obligatoria para el Senior?", opciones:["Bomba de vacío y recuperadora con motores a prueba de chispas (Spark-proof).", "Manómetros analógicos de alta presión con mangueras de 1/2 pulgada de diámetro.", "Detector de fugas ultrasónico calibrado específicamente para gases de efecto invernadero.", "Báscula digital con precisión de miligramos para cargas críticas de micro-gramos."], respuesta_correcta:0, explicacion:"Los refrigerantes A2L como R-32 y R-454B son levemente inflamables. Las herramientas con motores a prueba de chispas (spark-proof) son obligatorias para evitar la ignición durante la manipulación." },
  { id:"ns_0405", categoria:"NATE_SR_HVAC", pregunta:"Un sistema comercial con VAV (Variable Air Volume) tiene cajas que no abren. El ventilador principal está al 100%. ¿Qué revisa el Senior?", opciones:["El sensor de presión estática del conducto principal y su punto de consigna (set-point).", "El amperaje del motor del soplador para asegurar que no esté sobrecargado.", "Si el termostato de la zona está enviando una señal de 24V al actuador del damper.", "La carga de refrigerante del chiller que alimenta el serpentín de agua helada."], respuesta_correcta:0, explicacion:"En un sistema VAV, el sensor de presión estática controla la velocidad del ventilador principal. Si el sensor está descalibrado o su set-point es incorrecto, el ventilador opera al 100% intentando alcanzar una presión que no corresponde, independientemente de que las cajas no abran." },
  { id:"ns_0406", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor tiene una succión de 80 PSI y descarga de 550 PSI con R-410A. El aire interior es de 70°F. ¿Causa?", opciones:["Restricción en la válvula de expansión de la unidad exterior o falta de carga.", "Condensador interior extremadamente sucio que eleva la presión de descarga.", "Válvula inversora con fuga interna que permite el paso de gas a la succión.", "Falla del ventilador exterior que impide la absorción de calor ambiental."], respuesta_correcta:0, explicacion:"Succion baja (80 PSI) indica poca absorcion de calor exterior, y descarga alta (550 PSI) indica problemas de condensacion interior. La causa es restriccion en la TXV exterior o falta de carga de refrigerante." },
  { id:"ns_0407", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un líder de cuadrilla nota que un técnico usa un cilindro de nitrógeno sin regulador de presión. ¿Cuál es el riesgo técnico inmediato?", opciones:["Explosión del serpentín o componentes del sistema debido a la presión extrema (2000+ PSI).", "Contaminación del sistema con nitrógeno impuro al no estar regulado el flujo.", "Daño a las válvulas de servicio por la velocidad del gas al entrar al sistema.", "Congelación de las tuberías de cobre por la expansión adiabática del nitrógeno seco."], respuesta_correcta:0, explicacion:"Un cilindro de nitrógeno contiene presiones de 2000+ PSI. Sin regulador, esa presión entra directamente al sistema diseñado para presiones mucho menores, lo que puede causar una explosión catastrófica de serpentines, tuberías o componentes." },
  { id:"ns_0408", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller de absorción de Bromuro de Litio, se pierde el vacío. ¿Cuál es el síntoma operativo primario?", opciones:["Cristalización inmediata de la solución y paro total del sistema por seguridad.", "Aumento en el consumo de vapor o agua caliente para mantener la capacidad.", "Reducción en el flujo de agua helada a través del intercambiador secundario.", "El refrigerante (agua) empieza a hervir a una temperatura mucho más alta."], respuesta_correcta:0, explicacion:"En chillers de absorción con LiBr, la pérdida de vacío (entrada de aire) interfiere directamente con el proceso de absorción, causando cristalización inmediata de la solución y paro por seguridad." },
  { id:"ns_0409", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete industrial muestra un error de 'Phase Loss'. Al medir, las tres fases tienen 460V, pero el error persiste. ¿Qué sigue?", opciones:["Verificar el desequilibrio de voltaje y el monitor de fases (Phase Monitor) defectuoso.", "Reemplazar el contactor del compresor asumiendo que un polo está carbonizado.", "Cambiar los fusibles de potencia por unos de mayor capacidad de respuesta rápida.", "Resetear la placa de control desconectando el transformador de 24V por un minuto."], respuesta_correcta:0, explicacion:"Aunque las tres fases muestran 460V, un desequilibrio de voltaje entre fases (>2%) puede activar el error de Phase Loss. También el monitor de fases (Phase Monitor) puede estar defectuoso y generar falsas alarmas. Se debe medir el desequilibrio porcentual y probar el monitor." },
  { id:"ns_0410", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa el 'LTV' (Lifetime Value) frente al 'CAC' (Customer Acquisition Cost). ¿Cuál es la proporción ideal para un negocio HVAC saludable?", opciones:["LTV debe ser al menos 3 veces superior al CAC para asegurar rentabilidad y crecimiento.", "LTV y CAC deben ser iguales para garantizar que la empresa no pierda dinero.", "CAC debe ser superior al LTV en los primeros 5 años para ganar cuota de mercado.", "No existe relación entre ambos; el único dato relevante es la facturación bruta anual."], respuesta_correcta:0, explicacion:"La proporción ideal LTV:CAC es de al menos 3:1; esto significa que cada cliente debe generar al menos 3 veces lo que costó adquirirlo para asegurar rentabilidad sostenible." },
  { id:"ns_0411", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Oil Foaming' excesivo en el cárter tras un periodo de paro. ¿Cuál es la causa raíz Senior?", opciones:["Falla del calentador de cárter que permitió la saturación de refrigerante en el aceite.", "Uso de un aceite con viscosidad incorrecta para la presión operativa del sistema.", "Arranque del compresor con una carga térmica en el evaporador excesivamente alta.", "La unidad de purga está devolviendo refrigerante líquido directamente al depósito de aceite."], respuesta_correcta:0, explicacion:"Si el calentador de cárter falla durante el paro, el refrigerante migra y se disuelve en el aceite. Al arrancar, la caída de presión causa evaporación súbita del refrigerante, generando espuma excesiva." },
  { id:"ns_0412", categoria:"NATE_SR_RACK", pregunta:"En un rack con condensación por aire, el subenfriamiento es de 25°F pero la presión de descarga es baja. ¿Qué indica?", opciones:["Exceso de carga de refrigerante atrapado en el condensador durante clima frío.", "Funcionamiento eficiente del sistema gracias a la baja temperatura ambiente.", "Restricción en la línea de descarga antes de entrar al separador de aceite.", "Falla en las válvulas de inundación (head pressure control) que están abiertas."], respuesta_correcta:0, explicacion:"Alto subenfriamiento con presión de descarga baja indica que hay exceso de refrigerante líquido acumulado en el condensador, típicamente en clima frío. El condensador sobredimensionado o falta de control de presión de cabeza causa esta condición." },
  { id:"ns_0413", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere implementar un programa de 'Safety Incentives'. ¿Cuál es el diseño más efectivo para evitar el ocultamiento de accidentes?", opciones:["Bonos basados en la participación en entrenamientos y reportes de condiciones inseguras.", "Premios en efectivo para las cuadrillas que reporten cero accidentes en todo el año.", "Sanciones económicas directas para el técnico que sufra una lesión en el trabajo.", "Publicar los nombres de los técnicos que cometan errores de seguridad en la oficina."], respuesta_correcta:0, explicacion:"Los bonos basados en participación en entrenamientos y reportes de condiciones inseguras incentivan la prevención sin castigar accidentes, evitando que los empleados oculten incidentes." },
  { id:"ns_0414", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema inverter reporta un error de 'DC Fan Motor'. El técnico mide el voltaje de control pero el motor no gira. ¿Qué prueba el Senior?", opciones:["Si el motor gira libremente y la resistencia de los devanados del estator.", "El capacitor de arranque del motor del ventilador aunque sea de tipo DC.", "El voltaje de la red AC que alimenta a la unidad interior del mini-split.", "La continuidad de los fusibles de la placa electrónica de la unidad exterior."], respuesta_correcta:0, explicacion:"Ante un error de motor DC del ventilador, el Senior verifica que el rotor gire libremente (sin trabas mecánicas) y mide la resistencia de los devanados del estator para descartar un bobinado abierto o cortocircuitado." },
  { id:"ns_0415", categoria:"NATE_SR_HVAC", pregunta:"Al medir la temperatura de bulbo húmedo y seco, un técnico nota que son iguales. ¿Qué significa esto psicrométricamente?", opciones:["El aire está al 100% de humedad relativa (saturación total).", "El aire está extremadamente seco y no hay evaporación en el termómetro.", "El sistema de ventilación está moviendo aire a una velocidad excesiva.", "La carga térmica del edificio es exactamente igual a la capacidad del equipo."], respuesta_correcta:0, explicacion:"Cuando la temperatura de bulbo húmedo iguala la de bulbo seco, significa que no hay evaporación en la mecha del termómetro húmedo. Esto solo ocurre cuando el aire está al 100% de humedad relativa (saturado), ya que no puede absorber más humedad para causar enfriamiento evaporativo." },
  { id:"ns_0416", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor geotérmica de lazo cerrado tiene una presión de succión alta y descarga baja. El compresor suena suave. ¿Diagnóstico?", opciones:["Compresor con eficiencia volumétrica reducida (válvulas o scrolls dañados).", "Bajo flujo de agua en el lazo de tierra que reduce el intercambio de calor.", "Válvula de expansión electrónica bloqueada en la posición de abierta total.", "Exceso de anticongelante en el agua que aumenta la densidad del fluido."], respuesta_correcta:0, explicacion:"Succion alta y descarga baja con un compresor que suena suave es sintoma clasico de un compresor con valvulas o scrolls danados. No puede generar la diferencia de presion necesaria entre descarga y succion." },
  { id:"ns_0417", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera una cuadrilla de mantenimiento en un hospital. ¿Cuál es la prioridad técnica absoluta?", opciones:["Mantener los diferenciales de presión de aire y la filtración HEPA operativos.", "Asegurar que el consumo eléctrico de los chillers sea el mínimo posible.", "Limpiar los condensadores exteriores para evitar paros por alta presión.", "Verificar que todos los técnicos usen uniformes limpios y tarjetas de ID."], respuesta_correcta:0, explicacion:"En hospitales, los diferenciales de presión de aire y la filtración HEPA protegen a pacientes inmunodeprimidos de infecciones. Quirófanos y salas de aislamiento dependen de presión positiva/negativa controlada para prevenir contaminación cruzada." },
  { id:"ns_0418", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete con gas tiene el intercambiador de calor con hollín. ¿Qué ajuste de combustión es necesario?", opciones:["Aumentar el flujo de aire primario y verificar la presión de gas en el manifold.", "Reducir la velocidad del soplador de suministro para aumentar la temperatura.", "Instalar quemadores de acero inoxidable para evitar la acumulación de carbón.", "Aumentar el diámetro de la chimenea para mejorar el tiro natural del horno."], respuesta_correcta:0, explicacion:"El hollín indica combustión incompleta por falta de aire primario o exceso de gas. Se debe ajustar el shutter del quemador para aumentar el aire primario y verificar que la presión del manifold esté dentro de especificaciones para lograr una mezcla estequiométrica correcta." },
  { id:"ns_0419", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, la válvula EPR de una vitrina de lácteos falla cerrada. ¿Qué sucede con el producto?", opciones:["La vitrina dejará de enfriar y el producto se perderá por alta temperatura.", "La vitrina se congelará ya que la succión del rack es mucho más baja.", "El sistema hará bypass automático y mantendrá la temperatura de diseño.", "La válvula de expansión compensará la falta de flujo abriendo al 100%."], respuesta_correcta:0, explicacion:"Si la EPR falla cerrada, bloquea completamente el retorno de gas del evaporador al cabezal de succión. Sin flujo de refrigerante, el evaporador no puede absorber calor y la vitrina dejará de enfriar, poniendo el producto en riesgo." },
  { id:"ns_0420", categoria:"NATE_SR_CEO", pregunta:"Un CEO analiza el 'Aging Report' de sus cuentas por cobrar. ¿Qué indica una mayoría de facturas en el rango de 61-90 días?", opciones:["Fallas graves en el proceso de cobro o clientes con problemas financieros.", "Un aumento saludable en las ventas a crédito para grandes constructoras.", "Eficiencia en la facturación pero lentitud en la entrega de los servicios.", "Que la empresa tiene suficiente liquidez para financiar a sus propios clientes."], respuesta_correcta:0, explicacion:"Una mayoría de facturas en el rango de 61-90 días indica fallas serias en el proceso de cobro o que los clientes tienen problemas financieros que requieren acción inmediata." },
  { id:"ns_0421", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un approach de condensador de 12°F. Se realiza limpieza y baja a 2°F. ¿Qué ahorro estima el Senior?", opciones:["Reducción significativa del consumo eléctrico (aprox 10-15%) por menor presión de descarga.", "Mejora en la vida útil del aceite pero sin impacto real en el costo de energía.", "Aumento en la capacidad de flujo de agua helada a través del sistema del edificio.", "Reducción del ruido audible del compresor centrífugo durante la carga máxima."], respuesta_correcta:0, explicacion:"Un condensador sucio (approach de 12°F) eleva la presión de descarga, forzando al compresor a trabajar más. La limpieza (bajando a 2°F) reduce la descarga y ahorra aproximadamente 10-15% de energía." },
  { id:"ns_0422", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF reporta 'Liquid Pipe Thermistor Error'. Al revisar, el sensor está lleno de hielo. ¿Causa?", opciones:["Fuga de refrigerante en esa sección o aislamiento térmico deficiente.", "El sensor está operando correctamente bajo condiciones de carga extrema.", "La placa electrónica está enviando una señal de escarcha para protegerse.", "El ventilador de la unidad interior está girando en sentido contrario."], respuesta_correcta:0, explicacion:"La presencia de hielo en el sensor de la línea de líquido indica una fuga de refrigerante en esa sección (el gas al expandirse enfría la zona) o aislamiento térmico deficiente que permite condensación y congelamiento." },
  { id:"ns_0423", categoria:"NATE_SR_HVAC", pregunta:"Se encuentra una 'Ground Loop' (corriente a tierra) en un sistema de control DDC. ¿Cuál es el efecto?", opciones:["Señales erráticas de sensores y posibles daños a los microprocesadores.", "Aumento en el consumo de energía del transformador de control de 24V.", "Falla de los actuadores de los dampers que se quedarán siempre abiertos.", "Activación constante de las alarmas de incendio del edificio por ruido."], respuesta_correcta:0, explicacion:"Un 'ground loop' genera diferencias de potencial entre puntos de tierra que inducen corrientes parásitas en los cables de señal. Estas corrientes interfieren con las señales analógicas y digitales de los sensores, causando lecturas erráticas y posibles daños a los microprocesadores." },
  { id:"ns_0424", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller con R-1233zd (nuevo refrigerante de baja presión), ¿por qué el vacío es crítico?", opciones:["Porque opera bajo la presión atmosférica y cualquier aire causa alta presión de descarga.", "Porque el refrigerante es altamente inflamable y el aire provoca ignición.", "Porque la humedad descompone el refrigerante en cloro puro dañando el cobre.", "Porque el aceite POE usado es 10 veces más higroscópico que el aceite mineral."], respuesta_correcta:0, explicacion:"El R-1233zd opera bajo presión atmosférica como el R-123. Cualquier infiltración de aire causa presión parcial adicional que eleva la presión de descarga y reduce la eficiencia del sistema." },
  { id:"ns_0425", categoria:"NATE_SR_CEO", pregunta:"Un CEO busca diversificar hacia 'Solar HVAC'. ¿Cuál es el componente de mayor costo operativo?", opciones:["Capacitación técnica en electrónica de potencia y almacenamiento en baterías.", "La compra de paneles fotovoltaicos de silicio monocristalino por volumen.", "El marketing digital enfocado en clientes con alta conciencia ambiental.", "La instalación de estructuras de montaje de aluminio en techos residenciales."], respuesta_correcta:0, explicacion:"La diversificación a Solar HVAC requiere inversión significativa en capacitación técnica sobre electrónica de potencia y baterías, siendo el componente operativo de mayor costo." },
  { id:"ns_0426", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor activa el defrost cada 30 minutos sin hielo visible. ¿Qué revisa el Senior?", opciones:["El sensor de temperatura del serpentín exterior y el timer de la placa.", "La carga de refrigerante que podría estar por debajo de los límites nominales.", "Si el ventilador exterior se detiene completamente durante el funcionamiento.", "La configuración del termostato interior respecto a la calefacción auxiliar."], respuesta_correcta:0, explicacion:"Si el defrost se activa frecuentemente sin hielo visible, el sensor de temperatura del serpentin puede dar lecturas falsas de frio, o el timer de la placa esta mal configurado con intervalos demasiado cortos." },
  { id:"ns_0427", categoria:"NATE_SR_RACK", pregunta:"Un rack paralelo de baja temperatura presenta 'Oil Slugging' en el arranque. ¿Cómo lo soluciona?", opciones:["Mejorando la gestión del calentador de cárter y la lógica de secuencia de arranque.", "Instalando un filtro de succión de mayor micraje para permitir el paso del aceite.", "Reduciendo la carga de aceite total del sistema para que no se acumule tanto.", "Aumentando la temperatura de succión del rack mediante el ajuste de las vitrinas."], respuesta_correcta:0, explicacion:"El oil slugging al arranque ocurre por refrigerante líquido disuelto en el aceite del cárter. Los calentadores de cárter evaporan el refrigerante antes del arranque, y una secuencia de arranque adecuada con tiempos de precalentamiento previene el golpe de líquido." },
  { id:"ns_0428", categoria:"NATE_SR_PACKAGE", pregunta:"Un Rooftop de 50 toneladas tiene un Delta P de aire muy bajo. El soplador gira bien. ¿Qué revisa?", opciones:["Ductos desconectados o dampers de alivio barométrico trabados en abierto.", "Filtros de aire extremadamente limpios que no ofrecen ninguna resistencia.", "La rotación del motor del soplador que podría estar girando en sentido inverso.", "Si el serpentín del evaporador está congelado bloqueando totalmente el flujo."], respuesta_correcta:0, explicacion:"Si el soplador gira correctamente pero la presión estática es muy baja, el aire está escapando antes de llegar a las zonas. Las causas más comunes son ductos desconectados o un damper de alivio barométrico trabado en posición abierta, que actúa como un bypass masivo del sistema." },
  { id:"ns_0429", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior detecta que un técnico está recuperando refrigerante R-22 en un cilindro de R-410A. ¿Qué hace?", opciones:["Detener la operación, explicar el peligro de mezcla y usar el cilindro correcto.", "Permitirlo solo si el cilindro tiene suficiente capacidad de presión para el R-22.", "Anotar en el cilindro que ahora contiene una mezcla para que el centro de reciclaje sepa.", "Ignorarlo siempre que el cilindro sea de color gris con tapa amarilla (recuperación)."], respuesta_correcta:0, explicacion:"Mezclar refrigerantes diferentes contamina ambos gases, haciéndolos inutilizables y potencialmente peligrosos. Se deben usar cilindros de recuperación dedicados y correctamente etiquetados por tipo de refrigerante para cumplir con las normas EPA." },
  { id:"ns_0430", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga 'Smart'. El reporte indica 'Excessive Run Time'. ¿Qué concluye el Senior?", opciones:["El sistema tiene una fuga en el lado de baja (vacío) que aspira aire constantemente.", "La purga está defectuosa y su sensor de presión necesita una calibración nueva.", "El chiller ha estado operando a carga parcial durante demasiado tiempo seguido.", "La temperatura del agua de la torre es demasiado baja para que la purga sea eficiente."], respuesta_correcta:0, explicacion:"Un tiempo de operación excesivo de la purga indica que el sistema está aspirando aire constantemente a través de una fuga en el lado de baja presión (vacío), requiriendo localización de la fuga." },
  { id:"ns_0431", categoria:"NATE_SR_CEO", pregunta:"Un CEO busca implementar 'Predictive Maintenance'. ¿Cuál es el requisito tecnológico principal?", opciones:["Sensores de IoT para monitorear vibración, temperatura y corriente en tiempo real.", "Software de facturación que envíe recordatorios automáticos a los clientes cada año.", "Contratar a técnicos Senior que puedan 'predecir' fallas basándose en su experiencia.", "Instalar cámaras en todos los cuartos de máquinas para ver el estado de los equipos."], respuesta_correcta:0, explicacion:"El mantenimiento predictivo requiere sensores IoT que monitoreen vibración, temperatura y amperaje en tiempo real para detectar anomalías antes de que se conviertan en fallas." },
  { id:"ns_0432", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una succión de 118 PSI y descarga de 350 PSI. El sobrecalentamiento es 22°F. ¿Estado?", opciones:["Falta de refrigerante leve o restricción parcial en el dispositivo de expansión.", "Funcionamiento normal para un día con carga térmica moderada en el evaporador.", "Exceso de carga que está inundando el condensador del sistema exterior.", "Compresor fallando que no logra succionar suficiente masa de refrigerante."], respuesta_correcta:0, explicacion:"Sobrecalentamiento de 22°F es más alto que el rango ideal de 10-15°F, indicando que el evaporador no recibe suficiente refrigerante. Esto puede ser por falta leve de carga o una restricción parcial en la TXV o filtro deshidratador que limita el flujo de líquido." },
  { id:"ns_0433", categoria:"NATE_SR_MINISPLIT", pregunta:"Un VRF tiene un error de 'Oil Return Cycle Fail'. ¿Qué revisa el técnico Senior?", opciones:["La velocidad del compresor, las válvulas solenoide de retorno y el nivel de aceite.", "Si el filtro de aire interior está bloqueando el retorno de gas hacia la unidad.", "La carga de refrigerante líquido que podría estar atrapando el aceite abajo.", "Si el variador de frecuencia (VFD) tiene un error de sobrecalentamiento de placa."], respuesta_correcta:0, explicacion:"El ciclo de retorno de aceite en VRF depende de la velocidad del compresor, las válvulas solenoide de retorno de aceite y el nivel de aceite. Si alguno falla, el aceite no regresa al cárter adecuadamente." },
  { id:"ns_0434", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo refrigeración, una bomba de calor tiene un subenfriamiento de 5°F y sobrecalentamiento de 25°F. ¿Causa?", opciones:["Falta de carga de refrigerante (Undercharged).", "Exceso de carga de refrigerante (Overcharged).", "Válvula de expansión (TXV) fallida en posición abierta.", "Condensador exterior extremadamente sucio o bloqueado."], respuesta_correcta:0, explicacion:"Subenfriamiento bajo (5F) indica poco liquido en el condensador. Sobrecalentamiento alto (25F) confirma que el evaporador recibe poco refrigerante. Ambos sintomas juntos son diagnostico clasico de falta de carga." },
  { id:"ns_0435", categoria:"NATE_SR_RACK", pregunta:"Un rack de baja temperatura usa descongelación por gas caliente. El tubo de drenaje se congela. ¿Qué falta?", opciones:["Un cable calefactor (heat tape) en el drenaje y la trampa de aire externa.", "Aumentar el tiempo de deshielo para que el agua alcance a salir del edificio.", "Instalar una bomba de condensado de alta temperatura para forzar el drenaje.", "Cerrar la válvula de succión más rápido para evitar que el vapor se condense."], respuesta_correcta:0, explicacion:"En vitrinas de baja temperatura, el agua del deshielo puede congelarse en las líneas de drenaje que pasan por zonas frías. Se requiere cable calefactor (heat tape) en el tubo de drenaje y la trampa para mantener el agua fluyendo." },
  { id:"ns_0436", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'High Motor Amperage' constante. El voltaje es nominal. ¿Qué revisa?", opciones:["Fricción excesiva en cojinetes, alta presión de descarga o sobrecarga de gas.", "Si los ventiladores del condensador están girando a la velocidad correcta hoy.", "La configuración del variador de frecuencia que podría estar limitando el torque.", "Si la unidad de purga está devolviendo aire al evaporador del sistema centrífugo."], respuesta_correcta:0, explicacion:"Alto amperaje con voltaje nominal indica carga mecánica excesiva: fricción en cojinetes desgastados, alta presión de condensación por condensador sucio, o sobrecarga de gas que aumenta el trabajo de compresión." },
  { id:"ns_0437", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de serpentín de 100 toneladas. ¿Qué prueba de fugas es la más rigurosa?", opciones:["Prueba de nitrógeno a presión de diseño (e.g. 450 PSI) sostenida por 24 horas.", "Uso de burbujas de jabón en cada soldadura mientras el sistema está al vacío.", "Cargar el sistema con 5 libras de refrigerante y usar un detector electrónico.", "Observar si el vacío de 500 micrones se mantiene estable durante 10 minutos."], respuesta_correcta:0, explicacion:"La prueba de presión con nitrógeno a presión de diseño sostenida por 24 horas es la más rigurosa porque detecta incluso micro-fugas que solo se manifiestan bajo presión prolongada. En sistemas de gran tonelaje, esta verificación es esencial antes de cargar." },
  { id:"ns_0438", categoria:"NATE_SR_CEO", pregunta:"Un CEO busca reducir el 'Inventory Carrying Cost'. ¿Cuál es la estrategia logística?", opciones:["Implementar un sistema de inventario 'Just-In-Time' con proveedores locales.", "Comprar piezas por volumen y almacenarlas en el almacén central de la empresa.", "Permitir que los técnicos compren lo que necesiten en cualquier tienda de suministros.", "Eliminar el stock de las camionetas para que el técnico no sea responsable de piezas."], respuesta_correcta:0, explicacion:"El sistema Just-In-Time con proveedores locales reduce el costo de almacenamiento de inventario al mantener solo lo necesario, evitando capital inmovilizado en piezas." },
  { id:"ns_0439", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una descarga de 500 PSI con R-410A. El condensador está limpio. ¿Qué sigue?", opciones:["Verificar la rotación del ventilador exterior y la presencia de incondensables.", "Agregar más refrigerante líquido para intentar bajar la temperatura de descarga.", "Cambiar el compresor asumiendo que el bobinado interno está recalentado.", "Puentear el interruptor de alta presión para que el sistema siga operando hoy."], respuesta_correcta:0, explicacion:"Con condensador limpio y descarga de 500 PSI (extremadamente alta para R-410A), las causas probables son ventilador exterior girando al revés o no girando, o incondensables (aire/nitrógeno) en el sistema. Verificar la rotación del ventilador es el paso diagnóstico lógico." },
  { id:"ns_0440", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el contactor del compresor se funde cada 3 meses. ¿Qué causa raíz busca?", opciones:["Bajo voltaje (chattering), cables flojos o sobredimensionamiento de la carga.", "Humedad en el ambiente que oxida los contactos de plata del componente.", "Uso de un termostato de baja calidad que cicla el sistema muy rápido.", "Que el técnico está usando contactores de 30 amperios para motores de 40."], respuesta_correcta:0, explicacion:"Un contactor que se funde repetidamente indica chattering (vibración) por bajo voltaje en la bobina, conexiones flojas que generan arco eléctrico, o carga excesiva. El chattering impide el cierre completo de los contactos, generando arco continuo que quema los contactos prematuramente." },
  { id:"ns_0441", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo tiene una aproximación de condensador de 1°F. ¿Qué concluye el Senior?", opciones:["Transferencia térmica óptima y tubos perfectamente limpios en el lado agua.", "Falta de refrigerante líquido; no hay masa suficiente para el intercambio total.", "El flujo de agua es tan alto que no permite una lectura estable del sensor.", "Error de calibración en los sensores de temperatura de entrada y salida agua."], respuesta_correcta:0, explicacion:"Un approach de condensador de 1°F confirma que los tubos están perfectamente limpios y la transferencia térmica es óptima, con mínima diferencia entre la temperatura de saturación y la salida del agua." },
  { id:"ns_0442", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no responde al mando a distancia. El voltaje en la placa es de 5VDC. ¿Qué sigue?", opciones:["Verificar el receptor de infrarrojos y la continuidad del cable de señal.", "Reemplazar la placa principal exterior asumiendo que bloquea el sistema.", "Cambiar las baterías del control remoto aunque la pantalla sea visible.", "Resetear el sistema cortando la energía desde el interruptor principal."], respuesta_correcta:0, explicacion:"Con 5VDC presente en la placa (alimentación correcta), el siguiente paso es verificar el receptor de infrarrojos y la continuidad del cable de señal entre el receptor y la placa principal de la unidad interior." },
  { id:"ns_0443", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 410 PSI con R-410A. ¿Cómo está?", opciones:["Funcionamiento normal para un día con carga térmica estándar y alta temperatura.", "Falta de refrigerante líquido que impide que la descarga baje a niveles de 300.", "Restricción en el dispositivo de expansión que eleva la presión de alta.", "Compresor con eficiencia volumétrica reducida que no puede bombear gas."], respuesta_correcta:0, explicacion:"Con R-410A, succión de 110 PSI (~34°F sat.) y descarga de 410 PSI (~112°F sat.) son presiones normales para un día caluroso. El diferencial de presión es adecuado y la temperatura de saturación de descarga corresponde a una temperatura exterior elevada." },
  { id:"ns_0444", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere incentivar a sus técnicos Senior. ¿Cuál es el beneficio de un plan 'Tool Allowance'?", opciones:["Garantiza que el técnico use herramientas modernas y reduzca el tiempo de servicio.", "Reduce la responsabilidad de la empresa en caso de robo de herramientas propias.", "Es una forma de evadir impuestos al pagar beneficios en lugar de salarios brutos.", "Permite que la empresa compre herramientas baratas y las asigne a los técnicos."], respuesta_correcta:0, explicacion:"Un Tool Allowance garantiza que el técnico Senior use herramientas modernas y actualizadas, reduciendo el tiempo de servicio y mejorando la calidad del diagnóstico." },
  { id:"ns_0445", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿por qué el compresor zumba y se apaga por 'Internal Overload'?", opciones:["Capacitor de marcha defectuoso o compresor mecánicamente bloqueado.", "Falta de refrigerante líquido que no permite el arranque del motor.", "La válvula inversora se encuentra en una posición media bloqueando el flujo.", "El termostato de la zona está enviando una señal de 24V con fase invertida."], respuesta_correcta:0, explicacion:"Un compresor que zumba sin arrancar y se apaga por overload indica que el motor no puede girar. Las causas mas comunes son un capacitor de marcha defectuoso o un bloqueo mecanico interno del compresor." },
  { id:"ns_0446", categoria:"NATE_SR_RACK", pregunta:"Un rack paralelo tiene un visor de aceite con espuma persistente. ¿Qué indica?", opciones:["Migración de refrigerante líquido al cárter durante los ciclos de paro.", "Que el aceite es virgen y está liberando burbujas de aire atrapadas hoy.", "Funcionamiento perfecto del separador de aceite centrífugo del sistema.", "Que el calentador de cárter está operando con una potencia excesiva."], respuesta_correcta:0, explicacion:"La espuma persistente en el visor de aceite confirma migración de refrigerante líquido al cárter durante los periodos de paro. Al arrancar, la caída de presión en el cárter hace hervir el refrigerante dentro del aceite, generando espuma." },
  { id:"ns_0447", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Junior reporta que un cliente no quiere pagar el diagnóstico. ¿Qué hace el Senior?", opciones:["Explicar al cliente el valor del conocimiento técnico y la solución ofrecida.", "Aceptar que no pague para evitar una mala reseña en las redes sociales.", "Retirar la pieza instalada y dejar el sistema descompuesto como estaba.", "Darle un descuento del 50% para que el Junior pueda irse a otra llamada."], respuesta_correcta:0, explicacion:"El diagnóstico técnico tiene valor profesional: requiere conocimiento, experiencia y herramientas especializadas. Comunicar este valor al cliente de forma respetuosa valida el trabajo del técnico y establece estándares profesionales para la empresa." },
  { id:"ns_0448", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga manual. ¿Cómo sabe el técnico que hay aire dentro?", opciones:["La presión de condensación es mayor que la presión de saturación del gas.", "El compresor centrífugo empieza a vibrar por falta de masa de refrigerante.", "La temperatura del agua helada de salida sube por encima del set-point.", "El visor de líquido en el condensador muestra burbujas constantes hoy."], respuesta_correcta:0, explicacion:"La diferencia entre la presión real de condensación y la presión de saturación a la temperatura medida indica gases no condensables. Si la presión es mayor que la saturación, hay aire presente en el sistema." },
  { id:"ns_0449", categoria:"NATE_SR_HVAC", pregunta:"Un motor de soplador PSC tiene un capacitor de 5 MFD. Se mide y marca 3 MFD. ¿Efecto?", opciones:["El motor perderá torque, bajará sus RPM y se sobrecalentará rápidamente.", "El motor consumirá menos amperaje y funcionará de manera más eficiente.", "El motor girará a la misma velocidad pero hará un ruido eléctrico agudo.", "No habrá efecto visible hasta que el capacitor llegue a 0 MFD (abierto)."], respuesta_correcta:0, explicacion:"Un capacitor de 5 MFD que mide solo 3 MFD ha perdido el 40% de su capacitancia. Esto reduce significativamente el desfase de fase del devanado de arranque, causando pérdida de torque, reducción de RPM y sobrecalentamiento del motor por el esfuerzo extra." },
  { id:"ns_0450", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Overhead'. ¿Cuál es la medida más directa y técnica?", opciones:["Implementar software de despacho para optimizar rutas y reducir combustible.", "Bajar el precio de los filtros de aire para ganar más contratos de servicio.", "Reducir el salario de los técnicos Junior para ahorrar en la nómina semanal.", "Eliminar el uso de nitrógeno en las soldaduras para bajar costos de materiales."], respuesta_correcta:0, explicacion:"El software de despacho optimiza rutas y reduce el consumo de combustible y tiempo muerto, impactando directamente los costos indirectos (Overhead) de la operación." },
  { id:"ns_0451", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller de tornillo presenta una caída de presión de aceite de 10 PSI. El mínimo es 15 PSI. ¿Acción?", opciones:["Verificar saturación del filtro de aceite y funcionamiento de la bomba interna.", "Agregar 1 galón de aceite POE de inmediato para subir la presión del cárter.", "Reducir la velocidad del compresor para bajar la demanda de lubricación.", "Ignorar el valor si la temperatura de los rodamientos se mantiene estable."], respuesta_correcta:0, explicacion:"Una presión diferencial de aceite de 10 PSI (mínimo 15 PSI) indica un filtro de aceite saturado que restringe el flujo, o una bomba interna desgastada que no genera la presión suficiente." },
  { id:"ns_0452", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿cuál es la función primordial del 'Head Pressure Control Valve'?", opciones:["Inundar el condensador en invierno para mantener una presión de descarga mínima.", "Reducir el consumo de los ventiladores del condensador durante el verano seco.", "Evitar que el aceite se enfríe demasiado antes de entrar al separador principal.", "Aumentar el flujo de refrigerante hacia las vitrinas de baja temperatura hoy."], respuesta_correcta:0, explicacion:"La válvula de control de presión de cabeza retiene refrigerante líquido en el condensador durante clima frío, reduciendo el área de condensación efectiva. Esto mantiene la presión de descarga mínima necesaria para alimentar líquido a las válvulas de expansión." },
  { id:"ns_0453", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere comprar otra empresa HVAC. ¿Qué es lo primero que audita técnicamente?", opciones:["La calidad de las instalaciones pasadas y el índice de 'Callbacks' histórico.", "El diseño del logotipo y la uniformidad de la marca en las camionetas nuevas.", "La cantidad de herramientas de marca premium que posee la empresa objetivo.", "El número de seguidores que interactúan con la marca en sus redes sociales."], respuesta_correcta:0, explicacion:"Al adquirir otra empresa HVAC, la calidad de las instalaciones pasadas y el índice de callbacks histórico revelan la competencia técnica real y los riesgos de garantía futuros." },
  { id:"ns_0454", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter muestra el error 'P4' (IPM Overheat). El condensador está limpio. ¿Causa?", opciones:["Pasta térmica seca entre el módulo IPM y el disipador o falla del ventilador.", "Carga de refrigerante excesiva que obliga al compresor a trabajar forzado.", "Voltaje de línea eléctrica superior a 250VAC que sobrecalienta la placa.", "El termostato interior está configurado a una temperatura demasiado baja."], respuesta_correcta:0, explicacion:"Con el condensador limpio, el sobrecalentamiento del IPM se debe a la pasta térmica seca (pierde conductividad térmica) entre el módulo y el disipador, o a un fallo del ventilador que no enfría el gabinete." },
  { id:"ns_0455", categoria:"NATE_SR_HVAC", pregunta:"Un sistema con R-410A tiene una succión de 150 PSI y sobrecalentamiento de 2°F. ¿Diagnóstico?", opciones:["Sistema sobrecargado de refrigerante que está inundando el evaporador.", "Falta de refrigerante líquido que impide que la descarga suba a niveles 400.", "Filtro de aire extremadamente sucio que reduce la carga térmica del sistema.", "Válvula de expansión (TXV) bloqueada en la posición de cerrado total hoy."], respuesta_correcta:0, explicacion:"Succión de 150 PSI (~48°F sat.) es elevada y un sobrecalentamiento de 2°F significa que casi todo el evaporador está lleno de líquido. Esto es resultado de una sobrecarga de refrigerante que envía más líquido del que el evaporador puede evaporar, inundándolo." },
  { id:"ns_0456", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calor, una bomba de calor presenta la línea de succión escarchada hasta el compresor. ¿Causa?", opciones:["Operación normal; el acumulador de succión está protegiendo al motor hoy.", "Válvula inversora dañada que está fugando gas de descarga a la succión.", "Falla del ventilador exterior que impide que el refrigerante absorba calor.", "El termostato de la zona ha activado las resistencias de apoyo innecesarias."], respuesta_correcta:2, explicacion:"Si el ventilador exterior falla, el serpentin exterior no absorbe calor del aire ambiente. El refrigerante permanece frio y liquido, regresando por la linea de succion y causando escarcha hasta el compresor." },
  { id:"ns_0457", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior observa que un ayudante está soldando sin usar 'Nitrogen Purge'. ¿Consecuencia?", opciones:["Escamas de óxido (soot) dentro del tubo que taparán la TXV y el filtro.", "Que la soldadura de plata no se adhiera al cobre por falta de oxígeno.", "El cobre se volverá quebradizo y fallará mecánicamente por el calor hoy.", "No hay consecuencia técnica si la tubería es de menos de 1/2 pulgada de diámetro."], respuesta_correcta:0, explicacion:"Sin purga de nitrógeno, el oxígeno atrapado reacciona con el cobre caliente generando escamas de óxido cúprico (soot). Estas partículas circulan con el refrigerante y obstruyen el orificio de la TXV y el filtro deshidratador, causando restricciones." },
  { id:"ns_0458", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Surge' a carga parcial. ¿Cómo responde el control Senior?", opciones:["Ajustando los álabes de entrada (vanes) o modulando la velocidad vía VFD.", "Aumentando el set-point de temperatura de salida del agua helada al edificio.", "Cerrando la válvula de expansión para reducir la masa de refrigerante total.", "Apagando el chiller durante 10 minutos para que las presiones se igualen solo."], respuesta_correcta:0, explicacion:"El surge a carga parcial se controla ajustando los álabes de entrada (vanes) para regular el flujo de gas, o modulando la velocidad del compresor mediante VFD para mantener una operación estable." },
  { id:"ns_0459", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una descarga de 380 PSI y subenfriamiento de 12°F con R-410A. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y subenfriamiento están en rango de diseño.", "Falta de refrigerante leve; el subenfriamiento debería ser de 15 grados F.", "Exceso de carga; el subenfriamiento indica un condensador parcialmente inundado.", "Compresor perdiendo eficiencia volumétrica al no alcanzar los 450 PSI ideales."], respuesta_correcta:0, explicacion:"Descarga de 380 PSI (~104°F sat.) y subenfriamiento de 12°F con R-410A están dentro del rango normal de operación. Un subenfriamiento de 10-15°F es típico para sistemas con TXV, confirmando que la carga de refrigerante y el intercambio de calor son correctos." },
  { id:"ns_0460", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Profit Margin' de los mantenimientos. ¿Qué acción toma?", opciones:["Estandarizar procesos para reducir el tiempo en el sitio y el desperdicio.", "Aumentar el precio de los contratos de mantenimiento un 50% anual hoy.", "Contratar solo a técnicos de nivel básico (helpers) para realizar limpiezas.", "Eliminar el uso de químicos de limpieza de serpentines para ahorrar dinero."], respuesta_correcta:0, explicacion:"Estandarizar los procesos de mantenimiento reduce el tiempo en el sitio y minimiza el desperdicio de materiales, mejorando el margen de ganancia por cada visita." },
  { id:"ns_0461", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con evaporador inundado presenta 'Liquid Carryover'. ¿Qué daño Senior previene?", opciones:["Rotura de los álabes del impulsor o daño mecánico severo al compresor.", "Aumento en la presión de condensación por falta de área de intercambio agua.", "Falla en el sensor de nivel de refrigerante que bloqueará el sistema pronto.", "Sobrecalentamiento del motor por falta de gas de succión frío para el enfriamiento."], respuesta_correcta:0, explicacion:"El arrastre de líquido (liquid carryover) hacia el compresor centrífugo puede causar daño severo a los álabes del impulsor por impacto hidráulico, ya que los líquidos son incompresibles." },
  { id:"ns_0462", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no enfría. El voltaje entre S2 y S3 es de 24VDC constantes. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería ser pulsante (fluctuante) entre 0-24.", "La placa exterior está operando correctamente enviando la señal de control.", "El compresor inverter está aterrizado y consume el voltaje de comunicación.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior."], respuesta_correcta:0, explicacion:"La señal de comunicación entre unidades debe ser un voltaje DC pulsante (fluctuante entre 0-24V). Un voltaje constante de 24VDC indica que no hay modulación de datos: falla de comunicación." },
  { id:"ns_0463", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 120 PSI y descarga de 450 PSI. El aire sale a 65°F. ¿Causa?", opciones:["Bajo flujo de aire (filtros o conductos) o evaporador parcialmente sucio.", "Funcionamiento normal para un sistema operando en condiciones de alta carga.", "Falta de refrigerante líquido que impide que el aire se enfríe a 55 grados.", "Válvula de expansión (TXV) bloqueada en la posición de abierta total hoy."], respuesta_correcta:0, explicacion:"Temperatura de salida de 65°F es demasiado alta (debería ser ~55°F), lo que indica insuficiente transferencia de calor en el evaporador. Con descarga de 450 PSI, bajo flujo de aire por filtros sucios o conductos restringidos es la causa más probable del pobre enfriamiento." },
  { id:"ns_0464", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el serpentín del evaporador se congela. El ventilador funciona bien. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una TXV que está inyectando poco líquido.", "Si el motor del ventilador del condensador está girando a bajas RPM.", "Instalar un termostato de descongelación para que pare el compresor solo.", "Agregar refrigerante hasta que la presión de succión suba a 150 PSI hoy."], respuesta_correcta:0, explicacion:"Con ventilador operando normalmente, la congelación se debe a una presión de succión demasiado baja. La causa directa es carga baja de refrigerante (fuga) o una TXV que no inyecta suficiente líquido, resultando en temperaturas de evaporación por debajo del punto de congelación." },
  { id:"ns_0465", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir el 'Customer Satisfaction'. ¿Qué métrica es la más sólida?", opciones:["Tasa de renovación de contratos de mantenimiento e índice NPS (Net Promoter).", "Número total de llamadas de servicio recibidas durante la temporada alta.", "La cantidad de me gusta y comentarios positivos en la página de Facebook.", "El margen de utilidad neta de cada reparación realizada por los técnicos."], respuesta_correcta:0, explicacion:"La tasa de renovación de contratos y el NPS son las métricas más sólidas de satisfacción porque reflejan acciones reales del cliente (pagar de nuevo) y su disposición a recomendar." },
  { id:"ns_0466", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si la válvula diferencial de aceite está mal ajustada (muy baja)?", opciones:["Los compresores se apagarán por 'Oil Failure' al no recibir lubricante a tiempo.", "El aceite se inyectará con demasiada presión dañando los sellos del motor.", "El separador de aceite se desbordará hacia la línea de succión del sistema.", "La temperatura de descarga de los compresores subirá por encima de 250°F."], respuesta_correcta:0, explicacion:"Si la válvula diferencial está ajustada muy baja, no hay suficiente presión para empujar el aceite desde el depósito hasta los cárteres de los compresores. Los compresores se quedan sin lubricante y el control de seguridad dispara un Oil Failure." },
  { id:"ns_0467", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que no tiene la báscula para cargar un sistema VRF. ¿Qué dice el Senior?", opciones:["Prohibido cargar sin báscula; los sistemas VRF requieren peso exacto de fábrica.", "Que use el método del sobrecalentamiento y subenfriamiento para cargar gas.", "Que cargue hasta que las presiones se estabilicen en los 120/400 PSI nominales.", "Que use un cilindro graduado (charging cylinder) para medir el volumen líquido."], respuesta_correcta:0, explicacion:"Los sistemas VRF tienen múltiples evaporadores y líneas largas con carga crítica calculada por el fabricante. Las presiones varían según la demanda de cada zona, por lo que el método de presiones no funciona; se debe pesar la carga exacta." },
  { id:"ns_0468", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una caída de presión de agua excesiva en el condensador. ¿Causa probable?", opciones:["Incrustaciones de minerales o lodo en los tubos del intercambiador de calor.", "La bomba de agua de la torre está girando a una velocidad insuficiente hoy.", "El refrigerante está congelando el agua dentro de los tubos por baja presión.", "Las válvulas de aislamiento del condensador están completamente abiertas hoy."], respuesta_correcta:0, explicacion:"Una caída de presión excesiva en el condensador con agua indica incrustaciones de minerales o lodo que restringen el paso del agua por los tubos del intercambiador de calor." },
  { id:"ns_0469", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 115 PSI y descarga de 480 PSI. El subenfriamiento es 28°F. ¿Causa?", opciones:["Condensador extremadamente sucio o incondensables atrapados en el sistema.", "Falta de refrigerante líquido que impide que la succión suba a niveles 130.", "Válvula de expansión (TXV) bloqueada en la posición de abierta total hoy.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo."], respuesta_correcta:0, explicacion:"Descarga de 480 PSI es excesivamente alta y subenfriamiento de 28°F es muy elevado. Un condensador sucio atrapa calor elevando la descarga, y los incondensables (aire) ocupan espacio en el condensador, forzando al líquido a acumularse más y aumentando el subenfriamiento." },
  { id:"ns_0470", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el contactor del compresor zumba pero no cierra. ¿Qué revisa?", opciones:["Voltaje bajo en la bobina (menos de 18V) o suciedad en el núcleo magnético.", "Si los contactos principales están soldados debido a un cortocircuito previo.", "Si el capacitor de arranque del compresor tiene el relé potencial abierto.", "La continuidad de los fusibles de potencia de la línea de alta tensión AC."], respuesta_correcta:0, explicacion:"Un contactor que zumba indica que la fuerza electromagnética es insuficiente para cerrar la armadura. Esto ocurre cuando el voltaje de la bobina cae por debajo del mínimo (típicamente 18V en una bobina de 24V) o cuando hay suciedad u óxido en las caras del núcleo magnético que impide el cierre." },
  { id:"ns_0471", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Cash Flow'. ¿Cuál es la medida administrativa más eficiente?", opciones:["Cobrar en el momento del servicio y reducir los días de crédito a 30 máximo.", "Pedir un préstamo bancario a 10 años para cubrir los gastos de operación.", "Aumentar el stock de materiales en las camionetas para evitar ir a la tienda.", "Reducir el salario de los técnicos Junior para ahorrar dinero en la nómina."], respuesta_correcta:0, explicacion:"Cobrar en el momento del servicio y limitar el crédito a 30 días acelera el ciclo de efectivo, evitando la dependencia de financiamiento externo para operar." },
  { id:"ns_0472", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿cuál es la función de la válvula 'Liquid Header Solenoid'?", opciones:["Aislar la línea de líquido principal durante periodos de deshielo o paro rack.", "Regular la presión de inyección de aceite hacia los cárteres de compresores.", "Aumentar el subenfriamiento del líquido antes de que llegue a las vitrinas.", "Evitar que el refrigerante líquido regrese al separador de aceite del rack."], respuesta_correcta:0, explicacion:"La solenoide del cabezal de líquido aísla la línea principal de líquido durante deshielos o paros del rack. Esto evita que el refrigerante líquido continúe fluyendo hacia las vitrinas cuando no hay compresores operando para mantener la succión." },
  { id:"ns_0473", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta una purga de aire excesiva. Opera con R-134a. ¿Qué indica?", opciones:["La purga está defectuosa; el R-134a opera a presión positiva y no aspira aire.", "El chiller tiene una fuga masiva en el evaporador que permite la entrada aire.", "El sistema de sellado del eje del compresor ha fallado mecánicamente hoy.", "La temperatura del agua de la torre es demasiado baja para el condensador."], respuesta_correcta:0, explicacion:"El R-134a opera siempre a presión positiva. Si la purga indica expulsión de aire, es porque el sistema de purga está defectuoso ya que bajo presión positiva el aire no puede infiltrarse al sistema." },
  { id:"ns_0474", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no arranca. No hay códigos de error. ¿Qué revisa el Senior?", opciones:["El fusible de la placa interior y si el voltaje de llegada es de 240VAC.", "La carga de refrigerante por peso para descartar una fuga total de gas gas.", "Si el compresor está aterrizado midiendo la resistencia contra la carcasa.", "La placa electrónica de la unidad exterior por rastros de quemaduras hoy."], respuesta_correcta:0, explicacion:"Sin códigos de error, el sistema no está recibiendo energía o la placa no arranca. El Senior revisa primero el fusible de la placa interior y confirma 240VAC en la alimentación como diagnóstico básico." },
  { id:"ns_0475", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, la válvula inversora hace un ruido de 'Chattering'. ¿Causa?", opciones:["Bajo voltaje en la bobina de 24V o una señal de termostato inestable hoy.", "Falta de presión diferencial de refrigerante para mover el pistón interno.", "El aceite del sistema es demasiado espeso y bloquea el movimiento válvula.", "Es un sonido normal cuando el sistema opera a temperaturas bajo cero hoy."], respuesta_correcta:0, explicacion:"El chattering ocurre cuando la bobina solenoide de 24V no recibe voltaje suficiente para mantener el piston piloto en posicion firme, causando que el piston principal vibre entre las dos posiciones de la valvula." },
  { id:"ns_0476", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior detecta un error de diseño en un plano de conductos. ¿Qué hace?", opciones:["Notificar al ingeniero y proponer una solución técnica basada en campo.", "Instalar el sistema como dice el plano para evitar responsabilidad legal hoy.", "Corregir el diseño por su cuenta sin avisar a nadie para terminar rápido.", "Decirle al cliente que el ingeniero no sabe nada y que él lo hará mejor."], respuesta_correcta:0, explicacion:"La comunicación con el ingeniero de diseño es esencial para resolver errores de forma profesional. El técnico Senior aporta experiencia práctica de campo, pero los cambios deben documentarse y aprobarse dentro de la cadena de responsabilidad del proyecto." },
  { id:"ns_0477", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Reversal'. ¿Qué sucede si se ignora el error?", opciones:["El compresor girará al revés y no bombeará aceite ni refrigerante líquido hoy.", "La unidad funcionará al 50% de su capacidad nominal debido al desfase fase.", "El motor se quemará instantáneamente al intentar vencer la inercia carga.", "Las válvulas de expansión se cerrarán por seguridad al detectar el error hoy."], respuesta_correcta:0, explicacion:"La inversión de fases causa rotación inversa del compresor. Sin flujo correcto de refrigerante ni bombeo de aceite, se producen daños mecánicos inmediatos por falta de lubricación en los cojinetes." },
  { id:"ns_0478", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. El subenfriamiento es 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged).", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F confirma que no hay líquido subenfriado en la salida del condensador. Con presiones moderadas, esto indica falta severa de refrigerante: no hay suficiente masa de refrigerante para llenar el condensador con líquido antes de llegar al dispositivo de expansión." },
  { id:"ns_0479", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos."], respuesta_correcta:0, explicacion:"Smart Homes requiere técnicos con conocimiento en redes, protocolos de comunicación (Wi-Fi, Zigbee, Z-Wave) e integración de sistemas inteligentes, más allá del HVAC convencional." },
  { id:"ns_0480", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué indica una temperatura de succión muy alta en el cabezal?", opciones:["Sobrecalentamiento excesivo que dañará la lubricación de compresores pronto.", "Que el sistema está operando a su máxima eficiencia de evaporación hoy.", "Falta de refrigerante líquido en el recibidor principal del rack paralelo.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura."], respuesta_correcta:0, explicacion:"Una temperatura de succión excesivamente alta significa que el gas llega demasiado caliente a los compresores. Esto degrada el aceite lubricante y reduce el enfriamiento del motor, acelerando el desgaste de los cojinetes y partes internas." },
  { id:"ns_0481", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. ¿Qué revisa?", opciones:["Presencia de aire en la tubería, paddle roto o transductor descalibrado.", "La carga de refrigerante que podría estar congelando el agua en tubos.", "El sentido de rotación del motor del compresor centrífugo del sistema hoy.", "La apertura de las válvulas de expansión del circuito de refrigeración hoy."], respuesta_correcta:0, explicacion:"Con bomba encendida, una alarma de flow switch indica problemas mecánicos del sensor: paddle roto, aire en la tubería que afecta la lectura, o transductor de presión diferencial descalibrado." },
  { id:"ns_0482", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy."], respuesta_correcta:0, explicacion:"El goteo al parar el compresor indica que el agua acumulada durante la operación no drena correctamente. Una contrapendiente o bloqueo parcial en la parte alta del drenaje retiene agua que se libera al cesar la operación." },
  { id:"ns_0483", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de 0.9 en suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy."], respuesta_correcta:0, explicacion:"La distribución de presión estática de 0.9\" en suministro vs 0.2\" en retorno muestra que la restricción principal está en el lado de suministro. Conductos aplastados, demasiados codos, o difusores cerrados en el suministro causan esta asimetría de presión." },
  { id:"ns_0484", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre los 20°F y 30°F.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en modo calor esta por debajo del rango aceptable de 20-30F. Indica baja capacidad de calentamiento por falta de refrigerante, exceso de flujo de aire, o pobre absorcion de calor exterior." },
  { id:"ns_0485", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar prueba de acidez del aceite y usar filtros succión de limpieza.", "Añadir aditivo sellador de fugas para prevenir fallas futuras en líneas.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.", "Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy."], respuesta_correcta:0, explicacion:"Después de una quemadura de compresor, los ácidos y residuos carbonizados contaminan todo el sistema. La prueba de acidez determina el nivel de contaminación, y los filtros de succión de limpieza (suction line filters) protegen el compresor nuevo." },
  { id:"ns_0486", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. ¿Estado?", opciones:["Funcionamiento correcto; la purga está separando los no condensables hoy.", "Falla en el serpentín de condensación interno de la unidad de purga hoy.", "El sistema tiene una fuga masiva de agua hacia el lado del refrigerante.", "La temperatura del evaporador es demasiado alta para que la purga trabaje."], respuesta_correcta:0, explicacion:"Si la purga expulsa mucho aire y poco refrigerante, está separando correctamente los gases no condensables del refrigerante. Esto indica operación normal y eficiente de la unidad de purga." },
  { id:"ns_0487", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si el 'Oil Separator' queda pegado en posición abierta?", opciones:["Gas caliente de descarga pasará directo al depósito aceite y a la succión.", "El rack se quedará sin aceite en pocos minutos al no poder separarlo gas.", "Los compresores se apagarán por alta presión al bloquearse el flujo gas.", "El nivel de aceite en los cárteres subirá tanto que dañará los pistones."], respuesta_correcta:0, explicacion:"Con el flotador abierto permanentemente, gas caliente de descarga pasa sin control al depósito de aceite y puede alcanzar la succión. Este bypass reduce la capacidad del sistema y crea un cortocircuito de gas caliente." },
  { id:"ns_0488", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. ¿Qué KPI usa?", opciones:["Número de llamadas de nuevos clientes que mencionan haber visto la unidad.", "La cantidad de millas recorridas por cada vehículo en zonas residenciales.", "El costo total del diseño e instalación del rótulo dividido entre 12 meses.", "El aumento en la velocidad promedio de técnicos al conducir camionetas nuevas."], respuesta_correcta:0, explicacion:"El KPI directo para camionetas rotuladas es contar cuántos clientes nuevos mencionan haberla visto, ya que conecta la inversión visual con la generación real de negocio." },
  { id:"ns_0489", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. ¿Qué revisa?", opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy.", "La carga de refrigerante líquido basándose en el visor del evaporador hoy.", "Si la válvula de expansión está inyectando demasiado líquido al sistema.", "El estado de los filtros de aire de la manejadora de aire del edificio."], respuesta_correcta:0, explicacion:"La alta presión de condensación en un chiller enfriado por agua se debe principalmente a la temperatura del agua de torre y al funcionamiento de la bomba de condensador, que son los primeros puntos a verificar." },
  { id:"ns_0490", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión de 125 PSI y descarga 400 PSI con R-410A. ¿Estado aire?", opciones:["Funcionamiento normal bajo condiciones de carga térmica estándar hoy hoy.", "Falta de refrigerante que impide que temperatura del aire baje a 55 grados.", "Exceso de carga que está elevando la presión de descarga innecesariamente.", "Compresor con eficiencia reducida que no logra enfriar el aire correctamente."], respuesta_correcta:0, explicacion:"Con R-410A, succión de 125 PSI (~40°F sat.) y descarga de 400 PSI (~109°F sat.) son valores que caen dentro del rango normal de operación para condiciones estándar de carga térmica. El sistema está funcionando correctamente." },
  { id:"ns_0491", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. ¿Qué estrategia?", opciones:["Programa de membresías mantenimiento para convertir clientes en recurrentes.", "Aumentar el precio de la primera visita para maximizar la ganancia hoy.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos.", "Despedir a técnicos que no logren vender un sistema nuevo en cada visita."], respuesta_correcta:0, explicacion:"Las membresías de mantenimiento transforman clientes ocasionales en recurrentes, creando un flujo de ingresos predecible y aumentando la retención a largo plazo." },
  { id:"ns_0492", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una restricción en la válvula de expansión.", "Si el ventilador interior está sucio y no sopla suficiente aire frío hoy.", "El voltaje de la línea eléctrica que podría estar por debajo de 200V hoy.", "Si el control remoto está configurado en una temperatura demasiado baja."], respuesta_correcta:0, explicacion:"La protección de temperatura de descarga del compresor se activa por carga baja de refrigerante (el gas no enfría el compresor) o por restricción en la EEV que limita el flujo de refrigerante." },
  { id:"ns_0493", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba calor, ¿qué sucede si 'Check Valve' condensador falla abierta?", opciones:["En modo calor el refrigerante hará bypass a TXV impidiendo calentamiento.", "El sistema funcionará mejor al haber menos restricción al flujo líquido.", "La presión de descarga subirá hasta que switch de alta apague el equipo.", "El compresor se quemará por el retorno de líquido masivo en el arranque."], respuesta_correcta:0, explicacion:"Si la check valve del condensador falla abierta, en modo calor el refrigerante hace bypass a la TXV. Sin la restriccion de la TXV, no hay caida de presion y el sistema no calienta correctamente." },
  { id:"ns_0494", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o inyección de líquido?", opciones:["Para enfriar gas de succión y evitar que descarga dañe el aceite hoy hoy.", "Para aumentar la presión de succión cuando carga en vitrinas es baja hoy.", "Para limpiar el interior de compresores de acumulaciones de carbonilla hoy.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos hoy hoy."], respuesta_correcta:0, explicacion:"La válvula Quench inyecta refrigerante líquido para reducir la temperatura de descarga del compresor. Temperaturas de descarga excesivas degradan el aceite POE, formando ácidos y carbonilla que dañan válvulas y cojinetes." },
  { id:"ns_0495", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. ¿Criterio?", opciones:["El volumen de agua y la accesibilidad para eliminación segura del fluido.", "Cuál de las dos herramientas es más nueva y hace menos ruido al operar.", "La preferencia del cliente sobre qué herramienta quiere ver en su casa hoy.", "Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy."], respuesta_correcta:0, explicacion:"La decisión técnica se basa en el volumen de agua acumulada y la accesibilidad del punto de drenaje. Grandes volúmenes requieren bomba de capacidad adecuada; espacios reducidos pueden requerir aspiradora. La eliminación segura del fluido es prioritaria." },
  { id:"ns_0496", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar prueba presión a tubos del evaporador para buscar rupturas hoy.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema.", "Aumentar la temperatura del agua helada para evitar que vapor condense hoy.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy."], respuesta_correcta:0, explicacion:"La detección de agua indica una posible ruptura en los tubos del evaporador donde el agua del lazo puede infiltrarse al lado del refrigerante. La prueba de presión es urgente para localizar la fuga." },
  { id:"ns_0497", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión 130 PSI y descarga 380 PSI. Subenfriamiento 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango.", "Falta de refrigerante líquido; el subenfriamiento debería ser 15 grados hoy.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno.", "Compresor fallando; la diferencia presión entre succión y descarga es baja."], respuesta_correcta:0, explicacion:"Succión de 130 PSI y descarga de 380 PSI con subenfriamiento de 12°F están todos dentro de rangos aceptables para R-410A. El subenfriamiento de 10-15°F confirma carga correcta, y el diferencial de presión indica un compresor en buen estado." },
  { id:"ns_0498", categoria:"NATE_SR_PACKAGE", pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. ¿Qué revisa?", opciones:["El voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo hoy.", "Si los contactos principales están quemados o soldados entre sí hoy hoy hoy.", "El capacitor de arranque del compresor que podría estar descargado hoy hoy.", "La continuidad de los fusibles de potencia de la línea de 240 voltios hoy."], respuesta_correcta:0, explicacion:"El zumbido de un contactor sin cerrar es causado por voltaje insuficiente en la bobina o impedimento mecánico en el núcleo. Medir el voltaje de la bobina y limpiar las superficies del núcleo magnético es el diagnóstico correcto antes de reemplazar el componente." },
  { id:"ns_0499", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico cobra 'por fuera' a clientes. ¿Qué acción toma?", opciones:["Despido inmediato y posible acción legal según el contrato de trabajo hoy.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras hoy.", "Ignorar la situación si el técnico es el que más dinero genera hoy hoy hoy.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."], respuesta_correcta:0, explicacion:"Cobrar por fuera es una violación grave del contrato laboral y de la confianza; el despido inmediato y la acción legal son la respuesta apropiada para proteger el negocio." },
  { id:"ns_0500", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en el recibidor?", opciones:["Para evitar fraccionamiento de la mezcla y asegurar composición correcta hoy.", "Para que el refrigerante se mezcle más rápido con el aceite POE del rack.", "Para prevenir que las válvulas de descarga de compresores se calienten hoy.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."], respuesta_correcta:0, explicacion:"Las mezclas zeotrópicas como el R-448A deben cargarse en fase líquida para que todos los componentes entren al sistema en la proporción correcta. La carga en gas causa fraccionamiento y altera las propiedades termodinámicas de la mezcla." },
  { id:"ns_0501", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRV muestra una temperatura de descarga excesiva en el compresor maestro, pero los esclavos operan normal. ¿Qué debe auditar el Senior?", opciones:["La válvula de inyección de líquido del compresor maestro o el nivel de aceite.", "La carga total de refrigerante basándose en la presión de succión del sistema.", "El sensor de temperatura de ambiente exterior de la unidad maestra solamente.", "La configuración de los dip-switches de capacidad en todas las unidades interiores."], respuesta_correcta:0, explicacion:"Si solo el compresor maestro tiene temperatura de descarga alta y los esclavos operan normal, el problema es específico de ese compresor: la válvula de inyección de líquido o el nivel de aceite insuficiente." },
  { id:"ns_0502", categoria:"NATE_SR_PACKAGE", pregunta:"Un análisis de laboratorio reporta presencia de cobre en el aceite de un chiller centrífugo. ¿Cuál es la implicación técnica?", opciones:["Desgaste por fricción en los cojinetes de empuje o corrosión ácida en los tubos.", "Es un residuo normal del proceso de asentamiento del compresor tras el arranque.", "El refrigerante está reaccionando con el barniz del motor debido a la humedad.", "La bomba de aceite mecánica está cavitando y desprendiendo virutas metálicas."], respuesta_correcta:0, explicacion:"La presencia de cobre en el análisis de aceite indica copper plating, causado por desgaste de cojinetes de empuje o corrosión ácida que disuelve el cobre de los tubos del condensador/evaporador. Es una señal de alerta grave que requiere investigar la fuente y el nivel de acidez del aceite." },
  { id:"ns_0503", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa la compra de un local propio versus seguir rentando. ¿Qué factor fiscal es clave para la decisión de CAPEX?", opciones:["La depreciación del activo y la creación de capital en el balance general.", "El ahorro inmediato en el flujo de caja mensual al no pagar renta externa.", "La posibilidad de contratar a más personal administrativo en el nuevo espacio.", "El aumento en la visibilidad de la marca para los clientes locales de la zona."], respuesta_correcta:0, explicacion:"La compra de un local propio permite deducir la depreciación del activo fiscalmente y crea patrimonio (equity) en el balance general, siendo el factor fiscal clave en la decisión de CAPEX." },
  { id:"ns_0504", categoria:"NATE_SR_HVAC", pregunta:"En un ambiente con una humedad relativa del 90%, el diferencial entre bulbo seco y húmedo (wet bulb depression) será:", opciones:["Mínimo, indicando que el aire está muy cerca de su punto de saturación total.", "Máximo, debido a la gran cantidad de vapor de agua presente en el aire.", "Constante, independientemente de los cambios en la temperatura de bulbo seco.", "Inexistente, ya que ambos bulbos marcarán exactamente la misma temperatura."], respuesta_correcta:0, explicacion:"Con 90% de humedad relativa, el aire está muy cerca de la saturación (100%). La diferencia entre bulbo seco y húmedo (wet bulb depression) será mínima porque hay muy poca evaporación posible en el termómetro húmedo cuando el aire ya contiene casi toda la humedad que puede sostener." },
  { id:"ns_0505", categoria:"NATE_SR_RACK", pregunta:"Un sistema de refrigeración industrial usa R-717 (Amoníaco). ¿Por qué no se debe usar cobre en las tuberías?", opciones:["El amoníaco corroe agresivamente el cobre en presencia de cualquier humedad.", "La presión de operación del amoníaco excede la resistencia del cobre Tipo L.", "El cobre reacciona con el amoníaco creando un gas explosivo e inestable.", "Las vibraciones del compresor de amoníaco causarían fatiga térmica en el cobre."], respuesta_correcta:0, explicacion:"El amoníaco (NH3) ataca químicamente al cobre y sus aleaciones en presencia de humedad, formando compuestos de cobre-amoníaco que corroen y debilitan las tuberías. Por eso los sistemas de amoníaco usan exclusivamente tubería de acero." },
  { id:"ns_0506", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo refrigeración tiene un subenfriamiento de 18°F y sobrecalentamiento de 3°F. ¿Qué indica?", opciones:["Sistema con exceso de carga de refrigerante que inunda el condensador.", "Restricción en el filtro deshidratador de la línea de líquido del sistema.", "Bajo flujo de aire a través del serpentín exterior (condensador) en verano.", "Válvula inversora que no está sellando correctamente en la posición de frío."], respuesta_correcta:0, explicacion:"Subenfriamiento alto (18F) indica exceso de liquido en el condensador, y sobrecalentamiento bajo (3F) indica que el evaporador recibe demasiado refrigerante. Ambos sintomas confirman sobrecarga de refrigerante." },
  { id:"ns_0507", categoria:"NATE_SR_CEO", pregunta:"Un CEO detecta que sus técnicos no realizan el reporte de recuperación de gas. ¿Cuál es el riesgo legal ante la EPA?", opciones:["Multas severas por cada infracción y pérdida de la certificación de la empresa.", "Suspensión de la licencia de conducir comercial para todos los técnicos del equipo.", "Aumento en el costo de los permisos de construcción para nuevos proyectos HVAC.", "La imposibilidad de comprar refrigerante virgen en los centros de distribución."], respuesta_correcta:0, explicacion:"La EPA impone multas severas por cada infracción de registro de recuperación de refrigerante y puede revocar la certificación de la empresa, afectando su capacidad de operar." },
  { id:"ns_0508", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'low evaporator pressure' pero el agua helada sale a la temperatura de set-point. ¿Qué revisa el Senior?", opciones:["Falta de refrigerante o una válvula de expansión mal calibrada o fallida.", "El sensor de presión de succión que podría estar enviando una señal falsa.", "La limpieza de los tubos del condensador que afecta la presión de alta.", "El flujo de agua de la torre de enfriamiento que es demasiado bajo hoy."], respuesta_correcta:0, explicacion:"Si el agua sale a set-point pero la presión de succión es baja, hay falta de refrigerante o la válvula de expansión está restringida. El sistema compensa temporalmente pero opera de forma ineficiente." },
  { id:"ns_0509", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete con VAV tiene una presión estática de conductos que fluctúa violentamente. ¿Causa raíz?", opciones:["El lazo de control PID del variador de frecuencia (VFD) está mal sintonizado.", "El sensor de presión estática está ubicado demasiado cerca del soplador principal.", "Hay demasiadas cajas VAV cerrando simultáneamente durante la carga parcial.", "El motor del soplador tiene un rodamiento desgastado que varía las RPM totales."], respuesta_correcta:0, explicacion:"Fluctuaciones violentas de presión estática en un sistema VAV con VFD indican un lazo PID mal sintonizado. Si la ganancia proporcional es demasiado alta o el tiempo integral es demasiado corto, el VFD sobrecompensa cada cambio, creando oscilaciones que nunca se estabilizan." },
  { id:"ns_0510", categoria:"NATE_SR_CEO", pregunta:"Como CEO, usted decide invertir en una flota eléctrica. ¿Cuál es el principal desafío operativo para sus técnicos?", opciones:["La gestión del tiempo de carga y la planeación de rutas según la autonomía.", "La falta de espacio en el vehículo para herramientas pesadas y refrigerantes.", "El ruido excesivo del motor eléctrico que distrae al técnico durante el manejo.", "La dificultad para encontrar estaciones de carga en zonas residenciales nuevas."], respuesta_correcta:0, explicacion:"El principal desafío de flota eléctrica es gestionar los tiempos de carga y planear rutas según la autonomía del vehículo para no dejar técnicos varados sin completar sus llamadas." },
  { id:"ns_0511", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, se observa que la presión del recibidor fluctúa con la temperatura ambiente. ¿Qué componente falló?", opciones:["La válvula reguladora de presión del recibidor (ORI/ORD o equivalente).", "El ventilador del condensador remoto que no modula su velocidad por presión.", "La válvula diferencial de aceite que está permitiendo el paso de gas caliente.", "El transductor de presión de descarga que controla la lógica de los compresores."], respuesta_correcta:0, explicacion:"La válvula reguladora del recibidor (ORI/ORD) mantiene una presión estable independiente de las condiciones ambientales. Si falla, la presión del recibidor fluctúa directamente con la temperatura ambiente, afectando la alimentación de líquido a las vitrinas." },
  { id:"ns_0512", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF tiene un error de 'Suction Pressure Sensor'. ¿Cuál es el riesgo de seguir operando en modo manual?", opciones:["Falla del compresor por retorno de líquido o sobrecalentamiento extremo.", "Pérdida total de la comunicación entre la unidad exterior y los evaporadores.", "Aumento en el consumo de energía pero sin riesgo para la integridad mecánica.", "Que el sistema solo funcione en modo de calefacción independientemente del mando."], respuesta_correcta:0, explicacion:"Sin el sensor de presión de succión, el sistema no puede proteger al compresor contra retorno de líquido (presión alta) ni sobrecalentamiento extremo (presión muy baja), arriesgando una falla mecánica." },
  { id:"ns_0513", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo usa R-123. Se detecta una fuga ácida. ¿Qué acción de remediación es obligatoria post-reparación?", opciones:["Cambios sucesivos de aceite y filtros deshidratadores de alta capacidad ácida.", "Añadir un neutralizador líquido y no cambiar el aceite hasta el próximo año.", "Realizar un vacío de 50 micrones para asegurar que el ácido se evapore solo.", "Pintar el interior de la carcasa del evaporador para evitar que el ácido la dañe."], respuesta_correcta:0, explicacion:"Tras una fuga ácida en un sistema con R-123, se requieren cambios sucesivos de aceite y filtros deshidratadores de alta capacidad ácida para neutralizar y remover los contaminantes ácidos del sistema." },
  { id:"ns_0514", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa una instalación donde el drenaje de condensado no tiene trampa (P-Trap). ¿Efecto?", opciones:["El agua no drenará si el serpentín está en el lado de succión del soplador.", "La humedad en el edificio aumentará un 20% debido al aire que entra al tubo.", "El compresor se apagará por alta presión debido al calor que sube por el drenaje.", "No hay efecto técnico; las trampas solo se usan para evitar olores del drenaje."], respuesta_correcta:0, explicacion:"Cuando el serpentín está en el lado de succión (presión negativa), sin trampa P el aire es succionado por el tubo de drenaje impidiendo que el agua drene por gravedad. La trampa crea un sello de agua que bloquea el flujo de aire y permite el drenaje." },
  { id:"ns_0515", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC quiere reducir el 'Customer Acquisition Cost' (CAC). ¿Qué canal es más rentable a largo plazo?", opciones:["El SEO orgánico y la generación de contenido técnico útil para el cliente.", "Anuncios pagados en motores de búsqueda (PPC) durante la temporada de verano.", "Patrocinio de eventos deportivos locales para aumentar el reconocimiento visual.", "Envío masivo de correos postales con cupones de descuento para instalaciones."], respuesta_correcta:0, explicacion:"El SEO orgánico y el contenido técnico útil generan leads a costo marginal decreciente a largo plazo, siendo el canal más rentable comparado con la publicidad pagada continua." },
  { id:"ns_0516", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter presenta un ruido de expansión (hissing) fuerte en la unidad interior. ¿Causa Senior?", opciones:["Falta de refrigerante que genera burbujas de vapor en la línea de líquido.", "La válvula de expansión electrónica (EEV) está mal lubricada por el aceite.", "El ventilador interior está desbalanceado y genera una resonancia acústica.", "Es un sonido normal cuando el compresor modula a su frecuencia más alta."], respuesta_correcta:0, explicacion:"El ruido de expansión (hissing) fuerte en la unidad interior indica falta de refrigerante que genera burbujas de vapor (flash gas) en la línea de líquido antes de llegar a la válvula de expansión." },
  { id:"ns_0517", categoria:"NATE_SR_HVAC", pregunta:"Al enfriar aire por debajo de su punto de rocío (Dew Point), ¿qué cambio físico ocurre?", opciones:["Se produce condensación de agua y tanto la entalpía como la humedad bajan.", "La temperatura de bulbo seco baja pero la humedad absoluta se mantiene igual.", "El aire gana energía latente mientras pierde energía sensible proporcionalmente.", "La humedad relativa baja al 50% debido a la contracción de las moléculas de aire."], respuesta_correcta:0, explicacion:"Cuando el aire se enfría por debajo de su punto de rocío, el vapor de agua condensa sobre la superficie del serpentín. Esto remueve tanto calor sensible (temperatura) como calor latente (humedad), reduciendo la entalpía total y la humedad absoluta del aire." },
  { id:"ns_0518", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 40 toneladas presenta vibraciones en el compresor Scroll. El subenfriamiento es 0°F. ¿Causa?", opciones:["Slugging de líquido refrigerante debido a una falta de carga o falla de TXV.", "Desgaste natural de las espirales del scroll por operar a altas presiones.", "Falta de aceite en el sistema que no permite la lubricación de los cojinetes.", "El compresor está operando en sentido inverso por una falla de fase eléctrica."], respuesta_correcta:0, explicacion:"Un subenfriamiento de 0°F significa que el refrigerante llega al dispositivo de expansión como mezcla líquido-vapor en lugar de líquido subenfriado. Esto indica baja carga o falla de TXV, y el líquido sin evaporar puede llegar al compresor scroll causando slugging (golpe de líquido) y vibraciones severas." },
  { id:"ns_0519", categoria:"NATE_SR_CEO", pregunta:"Un CEO analiza su 'Net Profit Margin'. Si este es del 5%, ¿qué acción es prioritaria para mejorarlo?", opciones:["Controlar gastos operativos (Overhead) y optimizar la facturación por hora.", "Aumentar el salario de los técnicos para que vendan más sistemas nuevos.", "Reducir el costo de los materiales comprando piezas de marcas genéricas.", "Eliminar el departamento de mantenimiento para reducir los gastos de flota."], respuesta_correcta:0, explicacion:"Un Net Profit Margin del 5% es bajo; la acción prioritaria es controlar el Overhead y optimizar la facturación por hora para que más ingresos lleguen a la línea final." },
  { id:"ns_0520", categoria:"NATE_SR_RACK", pregunta:"En un rack, se instala un sistema de 'Heat Reclaim'. ¿Cómo afecta esto al condensador principal?", opciones:["Reduce la carga térmica que el condensador debe rechazar a la atmósfera.", "Aumenta la presión de descarga de los compresores de forma permanente.", "Requiere ventiladores de mayor caballaje para compensar la caída de presión.", "Elimina la necesidad de usar un recibidor de líquido en el sistema de rack."], respuesta_correcta:0, explicacion:"El Heat Reclaim aprovecha parte del calor de descarga para calentar agua o aire del edificio. Al extraer calor antes del condensador, se reduce la carga térmica que el condensador debe disipar, mejorando la eficiencia general del sistema." },
  { id:"ns_0521", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con R-134a tiene un approach de evaporador de 10°F y baja succión. El agua fluye bien. ¿Diagnóstico?", opciones:["Tubos del evaporador sucios en el lado del agua (biofilm o incrustación).", "Sobrecarga de refrigerante que inunda el intercambiador de calor de placas.", "Falla en el sensor de temperatura de entrada del agua helada al edificio.", "La bomba de aceite no está suministrando la presión necesaria al compresor."], respuesta_correcta:0, explicacion:"Un approach alto de evaporador (10°F) con flujo de agua correcto indica fouling en los tubos del lado del agua (biofilm o incrustación mineral) que actúa como aislante y reduce la transferencia térmica." },
  { id:"ns_0522", categoria:"NATE_SR_HVAC", pregunta:"Se encuentra un compresor residencial 'quemado' con olor ácido. ¿Qué debe hacer el Senior antes de instalar el nuevo?", opciones:["Lavado del sistema con agente de limpieza (flushing) y cambio de filtros.", "Simplemente realizar un vacío de 24 horas para extraer los vapores ácidos.", "Añadir el doble de la carga de aceite para diluir cualquier residuo ácido.", "Instalar un capacitor de arranque para ayudar al compresor nuevo a vencer la presión."], respuesta_correcta:0, explicacion:"Un compresor quemado con olor ácido indica descomposición del aceite y formación de ácidos que contaminaron todo el circuito frigorífico. Un lavado (flushing) con agente de limpieza elimina los residuos ácidos y las partículas, y los filtros nuevos atrapan contaminantes restantes." },
  { id:"ns_0523", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la 'Retención de Clientes'. ¿Qué métrica es la más representativa?", opciones:["Porcentaje de clientes con contrato de mantenimiento que renuevan anualmente.", "El número de nuevos clientes que llegan por recomendaciones de boca en boca.", "La cantidad total de facturas emitidas a clientes residenciales cada trimestre.", "El margen de utilidad neta de las instalaciones de equipos nuevos este año."], respuesta_correcta:0, explicacion:"El porcentaje de renovación anual de contratos de mantenimiento mide directamente la retención real: clientes que deciden seguir pagando por el servicio año tras año." },
  { id:"ns_0524", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, la válvula inversora queda trabada en la posición media. ¿Qué síntoma se observa?", opciones:["Presiones de succión y descarga casi iguales y falta total de capacidad.", "Aumento drástico de la presión de descarga hasta que el switch corta.", "Congelación inmediata del serpentín exterior independientemente del modo.", "El compresor arranca pero se apaga por protección interna en 30 segundos."], respuesta_correcta:0, explicacion:"Con la valvula inversora en posicion media, las presiones de alta y baja se igualan porque el gas circula libremente entre ambos lados. El compresor opera pero no puede establecer el diferencial necesario." },
  { id:"ns_0525", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split muestra el error 'Communication Fault'. Al medir, el cable de señal tiene 120VAC contra tierra. ¿Estado?", opciones:["Hay una fuga de voltaje AC al cable de señal; la placa está dañada o hay un corto.", "Es el voltaje normal de operación para sistemas inverter de alta eficiencia.", "El compresor está aterrizado y envía voltaje por el chasis a la placa de control.", "Falta la conexión de tierra física en la unidad exterior del sistema inverter."], respuesta_correcta:0, explicacion:"El cable de señal (comunicación) nunca debe tener 120VAC contra tierra. Esa presencia de voltaje AC indica una fuga de voltaje desde la placa de potencia al circuito de señal, señal de placa dañada o cortocircuito." },
  { id:"ns_0526", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se utiliza una válvula 'Static' de bypass de gas caliente?", opciones:["Para mantener una presión mínima de succión durante periodos de carga baja.", "Para deshelar los evaporadores de las vitrinas de lácteos de forma rápida.", "Para reducir la presión de descarga cuando el condensador remoto falla hoy.", "Para asegurar que el aceite regrese al rack paralelo desde las líneas largas."], respuesta_correcta:0, explicacion:"La válvula de bypass estática de gas caliente inyecta gas de descarga a la succión cuando la presión de succión baja demasiado por baja carga. Esto previene que los compresores operen en vacío y protege contra congelamiento de evaporadores." },
  { id:"ns_0527", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere implementar 'Performance Pay'. ¿Cuál es el peligro técnico de pagar por velocidad?", opciones:["Aumento de callbacks y omisión de pasos críticos como el vacío o pruebas de nitrógeno.", "Que los técnicos ganen más dinero que los gerentes de servicio de la empresa.", "Dificultad para calcular el pago exacto si el trabajo se complica mecánicamente.", "Descontento de los clientes por ver a los técnicos trabajando demasiado rápido."], respuesta_correcta:0, explicacion:"Pagar por velocidad incentiva a los técnicos a omitir pasos críticos como el vacío profundo, pruebas de nitrógeno o verificaciones finales, aumentando los callbacks." },
  { id:"ns_0528", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una caída de presión de 8 PSI en el evaporador. El diseño pide 5 PSI. ¿Acción Senior?", opciones:["Reducir el flujo de agua helada cerrando parcialmente la válvula de balanceo.", "Aumentar la velocidad de la bomba de agua para limpiar los tubos internamente.", "Agregar refrigerante líquido hasta que la caída de presión se estabilice en 5.", "Ignorar el valor si el Delta T de temperatura del agua es de exactamente 10°F."], respuesta_correcta:0, explicacion:"Una caída de presión de 8 PSI vs. diseño de 5 PSI indica flujo de agua excesivo. Se debe reducir cerrando parcialmente la válvula de balanceo para ajustar el flujo al caudal de diseño." },
  { id:"ns_0529", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior observa que el visor de líquido está lleno pero el subenfriamiento es de 0°F. ¿Diagnóstico?", opciones:["El visor está lleno de vapor (gas) o hay aire atrapado en el condensador.", "El sistema tiene una carga de refrigerante perfecta según los estándares NATE.", "La válvula de expansión está inyectando demasiado líquido al evaporador.", "Falta de flujo de aire en el condensador exterior que eleva la descarga."], respuesta_correcta:0, explicacion:"Un subenfriamiento de 0°F significa que el refrigerante está en el punto exacto de saturación sin enfriarse por debajo. Si el visor aparenta estar lleno, podría estar lleno de vapor (gas flash) o tener incondensables (aire) que dan una apariencia engañosa." },
  { id:"ns_0530", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Maintenance'. ¿Qué sensor es el más valioso para la predicción?", opciones:["Transductor de presión y amperímetro de compresor con conexión a la nube.", "Sensor de temperatura ambiente en el termostato de la sala de estar principal.", "Detector de humedad en la bandeja de condensados para evitar desbordes.", "Contador de horas de operación mecánica para programar visitas anuales."], respuesta_correcta:0, explicacion:"Los transductores de presión y amperímetros de compresor conectados a la nube permiten detectar anomalías en el rendimiento del compresor antes de que ocurra una falla catastrófica." },
  { id:"ns_0531", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Vibration Fault' en el eje de alta velocidad. ¿Qué debe revisar el Senior?", opciones:["Alineación del acoplamiento y estado de los cojinetes de rodillos o metal.", "Si el refrigerante tiene incondensables que causan turbulencia en el gas.", "La carga de aceite en el cárter que podría estar lubricando en exceso el eje.", "El voltaje de las tres fases de alimentación que podría estar desequilibrado."], respuesta_correcta:0, explicacion:"La vibración en el eje de alta velocidad de un chiller centrífugo indica problemas de alineación del acoplamiento o desgaste en los cojinetes, que son los componentes críticos del tren de transmisión." },
  { id:"ns_0532", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial con R-410A tiene succión de 110 PSI y descarga de 450 PSI. Subenfriamiento 20°F. ¿Estado?", opciones:["Restricción en la línea de líquido o válvula de expansión (TXV) fallida.", "Falta de refrigerante líquido en el sistema que impide que la succión suba.", "Exceso de carga de refrigerante que inunda el condensador exterior hoy.", "Compresor perdiendo eficiencia volumétrica al no poder bombear el gas."], respuesta_correcta:0, explicacion:"Succión baja (110 PSI) con descarga alta (450 PSI) y subenfriamiento alto (20°F) indican que el refrigerante se acumula en el lado de alta sin fluir correctamente al evaporador. Una restricción en la línea de líquido o TXV fallida impide el paso del refrigerante." },
  { id:"ns_0533", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que el 'Average Ticket' de mantenimiento es menor al costo operativo. ¿Acción?", opciones:["Reestructurar el precio del plan y capacitar en ventas de accesorios críticos.", "Reducir el tiempo que el técnico pasa en la casa del cliente a 20 minutos.", "Eliminar el uso de químicos de limpieza para reducir el costo de materiales.", "Pedir a los técnicos que usen sus propios vehículos para ahorrar en flota."], respuesta_correcta:0, explicacion:"Si el Average Ticket de mantenimiento no cubre el costo operativo, se debe reestructurar el precio del plan y capacitar al técnico en identificar y vender accesorios de valor real." },
  { id:"ns_0534", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no modula y opera siempre al 100%. El cliente se queja de frío. ¿Causa?", opciones:["Termistor de aire de retorno descalibrado o mal ubicado fuera del flujo.", "El compresor inverter ha perdido su capacidad de variar frecuencia interna.", "Placa de control exterior con un relé de bypass pegado mecánicamente.", "El control remoto está configurado en modo 'Turbo' o 'Jet Cool' fijo."], respuesta_correcta:0, explicacion:"Si el inverter opera siempre al 100% sin modular, el termistor de aire de retorno descalibrado o mal ubicado envía lecturas erróneas, haciendo que el sistema crea que nunca alcanza la temperatura deseada." },
  { id:"ns_0535", categoria:"NATE_SR_HVAC", pregunta:"Un motor de soplador PSC zumba y no arranca. El capacitor mide bien. ¿Qué prueba sigue?", opciones:["Resistencia de los devanados del motor y verificar si el eje está trabado.", "Cambiar el capacitor de todas formas por uno de mayor microfaradios hoy.", "Verificar si el termostato está enviando la señal de 24V al relé del motor.", "Limpiar la turbina del soplador para reducir la inercia de arranque mecánica."], respuesta_correcta:0, explicacion:"Si el capacitor mide bien pero el motor no arranca, el siguiente paso es verificar la resistencia de los devanados para descartar un devanado abierto o en corto, y comprobar si el eje está trabado mecánicamente. Estos son los dos fallos restantes más comunes en motores PSC." },
  { id:"ns_0536", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor tiene la descarga fría y la succión caliente. ¿Qué falló?", opciones:["La válvula inversora se quedó en modo refrigeración o está fugando bypass.", "Falta de refrigerante total que impide que el ciclo de calor se establezca.", "El ventilador interior está apagado y no hay intercambio de calor en casa.", "El sensor de temperatura exterior está bloqueando el arranque del compresor."], respuesta_correcta:0, explicacion:"Si en modo calor la descarga esta fria y la succion caliente, el refrigerante no sigue el ciclo de calefaccion. La valvula inversora se quedo en modo refrigeracion o tiene bypass interno, invirtiendo el flujo esperado." },
  { id:"ns_0537", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera una instalación de un rack comercial. ¿Por qué insiste en soldar con nitrógeno?", opciones:["Prevenir la formación de escamas de óxido que dañan válvulas solenoide.", "Aumentar la resistencia mecánica de la soldadura de plata en las uniones.", "Evitar que el cobre se enfríe demasiado rápido y se fracture la unión hoy.", "Es un requisito estético para que la tubería no se vea negra por fuera."], respuesta_correcta:0, explicacion:"En racks comerciales con múltiples válvulas solenoide, TXVs y filtros, las escamas de óxido generadas al soldar sin nitrógeno pueden obstruir estos componentes críticos. La purga de nitrógeno desplaza el oxígeno y previene la oxidación interna." },
  { id:"ns_0538", categoria:"NATE_SR_PACKAGE", pregunta:"Un Rooftop de 20 toneladas presenta un Delta T de 10°F. El flujo de aire es correcto. ¿Causa?", opciones:["Falta de refrigerante o compresores con baja eficiencia volumétrica hoy.", "Filtros de aire extremadamente limpios que no permiten el enfriamiento aire.", "La configuración del variador de frecuencia que limita las RPM del motor.", "Uso de un refrigerante con Glide que no ha sido cargado en fase líquida."], respuesta_correcta:0, explicacion:"Con flujo de aire correcto, un Delta T bajo (10°F vs. 18-22°F normal) significa que el sistema no tiene suficiente capacidad de enfriamiento. Las causas son falta de refrigerante que reduce la capacidad del evaporador, o compresores con baja eficiencia volumétrica que no bombean suficiente gas." },
  { id:"ns_0539", categoria:"NATE_SR_RACK", pregunta:"En un rack, el visor de aceite del compresor está lleno de refrigerante líquido. ¿Peligro?", opciones:["Lavado de cojinetes y posible golpe de líquido (slugging) al arrancar hoy.", "Mejora en la viscosidad del aceite que permite un arranque más suave hoy.", "Aumento en la presión de succión del sistema que ayuda a enfriar vitrinas.", "No hay peligro; el calentador de cárter lo evaporará en pocos minutos hoy."], respuesta_correcta:0, explicacion:"El refrigerante líquido en el cárter diluye y lava el aceite de los cojinetes, eliminando la película lubricante. Al arrancar, la caída de presión causa ebullición súbita del refrigerante que arrastra aceite, causando golpe de líquido y daño mecánico severo." },
  { id:"ns_0540", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Cash Cycle'. ¿Cuál es la medida más efectiva hoy?", opciones:["Implementar pagos digitales inmediatos y facturación electrónica en sitio.", "Aumentar los días de crédito a los proveedores de materiales industriales.", "Reducir el stock de piezas en el almacén para no tener capital parado hoy.", "Contratar a un gestor de cobranza externo para las facturas de 30 días."], respuesta_correcta:0, explicacion:"Los pagos digitales inmediatos y la facturación electrónica en sitio eliminan los retrasos de cobro, acortando drásticamente el ciclo de efectivo (Cash Cycle) de la empresa." },
  { id:"ns_0541", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Monitor'. Se miden 480V en las 3 fases. ¿Qué revisa?", opciones:["Desequilibrio de voltaje (unbalance) superior al 2% o monitor defectuoso.", "La rotación de las fases que fue invertida en la alimentación principal.", "El fusible de control de 24V que alimenta la bobina del contactor hoy.", "La carga de refrigerante que podría estar afectando la lógica de arranque."], respuesta_correcta:0, explicacion:"Con 480V estables en las tres fases, una falla del monitor de fase indica un desequilibrio de voltaje (unbalance) superior al 2% entre fases, o el propio monitor de fase está defectuoso." },
  { id:"ns_0542", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta ruidos de martilleo al apagar. ¿Qué revisa el Senior?", opciones:["Válvula de retención de descarga o falta de soportes en tubería de cobre.", "El capacitor de marcha que está descargando energía de forma errática hoy.", "Si el motor del ventilador del condensador tiene el aspa desequilibrada.", "La carga de refrigerante que es tan alta que causa una sobrepresión hoy."], respuesta_correcta:0, explicacion:"Los ruidos de martilleo al apagar ocurren cuando la presión de descarga empuja refrigerante de vuelta a través del compresor por falta de una válvula de retención. También pueden ser causados por tubería sin soportes que vibra cuando el flujo de refrigerante se detiene abruptamente." },
  { id:"ns_0543", categoria:"NATE_SR_CEO", pregunta:"Usted es CEO. Un técnico sufre una descarga eléctrica por no usar LOTO. ¿Responsabilidad?", opciones:["La empresa es responsable por no asegurar el cumplimiento del protocolo OSHA.", "Solo el técnico es responsable por negligencia personal en el sitio de obra.", "El cliente es responsable por no apagar el interruptor principal del edificio.", "Nadie es responsable si el técnico tiene su certificación NATE vigente hoy."], respuesta_correcta:0, explicacion:"Bajo OSHA, la empresa es responsable de implementar y hacer cumplir los protocolos de seguridad como LOTO; un accidente por incumplimiento es responsabilidad directa del empleador." },
  { id:"ns_0544", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split reporta error de 'Outdoor Coil Temp Sensor'. ¿Cómo afecta esto?", opciones:["El sistema no entrará en modo de deshielo o lo hará de forma ineficiente.", "El compresor inverter se bloqueará permanentemente por alta temperatura.", "La unidad interior solo funcionará en modo de ventilador hasta repararlo.", "El ventilador exterior girará a máxima velocidad sin importar la carga hoy."], respuesta_correcta:0, explicacion:"El sensor del serpentín exterior es necesario para detectar la formación de escarcha e iniciar el ciclo de deshielo. Sin este sensor, el deshielo no se activará o funcionará de forma ineficiente." },
  { id:"ns_0545", categoria:"NATE_SR_HVAC", pregunta:"Al aumentar la velocidad del aire a través de un serpentín frío, el Delta T bajará. ¿Por qué?", opciones:["Menor tiempo de contacto entre el aire y la superficie fría del serpentín.", "Aumento en la energía latente del aire que compensa la pérdida de calor.", "El refrigerante se evapora más rápido y enfría menos la masa de aire hoy.", "La humedad relativa sube tanto que impide la transferencia de calor seco."], respuesta_correcta:0, explicacion:"Al aumentar la velocidad del aire, cada partícula de aire pasa menos tiempo en contacto con la superficie fría del serpentín, absorbiendo menos calor. Aunque se mueve más masa de aire (más CFM), la diferencia de temperatura entre entrada y salida (Delta T) disminuye." },
  { id:"ns_0546", categoria:"NATE_SR_RACK", pregunta:"Se observa 'Short Cycling' en el compresor de lead de un rack. ¿Qué ajuste realiza?", opciones:["Aumentar la banda muerta (deadband) o diferencial en el controlador rack.", "Cambiar el sensor de presión de succión asumiendo que está descalibrado.", "Añadir más aceite al cárter para amortiguar el arranque del compresor hoy.", "Reducir la velocidad del ventilador del condensador para subir la presión."], respuesta_correcta:0, explicacion:"El ciclo corto (short cycling) ocurre cuando el diferencial entre el punto de encendido y apagado del compresor es insuficiente. Aumentar la banda muerta (deadband) en el controlador proporciona más separación entre los setpoints de corte y arranque." },
  { id:"ns_0547", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que terminó el vacío en 5 minutos en un sistema de 5 toneladas. ¿Acción?", opciones:["Repetir el vacío; es físicamente imposible eliminar humedad en ese tiempo.", "Felicitar al técnico por tener una bomba de vacío de gran capacidad (CFM).", "Verificar el visor de líquido para confirmar si el sistema está seco hoy.", "Permitir la carga de gas si el vacuómetro digital marca 499 micrones hoy."], respuesta_correcta:0, explicacion:"La evacuación de humedad es un proceso que requiere tiempo para que el agua atrapada en superficies y aceite se evapore a baja presión. Cinco minutos son insuficientes para un sistema de 5 toneladas; el vacío rápido solo indica baja presión, no ausencia de humedad." },
  { id:"ns_0548", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga manual. El técnico observa que sale gas pero la presión no baja. ¿Causa?", opciones:["Hay aire atrapado y el gas que sale es una mezcla de aire y refrigerante.", "La purga está ubicada en el punto más bajo del condensador por error hoy.", "El refrigerante es de tipo azeotrópico y no se separa de los incondensables.", "La temperatura del agua de la torre es demasiado alta para purgar aire hoy."], respuesta_correcta:0, explicacion:"Si al purgar sale gas pero la presión no baja, es porque el gas expulsado es una mezcla de aire y refrigerante. El aire atrapado mantiene la presión parcial elevada hasta que se extraiga completamente." },
  { id:"ns_0549", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión de 125 PSI y descarga de 450 PSI. El subenfriamiento es 20°F. ¿Estado?", opciones:["Sistema con exceso de carga de refrigerante (Overcharged) hoy hoy hoy.", "Falta de refrigerante líquido que impide que la descarga suba a 500 PSI.", "Restricción en el dispositivo de expansión que eleva la presión de alta.", "Compresor perdiendo eficiencia volumétrica por desgaste de los pistones."], respuesta_correcta:0, explicacion:"Succión de 125 PSI con descarga elevada de 450 PSI y subenfriamiento alto de 20°F indica exceso de refrigerante. El condensador está parcialmente inundado de líquido, lo que reduce su área efectiva de condensación y eleva tanto la presión de descarga como el subenfriamiento." },
  { id:"ns_0550", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir el 'Technician Efficiency'. ¿Qué KPI es el más preciso?", opciones:["Horas facturadas vs horas pagadas (Billable vs Non-Billable efficiency).", "Número total de llamadas de servicio terminadas por semana por técnico.", "Cantidad de ingresos generados en ventas de equipos nuevos mensualmente.", "Reducción en el costo de combustible de la camioneta asignada al técnico."], respuesta_correcta:0, explicacion:"La eficiencia técnica se mide con precisión comparando las horas facturadas (Billable) vs. las horas pagadas (Non-Billable), revelando cuánto tiempo productivo genera ingresos." },
  { id:"ns_0551", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller de tornillo tiene una falla de 'Slide Valve Failure'. ¿Cómo afecta esto?", opciones:["El compresor no podrá modular su capacidad y operará a carga fija hoy.", "El compresor se bloqueará mecánicamente y no podrá arrancar del todo hoy.", "La presión de aceite bajará drásticamente causando un paro por seguridad.", "El motor consumirá el doble de amperaje al intentar mover la válvula hoy."], respuesta_correcta:0, explicacion:"La válvula de corredera (slide valve) controla la capacidad del compresor de tornillo. Si falla, el compresor no puede modular y opera a carga fija, sin poder adaptarse a la demanda del edificio." },
  { id:"ns_0552", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, se observa que una vitrina descongela pero las otras no. ¿Qué revisa?", opciones:["La lógica de grupos de deshielo en el controlador principal del rack hoy.", "Si la válvula solenoide de gas caliente de esa vitrina está abierta hoy.", "La presión del recibidor que podría estar demasiado baja para el empuje.", "El sensor de temperatura de ambiente que bloquea el deshielo por calor."], respuesta_correcta:0, explicacion:"Si solo una vitrina descongela y las demás no, la programación de grupos de deshielo en el controlador puede estar incorrecta. Los grupos definen qué vitrinas entran en deshielo simultáneamente y si alguna fue excluida por error de configuración." },
  { id:"ns_0553", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa el 'Current Ratio'. Si el valor es de 0.8, ¿qué significa hoy?", opciones:["La empresa tiene dificultades de liquidez para pagar deudas a corto plazo.", "La empresa es extremadamente rentable y tiene un flujo de caja excelente.", "Los activos fijos superan a los pasivos circulantes en un margen del 20%.", "La empresa califica para los mejores préstamos bancarios de la industria."], respuesta_correcta:0, explicacion:"Un Current Ratio de 0.8 significa que los activos corrientes no cubren los pasivos corrientes; la empresa tiene dificultades de liquidez para pagar deudas a corto plazo." },
  { id:"ns_0554", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter muestra el error 'Outdoor Unit AC Leakage'. ¿Qué revisa?", opciones:["Fuga de corriente a tierra en el compresor o motor del ventilador hoy.", "Fuga de refrigerante en las conexiones flare de la unidad exterior hoy.", "Voltaje de línea eléctrica superior a los 260VAC que satura la placa.", "Si hay humedad condensada dentro de la caja de control electrónica hoy."], respuesta_correcta:0, explicacion:"El error 'AC Leakage' indica fuga de corriente a tierra. En la unidad exterior, las causas principales son el aislamiento deteriorado del compresor o del motor del ventilador que permite corriente a tierra." },
  { id:"ns_0555", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene un Delta T de 15°F. El Senior mide el amperaje del motor soplador y es bajo. ¿Causa?", opciones:["Filtros de aire sucios o serpentín del evaporador obstruido por polvo hoy.", "Falta de refrigerante líquido que reduce la carga térmica del sistema hoy.", "El motor del soplador está girando a una velocidad excesiva para el ducto.", "Las rejillas de suministro están completamente abiertas permitiendo flujo."], respuesta_correcta:0, explicacion:"Un Delta T alto con amperaje bajo del soplador indica flujo de aire reducido. Un motor PSC consume menos amperaje cuando tiene restricción (filtros sucios o evaporador obstruido), ya que la carga mecánica disminuye con menos flujo." },
  { id:"ns_0556", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calor, una bomba de calor presenta alta descarga y alta succión. ¿Qué falló?", opciones:["La válvula inversora está fugando bypass o el compresor perdió eficiencia.", "Falta de refrigerante líquido que impide que el sistema alcance presión.", "El ventilador exterior está apagado bloqueando la absorción de calor hoy.", "Exceso de carga de refrigerante que inunda el serpentín de la interior hoy."], respuesta_correcta:0, explicacion:"Succion alta y descarga alta con perdida de capacidad es sintoma de fuga interna en la valvula inversora. El gas de descarga se recircula a la succion, elevando ambas presiones sin transferir calor util." },
  { id:"ns_0557", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior observa que un ayudante carga refrigerante en estado gaseoso a una mezcla zeotrópica. ¿Riesgo?", opciones:["Fraccionamiento de la mezcla y pérdida de las propiedades de diseño hoy.", "Daño mecánico a las válvulas del compresor por la velocidad del gas hoy.", "Que el aceite POE se separe del refrigerante y tape el filtro hoy hoy hoy.", "No hay riesgo si el sistema está operando a plena carga térmica hoy hoy."], respuesta_correcta:0, explicacion:"Las mezclas zeotrópicas (como R-407C, R-410A) deben cargarse en estado líquido porque sus componentes tienen diferentes presiones de vapor. Cargar en gas causa fraccionamiento: los componentes más volátiles entran primero, alterando la composición de diseño." },
  { id:"ns_0558", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Low Approach' de condensador (0.5°F). ¿Cómo lo interpreta?", opciones:["Sensores descalibrados o transferencia térmica perfecta por limpieza hoy.", "Falta de refrigerante líquido que no cubre los tubos del intercambiador.", "Flujo de agua de torre excesivo que falsea la lectura del termistor hoy.", "El compresor está operando a su máxima frecuencia de rotación mecánica."], respuesta_correcta:0, explicacion:"Un approach de condensador de 0.5°F es extremadamente bajo y puede indicar sensores descalibrados, o una transferencia térmica excepcionalmente buena por tubos recién limpiados." },
  { id:"ns_0559", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 135 PSI y descarga de 400 PSI con R-410A. ¿Cómo está?", opciones:["Funcionamiento normal para un día con carga térmica alta y calor hoy hoy.", "Falta de refrigerante leve que impide que la descarga suba a 500 PSI.", "Exceso de carga que está elevando la succión por encima de los 120 PSI.", "Compresor defectuoso que no logra crear el diferencial de presión hoy."], respuesta_correcta:0, explicacion:"Con R-410A, succión de 135 PSI (~44°F sat.) y descarga de 400 PSI (~109°F sat.) son valores normales para un día con carga térmica alta. Las presiones están dentro de los rangos de diseño y el sistema opera correctamente." },
  { id:"ns_0560", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Billable Ratio' de su equipo. ¿Qué acción toma?", opciones:["Optimizar el despacho para reducir el tiempo de viaje entre llamadas hoy.", "Obligar a los técnicos a cobrar un mínimo de 2 horas por cada visita hoy.", "Reducir el salario base y aumentar las comisiones por ventas de equipos.", "Eliminar el uso de software de gestión para ahorrar en licencias hoy hoy."], respuesta_correcta:0, explicacion:"Optimizar el despacho para reducir el tiempo de viaje entre llamadas aumenta las horas facturables por día, mejorando directamente el Billable Ratio del equipo." },
  { id:"ns_0561", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Motor Temperature' con amperaje normal. ¿Qué revisa?", opciones:["La línea de enfriamiento del motor (refrigerante líquido) y su filtro hoy.", "La viscosidad del aceite que podría estar causando fricción en motor hoy.", "El flujo de agua en el condensador que es insuficiente para enfriar hoy.", "Si el compresor opera con un voltaje excesivamente alto o bajo hoy hoy."], respuesta_correcta:0, explicacion:"Con amperaje normal, la falla de temperatura del motor apunta a un problema en el sistema de enfriamiento del motor por refrigerante líquido. La línea de enfriamiento o su filtro pueden estar bloqueados." },
  { id:"ns_0562", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no arranca y el LED parpadea 3 veces. ¿Qué hace el Senior?", opciones:["Consultar el manual técnico para descodificar el código de error hoy hoy.", "Resetear el breaker y esperar a que el sistema se repare solo hoy hoy.", "Cambiar la placa exterior asumiendo que es una falla común de marca hoy.", "Agregar 1 libra de refrigerante para ver si el error desaparece hoy hoy."], respuesta_correcta:0, explicacion:"Los patrones de parpadeo del LED son códigos de diagnóstico propios de cada fabricante. El Senior siempre consulta el manual técnico para decodificar el error específico antes de actuar." },
  { id:"ns_0563", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene un sobrecalentamiento de 35°F y subenfriamiento de 12°F. ¿Causa?", opciones:["Falta de refrigerante líquido (Undercharged) o restricción en la TXV hoy.", "Exceso de carga de refrigerante que inunda el evaporador interior hoy.", "Filtro de aire extremadamente sucio que reduce la carga térmica hoy hoy.", "El compresor está perdiendo eficiencia y no succiona refrigerante hoy."], respuesta_correcta:0, explicacion:"Un sobrecalentamiento alto de 35°F indica que el evaporador no recibe suficiente refrigerante líquido. Con subenfriamiento de 12°F (aceptable), la causa más probable es falta de carga o una restricción en la TXV que limita el flujo de refrigerante al evaporador." },
  { id:"ns_0564", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calor, una bomba de calor presenta ruidos de martilleo hidráulico. ¿Causa?", opciones:["Retorno de líquido al compresor debido a una TXV exterior abierta hoy.", "La válvula inversora está cambiando de posición de forma aleatoria hoy.", "El aceite del sistema está demasiado frío y golpea los pistones hoy hoy.", "Es un sonido normal cuando las resistencias eléctricas se expanden hoy."], respuesta_correcta:0, explicacion:"Los ruidos de martilleo hidraulico ocurren cuando refrigerante liquido entra al compresor. Una TXV exterior abierta en modo calor permite paso excesivo de liquido que no se evapora completamente antes del compresor." },
  { id:"ns_0565", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que el 'DSO' (Days Sales Outstanding) es de 60 días. ¿Qué significa?", opciones:["La empresa tarda 60 días en promedio en cobrar sus facturas emitidas hoy.", "La empresa tiene suficiente capital para operar durante los próximos 60 días.", "Los técnicos tardan 60 días en promedio en terminar una instalación hoy.", "El inventario en el almacén se renueva cada 60 días de forma constante hoy."], respuesta_correcta:0, explicacion:"Un DSO de 60 días significa que la empresa tarda en promedio 60 días en cobrar sus facturas emitidas, lo cual es alto y puede crear problemas de flujo de caja." },
  { id:"ns_0566", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué indica una temperatura de succión muy fría (escarcha en el cabezal)?", opciones:["Retorno de refrigerante líquido que pone en riesgo a los compresores hoy.", "Que el sistema está operando a su máxima eficiencia de enfriamiento hoy.", "Falta de refrigerante en el recibidor que causa una expansión prematura.", "Que las válvulas EPR de todas las vitrinas están abiertas al 100% hoy hoy."], respuesta_correcta:0, explicacion:"La escarcha en el cabezal de succión indica que refrigerante líquido está llegando sin evaporarse completamente. El líquido enfría la tubería por debajo del punto de rocío del aire, formando escarcha. Esto es un riesgo directo de golpe de líquido." },
  { id:"ns_0567", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior debe explicar el 'GWP' a un aprendiz. ¿Qué significa hoy?", opciones:["Potencial de calentamiento global del refrigerante usado en el equipo hoy.", "Garantía de piezas y mano de obra que ofrece el fabricante del sistema.", "Eficiencia energética total del equipo en condiciones extremas de calor.", "Presión máxima de trabajo que puede soportar el serpentín de cobre hoy hoy."], respuesta_correcta:0, explicacion:"GWP (Global Warming Potential) indica el impacto ambiental de un refrigerante en comparación con el CO2 (GWP=1). Refrigerantes como R-410A tienen GWP de 2088, mientras que los nuevos R-32 y R-454B tienen GWP mucho menor." },
  { id:"ns_0568", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'High Approach' de evaporador (15°F). El agua fluye bien. ¿Acción?", opciones:["Limpieza mecánica de tubos del evaporador y análisis de agua helada hoy.", "Agregar refrigerante líquido hasta que el approach baje a 2 grados hoy.", "Aumentar la velocidad de la bomba de agua mediante el variador de frecuencia.", "Ignorar el valor si la temperatura de salida del agua es la correcta hoy hoy."], respuesta_correcta:0, explicacion:"Un approach alto de evaporador (15°F) con flujo correcto indica fouling severo en los tubos. La limpieza mecánica y el análisis del agua helada son necesarios para restaurar la transferencia térmica." },
  { id:"ns_0569", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 420 PSI con R-410A. ¿Cómo está?", opciones:["Falta de refrigerante leve o condensador exterior parcialmente sucio hoy.", "Funcionamiento normal para un día caluroso con carga térmica estándar hoy.", "Exceso de carga de refrigerante que inunda el condensador del sistema hoy.", "Compresor con eficiencia reducida que no puede bombear gas correctamente."], respuesta_correcta:0, explicacion:"Succión de 110 PSI (ligeramente baja) con descarga de 420 PSI (ligeramente alta) sugiere falta de refrigerante leve o un condensador parcialmente sucio. La succión baja indica menos refrigerante en el evaporador, mientras la descarga elevada puede indicar pobre disipación de calor." },
  { id:"ns_0570", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Customer Churn'. ¿Qué estrategia es la más efectiva?", opciones:["Plan de membresías de mantenimiento con visitas programadas y beneficios.", "Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos.", "Despedir a los técnicos que no logren vender un sistema nuevo cada semana."], respuesta_correcta:0, explicacion:"Un plan de membresías de mantenimiento con visitas programadas y beneficios exclusivos reduce el churn al crear un vínculo continuo y valor percibido por el cliente." },
  { id:"ns_0571", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula solenoide en la línea de líquido de cada vitrina?", opciones:["Controlar la temperatura de la vitrina mediante el corte del flujo líquido.", "Evitar que el aceite se acumule en el evaporador durante el funcionamiento.", "Aumentar el subenfriamiento del refrigerante antes de entrar a la TXV hoy.", "Proteger al compresor de un posible retorno de líquido en el arranque hoy."], respuesta_correcta:0, explicacion:"La solenoide de líquido corta el suministro de refrigerante a la vitrina cuando se satisface la temperatura. Al cerrar, inicia un pump-down del evaporador que evita la acumulación de líquido y permite un control preciso de temperatura." },
  { id:"ns_0572", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Loss'. ¿Qué componente protege al motor?", opciones:["Monitor de fase o relé de sobrecarga de estado sólido del sistema hoy hoy.", "Fusibles de retardo de tiempo instalados en la desconexión principal hoy.", "Interruptor termomagnético de la placa de control de 120 voltios hoy hoy.", "Contactor magnético que se abrirá por falta de voltaje en la bobina hoy."], respuesta_correcta:0, explicacion:"El monitor de fase y el relé de sobrecarga de estado sólido son los dispositivos diseñados específicamente para detectar pérdida de fase y proteger el motor del compresor contra daños." },
  { id:"ns_0573", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy."], respuesta_correcta:0, explicacion:"Cuando el goteo ocurre solo al parar el compresor, el agua retenida por contrapendiente o bloqueo parcial en el drenaje se libera cuando cesan la vibración y el flujo de aire de la unidad." },
  { id:"ns_0574", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de 0.9 en suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire hoy.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy hoy."], respuesta_correcta:0, explicacion:"Con presión estática de 0.9\" en suministro y solo 0.2\" en retorno, la mayor parte de la restricción del sistema está en el lado de suministro. Conductos restringidos, aplastados o difusores cerrados causan esta distribución de presión desproporcionada." },
  { id:"ns_0575", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre 20°F y 30°F hoy.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos hoy.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en modo calor es bajo. El rango normal es 20-30F. Un diferencial insuficiente indica problemas como baja carga de refrigerante, flujo de aire excesivo, o fallas en el serpentin exterior." },
  { id:"ns_0576", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar prueba de acidez del aceite y usar filtros succión de limpieza hoy.", "Añadir aditivo sellador de fugas para prevenir fallas futuras en líneas hoy.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.", "Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy."], respuesta_correcta:0, explicacion:"Una quemadura de compresor genera ácidos y partículas carbonizadas que contaminan todo el circuito frigorífico. La prueba de acidez del aceite cuantifica la contaminación, y los filtros de succión de limpieza capturan residuos antes de que lleguen al compresor nuevo." },
  { id:"ns_0577", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. ¿Estado?", opciones:["Funcionamiento correcto; la purga está separando los no condensables hoy hoy.", "Falla en el serpentín de condensación interno de la unidad de purga hoy hoy.", "El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy.", "La temperatura del evaporador es demasiado alta para que la purga trabaje."], respuesta_correcta:0, explicacion:"La purga que expulsa mucho aire pero poco refrigerante está cumpliendo su función correctamente: separar y expulsar los gases no condensables mientras retiene el refrigerante en el sistema." },
  { id:"ns_0578", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si el 'Oil Separator' queda pegado en posición abierta?", opciones:["Gas caliente de descarga pasará directo al depósito aceite y succión hoy hoy.", "El rack se quedará sin aceite en pocos minutos al no poder separarlo gas.", "Los compresores se apagarán por alta presión al bloquearse el flujo gas.", "El nivel de aceite en los cárteres subirá tanto que dañará los pistones hoy."], respuesta_correcta:0, explicacion:"El flotador del separador abierto permanentemente crea un camino directo para el gas caliente de descarga hacia el depósito de aceite. Este gas a alta presión puede empujar aceite y gas hacia la succión, reduciendo la eficiencia del sistema." },
  { id:"ns_0579", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. ¿Qué KPI usa?", opciones:["Número de llamadas de nuevos clientes que mencionan haber visto la unidad hoy.", "La cantidad de millas recorridas por cada vehículo en zonas residenciales.", "El costo total del diseño e instalación del rótulo dividido entre 12 meses.", "El aumento en la velocidad promedio de técnicos al conducir camionetas nuevas."], respuesta_correcta:0, explicacion:"La métrica clave para camionetas rotuladas es rastrear las llamadas de nuevos clientes que específicamente mencionan haber visto el vehículo, conectando visibilidad con conversión." },
  { id:"ns_0580", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. ¿Qué revisa?", opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy.", "La carga de refrigerante líquido basándose en el visor del evaporador hoy hoy.", "Si la válvula de expansión está inyectando demasiado líquido al sistema.", "El estado de los filtros de aire de la manejadora de aire del edificio hoy."], respuesta_correcta:0, explicacion:"La alta presión de condensación en un chiller con condensador de agua se diagnostica verificando primero la temperatura del agua de torre y el funcionamiento de la bomba de condensador." },
  { id:"ns_0581", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión de 125 PSI y descarga 400 PSI con R-410A. ¿Estado aire?", opciones:["Funcionamiento normal bajo condiciones de carga térmica estándar hoy hoy hoy.", "Falta de refrigerante que impide que temperatura del aire baje a 55 grados.", "Exceso de carga que está elevando la presión de descarga innecesariamente.", "Compresor con eficiencia reducida que no logra enfriar el aire correctamente."], respuesta_correcta:0, explicacion:"Succión de 125 PSI y descarga de 400 PSI con R-410A representan valores dentro del rango normal de operación. El diferencial de presión es adecuado para una carga térmica estándar, indicando que el sistema funciona correctamente." },
  { id:"ns_0582", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. ¿Qué estrategia?", opciones:["Programa de membresías mantenimiento para convertir clientes en recurrentes hoy.", "Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos.", "Despedir a técnicos que no logren vender un sistema nuevo en cada visita."], respuesta_correcta:0, explicacion:"Las membresías de mantenimiento son la estrategia más efectiva para convertir clientes de una sola visita en clientes recurrentes con ingresos predecibles." },
  { id:"ns_0583", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una restricción en la válvula de expansión hoy.", "Si el ventilador interior está sucio y no sopla suficiente aire frío hoy hoy.", "El voltaje de la línea eléctrica que podría estar por debajo de 200V hoy hoy.", "Si el control remoto está configurado en una temperatura demasiado baja hoy."], respuesta_correcta:0, explicacion:"La temperatura de descarga excesiva del compresor se debe a falta de refrigerante (el gas no enfría suficientemente el compresor) o una restricción en la EEV que limita el flujo." },
  { id:"ns_0584", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba calor, ¿qué sucede si 'Check Valve' condensador falla abierta?", opciones:["En modo calor el refrigerante hará bypass a TXV impidiendo calentamiento hoy.", "El sistema funcionará mejor al haber menos restricción al flujo líquido.", "La presión de descarga subirá hasta que switch de alta apague el equipo.", "El compresor se quemará por el retorno de líquido masivo en el arranque hoy."], respuesta_correcta:0, explicacion:"Si la check valve del condensador falla abierta, el refrigerante hace bypass a la TXV en modo calor. Sin la restriccion del dispositivo de expansion, no hay cambio de estado adecuado y el calentamiento se pierde." },
  { id:"ns_0585", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o inyección de líquido?", opciones:["Para enfriar gas de succión y evitar que descarga dañe el aceite hoy hoy hoy.", "Para aumentar la presión de succión cuando carga en vitrinas es baja hoy hoy.", "Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos hoy hoy hoy."], respuesta_correcta:0, explicacion:"La inyección de líquido (Quench) enfría el gas para mantener la temperatura de descarga dentro de límites seguros. Las temperaturas excesivas descomponen el aceite lubricante, formando ácidos y depósitos que dañan el compresor." },
  { id:"ns_0586", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. ¿Criterio?", opciones:["El volumen de agua y la accesibilidad para eliminación segura del fluido hoy.", "Cuál de las dos herramientas es más nueva y hace menos ruido al operar hoy.", "La preferencia del cliente sobre qué herramienta quiere ver en su casa hoy hoy.", "Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy."], respuesta_correcta:0, explicacion:"La elección entre aspiradora y bomba depende de factores técnicos: volumen total del agua acumulada y accesibilidad del espacio. Estas condiciones determinan cuál herramienta es más eficiente y segura para la situación específica." },
  { id:"ns_0587", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar prueba presión a tubos del evaporador para buscar rupturas hoy hoy.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.", "Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy hoy."], respuesta_correcta:0, explicacion:"Agua detectada por la purga requiere una prueba de presión urgente en los tubos del evaporador, ya que la fuente más probable de contaminación por agua es una ruptura en el intercambiador." },
  { id:"ns_0588", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión 130 PSI y descarga 380 PSI. Subenfriamiento 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango hoy.", "Falta de refrigerante líquido; el subenfriamiento debería ser 15 grados hoy hoy.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno hoy.", "Compresor fallando; la diferencia presión entre succión y descarga es baja hoy."], respuesta_correcta:0, explicacion:"Presiones de succión de 130 PSI y descarga de 380 PSI con subenfriamiento de 12°F son valores que caen dentro del rango óptimo de operación para R-410A. El subenfriamiento entre 10-15°F es ideal para confirmar carga correcta y operación eficiente del condensador." },
  { id:"ns_0589", categoria:"NATE_SR_PACKAGE", pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. ¿Qué revisa?", opciones:["El voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo hoy hoy.", "Si los contactos principales están quemados o soldados entre sí hoy hoy hoy hoy.", "El capacitor de arranque del compresor que podría estar descargado hoy hoy hoy.", "La continuidad de los fusibles de potencia de la línea de 240 voltios hoy hoy."], respuesta_correcta:0, explicacion:"Un contactor que zumba sin completar el cierre tiene un problema electromagnético o mecánico. El voltaje bajo en la bobina no genera suficiente fuerza de atracción, y la suciedad u óxido en el núcleo crea un entrehierro que impide el cierre completo de la armadura." },
  { id:"ns_0590", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico cobra 'por fuera' a clientes. ¿Qué acción toma?", opciones:["Despido inmediato y posible acción legal según el contrato de trabajo hoy hoy.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras hoy hoy.", "Ignorar la situación si el técnico es el que más dinero genera hoy hoy hoy hoy.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy hoy."], respuesta_correcta:0, explicacion:"El cobro por fuera es fraude laboral; el despido inmediato con posible acción legal es la única respuesta que protege la integridad y los ingresos de la empresa." },
  { id:"ns_0591", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en el recibidor?", opciones:["Para evitar fraccionamiento de la mezcla y asegurar composición correcta hoy hoy.", "Para que el refrigerante se mezcle más rápido con el aceite POE del rack hoy.", "Para prevenir que las válvulas de descarga de compresores se calienten hoy hoy.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy."], respuesta_correcta:0, explicacion:"El R-448A contiene múltiples componentes con diferentes volatilidades. Cargar en líquido asegura que la proporción de cada componente se mantiene exacta, evitando el fraccionamiento que alteraría las propiedades de la mezcla." },
  { id:"ns_0592", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. ¿Efecto?", opciones:["El controlador no podrá calcular la carga térmica real del edificio hoy hoy.", "El compresor se apagará inmediatamente por seguridad de flujo de agua hoy hoy.", "La unidad operará siempre al 100% de su capacidad nominal sin modular hoy hoy.", "No hay efecto si el sensor de 'Leaving Water' está operando correctamente hoy hoy."], respuesta_correcta:0, explicacion:"Sin el sensor de entering water, el controlador no puede calcular el Delta T ni la carga térmica real del edificio, impidiendo la modulación correcta de la capacidad del chiller." },
  { id:"ns_0593", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga de 550 PSI con R-410A. ¿Causa?", opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy.", "Falta de refrigerante líquido que impide que el sistema enfríe el aire hoy hoy.", "Válvula de expansión electrónica bloqueada en la posición de abierta total hoy.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy."], respuesta_correcta:0, explicacion:"Una descarga de 550 PSI con R-410A es extremadamente peligrosa (límite de operación ~600 PSI). Un condensador sucio impide la disipación de calor, y un ventilador exterior fallando elimina la convección forzada, ambos causando acumulación extrema de presión en el lado de alta." },
  { id:"ns_0594", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Average Response Time'. ¿Qué medida toma hoy?", opciones:["Implementar software de despacho inteligente y zonificación de técnicos hoy hoy.", "Aumentar el número de técnicos en la nómina aunque no haya llamadas suficientes.", "Reducir el tiempo de almuerzo de los técnicos para que estén más disponibles hoy.", "Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy."], respuesta_correcta:0, explicacion:"El software de despacho inteligente con zonificación geográfica asigna al técnico más cercano y disponible, reduciendo drásticamente el tiempo de respuesta a emergencias." },
  { id:"ns_0595", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería fluctuar entre 0 y 24VDC hoy hoy hoy.", "La placa exterior está operando correctamente enviando la señal de control hoy.", "El compresor inverter está aterrizado y consume el voltaje de comunicación hoy.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior hoy hoy."], respuesta_correcta:0, explicacion:"En sistemas inverter, la señal de comunicación entre S2 y S3 debe ser un voltaje DC pulsante (0-24V). Un voltaje fijo de 24VDC indica ausencia de modulación de datos: falla de comunicación." },
  { id:"ns_0596", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Defrost Sensor' falla en circuito abierto?", opciones:["El sistema nunca entrará en modo de deshielo y el serpentín se congelará hoy.", "El sistema entrará en modo de deshielo cada 30 minutos sin importar el hielo hoy.", "El compresor se quemará debido a la falta de control de sobrecalentamiento hoy.", "La unidad operará solo en modo refrigeración permanentemente por seguridad hoy."], respuesta_correcta:0, explicacion:"Si el sensor de defrost falla en circuito abierto, la placa no recibe la senal de temperatura baja del serpentin. Sin esta senal, el sistema nunca cumple la condicion para iniciar el deshielo y el hielo se acumula." },
  { id:"ns_0597", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un sistema VRF. ¿Por qué es vital pesar la carga?", opciones:["Los sistemas VRF son de carga crítica y las presiones no son indicadores hoy hoy.", "Es un requisito legal de la EPA para sistemas con más de 50 libras de gas hoy.", "Para asegurar que el aceite POE regrese correctamente a los compresores hoy hoy.", "Para evitar que la garantía del fabricante se anule tras la instalación hoy hoy."], respuesta_correcta:0, explicacion:"Los sistemas VRF operan con múltiples evaporadores a diferentes cargas, haciendo que las presiones varíen constantemente. La única forma confiable de asegurar la carga correcta es pesar el refrigerante según la fórmula del fabricante." },
  { id:"ns_0598", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Reversal'. ¿Qué sucede si se ignora el error?", opciones:["El compresor girará al revés y no bombeará aceite ni refrigerante líquido hoy hoy.", "La unidad funcionará al 50% de su capacidad nominal debido al desfase fase hoy.", "El motor se quemará instantáneamente al intentar vencer la inercia carga hoy hoy.", "Las válvulas de expansión se cerrarán por seguridad al detectar el error hoy hoy."], respuesta_correcta:0, explicacion:"La inversión de fases provoca rotación inversa del compresor centrífugo. Sin bombeo de aceite ni circulación de refrigerante correcta, el equipo sufre daños mecánicos por falta de lubricación." },
  { id:"ns_0599", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. Subenfriamiento 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged) hoy hoy hoy.", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy hoy hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio térmico.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F significa que sale vapor o mezcla bifásica del condensador en lugar de líquido puro. Con presiones no extremas, esto confirma una falta severa de refrigerante que no alcanza para llenar el condensador con líquido subenfriado." },
  { id:"ns_0600", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy hoy hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy hoy hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos hoy hoy."], respuesta_correcta:0, explicacion:"El mercado de Smart Homes demanda técnicos con habilidades en redes y protocolos de comunicación IoT para integrar termostatos, sensores y sistemas HVAC inteligentes." },
  { id:"ns_0601", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta una falla de 'Low Differential Pressure' en el evaporador. La bomba está encendida y el variador marca 60Hz. ¿Qué revisa el Senior?", opciones:["Válvulas de aislamiento parcialmente cerradas o cedazo (strainer) de agua obstruido.", "Carga de refrigerante insuficiente que impide la ebullición dentro de los tubos.", "Sentido de rotación del compresor centrífugo tras un mantenimiento eléctrico.", "Ajuste del set-point de temperatura de salida del agua helada al edificio."], respuesta_correcta:0, explicacion:"Con la bomba a 60Hz y baja presión diferencial en el evaporador, las válvulas de aislamiento parcialmente cerradas o un cedazo obstruido son las causas más probables de restricción de flujo de agua." },
  { id:"ns_0602", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo con CO2 (R-744), se produce un disparo de la válvula de seguridad del recibidor durante un apagón. ¿Por qué ocurre esto?", opciones:["La presión crítica del CO2 se alcanza rápidamente al subir la temperatura ambiente.", "El aceite se separa del refrigerante y genera una reacción química de alta presión.", "La válvula de bypass de gas flash se bloqueó en la posición de abierta total.", "El condensador evaporativo se vació y no hay forma de rechazar el calor latente."], respuesta_correcta:0, explicacion:"El CO2 tiene una presión crítica de 1070 PSI a 87.8°F. Sin compresores ni condensador funcionando durante un apagón, la temperatura del CO2 sube con el ambiente, la presión aumenta rápidamente hacia el punto crítico y las válvulas de seguridad se abren." },
  { id:"ns_0603", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que el 15% del inventario en las camionetas está 'obsoleto' o dañado. ¿Qué sistema de control implementa?", opciones:["Inventario rotativo (Cycle Counting) y estandarización de stock crítico por unidad.", "Prohibir que los técnicos lleven piezas y obligarlos a ir al almacén central cada vez.", "Descontar el valor de las piezas dañadas directamente del bono de productividad técnico.", "Aumentar el tamaño de las camionetas para que las piezas no se golpeen entre sí."], respuesta_correcta:0, explicacion:"El inventario rotativo (Cycle Counting) y la estandarización del stock crítico por unidad permiten detectar y corregir pérdidas, daños y obsolescencia de forma continua." },
  { id:"ns_0604", categoria:"NATE_SR_HVAC", pregunta:"Un controlador DDC pierde la comunicación con los sensores (COM Loss). ¿Cuál es la posición de seguridad (Fail-Safe) para un damper de aire exterior?", opciones:["Cerrado completamente para evitar la entrada de aire no acondicionado o congelación.", "Abierto al 100% para asegurar la ventilación mínima requerida por normativas ASHRAE.", "En la última posición conocida antes de la pérdida de señal del bus de datos.", "Modulando aleatoriamente basándose en el temporizador interno del controlador."], respuesta_correcta:0, explicacion:"En caso de pérdida de comunicación (COM Loss), la posición fail-safe para el damper de aire exterior es cerrado. Esto previene la entrada de aire exterior no acondicionado que podría causar congelamiento del serpentín en invierno o exceso de carga en verano." },
  { id:"ns_0605", categoria:"NATE_SR_HVAC", pregunta:"Al medir el sobrecalentamiento total en el compresor, el Senior obtiene 35°F. El sobrecalentamiento en el evaporador es de 10°F. ¿Diagnóstico?", opciones:["Ganancia de calor excesiva en la línea de succión debido a falta de aislamiento.", "Válvula de expansión (TXV) ajustada con una apertura excesivamente grande.", "Falta de refrigerante en el sistema que genera gas ralo en la línea de succión.", "Compresor con eficiencia volumétrica baja que no logra succionar la masa de gas."], respuesta_correcta:0, explicacion:"Si el sobrecalentamiento en el evaporador es 10°F (normal) pero el total en el compresor es 35°F, hay 25°F de ganancia de calor en la línea de succión. Esto indica falta de aislamiento térmico en la tubería de succión que absorbe calor del ambiente." },
  { id:"ns_0606", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor presenta escarcha densa solo en las vueltas superiores del serpentín exterior. ¿Qué indica?", opciones:["Restricción parcial en el distribuidor de refrigerante del serpentín exterior.", "Funcionamiento normal del ciclo de expansión antes de activar el deshielo.", "Falla del ventilador exterior que no logra mover aire a través de todo el panel.", "Exceso de aceite atrapado en la parte inferior del intercambiador de calor."], respuesta_correcta:0, explicacion:"Escarcha densa solo en ciertas secciones indica restriccion parcial en el distribuidor de refrigerante. Los circuitos bloqueados no reciben refrigerante, mientras que los libres se sobrecargan y la escarcha es desigual." },
  { id:"ns_0607", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior detecta que su equipo no utiliza un vacuómetro digital, sino los manómetros de servicio. ¿Cuál es la crítica técnica?", opciones:["Los manómetros no tienen la resolución necesaria para medir niveles de micrones reales.", "El aceite de los manómetros contaminará el sistema durante el proceso de vacío profundo.", "La EPA prohíbe el uso de mangueras estándar para procesos de evacuación de sistemas.", "El vacío destruye el sello de caucho interno de los manómetros analógicos convencionales."], respuesta_correcta:0, explicacion:"Los manómetros analógicos de servicio miden presiones en PSI y solo muestran si la aguja está 'bajo cero', sin resolución en micrones. Se necesita un vacuómetro digital para verificar con precisión que el sistema alcanzó 500 micrones o menos." },
  { id:"ns_0608", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller centrífugo, ¿cuál es el propósito de la 'Purge Unit' cuando se usa R-123?", opciones:["Remover aire y humedad, ya que el evaporador opera a presiones bajo la atmosférica.", "Extraer el exceso de refrigerante líquido que se acumula en el condensador de placas.", "Filtrar las partículas metálicas que se desprenden de los cojinetes de alta velocidad.", "Mantener la viscosidad del aceite constante mediante la eliminación de gas diluido."], respuesta_correcta:0, explicacion:"El R-123 opera bajo presión atmosférica en el evaporador, creando vacío. La unidad de purga remueve el aire y la humedad que se infiltran a través de sellos y juntas hacia el sistema." },
  { id:"ns_0609", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete industrial muestra un error de 'VFD Over-torque' en el motor del soplador. ¿Qué inspección física es prioritaria?", opciones:["Verificar si los dampers de suministro están cerrados o hay una obstrucción mecánica.", "Cambiar el variador de frecuencia por uno de mayor caballaje de forma inmediata.", "Medir el voltaje de fase a fase en la entrada del variador bajo carga máxima.", "Lubricar los rodamientos del motor aunque sean del tipo sellado de por vida."], respuesta_correcta:0, explicacion:"Un error de Over-torque indica que el VFD detecta una demanda de torque excesiva en el motor. La causa física más común son dampers cerrados, obstrucciones mecánicas en el soplador o algo trabando la rueda, lo que aumenta la resistencia al giro y dispara la protección del variador." },
  { id:"ns_0610", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa el 'Labor Efficiency Variance'. Si el tiempo real es mayor al presupuestado, ¿cuál es la acción correctiva?", opciones:["Identificar brechas de capacitación o problemas en la precisión de los estimados.", "Reducir el salario de los técnicos que no cumplan con los tiempos de la tabla.", "Eliminar los trabajos complejos y centrarse solo en mantenimientos residenciales.", "Aumentar el precio de la mano de obra para cubrir el exceso de tiempo trabajado."], respuesta_correcta:0, explicacion:"Si el tiempo real supera al presupuestado, la causa puede ser falta de capacitación o estimados imprecisos; identificar la brecha es clave antes de tomar medidas correctivas." },
  { id:"ns_0611", categoria:"NATE_SR_HVAC", pregunta:"En un gráfico psicrométrico, el movimiento horizontal hacia la izquierda representa un proceso de:", opciones:["Enfriamiento sensible (reducción de temperatura sin cambio en la humedad absoluta).", "Deshumidificación química mediante el uso de desecantes sólidos o líquidos.", "Enfriamiento y deshumidificación simultánea al tocar el punto de rocío.", "Calentamiento sensible debido a la fricción del aire en los conductos de metal."], respuesta_correcta:0, explicacion:"En el gráfico psicrométrico, un movimiento horizontal hacia la izquierda representa disminución de temperatura de bulbo seco sin cambio en la humedad absoluta (granos/lb). Este es un proceso de enfriamiento puramente sensible, donde no se remueve humedad del aire." },
  { id:"ns_0612", categoria:"NATE_SR_RACK", pregunta:"Un rack paralelo presenta una temperatura de descarga de 260°F en el compresor Lead. El Senior nota que el sobrecalentamiento de succión es de 40°F. ¿Acción?", opciones:["Aislar la vitrina que está inundando el rack o ajustar la válvula de expansión principal.", "Instalar un ventilador adicional sobre la cabeza del compresor para enfriarlo hoy.", "Agregar refrigerante líquido para bajar la temperatura de succión por masa total.", "Verificar si la inyección de líquido (Quench valve) está operando correctamente."], respuesta_correcta:3, explicacion:"Con 40°F de sobrecalentamiento y 260°F de descarga, el gas llega demasiado caliente al compresor. La válvula Quench debería inyectar líquido para enfriar el gas. Si no está operando, la temperatura de descarga se eleva peligrosamente." },
  { id:"ns_0613", categoria:"NATE_SR_CEO", pregunta:"Para mejorar la 'Lealtad del Empleado', un CEO HVAC decide implementar un 'Profit Sharing'. ¿Cómo se calcula usualmente?", opciones:["Un porcentaje de la utilidad neta distribuido según la antigüedad y desempeño técnico.", "Dividir el total de las ventas brutas del mes entre todos los empleados de la nómina.", "Dar un bono fijo a los técnicos que no tengan accidentes vehiculares en el semestre.", "Permitir que los técnicos compren acciones de la empresa a valor de mercado actual."], respuesta_correcta:0, explicacion:"El Profit Sharing se calcula como un porcentaje de la utilidad neta distribuido según antigüedad y desempeño, alineando los intereses del técnico con la rentabilidad de la empresa." },
  { id:"ns_0614", categoria:"NATE_SR_MINISPLIT", pregunta:"En un sistema VRF, ¿cuál es la consecuencia técnica de no instalar las juntas de derivación (Refnets) de forma perfectamente horizontal?", opciones:["Distribución desigual de aceite y refrigerante líquido hacia las unidades interiores.", "Aumento de la caída de presión que reduce la eficiencia SEER total del sistema.", "Ruidos de expansión excesivos debido a la turbulencia del gas en la derivación.", "Activación errónea del sensor de flujo de la caja controladora de rama (BC box)."], respuesta_correcta:0, explicacion:"Las juntas de derivación (Refnets) deben instalarse horizontalmente para garantizar distribución uniforme de aceite y refrigerante líquido. Si están inclinadas, el líquido y aceite fluyen desigualmente hacia las unidades." },
  { id:"ns_0615", categoria:"NATE_SR_CHILLERS", pregunta:"Se observa una 'aproximación negativa' en el condensador de un chiller enfriado por agua. ¿Qué concluye el Senior?", opciones:["Error de calibración en los termistores o en el transductor de presión de alta.", "El condensador está operando en un estado de eficiencia térmica absoluta ideal.", "La torre de enfriamiento está entregando agua más fría que la temperatura ambiente.", "Existe una fuga interna de refrigerante hacia el lazo de agua de condensación."], respuesta_correcta:0, explicacion:"Un approach negativo de condensador es físicamente imposible en condiciones normales. Siempre indica un error de calibración en los termistores o en el transductor de presión de descarga." },
  { id:"ns_0616", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 25 toneladas quema el contactor del compresor cada 4 meses. ¿Qué factor Senior investiga?", opciones:["Bajo voltaje en el circuito de control o cicleo excesivo (Short Cycling).", "Uso de contactores de 2 polos en un sistema que requiere 3 polos reales hoy.", "La calidad de la plata en los contactos del componente de repuesto genérico.", "Si el motor del compresor está operando con un factor de potencia muy bajo hoy."], respuesta_correcta:0, explicacion:"Un contactor que falla repetidamente cada pocos meses indica chattering por bajo voltaje (la bobina no cierra completamente los contactos, generando arco) o short cycling excesivo que multiplica los ciclos de arranque y desgasta los contactos prematuramente." },
  { id:"ns_0617", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que la presión de succión es 'normal' pero no hay enfriamiento. El Senior nota que el compresor no consume amperaje. ¿Diagnóstico?", opciones:["Compresor con falla mecánica interna (biela rota o scrolls separados).", "El contactor está cerrado pero los fusibles de potencia están quemados hoy.", "Falta total de carga de refrigerante que impide la compresión del gas hoy.", "El protector térmico interno del compresor está abierto por alta temperatura."], respuesta_correcta:0, explicacion:"Si la presión de succión parece normal pero el compresor no consume amperaje significativo, indica que el compresor gira pero no comprime (biela rota, scrolls separados o válvulas dañadas). El gas pasa sin compresión, igualando las presiones." },
  { id:"ns_0618", categoria:"NATE_SR_CEO", pregunta:"Al analizar el 'Customer Lifetime Value', un CEO decide enfocarse en el mercado de 'Property Management'. ¿Por qué?", opciones:["Provee un flujo constante de órdenes de trabajo y contratos de volumen masivo.", "Los administradores de propiedades siempre pagan por adelantado todas las facturas.", "Permite cobrar tarifas premium por reparaciones sencillas en edificios de lujo.", "No requiere que los técnicos tengan certificaciones especiales para entrar a trabajar."], respuesta_correcta:0, explicacion:"Property Management provee un flujo constante de órdenes de trabajo y contratos de volumen porque administran múltiples propiedades con necesidades HVAC continuas." },
  { id:"ns_0619", categoria:"NATE_SR_CHILLERS", pregunta:"Un sistema de agua helada presenta aire atrapado constantemente. ¿Qué componente debe revisar el Senior?", opciones:["El tanque de expansión y los purgadores de aire automáticos en los puntos altos.", "La velocidad de la bomba que podría estar cavitando por falta de presión hoy.", "El sello mecánico de la bomba de circulación que aspira aire durante el paro.", "Si el chiller está operando a una temperatura por debajo del punto de rocío hoy."], respuesta_correcta:0, explicacion:"El tanque de expansión mantiene la presión del sistema y los purgadores de aire en los puntos altos eliminan el aire atrapado. Si fallan estos componentes, el aire se acumula constantemente." },
  { id:"ns_0620", categoria:"NATE_SR_RACK", pregunta:"En un rack de refrigeración, ¿cuál es la función de la válvula de retención (check valve) en la línea de aceite?", opciones:["Evitar que el refrigerante líquido migre al separador de aceite durante el paro.", "Mantener la presión del depósito de aceite por encima de la presión de succión.", "Reducir las pulsaciones de la bomba de aceite que podrían dañar los sensores.", "Prevenir el retorno de gas de descarga hacia el cárter de los compresores hoy."], respuesta_correcta:0, explicacion:"La válvula check en la línea de aceite previene que el refrigerante líquido del sistema migre hacia el separador de aceite durante los periodos de paro. Esto mantiene la integridad del aceite y evita dilución por refrigerante." },
  { id:"ns_0621", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con R-134a tiene una presión de descarga de 210 PSI y temperatura de salida de agua de torre de 85°F. ¿Approach?", opciones:["Aproximadamente 50°F; indicando una transferencia de calor ineficiente hoy.", "Aproximadamente 10°F; indicando un condensador operando en rango normal.", "Aproximadamente 2°F; indicando que el condensador está perfectamente limpio.", "No se puede calcular sin conocer la temperatura de entrada del agua de torre."], respuesta_correcta:0, explicacion:"A 210 PSI, la temperatura de saturación del R-134a es ~135°F. Con agua de torre saliendo a 85°F, el approach es ~50°F, indicando una transferencia de calor muy ineficiente en el condensador." },
  { id:"ns_0622", categoria:"NATE_SR_HVAC", pregunta:"Se instala un motor ECM de repuesto y el flujo de aire es insuficiente. El motor es de la misma potencia. ¿Causa Senior?", opciones:["La placa de control no está programada con los taps de flujo correctos para el ducto.", "El motor ECM requiere un capacitor de arranque especial para vencer la inercia hoy.", "Los conductos de suministro tienen fugas masivas que no existían anteriormente hoy.", "El motor está girando en sentido contrario debido a la polaridad de los 24V hoy."], respuesta_correcta:0, explicacion:"Los motores ECM de repuesto requieren programación específica de la placa de control para definir los taps de flujo de aire (CFM) según el sistema de conductos. Sin la configuración correcta, el motor no entregará el flujo de aire diseñado aunque tenga la misma potencia nominal." },
  { id:"ns_0623", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC busca mejorar el 'Quick Ratio'. ¿Cuál de estas acciones lo logra directamente?", opciones:["Cobrar facturas pendientes y mantener el efectivo en la cuenta corriente hoy.", "Comprar más inventario de equipos nuevos para aprovechar descuentos por volumen.", "Pagar todas las deudas a largo plazo usando las ganancias retenidas del año hoy.", "Invertir en la compra de un nuevo edificio administrativo para la empresa hoy hoy."], respuesta_correcta:0, explicacion:"Cobrar facturas pendientes y mantener efectivo en la cuenta mejora directamente el Quick Ratio, ya que aumenta los activos líquidos disponibles frente a los pasivos corrientes." },
  { id:"ns_0624", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calefacción, una bomba de calor se apaga por alta presión de descarga. El soplador interior funciona. ¿Causa?", opciones:["Filtro de aire interior extremadamente sucio o serpentín interior bloqueado hoy.", "Falla del ventilador exterior que impide que el refrigerante absorba calor hoy.", "La válvula inversora no logró cambiar a la posición de calor completamente hoy.", "Falta de refrigerante líquido que causa que el compresor se sobrecaliente hoy hoy."], respuesta_correcta:0, explicacion:"En modo calor, el serpentin interior actua como condensador. Si el filtro de aire esta extremadamente sucio, el flujo de aire se reduce, impidiendo que el refrigerante rechace calor y elevando la presion de descarga." },
  { id:"ns_0625", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no arranca y marca error de 'DC Bus Low Voltage'. Al medir hay 240VAC entrada. ¿Qué revisa?", opciones:["El puente rectificador y los capacitores de potencia en la placa exterior hoy.", "La comunicación entre la unidad interior y exterior mediante el cable S3 hoy.", "Si el compresor está aterrizado midiendo resistencia contra la carcasa hoy hoy.", "El transformador de control que alimenta a la placa electrónica de la interior."], respuesta_correcta:0, explicacion:"Con 240VAC de entrada correctos pero error de 'DC Bus Low Voltage', el puente rectificador no está convirtiendo AC a DC o los capacitores de potencia están descargados/dañados en la placa exterior." },
  { id:"ns_0626", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué síntoma indica que el separador de aceite está 'pasando' aceite al condensador?", opciones:["Nivel bajo constante en el depósito y pérdida de capacidad en los evaporadores.", "Alta temperatura de descarga y ciclos cortos de todos los compresores del rack.", "Espuma en la mirilla de la línea de líquido justo antes de las vitrinas hoy.", "Aumento en la presión de succión debido a la viscosidad del aceite en gas hoy."], respuesta_correcta:0, explicacion:"Si el separador deja pasar aceite al condensador, el depósito de aceite tendrá un nivel bajo constante. Además, el aceite acumulado en evaporadores forma una película aislante en las paredes que reduce la transferencia de calor y la capacidad frigorífica." },
  { id:"ns_0627", categoria:"NATE_SR_CEO", pregunta:"Un CEO decide implementar 'In-House Training'. ¿Cuál es el KPI para justificar el gasto?", opciones:["Reducción en el porcentaje de 'Callbacks' y aumento en la eficiencia por hora.", "La cantidad de técnicos que logran obtener su certificación EPA 608 este año.", "El ahorro en el costo de contratar empresas externas de capacitación técnica hoy.", "La satisfacción de los empleados medida a través de encuestas anónimas hoy hoy."], respuesta_correcta:0, explicacion:"La reducción en callbacks y el aumento en eficiencia por hora son KPIs medibles que justifican directamente la inversión en capacitación interna con resultados financieros concretos." },
  { id:"ns_0628", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una caída de temperatura de 15°F en el evaporador. El diseño es de 10°F. ¿Causa?", opciones:["Bajo flujo de agua a través del evaporador debido a bomba o válvulas hoy.", "Flujo de agua excesivo que permite una transferencia de calor más rápida hoy.", "Carga térmica del edificio superior a la capacidad nominal del chiller hoy hoy.", "Incrustaciones en los tubos que obligan al agua a enfriarse más lentamente hoy."], respuesta_correcta:0, explicacion:"Un Delta T de 15°F vs. diseño de 10°F indica bajo flujo de agua. El agua permanece más tiempo en el evaporador, enfriándose más de lo normal debido a bomba deficiente o válvulas restringidas." },
  { id:"ns_0629", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que no puede soldar una tubería de 2 pulgadas porque hay agua dentro. ¿Consejo Senior?", opciones:["Usar una bomba de vacío o nitrógeno para desplazar el agua antes de soldar hoy.", "Aumentar la potencia de la antorcha para evaporar el agua mientras se suelda.", "Usar soldadura de estaño/plomo que requiere menos temperatura para fundir hoy.", "Poner un tapón de pan dentro del tubo para bloquear el agua temporalmente hoy."], respuesta_correcta:0, explicacion:"El agua dentro de la tubería absorbe el calor de la antorcha e impide que el cobre alcance la temperatura necesaria para la soldadura. Desplazar el agua con nitrógeno o extraerla con bomba de vacío es necesario para lograr una unión de calidad." },
  { id:"ns_0630", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Vehicle Downtime'. ¿Qué acción es la más efectiva hoy?", opciones:["Programa de mantenimiento preventivo riguroso y flota de reserva mínima hoy.", "Obligar a los técnicos a reparar sus propias camionetas durante el fin de semana.", "Comprar solo vehículos usados para reducir el impacto financiero de las fallas.", "Eliminar el uso de GPS para evitar que los técnicos conduzcan distancias largas."], respuesta_correcta:0, explicacion:"Un programa de mantenimiento preventivo riguroso para la flota y una reserva mínima de vehículos aseguran que siempre haya camionetas disponibles para las llamadas de servicio." },
  { id:"ns_0631", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Oil Loss' sin fugas visibles. ¿Qué revisa el Senior?", opciones:["El sistema de recuperación de aceite (eductor) y la temperatura del evaporador.", "Si el compresor está operando a una velocidad excesiva para la carga hoy.", "La viscosidad del aceite que podría ser demasiado baja para el refrigerante hoy.", "Si la unidad de purga está extrayendo aceite junto con los incondensables hoy."], respuesta_correcta:0, explicacion:"Sin fugas visibles, la pérdida de aceite en un chiller centrífugo se debe a fallas en el sistema de recuperación de aceite (eductor) o acumulación de aceite en el evaporador por baja temperatura." },
  { id:"ns_0632", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga de 450 PSI y succión de 120 PSI con R-410A. ¿Cómo está?", opciones:["Funcionamiento normal para un día con alta temperatura exterior y carga hoy.", "Falta de refrigerante leve que impide que la descarga baje a los 300 PSI.", "Restricción en la válvula de expansión que eleva la presión de alta hoy hoy.", "Compresor con eficiencia reducida que no puede bombear gas correctamente hoy."], respuesta_correcta:0, explicacion:"Con R-410A, descarga de 450 PSI (~120°F sat.) puede ser normal en un día muy caluroso con temperatura exterior alta. Con succión de 120 PSI (~38°F sat.), el sistema está operando dentro de parámetros aceptables para condiciones de alta carga térmica." },
  { id:"ns_0633", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir el 'ROI' de su publicidad en Google. ¿Qué dato es vital hoy?", opciones:["Conversión de clics en llamadas de servicio que resultaron en ventas reales.", "El número total de impresiones del anuncio en las búsquedas locales hoy hoy.", "El costo por clic (CPC) comparado con el promedio de la industria nacional.", "La posición del anuncio en la primera página de resultados de búsqueda hoy hoy."], respuesta_correcta:0, explicacion:"El dato vital para medir ROI de Google Ads es cuántos clics se convirtieron en llamadas de servicio que resultaron en ventas reales con margen de utilidad." },
  { id:"ns_0634", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no enfría. El compresor exterior arranca pero se apaga en 10 seg. ¿Causa?", opciones:["Falla de IPM (módulo de potencia) o compresor mecánicamente trabado hoy hoy.", "Falta de refrigerante líquido que activa el sensor de baja presión hoy hoy.", "El ventilador interior está apagado y la unidad se bloquea por seguridad hoy.", "El control remoto está configurado en una temperatura demasiado alta hoy hoy."], respuesta_correcta:0, explicacion:"Si el compresor arranca y se apaga en 10 segundos, el IPM detecta sobrecorriente (compresor mecánicamente trabado) o el módulo de potencia mismo está dañado y no puede mantener la operación." },
  { id:"ns_0635", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calor, una bomba de calor tiene un ruido de soplido fuerte en la inversora. ¿Causa?", opciones:["Fuga interna de gas de descarga hacia la succión a través de la válvula hoy.", "El refrigerante líquido está pasando por la válvula a alta velocidad hoy hoy.", "La bobina solenoide está vibrando contra el cuerpo de la válvula hoy hoy hoy.", "Es un sonido normal del flujo de refrigerante en sistemas de gran capacidad."], respuesta_correcta:0, explicacion:"Un soplido constante en la valvula inversora indica fuga interna de gas de descarga (alta presion) hacia la succion (baja presion). Esta fuga reduce la capacidad del sistema y produce un ruido audible." },
  { id:"ns_0636", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué sucede si la válvula diferencial de aceite está mal ajustada (muy alta)?", opciones:["Se inyecta demasiado aceite al cárter y puede causar daños mecánicos hoy hoy.", "No habrá suficiente presión para que el aceite regrese a los compresores hoy.", "El separador de aceite se desbordará hacia la línea de descarga del rack hoy.", "La temperatura del aceite bajará por debajo del punto de lubricación hoy hoy."], respuesta_correcta:0, explicacion:"Un ajuste excesivamente alto de la válvula diferencial permite un flujo desmedido de aceite hacia los cárteres. El exceso de aceite puede causar golpe hidráulico, dañar los platos de válvulas, y provocar arrastre de aceite hacia los evaporadores." },
  { id:"ns_0637", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Junior instala una unidad y no conecta la tierra física. El Senior advierte que:", opciones:["Es un riesgo mortal de descarga eléctrica y puede dañar placas electrónicas.", "El compresor consumirá más amperaje al no tener una referencia de neutro hoy.", "La garantía del fabricante se anula si no hay conexión a tierra certificada.", "El equipo hará más ruido debido a la falta de masa para las vibraciones hoy."], respuesta_correcta:0, explicacion:"Sin conexión a tierra, cualquier fuga de corriente electrifica el chasis del equipo, creando un riesgo de electrocución mortal. Las placas electrónicas de control también son vulnerables a daños por sobretensiones sin una referencia de tierra adecuada." },
  { id:"ns_0638", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una caída de presión de agua de 15 PSI en el evaporador. ¿Cómo verifica flujo?", opciones:["Consultando la curva de la bomba y la tabla de diseño del fabricante hoy hoy.", "Midiendo la temperatura de salida del agua con un termómetro láser hoy hoy.", "Observando el movimiento del agua en el tanque de expansión abierto hoy hoy.", "Contando las revoluciones por minuto del motor de la bomba de agua helada."], respuesta_correcta:0, explicacion:"La caída de presión de agua se correlaciona con el flujo según las curvas del fabricante. Consultando estos datos, se puede determinar si el flujo real corresponde al diferencial de presión medido." },
  { id:"ns_0639", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta ruidos de 'Water Hammering' en líneas de refrigerante. ¿Causa?", opciones:["Líquido refrigerante regresando al compresor o falta de soportes tubería hoy.", "Aire atrapado en el sistema que no fue evacuado durante el proceso de vacío.", "Una válvula de expansión que abre y cierra violentamente por falta de carga.", "El uso de tubería de succión con diámetro mayor al especificado por diseño."], respuesta_correcta:0, explicacion:"El 'water hammering' ocurre cuando refrigerante líquido golpea contra cambios de dirección en la tubería o regresa violentamente al compresor. Tuberías sin soportes adecuados amplifican estas vibraciones hidráulicas, creando ruidos de martilleo audibles." },
  { id:"ns_0640", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar la retención de clientes. ¿Cuál es el impacto de un programa mantenimiento?", opciones:["Aumenta lealtad, reduce emergencias y genera ingresos recurrentes hoy hoy hoy.", "Permite cobrar más caro por reparaciones de emergencia al cliente fiel hoy.", "Reduce necesidad de técnicos Senior ya que el equipo estará siempre nuevo.", "Elimina competencia al obligar al cliente a firmar contrato de exclusividad."], respuesta_correcta:0, explicacion:"Los programas de mantenimiento preventivo aumentan la lealtad del cliente, previenen emergencias costosas y crean un flujo de ingresos recurrente y predecible." },
  { id:"ns_0641", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta una purga de aire constante. Opera con R-134a. ¿Qué indica?", opciones:["La purga está defectuosa; el R-134a opera a presión positiva y no aspira aire.", "El chiller tiene una fuga masiva en el evaporador que permite la entrada aire.", "El sistema de sellado del eje del compresor ha fallado mecánicamente hoy hoy.", "La temperatura del agua de la torre es demasiado baja para el condensador hoy."], respuesta_correcta:0, explicacion:"El R-134a opera a presión positiva en todo el sistema. Una purga constante de aire es imposible bajo estas condiciones, indicando que el dispositivo de purga está defectuoso." },
  { id:"ns_0642", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no arranca. No hay códigos de error. ¿Qué revisa el Senior?", opciones:["El fusible de la placa interior y si el voltaje de llegada es de 240VAC hoy.", "La carga de refrigerante por peso para descartar una fuga total de gas gas.", "Si el compresor está aterrizado midiendo la resistencia contra la carcasa.", "La placa electrónica de la unidad exterior por rastros de quemaduras hoy hoy."], respuesta_correcta:0, explicacion:"Sin códigos de error, el sistema no recibe alimentación. El Senior verifica el fusible de la placa interior y confirma que llegan 240VAC, ya que sin energía no hay diagnóstico electrónico posible." },
  { id:"ns_0643", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. Subenfriamiento 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged) hoy hoy.", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio térmico.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F indica ausencia de líquido subenfriado en la salida del condensador. Esto es la firma diagnóstica más clara de falta severa de refrigerante (undercharged), donde la masa de refrigerante es insuficiente para completar la condensación." },
  { id:"ns_0644", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos hoy."], respuesta_correcta:0, explicacion:"Para Smart Homes se necesitan técnicos con capacitación en redes, protocolos de comunicación e integración de dispositivos inteligentes con los sistemas HVAC." },
  { id:"ns_0645", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué indica una temperatura de succión muy alta en el cabezal?", opciones:["Sobrecalentamiento excesivo que dañará la lubricación de compresores pronto.", "Que el sistema está operando a su máxima eficiencia de evaporación hoy hoy.", "Falta de refrigerante líquido en el recibidor principal del rack paralelo hoy.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura hoy."], respuesta_correcta:0, explicacion:"El sobrecalentamiento excesivo del gas de succión aumenta la temperatura en la cámara de compresión y en el aceite. Las propiedades lubricantes del aceite se degradan con el calor, acortando la vida útil de cojinetes y pistones." },
  { id:"ns_0646", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. ¿Qué revisa?", opciones:["Presencia de aire en la tubería, paddle roto o transductor descalibrado hoy.", "La carga de refrigerante que podría estar congelando el agua en tubos hoy.", "El sentido de rotación del motor del compresor centrífugo del sistema hoy hoy.", "La apertura de las válvulas de expansión del circuito de refrigeración hoy hoy."], respuesta_correcta:0, explicacion:"Con la bomba funcionando, una alarma de flow switch indica problemas con el sensor: paddle roto, aire atrapado en la tubería, o transductor de presión diferencial que necesita calibración." },
  { id:"ns_0647", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior hoy.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy hoy."], respuesta_correcta:0, explicacion:"El goteo solo al parar el compresor indica un problema de drenaje: contrapendiente o bloqueo parcial en la parte superior retiene agua durante la operación que se libera cuando el sistema se detiene." },
  { id:"ns_0648", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de 0.9 en suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy hoy hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire hoy.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy hoy."], respuesta_correcta:0, explicacion:"Presión estática desproporcionada (0.9\" suministro vs 0.2\" retorno) confirma que la restricción está concentrada en el lado de suministro del sistema de conductos, ya sea por difusores cerrados, conductos aplastados o subdimensionados." },
  { id:"ns_0649", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre 20°F y 30°F hoy hoy.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos hoy.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo hoy."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en modo calor es insuficiente. El rango saludable es 20-30F. Este diferencial bajo sugiere que el sistema no genera suficiente calor por baja carga, problemas de flujo de aire, o fallas mecanicas." },
  { id:"ns_0650", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar prueba de acidez del aceite y usar filtros succión de limpieza hoy.", "Añadir aditivo sellador de fugas para prevenir fallas futuras en líneas hoy.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado hoy.", "Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy."], respuesta_correcta:0, explicacion:"Tras un burnout del compresor, los ácidos y partículas carbonizadas circulan por todo el sistema. La prueba de acidez evalúa la severidad de la contaminación y los filtros de succión atrapan los residuos para evitar la destrucción del compresor de reemplazo." },
  { id:"ns_0651", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. ¿Estado?", opciones:["Funcionamiento correcto; la purga está separando los no condensables hoy hoy hoy.", "Falla en el serpentín de condensación interno de la unidad de purga hoy hoy.", "El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy.", "La temperatura del evaporador es demasiado alta para que la purga trabaje hoy."], respuesta_correcta:0, explicacion:"Si la purga expulsa principalmente aire con poco refrigerante, está funcionando correctamente al separar los no condensables del refrigerante, cumpliendo su propósito de diseño." },
  { id:"ns_0652", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si el 'Oil Separator' queda pegado en posición abierta?", opciones:["Gas caliente de descarga pasará directo al depósito aceite y succión hoy hoy.", "El rack se quedará sin aceite en pocos minutos al no poder separarlo gas hoy.", "Los compresores se apagarán por alta presión al bloquearse el flujo gas hoy.", "El nivel de aceite en los cárteres subirá tanto que dañará los pistones hoy."], respuesta_correcta:0, explicacion:"Con el flotador del separador permanentemente abierto, el gas de descarga caliente pasa directo al depósito de aceite y puede alcanzar la línea de succión. Esto genera un bypass interno que reduce la capacidad de refrigeración del rack." },
  { id:"ns_0653", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. ¿Qué KPI usa?", opciones:["Número de llamadas de nuevos clientes que mencionan haber visto la unidad hoy hoy.", "La cantidad de millas recorridas por cada vehículo en zonas residenciales hoy.", "El costo total del diseño e instalación del rótulo dividido entre 12 meses.", "El aumento en la velocidad promedio de técnicos al conducir camionetas nuevas."], respuesta_correcta:0, explicacion:"Medir cuántos clientes nuevos mencionan haber visto la camioneta rotulada es la forma más directa de evaluar el retorno de inversión de la publicidad vehicular." },
  { id:"ns_0654", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. ¿Qué revisa?", opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy hoy.", "La carga de refrigerante líquido basándose en el visor del evaporador hoy hoy.", "Si la válvula de expansión está inyectando demasiado líquido al sistema hoy.", "El estado de los filtros de aire de la manejadora de aire del edificio hoy."], respuesta_correcta:0, explicacion:"La alta presión de condensación con condensador de agua requiere verificar primero la temperatura del agua de torre y el funcionamiento de la bomba de condensador como causas directas." },
  { id:"ns_0655", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión de 125 PSI y descarga 400 PSI con R-410A. ¿Estado aire?", opciones:["Funcionamiento normal bajo condiciones de carga térmica estándar hoy hoy hoy hoy.", "Falta de refrigerante que impide que temperatura del aire baje a 55 grados hoy.", "Exceso de carga que está elevando la presión de descarga innecesariamente hoy.", "Compresor con eficiencia reducida que no logra enfriar el aire correctamente."], respuesta_correcta:0, explicacion:"Las presiones de succión de 125 PSI y descarga de 400 PSI con R-410A son normales para operación estándar. El sistema está funcionando dentro de sus parámetros de diseño bajo condiciones de carga térmica típicas." },
  { id:"ns_0656", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. ¿Qué estrategia?", opciones:["Programa de membresías mantenimiento para convertir clientes en recurrentes hoy hoy.", "Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy hoy.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos hoy.", "Despedir a técnicos que no logren vender un sistema nuevo en cada visita hoy."], respuesta_correcta:0, explicacion:"Las membresías de mantenimiento convierten clientes únicos en recurrentes, generando ingresos estables y predecibles que fortalecen el modelo de negocio." },
  { id:"ns_0657", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una restricción en la válvula de expansión hoy hoy.", "Si el ventilador interior está sucio y no sopla suficiente aire frío hoy hoy.", "El voltaje de la línea eléctrica que podría estar por debajo de 200V hoy hoy.", "Si el control remoto está configurado en una temperatura demasiado baja hoy."], respuesta_correcta:0, explicacion:"La protección de temperatura de descarga se activa por carga de refrigerante insuficiente o restricción en la válvula de expansión, ambas condiciones causan que el gas de descarga se sobrecaliente." },
  { id:"ns_0658", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba calor, ¿qué sucede si 'Check Valve' condensador falla abierta?", opciones:["En modo calor el refrigerante hará bypass a TXV impidiendo calentamiento hoy hoy.", "El sistema funcionará mejor al haber menos restricción al flujo líquido hoy.", "La presión de descarga subirá hasta que switch de alta apague el equipo hoy.", "El compresor se quemará por el retorno de líquido masivo en el arranque hoy."], respuesta_correcta:0, explicacion:"La check valve permite bypass en modo calor. Si falla abierta, el refrigerante no pasa por la TXV, eliminando la restriccion necesaria para la caida de presion y el calentamiento adecuado del sistema." },
  { id:"ns_0659", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o inyección de líquido?", opciones:["Para enfriar gas de succión y evitar que descarga dañe el aceite hoy hoy hoy hoy.", "Para aumentar la presión de succión cuando carga en vitrinas es baja hoy hoy.", "Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos hoy hoy."], respuesta_correcta:0, explicacion:"La válvula Quench controla la temperatura de descarga inyectando refrigerante líquido. Esto es esencial en racks de baja temperatura donde el alto ratio de compresión genera temperaturas de descarga que pueden descomponer el aceite lubricante." },
  { id:"ns_0660", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. ¿Criterio?", opciones:["El volumen de agua y la accesibilidad para eliminación segura del fluido hoy hoy.", "Cuál de las dos herramientas es más nueva y hace menos ruido al operar hoy.", "La preferencia del cliente sobre qué herramienta quiere ver en su casa hoy.", "Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy."], respuesta_correcta:0, explicacion:"La selección correcta de herramienta se basa en criterios técnicos: cuánta agua hay que remover y si el punto de acumulación es accesible. Estas condiciones dictan la herramienta óptima para una resolución eficiente y segura." },
  { id:"ns_0661", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar prueba presión a tubos del evaporador para buscar rupturas hoy hoy hoy.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.", "Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy."], respuesta_correcta:0, explicacion:"La detección de agua por la purga es una emergencia que requiere prueba de presión inmediata en los tubos del evaporador para identificar posibles rupturas que contaminen el refrigerante." },
  { id:"ns_0662", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión 130 PSI y descarga 380 PSI. Subenfriamiento 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango hoy hoy.", "Falta de refrigerante líquido; el subenfriamiento debería ser 15 grados hoy.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno hoy.", "Compresor fallando; la diferencia presión entre succión y descarga es baja hoy."], respuesta_correcta:0, explicacion:"Presiones de 130/380 PSI con subenfriamiento de 12°F son valores que caen dentro del rango óptimo de operación para R-410A. El subenfriamiento entre 10-15°F es ideal para confirmar carga correcta y condensación eficiente." },
  { id:"ns_0663", categoria:"NATE_SR_PACKAGE", pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. ¿Qué revisa?", opciones:["El voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo hoy hoy hoy.", "Si los contactos principales están quemados o soldados entre sí hoy hoy hoy.", "El capacitor de arranque del compresor que podría estar descargado hoy hoy.", "La continuidad de los fusibles de potencia de la línea de 240 voltios hoy hoy."], respuesta_correcta:0, explicacion:"El zumbido del contactor sin cierre mecánico es diagnóstico de fuerza electromagnética insuficiente. Se verifica primero el voltaje de la bobina (debe ser mínimo 85% del nominal) y la limpieza del núcleo magnético, ya que la suciedad impide el contacto total de las superficies polares." },
  { id:"ns_0664", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico cobra 'por fuera' a clientes. ¿Qué acción toma?", opciones:["Despido inmediato y posible acción legal según el contrato de trabajo hoy hoy hoy.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras hoy hoy.", "Ignorar la situación si el técnico es el que más dinero genera hoy hoy hoy.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."], respuesta_correcta:0, explicacion:"El cobro por fuera constituye fraude; la respuesta correcta es el despido inmediato y la evaluación de acciones legales según lo estipulado en el contrato laboral." },
  { id:"ns_0665", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en el recibidor?", opciones:["Para evitar fraccionamiento de la mezcla y asegurar composición correcta hoy hoy hoy.", "Para que el refrigerante se mezcle más rápido con el aceite POE del rack hoy.", "Para prevenir que las válvulas de descarga de compresores se calienten hoy hoy.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy hoy."], respuesta_correcta:0, explicacion:"Al cargar R-448A en fase líquida, se garantiza que la mezcla de componentes (R-32, R-125, R-134a, R-1234yf, R-1234ze) entre al sistema con la composición de diseño, evitando el fraccionamiento que ocurriría si se carga en gas." },
  { id:"ns_0666", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. ¿Efecto?", opciones:["El controlador no podrá calcular la carga térmica real del edificio hoy hoy hoy.", "El compresor se apagará inmediatamente por seguridad de flujo de agua hoy hoy.", "La unidad operará siempre al 100% de su capacidad nominal sin modular hoy hoy.", "No hay efecto si el sensor de 'Leaving Water' está operando correctamente hoy hoy."], respuesta_correcta:0, explicacion:"Sin el sensor de entering water, el controlador pierde la referencia de carga térmica del edificio y no puede calcular correctamente la modulación de capacidad necesaria." },
  { id:"ns_0667", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga de 550 PSI con R-410A. ¿Causa?", opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy.", "Falta de refrigerante líquido que impide que el sistema enfríe el aire hoy hoy.", "Válvula de expansión electrónica bloqueada en la posición de abierta total hoy.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy."], respuesta_correcta:0, explicacion:"Una descarga de 550 PSI con R-410A es críticamente alta y requiere atención inmediata. Un condensador extremadamente sucio o un ventilador que no funciona elimina la capacidad de rechazar calor, causando una acumulación peligrosa de presión." },
  { id:"ns_0668", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Average Response Time'. ¿Qué medida toma hoy?", opciones:["Implementar software de despacho inteligente y zonificación de técnicos hoy hoy hoy.", "Aumentar el número de técnicos en la nómina aunque no haya llamadas suficientes.", "Reducir el tiempo de almuerzo de los técnicos para que estén más disponibles hoy.", "Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy."], respuesta_correcta:0, explicacion:"El software de despacho inteligente con zonificación reduce el tiempo de respuesta al enviar automáticamente al técnico más cercano y mejor calificado para cada emergencia." },
  { id:"ns_0669", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería fluctuar entre 0 y 24VDC hoy hoy hoy hoy.", "La placa exterior está operando correctamente enviando la señal de control hoy.", "El compresor inverter está aterrizado y consume el voltaje de comunicación hoy.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior hoy hoy."], respuesta_correcta:0, explicacion:"La comunicación inverter entre S2 y S3 usa señales DC pulsantes (0-24V). Un voltaje fijo de 24VDC constante significa que no hay transmisión de datos: existe una falla de comunicación." },
  { id:"ns_0670", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Defrost Sensor' falla en circuito abierto?", opciones:["El sistema nunca entrará en modo de deshielo y el serpentín se congelará hoy hoy.", "El sistema entrará en modo de deshielo cada 30 minutos sin importar el hielo hoy.", "El compresor se quemará debido a la falta de control de sobrecalentamiento hoy.", "La unidad operará solo en modo refrigeración permanentemente por seguridad hoy."], respuesta_correcta:0, explicacion:"Con el sensor de defrost en circuito abierto, la placa interpreta que la temperatura del serpentin nunca baja lo suficiente. El sistema no cumple las condiciones para iniciar el deshielo y el hielo se acumula." },
  { id:"ns_0671", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un sistema VRF. ¿Por qué es vital pesar la carga?", opciones:["Los sistemas VRF son de carga crítica y las presiones no son indicadores hoy hoy hoy.", "Es un requisito legal de la EPA para sistemas con más de 50 libras de gas hoy.", "Para asegurar que el aceite POE regrese correctamente a los compresores hoy hoy.", "Para evitar que la garantía del fabricante se anule tras la instalación hoy hoy."], respuesta_correcta:0, explicacion:"En sistemas VRF con múltiples zonas y líneas extensas, las presiones fluctúan según la demanda térmica de cada evaporador. Por eso, el pesaje exacto de refrigerante según la fórmula del fabricante es el único método confiable de carga." },
  { id:"ns_0672", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Reversal'. ¿Qué sucede si se ignora el error?", opciones:["El compresor girará al revés y no bombeará aceite ni refrigerante líquido hoy hoy hoy.", "La unidad funcionará al 50% de su capacidad nominal debido al desfase fase hoy.", "El motor se quemará instantáneamente al intentar vencer la inercia carga hoy hoy.", "Las válvulas de expansión se cerrarán por seguridad al detectar el error hoy hoy."], respuesta_correcta:0, explicacion:"Phase Reversal causa rotación inversa del compresor, eliminando el bombeo de aceite y la circulación de refrigerante. Los cojinetes fallan rápidamente sin lubricación adecuada." },
  { id:"ns_0673", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. Subenfriamiento 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged) hoy hoy hoy hoy.", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy hoy hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio térmico.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F con presiones moderadas es el indicador diagnóstico definitivo de falta severa de refrigerante. No hay suficiente masa de refrigerante en el sistema para que el condensador produzca líquido subenfriado en su salida." },
  { id:"ns_0674", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy hoy hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy hoy hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy hoy hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos hoy hoy."], respuesta_correcta:0, explicacion:"Smart Homes exige técnicos que dominen redes y protocolos de comunicación para integrar termostatos inteligentes, sensores IoT y sistemas de automatización con el HVAC." },
  { id:"ns_0675", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué indica una temperatura de succión muy alta en el cabezal?", opciones:["Sobrecalentamiento excesivo que dañará la lubricación de compresores pronto hoy hoy.", "Que el sistema está operando a su máxima eficiencia de evaporación hoy hoy hoy.", "Falta de refrigerante líquido en el recibidor principal del rack paralelo hoy hoy.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura hoy hoy."], respuesta_correcta:0, explicacion:"El gas de succión demasiado caliente significa que los compresores reciben vapor con poco contenido de refrigerante líquido para enfriar el motor. Esto causa degradación acelerada del aceite y posible daño en los devanados del motor eléctrico." },
  { id:"ns_0676", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. ¿Qué revisa?", opciones:["Presencia de aire en la tubería, paddle roto o transductor descalibrado hoy hoy hoy.", "La carga de refrigerante que podría estar congelando el agua en tubos hoy hoy.", "El sentido de rotación del motor del compresor centrífugo del sistema hoy hoy hoy.", "La apertura de las válvulas de expansión del circuito de refrigeración hoy hoy hoy."], respuesta_correcta:0, explicacion:"Una alarma de flow switch con bomba operando indica un problema del sensor (paddle, transductor) o aire en la tubería, no del sistema de refrigeración del chiller." },
  { id:"ns_0677", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior hoy hoy hoy.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy hoy.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido hoy.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy hoy hoy."], respuesta_correcta:0, explicacion:"El goteo al detenerse el compresor es causado por agua acumulada que no drena durante la operación debido a contrapendiente o bloqueo parcial alto en la línea de drenaje." },
  { id:"ns_0678", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de 0.9 en suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy hoy hoy hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire hoy hoy.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy hoy hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy hoy hoy."], respuesta_correcta:0, explicacion:"La distribución 0.9\"/0.2\" de presión estática indica restricción predominante en el suministro. Cuando la mayoría de la caída de presión está en el suministro, hay que buscar conductos restringidos, dañados o difusores cerrados en ese lado." },
  { id:"ns_0679", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre 20°F y 30°F hoy hoy hoy.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos hoy hoy.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube hoy.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo hoy hoy."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en calefaccion esta fuera del rango aceptable (20-30F). Indica capacidad insuficiente, que puede deberse a baja carga de refrigerante, exceso de flujo de aire, o absorcion deficiente de calor exterior." },
  { id:"ns_0680", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar prueba de acidez del aceite y usar filtros succión de limpieza hoy hoy.", "Añadir aditivo sellador de fugas para prevenir fallas futuras en líneas hoy hoy.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado hoy hoy.", "Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy hoy."], respuesta_correcta:0, explicacion:"El procedimiento post-burnout incluye obligatoriamente la prueba de acidez del aceite y la instalación de filtros de succión de limpieza. Estos pasos eliminan contaminantes ácidos y residuos sólidos que destruirían prematuramente el compresor nuevo." },
  { id:"ns_0681", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. ¿Estado?", opciones:["Funcionamiento correcto; la purga está separando los no condensables hoy hoy hoy hoy.", "Falla en el serpentín de condensación interno de la unidad de purga hoy hoy hoy.", "El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy hoy.", "La temperatura del evaporador es demasiado alta para que la purga trabaje hoy hoy."], respuesta_correcta:0, explicacion:"La purga que expulsa aire con mínimo refrigerante funciona correctamente. Su diseño separa gases no condensables y los expulsa mientras retorna el refrigerante al sistema." },
  { id:"ns_0682", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si el 'Oil Separator' queda pegado en posición abierta?", opciones:["Gas caliente de descarga pasará directo al depósito aceite y succión hoy hoy hoy.", "El rack se quedará sin aceite en pocos minutos al no poder separarlo gas hoy hoy.", "Los compresores se apagarán por alta presión al bloquearse el flujo gas hoy hoy.", "El nivel de aceite en los cárteres subirá tanto que dañará los pistones hoy hoy."], respuesta_correcta:0, explicacion:"Un flotador trabado abierto en el separador permite el paso directo de gas de descarga a alta presión y temperatura hacia el depósito de aceite. Este cortocircuito interno compromete tanto la separación de aceite como la eficiencia del sistema." },
  { id:"ns_0683", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. ¿Qué KPI usa?", opciones:["Número de llamadas de nuevos clientes que mencionan haber visto la unidad hoy hoy hoy.", "La cantidad de millas recorridas por cada vehículo en zonas residenciales hoy hoy.", "El costo total del diseño e instalación del rótulo dividido entre 12 meses hoy.", "El aumento en la velocidad promedio de técnicos al conducir camionetas nuevas hoy."], respuesta_correcta:0, explicacion:"El KPI para camionetas rotuladas es el número de llamadas de nuevos clientes que reportan haber visto el vehículo, vinculando directamente la inversión con nuevos leads." },
  { id:"ns_0684", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. ¿Qué revisa?", opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy hoy hoy.", "La carga de refrigerante líquido basándose en el visor del evaporador hoy hoy hoy.", "Si la válvula de expansión está inyectando demasiado líquido al sistema hoy hoy.", "El estado de los filtros de aire de la manejadora de aire del edificio hoy hoy."], respuesta_correcta:0, explicacion:"Alta presión de condensación con condensador de agua se diagnostica primero verificando la temperatura del agua de torre y la operación de la bomba de agua de condensador." },
  { id:"ns_0685", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión de 125 PSI y descarga 400 PSI con R-410A. ¿Estado aire?", opciones:["Funcionamiento normal bajo condiciones de carga térmica estándar hoy hoy hoy hoy hoy.", "Falta de refrigerante que impide que temperatura del aire baje a 55 grados hoy hoy.", "Exceso de carga que está elevando la presión de descarga innecesariamente hoy hoy.", "Compresor con eficiencia reducida que no logra enfriar el aire correctamente hoy."], respuesta_correcta:0, explicacion:"Succión de 125 PSI y descarga de 400 PSI son valores estándar para R-410A bajo condiciones normales de carga. El diferencial de presión y las temperaturas de saturación corresponden a operación correcta del sistema." },
  { id:"ns_0686", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. ¿Qué estrategia?", opciones:["Programa de membresías mantenimiento para convertir clientes en recurrentes hoy hoy hoy.", "Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy hoy hoy.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos hoy hoy.", "Despedir a técnicos que no logren vender un sistema nuevo en cada visita hoy hoy."], respuesta_correcta:0, explicacion:"Un programa de membresías de mantenimiento es la estrategia clave para reducir el porcentaje de clientes que solo usan el servicio una vez." },
  { id:"ns_0687", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una restricción en la válvula de expansión hoy hoy hoy.", "Si el ventilador interior está sucio y no sopla suficiente aire frío hoy hoy hoy.", "El voltaje de la línea eléctrica que podría estar por debajo de 200V hoy hoy hoy.", "Si el control remoto está configurado en una temperatura demasiado baja hoy hoy."], respuesta_correcta:0, explicacion:"La temperatura de descarga excesiva se produce por falta de refrigerante o restricción en la EEV, ya que ambas condiciones reducen el enfriamiento del compresor por el gas de succión." },
  { id:"ns_0688", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba calor, ¿qué sucede si 'Check Valve' condensador falla abierta?", opciones:["En modo calor el refrigerante hará bypass a TXV impidiendo calentamiento hoy hoy hoy.", "El sistema funcionará mejor al haber menos restricción al flujo líquido hoy hoy.", "La presión de descarga subirá hasta que switch de alta apague el equipo hoy hoy.", "El compresor se quemará por el retorno de líquido masivo en el arranque hoy hoy."], respuesta_correcta:0, explicacion:"Si la check valve del condensador falla abierta, el refrigerante en modo calor hace bypass a la TXV sin restriccion. Sin caida de presion en el dispositivo de expansion, no hay transferencia de calor efectiva." },
  { id:"ns_0689", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o inyección de líquido?", opciones:["Para enfriar gas de succión y evitar que descarga dañe el aceite hoy hoy hoy hoy hoy.", "Para aumentar la presión de succión cuando carga en vitrinas es baja hoy hoy hoy.", "Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy hoy.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos hoy hoy hoy."], respuesta_correcta:0, explicacion:"La inyección de líquido Quench protege los compresores manteniendo la temperatura de descarga en rangos seguros. El aceite POE se descompone a temperaturas superiores a 250°F, generando ácidos que corroen componentes internos del compresor." },
  { id:"ns_0690", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. ¿Criterio?", opciones:["El volumen de agua y la accesibilidad para eliminación segura del fluido hoy hoy hoy.", "Cuál de las dos herramientas es más nueva y hace menos ruido al operar hoy hoy.", "La preferencia del cliente sobre qué herramienta quiere ver en su casa hoy hoy.", "Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy hoy."], respuesta_correcta:0, explicacion:"El criterio técnico correcto evalúa el volumen total de agua y las condiciones de acceso al punto de drenaje. Estos factores determinan si una aspiradora de agua o una bomba es la herramienta más apropiada para la eliminación segura y eficiente." },
  { id:"ns_0691", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar prueba presión a tubos del evaporador para buscar rupturas hoy hoy hoy hoy.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy hoy.", "Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy hoy.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy hoy."], respuesta_correcta:0, explicacion:"Water Detected por la purga requiere acción urgente: prueba de presión a los tubos del evaporador para identificar la fuente de contaminación por agua antes de que dañe el sistema." },
  { id:"ns_0692", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión 130 PSI y descarga 380 PSI. Subenfriamiento 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango hoy hoy hoy.", "Falta de refrigerante líquido; el subenfriamiento debería ser 15 grados hoy hoy.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno hoy hoy.", "Compresor fallando; la diferencia presión entre succión y descarga es baja hoy hoy."], respuesta_correcta:0, explicacion:"Las presiones de 130/380 PSI con 12°F de subenfriamiento confirman operación óptima. Todos los valores están en rangos aceptables para R-410A, indicando carga correcta y buen funcionamiento del compresor y componentes." },
  { id:"ns_0693", categoria:"NATE_SR_PACKAGE", pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. ¿Qué revisa?", opciones:["El voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo hoy hoy hoy hoy.", "Si los contactos principales están quemados o soldados entre sí hoy hoy hoy hoy.", "El capacitor de arranque del compresor que podría estar descargado hoy hoy hoy.", "La continuidad de los fusibles de potencia de la línea de 240 voltios hoy hoy hoy."], respuesta_correcta:0, explicacion:"Cuando un contactor zumba sin cerrar, la bobina electromagnética no puede vencer la fuerza del resorte de retorno. Las dos causas principales son voltaje bajo en la bobina (caída por cableado o transformador débil) y contaminación del núcleo que aumenta el entrehierro efectivo." },
  { id:"ns_0694", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico cobra 'por fuera' a clientes. ¿Qué acción toma?", opciones:["Despido inmediato y posible acción legal según el contrato de trabajo hoy hoy hoy hoy.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras hoy hoy hoy.", "Ignorar la situación si el técnico es el que más dinero genera hoy hoy hoy hoy.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy hoy."], respuesta_correcta:0, explicacion:"Cobrar por fuera viola la confianza y el contrato laboral; el despido inmediato con posible acción legal es la medida necesaria para preservar la integridad del negocio." },
  { id:"ns_0695", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en el recibidor?", opciones:["Para evitar fraccionamiento de la mezcla y asegurar composición correcta hoy hoy hoy hoy.", "Para que el refrigerante se mezcle más rápido con el aceite POE del rack hoy hoy.", "Para prevenir que las válvulas de descarga de compresores se calienten hoy hoy hoy.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy hoy hoy."], respuesta_correcta:0, explicacion:"El fraccionamiento de mezclas zeotrópicas como el R-448A ocurre cuando los componentes se separan al evaporarse a diferentes temperaturas. Cargar siempre en líquido mantiene la proporción exacta de cada componente en la mezcla refrigerante." },
  { id:"ns_0696", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. ¿Efecto?", opciones:["El controlador no podrá calcular la carga térmica real del edificio hoy hoy hoy hoy.", "El compresor se apagará inmediatamente por seguridad de flujo de agua hoy hoy hoy.", "La unidad operará siempre al 100% de su capacidad nominal sin modular hoy hoy hoy.", "No hay efecto si el sensor de 'Leaving Water' está operando correctamente hoy hoy hoy."], respuesta_correcta:0, explicacion:"Sin el sensor de entrada de agua, el controlador no puede determinar la carga térmica real, afectando la capacidad de modular correctamente la operación del chiller." },
  { id:"ns_0697", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga de 550 PSI con R-410A. ¿Causa?", opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy hoy.", "Falta de refrigerante líquido que impide que el sistema enfríe el aire hoy hoy hoy.", "Válvula de expansión electrónica bloqueada en la posición de abierta total hoy hoy.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy hoy."], respuesta_correcta:0, explicacion:"Descarga de 550 PSI es extremadamente alta para R-410A y se acerca al límite de seguridad del sistema. Sin disipación adecuada de calor por condensador sucio o ventilador fallando, la presión se acumula hasta niveles peligrosos que activan la protección de alta presión." },
  { id:"ns_0698", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Average Response Time'. ¿Qué medida toma hoy?", opciones:["Implementar software de despacho inteligente y zonificación de técnicos hoy hoy hoy hoy.", "Aumentar el número de técnicos en la nómina aunque no haya llamadas suficientes hoy.", "Reducir el tiempo de almuerzo de los técnicos para que estén más disponibles hoy hoy.", "Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy hoy."], respuesta_correcta:0, explicacion:"Implementar software de despacho inteligente con zonificación de técnicos es la medida más técnica y efectiva para reducir el Average Response Time de la empresa." },
  { id:"ns_0699", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería fluctuar entre 0 y 24VDC hoy hoy hoy hoy hoy.", "La placa exterior está operando correctamente enviando la señal de control hoy hoy.", "El compresor inverter está aterrizado y consume el voltaje de comunicación hoy hoy.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior hoy hoy hoy."], respuesta_correcta:0, explicacion:"La señal entre S2 y S3 debe fluctuar entre 0 y 24VDC para transmitir datos. Un voltaje fijo de 24VDC indica falla de comunicación porque no hay modulación de señal digital." },
  { id:"ns_0700", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Defrost Sensor' falla en circuito abierto?", opciones:["El sistema nunca entrará en modo de deshielo y el serpentín se congelará hoy hoy hoy.", "El sistema entrará en modo de deshielo cada 30 minutos sin importar el hielo hoy hoy.", "El compresor se quemará debido a la falta de control de sobrecalentamiento hoy hoy.", "La unidad operará solo en modo refrigeración permanentemente por seguridad hoy hoy."], respuesta_correcta:0, explicacion:"Cuando el sensor de defrost falla en circuito abierto, la placa nunca recibe la lectura de temperatura fria del serpentin. Sin cumplir esta condicion, el ciclo de deshielo nunca se inicia y el serpentin se congela." },
  { id:"ns_0701", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Vibration Trip' a altas RPM. Al inspeccionar, se encuentra un ligero desgaste en los sellos de laberinto. ¿Qué riesgo Senior existe?", opciones:["Pérdida de eficiencia por bypass interno de gas y aumento del ruido acústico.", "Migración masiva de aceite hacia el condensador que bloqueará el intercambio.", "Explosión por sobrepresión interna al mezclarse el aire con el refrigerante.", "Reducción inmediata de la temperatura de descarga por debajo de saturación."], respuesta_correcta:0, explicacion:"El desgaste de sellos de laberinto permite bypass interno de gas entre etapas de compresión, reduciendo la eficiencia del compresor y aumentando el nivel de ruido acústico durante la operación." },
  { id:"ns_0702", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo con NH3 (Amoníaco), ¿cuál es la función de la válvula de purga de aire automática?", opciones:["Eliminar gases no condensables del condensador para reducir la presión de alta.", "Liberar presión de succión hacia la atmósfera en caso de un paro de emergencia.", "Drenar el aceite acumulado en el fondo de los evaporadores de baja temperatura.", "Inyectar nitrógeno para mantener la presión positiva cuando el rack está parado."], respuesta_correcta:0, explicacion:"Los gases no condensables (aire) se acumulan en el condensador y aumentan la presión de descarga innecesariamente. La válvula de purga automática detecta y elimina estos gases, manteniendo la eficiencia del condensador y reduciendo el consumo energético." },
  { id:"ns_0703", categoria:"NATE_SR_CEO", pregunta:"Un CEO recibe una reseña negativa viral sobre un técnico Senior. ¿Cuál es la estrategia de 'Damage Control' más efectiva?", opciones:["Responder con empatía, ofrecer una solución pública y realizar una auditoría interna.", "Ignorar el comentario para evitar que el algoritmo de redes sociales lo difunda más.", "Demandar al cliente por difamación si no presenta pruebas técnicas del mal servicio.", "Despedir al técnico Senior inmediatamente para demostrar firmeza ante el público."], respuesta_correcta:0, explicacion:"Responder con empatía, ofrecer una solución pública y hacer una auditoría interna demuestra profesionalismo, convierte una crisis en oportunidad y protege la reputación a largo plazo." },
  { id:"ns_0704", categoria:"NATE_SR_PACKAGE", pregunta:"Un variador de frecuencia (VFD) genera interferencia (EMI) que afecta a los sensores DDC cercanos. ¿Qué componente debe instalar el Senior?", opciones:["Un filtro de armónicos en la entrada o cables de motor blindados con tierra.", "Un transformador de aislamiento de mayor capacidad para alimentar al variador.", "Capacitores de corrección de factor de potencia en paralelo con el motor AC.", "Un supresor de picos (TVSS) en el tablero de distribución eléctrica principal."], respuesta_correcta:0, explicacion:"Los VFD generan armónicos y ruido EMI por la conmutación PWM de alta frecuencia. Un filtro de armónicos en la entrada reduce las corrientes armónicas, y los cables blindados con tierra adecuada contienen la radiación electromagnética, protegiendo los sensores DDC cercanos de interferencias." },
  { id:"ns_0705", categoria:"NATE_SR_HVAC", pregunta:"Un sistema de 10 toneladas tiene un Delta P de 0.1 pulg. W.C. a través de un serpentín de enfriamiento. ¿Qué indica este valor?", opciones:["Falta de flujo de aire crítico o serpentín extremadamente sobredimensionado.", "Serpentín saturado de suciedad que requiere una limpieza química profunda hoy.", "Operación nominal según las tablas de diseño para sistemas de alta velocidad.", "Que el motor del soplador está girando al doble de sus RPM de placa nominal."], respuesta_correcta:0, explicacion:"Un Delta P de solo 0.1\" W.C. a través de un serpentín de 10 toneladas es extremadamente bajo e indica que casi no hay aire pasando. Esto significa falta de flujo de aire crítico, ya sea por un soplador fallando, conductos desconectados o un serpentín enormemente sobredimensionado." },
  { id:"ns_0706", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor presenta una succión de 60 PSI con R-410A. El serpentín exterior está limpio. ¿Qué revisa el Senior?", opciones:["La válvula de expansión exterior o una posible falta de carga de refrigerante.", "El ventilador interior que podría estar moviendo aire a una velocidad excesiva.", "La válvula inversora que podría estar parcialmente movida hacia refrigeración.", "El sensor de temperatura de aire de retorno que activa el ciclo de deshielo."], respuesta_correcta:0, explicacion:"Una succion de 60 PSI con R-410A equivale a aproximadamente 17F de saturacion, lo cual es bajo para modo calor. Con el serpentin limpio, la causa mas probable es una TXV exterior defectuosa o falta de carga." },
  { id:"ns_0707", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un equipo que realiza una prueba de presión con aire comprimido en lugar de nitrógeno. ¿Por qué es una falla grave?", opciones:["El aire introduce humedad y oxígeno, lo que causará acidez y oxidación interna.", "El aire comprimido no alcanza las presiones necesarias para detectar micro-fugas.", "La EPA prohíbe el uso de aire atmosférico en sistemas que usaron aceites POE.", "El aire comprimido es explosivo cuando se mezcla con restos de aceite mineral."], respuesta_correcta:0, explicacion:"El aire comprimido contiene humedad y oxígeno. La humedad reacciona con el refrigerante y el aceite formando ácidos corrosivos, y el oxígeno oxida las superficies internas de cobre. El nitrógeno seco es inerte y libre de humedad, por eso es el estándar." },
  { id:"ns_0708", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller centrífugo, ¿qué parámetro define el 'Choke Point' o punto de saturación de flujo?", opciones:["La velocidad del sonido del refrigerante en la garganta del impulsor del motor.", "La temperatura máxima que puede soportar el aceite antes de carbonizarse hoy.", "La presión diferencial máxima entre el condensador y el evaporador del sistema.", "El amperaje máximo de placa del motor dividido por el factor de servicio real."], respuesta_correcta:0, explicacion:"El choke point ocurre cuando el flujo de gas alcanza la velocidad del sonido (velocidad sónica) en la garganta del impulsor, limitando el flujo máximo independientemente del diferencial de presión." },
  { id:"ns_0709", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 30 toneladas presenta una falla de 'Low Suction Pressure'. El filtro está limpio. ¿Qué revisa el Senior?", opciones:["La carga de refrigerante y el funcionamiento de la válvula de expansión térmica.", "La rotación del ventilador del condensador que podría estar girando al revés.", "Si el economizador está introduciendo demasiado aire exterior frío al sistema.", "El ajuste del interruptor de alta presión que podría estar disparando el paro."], respuesta_correcta:0, explicacion:"Una presión de succión baja con filtro limpio indica que no llega suficiente refrigerante al evaporador. Las causas principales son carga baja (fuga) o una TXV que no abre lo suficiente, restringiendo el flujo de refrigerante líquido y bajando la presión de evaporación." },
  { id:"ns_0710", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC analiza el 'Customer Retention Rate'. Si este baja del 70%, ¿cuál es el impacto financiero?", opciones:["Aumento drástico en el CAC (Customer Acquisition Cost) para mantener el ingreso.", "Reducción inmediata en los costos de marketing al haber menos clientes activos.", "Mejora en el margen de utilidad neta al enfocarse solo en clientes nuevos hoy.", "Incremento en el valor de reventa de la empresa por la rotación de cartera."], respuesta_correcta:0, explicacion:"Cuando la retención cae del 70%, la empresa debe gastar mucho más en adquirir nuevos clientes (CAC alto) para reemplazar a los que se van, afectando severamente la rentabilidad." },
  { id:"ns_0711", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que marca 'High Non-Condensable Concentration'. El sistema opera a presión positiva. ¿Causa?", opciones:["Infiltración de aire durante una carga de refrigerante o servicio mal realizado.", "Falla en el serpentín de condensación de la purga que no licúa el refrigerante.", "El refrigerante se está descomponiendo químicamente por alta temperatura descarga.", "Agua infiltrada desde el evaporador que se está evaporando dentro del sistema."], respuesta_correcta:0, explicacion:"En un sistema a presión positiva, la alta concentración de no condensables indica que el aire entró durante un servicio o carga de refrigerante mal realizada, no por infiltración durante operación." },
  { id:"ns_0712", categoria:"NATE_SR_RACK", pregunta:"En un rack de refrigeración, ¿cuál es el síntoma de un separador de aceite con el flotador perforado?", opciones:["Paso masivo de gas de descarga hacia el depósito de aceite y la línea de succión.", "Falla de lubricación inmediata al no retornar aceite hacia los compresores hoy.", "Aumento en la presión de descarga debido a la restricción de flujo de gas hoy.", "Nivel de aceite excesivamente alto en el cárter de todos los compresores rack."], respuesta_correcta:0, explicacion:"Un flotador perforado se hunde y queda permanentemente abierto, permitiendo el paso continuo de gas de descarga caliente hacia el depósito de aceite y eventualmente hacia la succión, creando un bypass que reduce la capacidad del sistema." },
  { id:"ns_0713", categoria:"NATE_SR_CEO", pregunta:"Un CEO evalúa el 'Account Payable Turnover'. Si este valor es muy bajo, ¿qué indica?", opciones:["La empresa está tardando demasiado en pagar a sus proveedores de materiales.", "La empresa tiene un flujo de caja excelente y paga todas sus deudas pronto.", "Los clientes están pagando sus facturas de servicio de forma casi instantánea.", "El inventario de piezas se está moviendo más rápido de lo presupuestado hoy."], respuesta_correcta:0, explicacion:"Un Account Payable Turnover bajo significa que la empresa tarda demasiado en pagar a sus proveedores, lo que puede dañar relaciones comerciales y limitar el crédito futuro." },
  { id:"ns_0714", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF tiene un error de 'Sub-cooling Thermistor'. ¿Cómo afecta esto la eficiencia?", opciones:["El sistema no puede optimizar la carga de líquido, aumentando el consumo eléctrico.", "El compresor inverter se bloqueará para evitar que el líquido llegue a succión.", "La unidad exterior se apagará por completo hasta que el sensor sea reemplazado.", "No afecta si la temperatura de descarga se mantiene por debajo de 200 grados F."], respuesta_correcta:0, explicacion:"El termistor de subenfriamiento permite al sistema optimizar la cantidad de líquido en el condensador. Sin esta lectura, el sistema no ajusta eficientemente la carga de líquido, aumentando el consumo eléctrico." },
  { id:"ns_0715", categoria:"NATE_SR_HVAC", pregunta:"Se encuentra un 'Voltage Imbalance' del 4% en un motor trifásico. ¿Cuál es el aumento de temperatura estimado?", opciones:["Aproximadamente un 25% a 30% por encima de la temperatura de operación normal.", "Menos del 5%, lo cual es despreciable para motores con factor de servicio 1.15.", "El motor operará más frío debido a la reducción del par motor (torque) total.", "Depende únicamente de si el motor es de alta eficiencia (NEMA Premium) o no."], respuesta_correcta:0, explicacion:"Un desbalance de voltaje del 4% causa un aumento desproporcionado de temperatura en los devanados de aproximadamente 25-30%. La regla general es que el aumento de temperatura es proporcional al cuadrado del porcentaje de desbalance multiplicado por un factor de ~2." },
  { id:"ns_0716", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor activa el defrost. El ventilador exterior no se detiene. ¿Causa?", opciones:["Relé de la placa de control pegado o lógica de control de defrost defectuosa.", "Es un comportamiento normal en modelos nuevos que usan VFD en el ventilador.", "La válvula inversora no logró cambiar de posición y el sistema sigue en calor.", "El sensor de temperatura de ambiente exterior está marcando un valor falso hoy."], respuesta_correcta:0, explicacion:"Durante el defrost, el ventilador exterior debe detenerse para que el gas caliente derrita el hielo sin que el aire frio enfrie el serpentin. Si el rele de la placa esta pegado, el ventilador sigue y el deshielo es ineficaz." },
  { id:"ns_0717", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior observa que un Junior no realiza el 'Triple Vacío'. ¿Cuál es el beneficio que se pierde?", opciones:["La capacidad de remover humedad profunda mediante la dilución con nitrógeno seco.", "El ahorro de tiempo en el proceso de evacuación de sistemas de gran tonelaje.", "La verificación de la estanqueidad del sistema antes de cargar el refrigerante.", "La eliminación de los incondensables que quedan atrapados en el aceite POE hoy."], respuesta_correcta:0, explicacion:"El triple vacío consiste en evacuar, romper el vacío con nitrógeno seco, y repetir tres veces. Cada ciclo de nitrógeno diluye y arrastra la humedad residual que el vacío solo no puede eliminar completamente, logrando un secado mucho más profundo." },
  { id:"ns_0718", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con evaporador de placas presenta una fuga interna. ¿Cuál es el síntoma?", opciones:["Mezcla de agua en el refrigerante y refrigerante en el lazo de agua helada.", "Aumento drástico de la presión de succión debido a la densidad del agua.", "El aceite se vuelve lechoso y el compresor se apaga por alta presión aceite.", "La temperatura del agua helada baja de golpe por debajo del punto congelación."], respuesta_correcta:0, explicacion:"Una fuga interna en un evaporador de placas permite que el agua y el refrigerante se mezclen en ambas direcciones, contaminando tanto el circuito de refrigerante como el lazo de agua helada." },
  { id:"ns_0719", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete industrial tiene un motor de soplador con polea ajustable. Para aumentar CFM, ¿qué hace?", opciones:["Cerrar la polea del motor para aumentar el diámetro efectivo y las RPM.", "Abrir la polea del motor para reducir la tensión de la correa y el roce hoy.", "Cambiar la polea del soplador por una de mayor diámetro para ganar torque.", "Ajustar los tornillos de la base del motor para estirar la correa al máximo."], respuesta_correcta:0, explicacion:"En una polea ajustable del motor, cerrar las mitades aumenta el diámetro efectivo donde corre la correa. Esto aumenta la relación de poleas, haciendo que la polea del soplador gire más rápido (más RPM), lo que incrementa los CFM entregados al sistema de ductos." },
  { id:"ns_0720", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere implementar 'Job Costing' en tiempo real. ¿Qué dato es el más difícil de capturar?", opciones:["El costo exacto de los consumibles menores y el tiempo de viaje real hoy.", "El precio de los equipos principales como condensadores o manejadoras aire.", "El salario bruto de los técnicos Senior que realizan la instalación hoy hoy.", "La cantidad de refrigerante recuperado durante el proceso de desinstalación."], respuesta_correcta:0, explicacion:"Los consumibles menores (selladores, cinta, conectores) y el tiempo de viaje real son los datos más difíciles de capturar en tiempo real para un Job Costing preciso." },
  { id:"ns_0721", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un 'Approach' de condensador de 15°F. Se sospecha de aire. ¿Cómo lo confirma?", opciones:["Comparando la presión de descarga con la temperatura de saturación del gas.", "Midiendo la temperatura de la carcasa del condensador con un sensor láser.", "Drenando una muestra de refrigerante y oliendo si hay presencia de ácido.", "Observando si hay burbujas en la mirilla de la línea de líquido del chiller."], respuesta_correcta:0, explicacion:"Comparando la presión de descarga real con la presión de saturación a la temperatura medida del refrigerante, se confirma la presencia de aire. Si la presión real es mayor, hay no condensables." },
  { id:"ns_0722", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una succión de 100 PSI y descarga de 400 PSI con R-410A. ¿Cómo está el flujo?", opciones:["Bajo flujo de aire en el evaporador o falta de carga de refrigerante leve.", "Funcionamiento normal considerando una temperatura exterior de 95 grados F.", "Exceso de carga que está inundando el serpentín del condensador exterior.", "Compresor con válvulas dañadas que no logran bombear el gas correctamente."], respuesta_correcta:0, explicacion:"Succión de 100 PSI (baja, ~30°F sat.) con descarga de 400 PSI indica que el evaporador no absorbe suficiente calor. Bajo flujo de aire reduce la carga térmica en el evaporador, y falta leve de carga también explica la succión baja con descarga relativamente normal." },
  { id:"ns_0723", categoria:"NATE_SR_CEO", pregunta:"Como CEO, usted es auditado por el manejo de cilindros de recuperación. ¿Qué falta es grave?", opciones:["Cilindros con fecha de prueba hidrostática vencida (más de 5 años).", "Usar cilindros de color gris con tapa amarilla para refrigerante R-410A.", "Transportar más de 3 cilindros en una camioneta de servicio estándar hoy.", "No tener el logotipo de la empresa impreso en la etiqueta del cilindro."], respuesta_correcta:0, explicacion:"Los cilindros de recuperación con prueba hidrostática vencida (más de 5 años) representan un riesgo de seguridad y una falta grave ante auditorías DOT y EPA." },
  { id:"ns_0724", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calefacción, una bomba de calor tiene un Delta T de 10°F. Las resistencias están apagadas. ¿Causa?", opciones:["Falta de refrigerante líquido o flujo de aire interior excesivamente alto.", "Operación normal; el Delta T subirá cuando la temperatura exterior baje.", "Válvula inversora que no cambió de posición y sigue en modo refrigeración.", "Condensador exterior sucio que impide la absorción de calor ambiental hoy."], respuesta_correcta:0, explicacion:"Un Delta T de 10F sin resistencias es muy bajo. Indica que el compresor no genera suficiente calor. Las causas principales son falta de refrigerante o flujo de aire interior excesivamente alto que diluye el calor." },
  { id:"ns_0725", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema inverter reporta error de 'Compressor Position Detection'. ¿Qué pieza falló?", opciones:["La placa electrónica de potencia (IPM) o los imanes del rotor del compresor.", "El sensor de presión de succión que no detecta el arranque del motor hoy.", "El capacitor de marcha que está desvalorizado y no provee el par inicial.", "La comunicación entre el termostato de pared y la unidad interior del AC."], respuesta_correcta:0, explicacion:"El error de detección de posición del compresor indica que la placa IPM no puede determinar la posición del rotor. La falla está en la placa de potencia (IPM) o en los imanes del rotor del compresor." },
  { id:"ns_0726", categoria:"NATE_SR_RACK", pregunta:"Un rack de baja temperatura usa R-404A. La succión es de 0 PSI. Las vitrinas están calientes. ¿Causa?", opciones:["Fuga total de refrigerante o una restricción masiva en la línea de succión.", "Funcionamiento normal; la presión bajó al alcanzarse la temperatura de set.", "El separador de aceite se quedó pegado en la posición de abierto total hoy.", "Los ventiladores del condensador remoto están girando a máxima velocidad."], respuesta_correcta:0, explicacion:"Una presión de succión de 0 PSI con vitrinas calientes indica que no hay refrigerante circulando. Las dos causas principales son una fuga total que vació el sistema, o una restricción severa en la línea de succión que impide el flujo de gas." },
  { id:"ns_0727", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Upselling' en mantenimiento. ¿Qué incentivo es más ético?", opciones:["Bonos por identificar y reportar componentes con desgaste crítico comprobado.", "Comisiones directas por cada sistema nuevo vendido independientemente del estado.", "Sanciones para los técnicos que no vendan al menos un accesorio por visita.", "Premios por rapidez en terminar la llamada de servicio de mantenimiento hoy."], respuesta_correcta:0, explicacion:"Bonificar por identificar componentes con desgaste crítico comprobado es ético porque el técnico reporta hallazgos reales que benefician al cliente y no inventa necesidades." },
  { id:"ns_0728", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Low Flow' intermitente. El tanque de expansión está lleno. ¿Qué revisa?", opciones:["Presencia de aire en el lazo de agua o sensor de flujo (paddle) dañado.", "La carga de refrigerante líquido basándose en el visor del evaporador hoy.", "Si la válvula de expansión está inyectando líquido al cárter del motor hoy.", "El estado de los filtros de aire de la manejadora de aire del edificio hoy."], respuesta_correcta:0, explicacion:"Con tanque de expansión lleno, un bajo flujo intermitente indica aire atrapado en el lazo de agua que causa bolsas de aire, o un sensor de flujo (paddle) dañado que genera lecturas inconsistentes." },
  { id:"ns_0729", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un sistema donde el cliente puenteó el switch de alta presión. ¿Acción?", opciones:["Retirar el puente, reparar la causa del disparo y advertir sobre el peligro.", "Dejar el puente si el sistema está enfriando bien y el cliente está feliz.", "Ajustar el switch de alta a un valor superior para que no dispare tanto hoy.", "Cobrar el diagnóstico y no tocar el sistema por riesgo de responsabilidad."], respuesta_correcta:0, explicacion:"El switch de alta presión es un dispositivo de seguridad que protege contra sobrepresión peligrosa. Puentearlo elimina esa protección y puede causar explosión del serpentín o daño catastrófico. Se debe retirar el puente y resolver la causa raíz del disparo." },
  { id:"ns_0730", categoria:"NATE_SR_CEO", pregunta:"Un CEO decide usar 'Sub-contractors' para instalaciones. ¿Cuál es el mayor riesgo?", opciones:["Inconsistencia en la calidad del trabajo y falta de control sobre la garantía.", "Aumento en los costos fijos mensuales al tener que pagar facturas externas.", "Dificultad para programar las visitas de mantenimiento preventivo anual hoy.", "Que el subcontratista use sus propias herramientas en lugar de las nuestras."], respuesta_correcta:0, explicacion:"Los subcontratistas crean inconsistencia en la calidad del trabajo y la empresa pierde control sobre las garantías, ya que el cliente responsabiliza al contratista principal." },
  { id:"ns_0731", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una aproximación de evaporador de 0°F. El Senior sospecha de:", opciones:["Sensores de temperatura descalibrados o refrigerante líquido en la succión.", "El chiller está operando en su punto máximo de eficiencia termodinámica hoy.", "Los tubos del evaporador han sido limpiados recientemente con ácido fuerte.", "El flujo de agua a través del evaporador es exactamente el doble del nominal."], respuesta_correcta:0, explicacion:"Un approach de evaporador de 0°F es termodinámicamente improbable y señala sensores descalibrados o refrigerante líquido en la succión que falsea las mediciones de temperatura y presión." },
  { id:"ns_0732", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta ruidos de 'Water Hammering' en las líneas de refrigerante. ¿Causa?", opciones:["Líquido refrigerante regresando al compresor o falta de soportes en tubería.", "Aire atrapado en el sistema que no fue evacuado durante el proceso de vacío.", "Una válvula de expansión que abre y cierra violentamente por falta de carga.", "El uso de tubería de succión con un diámetro mayor al especificado por diseño."], respuesta_correcta:0, explicacion:"El 'water hammering' se produce por el impacto hidráulico del refrigerante líquido contra las paredes de la tubería o los componentes del compresor. Líquido regresando al compresor o tubería sin soportes son las causas más frecuentes de este fenómeno destructivo." },
  { id:"ns_0733", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Gross Profit Margin'. ¿Cuál de estas acciones impacta más rápido?", opciones:["Mejorar la precisión de los presupuestos para reducir el desperdicio de materiales.", "Contratar a más personal administrativo para gestionar mejor las facturas de cobro.", "Comprar uniformes más económicos para reducir el gasto general de la empresa.", "Aumentar el límite de crédito de los clientes para fomentar compras más grandes."], respuesta_correcta:0, explicacion:"Presupuestos más precisos reducen el desperdicio de materiales y el tiempo no productivo, lo que mejora el Gross Profit Margin de forma rápida y directamente medible." },
  { id:"ns_0734", categoria:"NATE_SR_MINISPLIT", pregunta:"Un sistema VRF tiene un ruido de expansión fuerte en las unidades interiores. ¿Causa?", opciones:["Falta de carga de refrigerante que causa vapor en la línea de líquido hoy.", "La placa de control está moviendo la EEV demasiado rápido entre pasos hoy.", "El aceite del sistema es demasiado espeso y causa fricción en la válvula.", "Es un comportamiento normal cuando el sistema opera a máxima frecuencia hoy."], respuesta_correcta:0, explicacion:"El ruido de expansión en unidades interiores VRF indica falta de refrigerante que genera vapor (flash gas) en la línea de líquido, creando turbulencia audible al pasar por la válvula de expansión." },
  { id:"ns_0735", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor geotérmica tiene una falla de 'High Pressure'. El lazo es abierto. ¿Causa?", opciones:["Incrustaciones de minerales en el intercambiador de calor de agua/gas hoy.", "La bomba del pozo se detuvo o el filtro de sedimentos está obstruido hoy.", "La temperatura del subsuelo ha subido por encima de los 80 grados F hoy.", "Hay una fuga de refrigerante hacia el agua del pozo por una ruptura hoy."], respuesta_correcta:0, explicacion:"En geotermicas de lazo abierto, los minerales del agua del pozo forman incrustaciones en el intercambiador de calor. Esto reduce la transferencia termica y eleva la presion de descarga hasta activar el switch de alta." },
  { id:"ns_0736", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si la válvula diferencial de aceite está mal ajustada (muy alta)?", opciones:["Se inyecta demasiado aceite al cárter y puede causar daños mecánicos hoy.", "No habrá suficiente presión para que el aceite regrese a los compresores.", "El separador de aceite se desbordará hacia la línea de descarga del rack.", "La temperatura del aceite bajará por debajo del punto de lubricación hoy."], respuesta_correcta:0, explicacion:"Un diferencial de aceite ajustado muy alto fuerza demasiado aceite hacia los cárteres de los compresores. El exceso de aceite líquido puede ser comprimido accidentalmente, causando daño mecánico en válvulas, bielas y pistones." },
  { id:"ns_0737", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior detecta un error de diseño en un plano de conductos. ¿Qué hace?", opciones:["Notificar al ingeniero de diseño y sugerir una corrección basada en campo.", "Instalar el sistema como dice el plano para no tener responsabilidad legal.", "Corregir el diseño por su cuenta sin avisar a nadie para terminar rápido.", "Decirle al cliente que el ingeniero no sabe nada y que él lo hará mejor."], respuesta_correcta:0, explicacion:"Un técnico Senior experimentado puede identificar errores de diseño gracias a su experiencia de campo. La acción correcta es notificar al ingeniero con una propuesta de corrección, manteniendo la colaboración profesional y la documentación adecuada." },
  { id:"ns_0738", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que expulsa refrigerante líquido. ¿Qué componente falló?", opciones:["La válvula de flotador o el orificio de separación de la unidad de purga.", "El compresor centrífugo que está enviando líquido hacia el condensador.", "El sensor de presión de la purga que está enviando una señal errónea.", "El calentador de la purga que no está evaporando el líquido recolectado."], respuesta_correcta:0, explicacion:"La válvula de flotador de la purga separa el líquido del gas. Si falla o el orificio de separación se obstruye, refrigerante líquido pasa a la cámara de expulsión en vez de solo gases." },
  { id:"ns_0739", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 115 PSI y descarga de 320 PSI con R-410A. ¿Cómo está?", opciones:["Funcionamiento normal para un día con temperatura exterior moderada hoy.", "Falta de refrigerante líquido que impide que la descarga suba más hoy.", "Evaporador sucio que reduce la presión de succión por debajo de 120 hoy.", "Compresor con desgaste moderado que aún mantiene el diferencial útil hoy."], respuesta_correcta:0, explicacion:"Succión de 115 PSI (~36°F sat.) y descarga de 320 PSI (~90°F sat.) con R-410A son presiones normales para un día con temperatura exterior moderada de 75-80°F. El sistema opera dentro de parámetros aceptables de diseño." },
  { id:"ns_0740", categoria:"NATE_SR_PACKAGE", pregunta:"En una unidad paquete, el serpentín del evaporador se congela. El filtro está limpio. ¿Qué sigue?", opciones:["Verificar la velocidad del motor del soplador y la carga de refrigerante.", "Reemplazar la válvula de expansión térmica (TXV) por una nueva hoy.", "Instalar un termostato de descongelación para que pare el compresor.", "Agregar refrigerante hasta que la presión de succión suba a 130 PSI hoy."], respuesta_correcta:0, explicacion:"Descartado el filtro sucio, las siguientes causas de congelación son el soplador operando a velocidad reducida (correa floja, motor débil) que reduce el flujo de aire, o carga baja de refrigerante que baja la temperatura de evaporación por debajo del punto de congelación del agua." },
  { id:"ns_0741", categoria:"NATE_SR_CEO", pregunta:"Un CEO debe cumplir con la ley FLSA (Fair Labor Standards Act). ¿Qué regula?", opciones:["El pago de horas extras y el salario mínimo para los empleados técnicos.", "La seguridad de los técnicos en el sitio de trabajo y el uso de EPP.", "La certificación de los equipos HVAC según su eficiencia energética.", "El manejo y disposición final de los refrigerantes usados en el campo."], respuesta_correcta:0, explicacion:"La FLSA regula el salario mínimo federal y el pago obligatorio de horas extras (1.5x después de 40 horas semanales) para empleados no exentos, incluyendo técnicos HVAC." },
  { id:"ns_0742", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-407A. El técnico mezcla con R-404A por error. ¿Consecuencia?", opciones:["La relación presión/temperatura será impredecible y el sistema fallará.", "El sistema funcionará bien ya que ambos refrigerantes son del tipo HFC.", "La eficiencia aumentará un 5% pero el compresor hará un poco más de ruido.", "El aceite se separará del refrigerante y los compresores se bloquearán."], respuesta_correcta:0, explicacion:"Mezclar R-407A con R-404A crea una combinación con propiedades termodinámicas impredecibles. Las tablas de presión/temperatura no aplican, los controles del sistema no pueden funcionar correctamente, y el rendimiento será errático y eventualmente dañino." },
  { id:"ns_0743", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta una purga de aire constante. Opera con R-134a. ¿Qué indica?", opciones:["La purga está defectuosa; el R-134a opera a presión positiva y no aspira aire.", "El chiller tiene una fuga masiva en el evaporador que permite la entrada aire.", "El sistema de sellado del eje del compresor ha fallado mecánicamente hoy.", "La temperatura del agua de la torre es demasiado baja para el condensador hoy."], respuesta_correcta:0, explicacion:"Con R-134a (presión positiva), el aire no se infiltra al sistema durante operación normal. Una purga constante de aire indica un defecto en el sistema de purga que genera falsas lecturas." },
  { id:"ns_0744", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no arranca. No hay códigos de error. ¿Qué revisa el Senior?", opciones:["El fusible de la unidad interior y si el voltaje de llegada es de 240VAC.", "La carga de refrigerante por peso para descartar una fuga total de gas gas.", "Si el compresor está aterrizado midiendo la resistencia contra la carcasa.", "La placa electrónica de la unidad exterior por rastros de quemaduras hoy hoy."], respuesta_correcta:0, explicacion:"Sin códigos de error visibles, el problema es de alimentación básica. El Senior revisa el fusible de la unidad interior y confirma 240VAC de llegada como primer paso de diagnóstico." },
  { id:"ns_0745", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. Subenfriamiento 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged) hoy hoy.", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio térmico.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F con presiones de 110/350 PSI indica falta severa de refrigerante. El condensador no tiene suficiente líquido para producir subenfriamiento, lo cual es el síntoma más confiable de un sistema undercharged." },
  { id:"ns_0746", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos hoy."], respuesta_correcta:0, explicacion:"El mercado Smart Homes necesita técnicos con habilidades en redes y protocolos de comunicación para integrar dispositivos IoT con sistemas HVAC de forma eficiente." },
  { id:"ns_0747", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué indica una temperatura de succión muy alta en el cabezal?", opciones:["Sobrecalentamiento excesivo que dañará la lubricación de compresores pronto.", "Que el sistema está operando a su máxima eficiencia de evaporación hoy hoy.", "Falta de refrigerante líquido en el recibidor principal del rack paralelo hoy.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura hoy."], respuesta_correcta:0, explicacion:"Temperatura de succión elevada en el cabezal confirma un sobrecalentamiento excesivo. El gas demasiado caliente no enfría adecuadamente el motor del compresor y degrada el aceite lubricante, reduciendo la vida útil del equipo." },
  { id:"ns_0748", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. ¿Qué revisa?", opciones:["Presencia de aire en la tubería, paddle roto o transductor descalibrado hoy.", "La carga de refrigerante que podría estar congelando el agua en tubos hoy.", "El sentido de rotación del motor del compresor centrífugo del sistema hoy hoy.", "La apertura de las válvulas de expansión del circuito de refrigeración hoy hoy."], respuesta_correcta:0, explicacion:"Flow Switch Alarm con bomba operando apunta a un paddle dañado, aire en la tubería que interfiere con la medición, o un transductor descalibrado que genera la alarma incorrectamente." },
  { id:"ns_0749", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior hoy.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy hoy."], respuesta_correcta:0, explicacion:"El goteo solo al parar el compresor indica contrapendiente o bloqueo parcial en el drenaje que retiene agua durante la operación y la libera cuando la unidad se detiene." },
  { id:"ns_0750", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de 0.9 en suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy hoy hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire hoy.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy hoy."], respuesta_correcta:0, explicacion:"Presión estática de 0.9\" en suministro versus 0.2\" en retorno muestra restricción concentrada en el lado de suministro. Los conductos de suministro restringidos o difusores cerrados son la causa de esta distribución desbalanceada." },
  { id:"ns_0751", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre 20°F y 30°F hoy hoy.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos hoy.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo hoy."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en modo calor es bajo. Lo normal es 20-30F. Significa que el sistema no transfiere suficiente calor al aire, por problemas de carga de refrigerante, flujo de aire o absorcion de calor exterior." },
  { id:"ns_0752", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar prueba de acidez del aceite y usar filtros succión de limpieza hoy hoy.", "Añadir aditivo sellador de fugas para prevenir fallas futuras en líneas hoy hoy.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado hoy.", "Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy hoy."], respuesta_correcta:0, explicacion:"El burnout del compresor libera ácidos y carbón al circuito frigorífico. Verificar la acidez del aceite indica el grado de contaminación, y los filtros de succión de limpieza son esenciales para capturar partículas y proteger el compresor de reemplazo." },
  { id:"ns_0753", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. ¿Estado?", opciones:["Funcionamiento correcto; la purga está separando los no condensables hoy hoy hoy.", "Falla en el serpentín de condensación interno de la unidad de purga hoy hoy.", "El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy.", "La temperatura del evaporador es demasiado alta para que la purga trabaje hoy."], respuesta_correcta:0, explicacion:"La purga que expulsa aire con poco refrigerante está operando correctamente, separando eficientemente los gases no condensables mientras minimiza la pérdida de refrigerante." },
  { id:"ns_0754", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si el 'Oil Separator' queda pegado en posición abierta?", opciones:["Gas caliente de descarga pasará directo al depósito aceite y succión hoy hoy.", "El rack se quedará sin aceite en pocos minutos al no poder separarlo gas hoy.", "Los compresores se apagarán por alta presión al bloquearse el flujo gas hoy.", "El nivel de aceite en los cárteres subirá tanto que dañará los pistones hoy."], respuesta_correcta:0, explicacion:"El flotador abierto del separador crea un camino libre para el gas de descarga hacia el depósito y la succión. Este bypass interno hace que parte del gas recircule sin pasar por el condensador ni los evaporadores, perdiendo capacidad." },
  { id:"ns_0755", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. ¿Qué KPI usa?", opciones:["Número de llamadas de nuevos clientes que mencionan haber visto la unidad hoy hoy.", "La cantidad de millas recorridas por cada vehículo en zonas residenciales hoy.", "El costo total del diseño e instalación del rótulo dividido entre 12 meses hoy.", "El aumento en la velocidad promedio de técnicos al conducir camionetas nuevas."], respuesta_correcta:0, explicacion:"Rastrear las llamadas de nuevos clientes que vieron la camioneta rotulada es el KPI más directo para medir el retorno de la inversión en publicidad vehicular." },
  { id:"ns_0756", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. ¿Qué revisa?", opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy hoy.", "La carga de refrigerante líquido basándose en el visor del evaporador hoy hoy.", "Si la válvula de expansión está inyectando demasiado líquido al sistema hoy.", "El estado de los filtros de aire de la manejadora de aire del edificio hoy."], respuesta_correcta:0, explicacion:"Alta presión de condensación en un sistema con condensador de agua se diagnostica verificando la temperatura del agua de torre y confirmando que la bomba de condensador funciona correctamente." },
  { id:"ns_0757", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión de 125 PSI y descarga 400 PSI con R-410A. ¿Estado aire?", opciones:["Funcionamiento normal bajo condiciones de carga térmica estándar hoy hoy hoy hoy.", "Falta de refrigerante que impide que temperatura del aire baje a 55 grados hoy.", "Exceso de carga que está elevando la presión de descarga innecesariamente hoy.", "Compresor con eficiencia reducida que no logra enfriar el aire correctamente."], respuesta_correcta:0, explicacion:"Las presiones de 125/400 PSI con R-410A están dentro del rango normal de operación bajo condiciones de carga térmica estándar. El sistema opera correctamente con un diferencial de presión adecuado." },
  { id:"ns_0758", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. ¿Qué estrategia?", opciones:["Programa de membresías mantenimiento para convertir clientes en recurrentes hoy hoy.", "Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy hoy.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos hoy.", "Despedir a técnicos que no logren vender un sistema nuevo en cada visita hoy."], respuesta_correcta:0, explicacion:"Las membresías de mantenimiento son la herramienta más efectiva para convertir clientes de una sola transacción en clientes recurrentes con valor a largo plazo." },
  { id:"ns_0759", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una restricción en la válvula de expansión hoy hoy.", "Si el ventilador interior está sucio y no sopla suficiente aire frío hoy hoy.", "El voltaje de la línea eléctrica que podría estar por debajo de 200V hoy hoy.", "Si el control remoto está configurado en una temperatura demasiado baja hoy."], respuesta_correcta:0, explicacion:"La protección de temperatura de descarga del compresor se activa por carga baja de refrigerante o restricción en la EEV, condiciones que causan sobrecalentamiento excesivo del gas de descarga." },
  { id:"ns_0760", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba calor, ¿qué sucede si 'Check Valve' condensador falla abierta?", opciones:["En modo calor el refrigerante hará bypass a TXV impidiendo calentamiento hoy hoy.", "El sistema funcionará mejor al haber menos restricción al flujo líquido hoy.", "La presión de descarga subirá hasta que switch de alta apague el equipo hoy.", "El compresor se quemará por el retorno de líquido masivo en el arranque hoy."], respuesta_correcta:0, explicacion:"Si la check valve del condensador falla abierta, en modo calor el refrigerante pasa sin restriccion en vez de la TXV. Sin la restriccion de expansion, el refrigerante no cambia de estado y el calentamiento se pierde." },
  { id:"ns_0761", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o inyección de líquido?", opciones:["Para enfriar gas de succión y evitar que descarga dañe el aceite hoy hoy hoy hoy.", "Para aumentar la presión de succión cuando carga en vitrinas es baja hoy hoy.", "Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos hoy hoy."], respuesta_correcta:0, explicacion:"La válvula Quench es fundamental en racks con altas relaciones de compresión. Al inyectar líquido, absorbe calor del gas de descarga por evaporación, manteniendo la temperatura en rangos seguros para la integridad del aceite y el compresor." },
  { id:"ns_0762", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. ¿Criterio?", opciones:["El volumen de agua y la accesibilidad para eliminación segura del fluido hoy hoy.", "Cuál de las dos herramientas es más nueva y hace menos ruido al operar hoy.", "La preferencia del cliente sobre qué herramienta quiere ver en su casa hoy.", "Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy."], respuesta_correcta:0, explicacion:"El profesional evalúa el volumen de agua y las condiciones de acceso para elegir la herramienta correcta. Una bomba puede manejar grandes volúmenes; una aspiradora es más práctica en espacios reducidos. La seguridad en la eliminación del fluido es primordial." },
  { id:"ns_0763", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar prueba presión a tubos del evaporador para buscar rupturas hoy hoy hoy.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.", "Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy."], respuesta_correcta:0, explicacion:"La detección de agua por la purga es crítica y requiere prueba de presión urgente en los tubos del evaporador para encontrar la ruptura antes de que el agua dañe el compresor y el aceite." },
  { id:"ns_0764", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión 130 PSI y descarga 380 PSI. Subenfriamiento 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango hoy hoy.", "Falta de refrigerante líquido; el subenfriamiento debería ser 15 grados hoy.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno hoy.", "Compresor fallando; la diferencia presión entre succión y descarga es baja hoy."], respuesta_correcta:0, explicacion:"Presiones de 130/380 PSI con subenfriamiento de 12°F son indicadores de operación óptima con R-410A. El subenfriamiento en el rango de 10-15°F confirma una carga de refrigerante correcta." },
  { id:"ns_0765", categoria:"NATE_SR_PACKAGE", pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. ¿Qué revisa?", opciones:["El voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo hoy hoy hoy.", "Si los contactos principales están quemados o soldados entre sí hoy hoy hoy.", "El capacitor de arranque del compresor que podría estar descargado hoy hoy.", "La continuidad de los fusibles de potencia de la línea de 240 voltios hoy hoy."], respuesta_correcta:0, explicacion:"El zumbido del contactor indica energización parcial de la bobina. La fuerza magnética es proporcional al voltaje; si este es bajo, la armadura vibra sin cerrar. La suciedad en el núcleo también impide el sellado magnético completo, perpetuando el zumbido y eventual quema de la bobina." },
  { id:"ns_0766", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico cobra 'por fuera' a clientes. ¿Qué acción toma?", opciones:["Despido inmediato y posible acción legal según el contrato de trabajo hoy hoy hoy.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras hoy hoy.", "Ignorar la situación si el técnico es el que más dinero genera hoy hoy hoy.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."], respuesta_correcta:0, explicacion:"El cobro por fuera a clientes es una falta grave que amerita despido inmediato y posible acción legal para proteger los ingresos y la reputación de la empresa." },
  { id:"ns_0767", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en el recibidor?", opciones:["Para evitar fraccionamiento de la mezcla y asegurar composición correcta hoy hoy.", "Para que el refrigerante se mezcle más rápido con el aceite POE del rack hoy.", "Para prevenir que las válvulas de descarga de compresores se calienten hoy hoy.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy."], respuesta_correcta:0, explicacion:"El R-448A es zeotrópico y sus componentes tienen diferentes presiones de vapor. Si se carga en gas, los componentes más ligeros salen primero del cilindro, alterando la composición final del sistema. La carga en líquido previene esta separación." },
  { id:"ns_0768", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. ¿Efecto?", opciones:["El controlador no podrá calcular la carga térmica real del edificio hoy hoy hoy.", "El compresor se apagará inmediatamente por seguridad de flujo de agua hoy hoy.", "La unidad operará siempre al 100% de su capacidad nominal sin modular hoy hoy.", "No hay efecto si el sensor de 'Leaving Water' está operando correctamente hoy hoy."], respuesta_correcta:0, explicacion:"Sin sensor de entering water, el controlador pierde la capacidad de medir la carga térmica real, impidiendo una modulación precisa de la capacidad de enfriamiento." },
  { id:"ns_0769", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga de 550 PSI con R-410A. ¿Causa?", opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy.", "Falta de refrigerante líquido que impide que el sistema enfríe el aire hoy hoy.", "Válvula de expansión electrónica bloqueada en la posición de abierta total hoy.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy."], respuesta_correcta:0, explicacion:"Descarga de 550 PSI con R-410A representa una condición crítica. Sin rechazo de calor adecuado por un condensador sucio o ventilador fallando, la presión alcanza niveles peligrosamente altos que pueden dañar el compresor o activar protecciones de seguridad." },
  { id:"ns_0770", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Average Response Time'. ¿Qué medida toma hoy?", opciones:["Implementar software de despacho inteligente y zonificación de técnicos hoy hoy hoy.", "Aumentar el número de técnicos en la nómina aunque no haya llamadas suficientes hoy.", "Reducir el tiempo de almuerzo de los técnicos para que estén más disponibles hoy.", "Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy."], respuesta_correcta:0, explicacion:"El despacho inteligente con zonificación de técnicos asigna el recurso más cercano a cada llamada, reduciendo el tiempo de respuesta de forma sistemática y medible." },
  { id:"ns_0771", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería fluctuar entre 0 y 24VDC hoy hoy hoy.", "La placa exterior está operando correctamente enviando la señal de control hoy.", "El compresor inverter está aterrizado y consume el voltaje de comunicación hoy.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior hoy hoy."], respuesta_correcta:0, explicacion:"La comunicación entre unidades inverter usa voltaje DC pulsante (0-24V) en los terminales S2/S3. Un voltaje fijo de 24VDC indica que no hay modulación de datos: falla de comunicación." },
  { id:"ns_0772", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Defrost Sensor' falla en circuito abierto?", opciones:["El sistema nunca entrará en modo de deshielo y el serpentín se congelará hoy hoy.", "El sistema entrará en modo de deshielo cada 30 minutos sin importar el hielo hoy.", "El compresor se quemará debido a la falta de control de sobrecalentamiento hoy.", "La unidad operará solo en modo refrigeración permanentemente por seguridad hoy."], respuesta_correcta:0, explicacion:"El sensor de defrost en circuito abierto impide que la placa detecte la temperatura baja del serpentin exterior. Sin esta senal, la condicion de inicio de deshielo nunca se cumple y el hielo se acumula hasta bloquear el serpentin." },
  { id:"ns_0773", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un sistema VRF. ¿Por qué es vital pesar la carga?", opciones:["Los sistemas VRF son de carga crítica y las presiones no son indicadores hoy hoy.", "Es un requisito legal de la EPA para sistemas con más de 50 libras de gas hoy.", "Para asegurar que el aceite POE regrese correctamente a los compresores hoy hoy.", "Para evitar que la garantía del fabricante se anule tras la instalación hoy hoy."], respuesta_correcta:0, explicacion:"Los VRF modulan capacidad continuamente, haciendo que las presiones cambien según la demanda. El pesaje de refrigerante según la fórmula del fabricante (carga base + longitud de tuberías adicionales) es la única forma precisa de cargar estos sistemas." },
  { id:"ns_0774", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Reversal'. ¿Qué sucede si se ignora el error?", opciones:["El compresor girará al revés y no bombeará aceite ni refrigerante líquido hoy hoy.", "La unidad funcionará al 50% de su capacidad nominal debido al desfase fase hoy.", "El motor se quemará instantáneamente al intentar vencer la inercia carga hoy hoy.", "Las válvulas de expansión se cerrarán por seguridad al detectar el error hoy hoy."], respuesta_correcta:0, explicacion:"La inversión de fases causa que el compresor gire al revés, perdiendo el bombeo de aceite y refrigerante. Sin lubricación, los cojinetes y el impulsor sufren daños mecánicos severos." },
  { id:"ns_0775", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. Subenfriamiento 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged) hoy hoy hoy.", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy hoy hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio térmico.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F es la señal más definitiva de falta severa de refrigerante. Sin suficiente masa de refrigerante, el condensador no puede producir líquido subenfriado y solo entrega mezcla bifásica al dispositivo de expansión." },
  { id:"ns_0776", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy hoy hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy hoy hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos hoy hoy."], respuesta_correcta:0, explicacion:"Smart Homes requiere técnicos entrenados en redes, protocolos de comunicación e integración de sistemas inteligentes, competencias que exceden la formación HVAC tradicional." },
  { id:"ns_0777", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué indica una temperatura de succión muy alta en el cabezal?", opciones:["Sobrecalentamiento excesivo que dañará la lubricación de compresores pronto.", "Que el sistema está operando a su máxima eficiencia de evaporación hoy hoy hoy.", "Falta de refrigerante líquido en el recibidor principal del rack paralelo hoy hoy.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura hoy hoy."], respuesta_correcta:0, explicacion:"La temperatura alta en el cabezal de succión significa gas excesivamente sobrecalentado. Esto compromete la lubricación al reducir la viscosidad del aceite por calor, y puede causar daño térmico en los devanados del motor del compresor." },
  { id:"ns_0778", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. ¿Qué revisa?", opciones:["Presencia de aire en la tubería, paddle roto o transductor descalibrado hoy hoy hoy.", "La carga de refrigerante que podría estar congelando el agua en tubos hoy hoy.", "El sentido de rotación del motor del compresor centrífugo del sistema hoy hoy hoy.", "La apertura de las válvulas de expansión del circuito de refrigeración hoy hoy hoy."], respuesta_correcta:0, explicacion:"Una alarma de flow switch con bomba encendida indica problemas en la detección de flujo: paddle roto, aire atrapado, o transductor diferencial fuera de calibración." },
  { id:"ns_0779", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior hoy hoy hoy.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy hoy.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido hoy.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy hoy hoy."], respuesta_correcta:0, explicacion:"El goteo al detenerse el compresor se debe a una contrapendiente o bloqueo parcial en la parte alta del drenaje que retiene el condensado y lo libera cuando cesa la operación." },
  { id:"ns_0780", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de 0.9 en suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy hoy hoy hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire hoy hoy.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy hoy hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy hoy hoy."], respuesta_correcta:0, explicacion:"La asimetría de presión estática (0.9\" suministro vs 0.2\" retorno) indica que la restricción del sistema está mayoritariamente en el lado de suministro, causada por conductos restringidos, aplastados o difusores parcial o totalmente cerrados." },
  { id:"ns_0781", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre 20°F y 30°F hoy hoy hoy.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos hoy hoy.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube hoy.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo hoy hoy."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en calefaccion esta por debajo del rango aceptable de 20-30F. Senala capacidad deficiente, tipicamente causada por baja carga de refrigerante, alto flujo de aire, o mala absorcion de calor exterior." },
  { id:"ns_0782", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar prueba de acidez del aceite y usar filtros succión de limpieza hoy hoy.", "Añadir aditivo sellador de fugas para prevenir fallas futuras en líneas hoy hoy.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado hoy hoy.", "Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy hoy."], respuesta_correcta:0, explicacion:"Después de un burnout, el sistema completo está contaminado con ácidos y residuos de descomposición. La prueba de acidez mide la contaminación y los filtros de succión atrapan partículas sólidas, ambos esenciales para proteger la inversión en el compresor nuevo." },
  { id:"ns_0783", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. ¿Estado?", opciones:["Funcionamiento correcto; la purga está separando los no condensables hoy hoy hoy hoy.", "Falla en el serpentín de condensación interno de la unidad de purga hoy hoy hoy.", "El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy hoy.", "La temperatura del evaporador es demasiado alta para que la purga trabaje hoy hoy."], respuesta_correcta:0, explicacion:"Purga que expulsa aire con poco refrigerante está funcionando como fue diseñada, separando correctamente los no condensables del refrigerante antes de expulsarlos." },
  { id:"ns_0784", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si el 'Oil Separator' queda pegado en posición abierta?", opciones:["Gas caliente de descarga pasará directo al depósito aceite y succión hoy hoy hoy.", "El rack se quedará sin aceite en pocos minutos al no poder separarlo gas hoy hoy.", "Los compresores se apagarán por alta presión al bloquearse el flujo gas hoy hoy.", "El nivel de aceite en los cárteres subirá tanto que dañará los pistones hoy hoy."], respuesta_correcta:0, explicacion:"Cuando el separador queda abierto, gas de descarga a alta temperatura y presión fluye directamente al depósito de aceite, empujando aceite hacia la succión y creando un cortocircuito que compromete la refrigeración del sistema." },
  { id:"ns_0785", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. ¿Qué KPI usa?", opciones:["Número de llamadas de nuevos clientes que mencionan haber visto la unidad hoy hoy hoy.", "La cantidad de millas recorridas por cada vehículo en zonas residenciales hoy hoy.", "El costo total del diseño e instalación del rótulo dividido entre 12 meses hoy.", "El aumento en la velocidad promedio de técnicos al conducir camionetas nuevas hoy."], respuesta_correcta:0, explicacion:"Contabilizar las llamadas de nuevos clientes que mencionan la camioneta rotulada mide directamente la conversión de la publicidad vehicular en oportunidades de negocio." },
  { id:"ns_0786", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. ¿Qué revisa?", opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy hoy hoy.", "La carga de refrigerante líquido basándose en el visor del evaporador hoy hoy hoy.", "Si la válvula de expansión está inyectando demasiado líquido al sistema hoy hoy.", "El estado de los filtros de aire de la manejadora de aire del edificio hoy hoy."], respuesta_correcta:0, explicacion:"La alta presión de condensación con condensador de agua se investiga verificando temperatura del agua de torre y funcionamiento de la bomba como factores principales." },
  { id:"ns_0787", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión de 125 PSI y descarga 400 PSI con R-410A. ¿Estado aire?", opciones:["Funcionamiento normal bajo condiciones de carga térmica estándar hoy hoy hoy hoy hoy.", "Falta de refrigerante que impide que temperatura del aire baje a 55 grados hoy hoy.", "Exceso de carga que está elevando la presión de descarga innecesariamente hoy hoy.", "Compresor con eficiencia reducida que no logra enfriar el aire correctamente hoy."], respuesta_correcta:0, explicacion:"Succión de 125 PSI y descarga de 400 PSI con R-410A son valores normales que indican funcionamiento correcto del sistema bajo condiciones de carga térmica estándar." },
  { id:"ns_0788", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. ¿Qué estrategia?", opciones:["Programa de membresías mantenimiento para convertir clientes en recurrentes hoy hoy hoy.", "Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy hoy hoy.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos hoy hoy.", "Despedir a técnicos que no logren vender un sistema nuevo en cada visita hoy hoy."], respuesta_correcta:0, explicacion:"La estrategia más efectiva para reducir los clientes de una sola vez es crear un programa de membresías de mantenimiento que ofrezca valor continuo." },
  { id:"ns_0789", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una restricción en la válvula de expansión hoy hoy hoy.", "Si el ventilador interior está sucio y no sopla suficiente aire frío hoy hoy hoy.", "El voltaje de la línea eléctrica que podría estar por debajo de 200V hoy hoy hoy.", "Si el control remoto está configurado en una temperatura demasiado baja hoy hoy."], respuesta_correcta:0, explicacion:"La protección de temperatura de descarga se dispara por carga insuficiente de refrigerante o restricción en la válvula de expansión, ambas causas generan sobrecalentamiento del gas de descarga." },
  { id:"ns_0790", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba calor, ¿qué sucede si 'Check Valve' condensador falla abierta?", opciones:["En modo calor el refrigerante hará bypass a TXV impidiendo calentamiento hoy hoy hoy.", "El sistema funcionará mejor al haber menos restricción al flujo líquido hoy hoy.", "La presión de descarga subirá hasta que switch de alta apague el equipo hoy hoy.", "El compresor se quemará por el retorno de líquido masivo en el arranque hoy hoy."], respuesta_correcta:0, explicacion:"Con la check valve del condensador fallida abierta, el refrigerante en modo calor hace bypass a la TXV sin restriccion. La falta de caida de presion impide la transferencia de calor y el sistema no calienta." },
  { id:"ns_0791", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o inyección de líquido?", opciones:["Para enfriar gas de succión y evitar que descarga dañe el aceite hoy hoy hoy hoy hoy.", "Para aumentar la presión de succión cuando carga en vitrinas es baja hoy hoy hoy.", "Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy hoy.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos hoy hoy hoy."], respuesta_correcta:0, explicacion:"En sistemas de baja temperatura con alta relación de compresión, la temperatura de descarga puede exceder los 275°F. La válvula Quench inyecta líquido controladamente para reducir esta temperatura y proteger el aceite y el compresor." },
  { id:"ns_0792", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. ¿Criterio?", opciones:["El volumen de agua y la accesibilidad para eliminación segura del fluido hoy hoy hoy.", "Cuál de las dos herramientas es más nueva y hace menos ruido al operar hoy hoy.", "La preferencia del cliente sobre qué herramienta quiere ver en su casa hoy hoy.", "Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy hoy."], respuesta_correcta:0, explicacion:"La decisión profesional se fundamenta en criterios técnicos: la cantidad de agua presente y la accesibilidad del espacio donde se acumuló. Estos factores determinan cuál herramienta logra la eliminación más segura y eficiente del fluido." },
  { id:"ns_0793", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar prueba presión a tubos del evaporador para buscar rupturas hoy hoy hoy hoy.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy hoy.", "Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy hoy.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy hoy."], respuesta_correcta:0, explicacion:"Water Detected por la purga es una alarma urgente que demanda prueba de presión a los tubos del evaporador para localizar y reparar la ruptura que permite entrada de agua al refrigerante." },
  { id:"ns_0794", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión 130 PSI y descarga 380 PSI. Subenfriamiento 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango hoy hoy hoy.", "Falta de refrigerante líquido; el subenfriamiento debería ser 15 grados hoy hoy.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno hoy hoy.", "Compresor fallando; la diferencia presión entre succión y descarga es baja hoy hoy."], respuesta_correcta:0, explicacion:"Las presiones de 130/380 PSI con 12°F de subenfriamiento están en rango óptimo para R-410A. El subenfriamiento entre 10-15°F es ideal para confirmar carga correcta y operación eficiente del condensador." },
  { id:"ns_0795", categoria:"NATE_SR_PACKAGE", pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. ¿Qué revisa?", opciones:["El voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo hoy hoy hoy hoy.", "Si los contactos principales están quemados o soldados entre sí hoy hoy hoy hoy.", "El capacitor de arranque del compresor que podría estar descargado hoy hoy hoy.", "La continuidad de los fusibles de potencia de la línea de 240 voltios hoy hoy hoy."], respuesta_correcta:0, explicacion:"Un contactor que vibra y zumba repetidamente tiene un problema de fuerza de cierre. La medición del voltaje en la bobina confirma si hay caída de tensión, y la inspección visual del núcleo revela si hay contaminantes que impiden el contacto metal-con-metal necesario para el cierre." },
  { id:"ns_0796", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico cobra 'por fuera' a clientes. ¿Qué acción toma?", opciones:["Despido inmediato y posible acción legal según el contrato de trabajo hoy hoy hoy hoy.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras hoy hoy hoy.", "Ignorar la situación si el técnico es el que más dinero genera hoy hoy hoy hoy.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy hoy."], respuesta_correcta:0, explicacion:"El cobro por fuera es una violación contractual seria; el despido inmediato y la posible acción legal son las medidas proporcionales a la gravedad de la falta." },
  { id:"ns_0797", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en el recibidor?", opciones:["Para evitar fraccionamiento de la mezcla y asegurar composición correcta hoy hoy hoy hoy.", "Para que el refrigerante se mezcle más rápido con el aceite POE del rack hoy hoy.", "Para prevenir que las válvulas de descarga de compresores se calienten hoy hoy hoy.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy hoy hoy."], respuesta_correcta:0, explicacion:"La integridad de la composición del R-448A depende de que se cargue en estado líquido. Al cargar en gas, el cilindro libera primero los componentes más volátiles, dejando los más pesados atrás y alterando la mezcla en el sistema." },
  { id:"ns_0798", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. ¿Efecto?", opciones:["El controlador no podrá calcular la carga térmica real del edificio hoy hoy hoy hoy.", "El compresor se apagará inmediatamente por seguridad de flujo de agua hoy hoy hoy.", "La unidad operará siempre al 100% de su capacidad nominal sin modular hoy hoy hoy.", "No hay efecto si el sensor de 'Leaving Water' está operando correctamente hoy hoy hoy."], respuesta_correcta:0, explicacion:"Sin el sensor de entering water operativo, el controlador no puede calcular la carga térmica del edificio ni modular la capacidad del chiller de forma correcta." },
  { id:"ns_0799", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga de 550 PSI con R-410A. ¿Causa?", opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy hoy.", "Falta de refrigerante líquido que impide que el sistema enfríe el aire hoy hoy hoy.", "Válvula de expansión electrónica bloqueada en la posición de abierta total hoy hoy.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy hoy."], respuesta_correcta:0, explicacion:"Una descarga de 550 PSI es extremadamente alta para R-410A e indica falta de rechazo de calor. Un condensador muy sucio o ventilador exterior que no funciona son las causas más directas de esta acumulación peligrosa de presión." },
  { id:"ns_0800", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Average Response Time'. ¿Qué medida toma hoy?", opciones:["Implementar software de despacho inteligente y zonificación de técnicos hoy hoy hoy hoy.", "Aumentar el número de técnicos en la nómina aunque no haya llamadas suficientes hoy.", "Reducir el tiempo de almuerzo de los técnicos para que estén más disponibles hoy hoy.", "Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy hoy."], respuesta_correcta:0, explicacion:"Software de despacho inteligente con zonificación geográfica es la solución técnica más efectiva para reducir sistemáticamente el tiempo de respuesta promedio." },
  { id:"ns_0801", categoria:"NATE_SR_HVAC", pregunta:"En un sistema VAV, el sensor de presión estática del conducto principal marca 2.5 pulg. W.C. (Set-point 1.5). ¿Cuál es la consecuencia Senior inmediata?", opciones:["Ruido excesivo en los difusores y posible daño a los sellos de las cajas VAV.", "El soplador entrará en modo de ahorro de energía para compensar la presión.", "Las cajas VAV se abrirán al 100% para liberar el exceso de presión estática.", "El chiller se apagará por falta de carga térmica debido al bajo flujo de aire."], respuesta_correcta:0, explicacion:"Con presión estática de 2.5\" W.C. (67% sobre el set-point de 1.5\"), los difusores y cajas VAV experimentan velocidades de aire excesivas que generan ruido. La alta presión también puede dañar los sellos y actuadores de las cajas VAV por el esfuerzo mecánico." },
  { id:"ns_0802", categoria:"NATE_SR_RACK", pregunta:"Un rack paralelo presenta una 'alta presión de succión' generalizada. Todos los compresores están encendidos al 100%. ¿Qué sospecha el Senior?", opciones:["Carga térmica excesiva en la tienda o compresores con válvulas internas dañadas.", "Falta de refrigerante líquido en el recibidor que impide la evaporación correcta.", "Las válvulas EPR están restringiendo demasiado el flujo de gas hacia el rack.", "El condensador remoto está inundado de líquido debido al clima frío exterior."], respuesta_correcta:0, explicacion:"Con todos los compresores al 100% y presión de succión alta, hay más carga térmica de la que el rack puede manejar. Esto puede ser por condiciones extremas en la tienda, o compresores con válvulas internas dañadas que no bombean eficientemente." },
  { id:"ns_0803", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Non-Billable Travel Time'. ¿Qué estrategia de despacho es la más técnica?", opciones:["Zonificación geográfica de técnicos y uso de almacenes móviles (camionetas stock).", "Reducir la velocidad máxima permitida de los vehículos para ahorrar combustible.", "Obligar a los técnicos a terminar cada llamada en menos de 45 minutos reloj.", "Eliminar el cobro por diagnóstico para atraer más clientes en una misma zona."], respuesta_correcta:0, explicacion:"La zonificación geográfica y los almacenes móviles reducen el tiempo de viaje no facturable al mantener al técnico cerca de sus próximas llamadas con las piezas necesarias." },
  { id:"ns_0804", categoria:"NATE_SR_MINISPLIT", pregunta:"Un VRF presenta un error de 'EEV Coil Failure'. Al medir la bobina, el Senior encuentra 0 Ohms. ¿Qué indica esto?", opciones:["Un cortocircuito interno en la bobina de la válvula de expansión electrónica.", "Que la bobina está operando en su punto de máxima inducción magnética hoy.", "Una falta de comunicación entre la placa interior y el actuador de la válvula.", "Que el cable de señal está desconectado pero la bobina físicamente está bien."], respuesta_correcta:0, explicacion:"Una lectura de 0 Ohms en la bobina de la EEV indica un cortocircuito interno. Una bobina sana debe tener una resistencia medible (típicamente decenas a cientos de Ohms) según el modelo." },
  { id:"ns_0805", categoria:"NATE_SR_HVAC", pregunta:"Se encuentra un 'Phase Imbalance' del 2% en un edificio comercial. ¿Por qué el Senior no recomienda actuar de inmediato?", opciones:["Porque el límite aceptable por la mayoría de fabricantes es de hasta un 3%.", "Porque el costo de corregir el desequilibrio es mayor al ahorro de energía.", "Porque el desequilibrio de voltaje no afecta la vida útil de los motores Scroll.", "Porque el monitor de fases compensará automáticamente la diferencia de tensión."], respuesta_correcta:0, explicacion:"La mayoría de fabricantes de motores y compresores especifican un límite de desbalance de fase del 2-3%. Un 2% está dentro del rango aceptable, por lo que no justifica una inversión inmediata en corrección, ya que el impacto en la vida del equipo es mínimo." },
  { id:"ns_0806", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo calor tiene un 'Frost Pattern' desigual (franjas de hielo). ¿Diagnóstico?", opciones:["Falta parcial de refrigerante o restricción en un circuito del distribuidor.", "Operación normal cuando la humedad relativa exterior es superior al 80%.", "Falla del motor del ventilador exterior que no cubre todo el serpentín hoy.", "La válvula inversora no logró cambiar totalmente a la posición de calefacción."], respuesta_correcta:0, explicacion:"Un patron de escarcha desigual (franjas) indica que algunos circuitos del distribuidor estan parcialmente bloqueados o hay falta de refrigerante. Los circuitos con flujo se escarchan; los restantes quedan secos." },
  { id:"ns_0807", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior nota que su equipo está purgando las mangueras con refrigerante al conectar. ¿Qué norma de la EPA se está violando?", opciones:["La prohibición de venteo intencional de refrigerantes (De minimis exception no aplica).", "La obligación de usar cilindros de recuperación de color gris con tapa amarilla.", "El requisito de llevar un registro de peso exacto de cada onza de gas utilizada.", "La necesidad de tener un vacuómetro digital conectado durante cada carga de gas."], respuesta_correcta:0, explicacion:"La Sección 608 de la EPA prohíbe el venteo intencional de refrigerantes a la atmósfera. Purgar mangueras liberando refrigerante es una violación directa de esta norma, con multas de hasta $44,539 por día por incidente." },
  { id:"ns_0808", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller de tornillo, el sensor de 'Oil Level' dispara una alarma, pero la mirilla está llena. ¿Qué revisa el Senior?", opciones:["Presencia de espuma de refrigerante en el aceite que falsea el sensor óptico.", "La viscosidad del aceite que es demasiado alta para el flujo del sensor hoy.", "Si el calentador de cárter está quemado y el aceite se encuentra muy frío.", "La calibración del sensor de presión diferencial de la bomba de lubricación."], respuesta_correcta:0, explicacion:"La espuma de refrigerante en el aceite genera lecturas falsas en el sensor óptico de nivel. El refrigerante disuelto en el aceite se evapora y crea espuma que el sensor interpreta como bajo nivel." },
  { id:"ns_0809", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete de 50 toneladas tiene un Delta P de aceite bajo. El técnico agrega aceite pero el problema persiste. ¿Causa?", opciones:["Migración de refrigerante líquido al cárter que diluye el aceite constantemente.", "El separador de aceite tiene la malla interna rota y no atrapa el lubricante.", "La bomba de aceite mecánica tiene un desgaste en los engranajes internos hoy.", "El filtro de succión de aceite está obstruido por partículas de carbón ácido."], respuesta_correcta:0, explicacion:"Si agregar aceite no corrige el Delta P bajo, es porque algo sigue diluyendo el lubricante. La migración de refrigerante líquido al cárter durante los períodos de apagado disuelve el aceite continuamente, reduciendo su viscosidad y la capacidad de la bomba para mantener presión diferencial." },
  { id:"ns_0810", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC quiere aumentar el 'EBITDA'. ¿Cuál es la palanca operativa más potente?", opciones:["Mejorar el margen bruto mediante la eficiencia técnica y reducción de mermas.", "Aumentar el gasto en marketing para saturar el mercado residencial local hoy.", "Comprar una flota nueva de vehículos para reducir el gasto de mantenimiento.", "Reducir el salario de los técnicos Senior para bajar el costo de venta directo."], respuesta_correcta:0, explicacion:"Mejorar el margen bruto mediante eficiencia técnica y reducción de mermas impacta directamente el EBITDA porque aumenta la utilidad operativa sin necesidad de más ingresos." },
  { id:"ns_0811", categoria:"NATE_SR_HVAC", pregunta:"Si el aire pasa por un serpentín de enfriamiento y la temperatura de bulbo seco baja pero el punto de rocío se mantiene igual:", opciones:["El enfriamiento fue puramente sensible (no hubo deshumidificación).", "El serpentín está operando por debajo del punto de rocío del aire hoy.", "La humedad relativa del aire ha disminuido drásticamente tras el proceso.", "El sistema tiene una falta de carga de refrigerante que impide condensar."], respuesta_correcta:0, explicacion:"Si la temperatura de bulbo seco baja pero el punto de rocío se mantiene igual, significa que no se removió humedad del aire. El enfriamiento fue puramente sensible, lo que ocurre cuando la superficie del serpentín opera por encima del punto de rocío del aire." },
  { id:"ns_0812", categoria:"NATE_SR_RACK", pregunta:"Un sistema de rack utiliza 'Subcooling' por intercambiador de placas. ¿Qué beneficio Senior es el más importante?", opciones:["Aumento de la capacidad frigorífica y prevención de gas flash en líneas largas.", "Reducción de la presión de descarga de los compresores de la etapa de alta.", "Eliminación de la necesidad de usar acumuladores de succión en el rack hoy.", "Mejora en el retorno de aceite desde las vitrinas de congelados más lejanas."], respuesta_correcta:0, explicacion:"El subenfriamiento adicional mediante intercambiador de placas enfría el líquido muy por debajo de su punto de saturación. Esto previene la formación de gas flash en líneas largas y aumenta la capacidad frigorífica al entregar más líquido útil a los evaporadores." },
  { id:"ns_0813", categoria:"NATE_SR_CEO", pregunta:"Como CEO, usted nota que sus mejores técnicos se van a la competencia. ¿Qué factor debe auditar primero?", opciones:["La cultura organizacional, el balance vida-trabajo y la compensación total.", "El estado de las herramientas y la modernidad de las camionetas de la flota.", "La cantidad de llamadas de servicio que cada técnico debe atender al día.", "El diseño de los uniformes y la calidad de los beneficios de salud ofrecidos."], respuesta_correcta:0, explicacion:"La cultura organizacional, el balance vida-trabajo y la compensación total son los factores principales que determinan si los mejores técnicos se quedan o se van a la competencia." },
  { id:"ns_0814", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter muestra el error 'P0' (IPM Error). Al revisar, el ventilador exterior está trabado. ¿Relación?", opciones:["La falta de flujo de aire sobrecalentó el módulo IPM por alta corriente.", "El IPM controla tanto al compresor como al ventilador en este modelo hoy.", "El error P0 es una falla de comunicación causada por el ruido del motor.", "No hay relación; el técnico debe buscar una falla en la placa electrónica."], respuesta_correcta:0, explicacion:"Sin flujo de aire del ventilador exterior, el condensador no disipa calor, la presión de descarga sube y el compresor demanda más corriente, sobrecalentando el módulo IPM y disparando el error P0." },
  { id:"ns_0815", categoria:"NATE_SR_CHILLERS", pregunta:"En un lazo de agua helada, se observa 'Corrosión Galvánica'. ¿Qué causó esto?", opciones:["Contacto directo entre metales disímiles (ej. cobre y acero) sin aislamiento.", "El uso de glicol etilénico en una concentración superior al 50% en el lazo.", "Una velocidad de flujo de agua excesiva que erosiona las paredes del tubo.", "La falta de purga de aire que permite que el oxígeno reaccione con el hierro."], respuesta_correcta:0, explicacion:"La corrosión galvánica ocurre cuando dos metales disímiles (como cobre y acero) están en contacto directo en presencia de un electrolito (agua), creando una celda electroquímica destructiva." },
  { id:"ns_0816", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un approach de condensador de 2°F, pero la descarga es de 450 PSI con R-410A. ¿Diagnóstico?", opciones:["Incondensables (aire) en el sistema o sobrecarga de refrigerante líquida.", "El condensador está perfectamente limpio y operando en rango de diseño hoy.", "Falta de refrigerante que impide que la transferencia de calor sea total.", "La torre de enfriamiento está entregando agua demasiado caliente al sistema."], respuesta_correcta:0, explicacion:"Con approach de 2°F (condensador limpio), una descarga de 450 PSI con R-410A está muy por encima de lo normal. Esto indica gases no condensables en el sistema o sobrecarga de refrigerante." },
  { id:"ns_0817", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa una soldadura que se ve 'fría' y opaca. ¿Qué instruye al Junior?", opciones:["Limpiar, aplicar más calor uniformemente y asegurar la capilaridad del aporte.", "Lijar la superficie y cubrirla con una capa de sellador epóxico para gas.", "Pintar la unión para evitar que el cliente note la mala calidad estética hoy.", "Dejarla así si la prueba de nitrógeno a 100 PSI no muestra burbujas hoy."], respuesta_correcta:0, explicacion:"Una soldadura fría y opaca indica que no se alcanzó la temperatura adecuada y el material de aporte no fluyó por capilaridad. Se debe limpiar la unión, recalentar uniformemente y permitir que la soldadura de plata fluya correctamente por acción capilar." },
  { id:"ns_0818", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere mejorar el 'Current Ratio' (Liquidez). ¿Qué acción es contraproducente?", opciones:["Comprar una gran cantidad de inventario pagando en efectivo de inmediato.", "Cobrar las cuentas pendientes de clientes comerciales a más de 90 días hoy.", "Vender activos fijos que no se utilizan y mantener el dinero en el banco.", "Renegociar deudas de corto plazo para convertirlas en créditos a largo plazo."], respuesta_correcta:0, explicacion:"Comprar inventario pagando en efectivo reduce los activos líquidos sin reducir los pasivos corrientes, empeorando el Current Ratio; es contraproducente para la liquidez." },
  { id:"ns_0819", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de succión de 105 PSI y descarga de 480 PSI. ¿Estado?", opciones:["Restricción en el lado de alta o condensador extremadamente sucio hoy hoy.", "Funcionamiento normal para un día con 105 grados F de temperatura exterior.", "Falta de refrigerante líquido que impide que la succión suba a 120 PSI.", "Válvula de expansión (TXV) bloqueada en la posición de abierta total hoy."], respuesta_correcta:0, explicacion:"Succión de 105 PSI (baja) con descarga de 480 PSI (muy alta) indica restricción en el lado de alta del sistema. Un condensador sucio o restricción en la línea de líquido impide el flujo normal, acumulando presión en el lado de descarga." },
  { id:"ns_0820", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿cuál es el propósito de la válvula 'Check' en la descarga de cada compresor?", opciones:["Evitar la migración de refrigerante líquido desde el condensador al compresor parado.", "Aumentar la presión de descarga para mejorar la separación de aceite hoy.", "Permitir que el aceite regrese al cárter solo cuando el compresor está encendido.", "Proteger al condensador de las pulsaciones de gas de los compresores Scroll."], respuesta_correcta:0, explicacion:"La válvula check de descarga impide el flujo reverso de refrigerante hacia un compresor que está apagado. Sin esta protección, el líquido del condensador migraría al compresor frío, causando golpe de líquido al siguiente arranque." },
  { id:"ns_0821", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Monitor'. El voltaje es estable a 460V. ¿Qué revisa?", opciones:["Secuencia de fases incorrecta tras una reparación eléctrica en el edificio.", "El fusible de control de 24V que alimenta la bobina del contactor hoy hoy.", "Si los ventiladores del condensador están girando en sentido inverso hoy.", "La carga de refrigerante que podría estar afectando la lógica de arranque."], respuesta_correcta:0, explicacion:"Con voltaje estable a 460V, una falla del monitor de fase indica que la secuencia de fases fue invertida, típicamente después de una reparación eléctrica en el edificio que alteró las conexiones." },
  { id:"ns_0822", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere implementar 'Dynamic Pricing'. ¿Cuál es el riesgo de marca?", opciones:["Percepción de falta de transparencia o 'precio abusivo' en momentos de crisis.", "Aumento en el costo de los materiales al fluctuar los precios de venta hoy.", "Que los técnicos no sepan calcular el precio correcto en cada visita técnica.", "Reducción en la cantidad de llamadas de mantenimiento preventivo anual hoy."], respuesta_correcta:0, explicacion:"El Dynamic Pricing crea riesgo de marca cuando los clientes perciben los precios altos durante emergencias como abuso o falta de transparencia, dañando la confianza." },
  { id:"ns_0823", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no enfría. El voltaje entre S1 y S2 es 240VAC. ¿Conclusión?", opciones:["La alimentación eléctrica llega correctamente a la unidad exterior hoy hoy.", "Hay una falla de comunicación masiva entre la interior y la exterior hoy.", "El fusible de la placa electrónica exterior está fundido y debe cambiarse.", "El compresor inverter está aterrizado y consume el voltaje de la línea."], respuesta_correcta:0, explicacion:"Un voltaje de 240VAC entre S1 y S2 confirma que la alimentación eléctrica llega correctamente a la unidad exterior. El problema de enfriamiento debe buscarse en otro componente del sistema." },
  { id:"ns_0824", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿por qué el compresor se calienta en modo calefacción?", opciones:["Relación de compresión más alta y menor masa de gas para enfriar el motor.", "El ventilador exterior gira más lento para permitir que el serpentín caliente.", "Las resistencias eléctricas están demasiado cerca de la succión del compresor.", "El aceite POE pierde viscosidad al operar con temperaturas exteriores bajas."], respuesta_correcta:0, explicacion:"En modo calefaccion, la temperatura exterior baja reduce la presion de succion, aumentando la relacion de compresion. Ademas, menos masa de gas de succion enfria el motor del compresor, resultando en temperaturas mas altas." },
  { id:"ns_0825", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que la bomba de vacío no baja de 2000 micrones. ¿Qué hace el Senior?", opciones:["Cambiar el aceite de la bomba y verificar si hay fugas en las mangueras.", "Dejarla encendida por 12 horas más asumiendo que el sistema está muy húmedo.", "Cargar un poco de nitrógeno y luego intentar el vacío de nuevo hoy hoy.", "Usar el manómetro analógico para ver si la aguja baja más allá del cero."], respuesta_correcta:0, explicacion:"Si la bomba no baja de 2000 micrones, las causas más comunes son aceite contaminado con humedad (pierde eficiencia) o fugas en las mangueras/conexiones. Cambiar el aceite y verificar la hermeticidad de las conexiones resuelve la mayoría de estos casos." },
  { id:"ns_0826", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Qué precaución toma el Senior al cargar gas?", opciones:["Cargar siempre en estado líquido para evitar el fraccionamiento de la mezcla.", "Cargar en estado gaseoso para no dañar las válvulas de los compresores hoy.", "Utilizar aceite mineral para asegurar que el refrigerante sea miscible hoy.", "No cargar más de 50 libras a la vez para evitar picos de presión alta hoy."], respuesta_correcta:0, explicacion:"El R-448A es una mezcla zeotrópica de cinco componentes. Cargar en estado líquido es obligatorio para que todos los componentes entren al sistema en las proporciones de diseño, ya que en fase gaseosa se fraccionarían por diferencias de volatilidad." },
  { id:"ns_0827", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de temperatura de 'Leaving Water' roto. ¿Efecto?", opciones:["El controlador no podrá modular la capacidad para mantener el set-point.", "El compresor se apagará inmediatamente por seguridad de flujo de agua hoy.", "La unidad operará siempre al 100% de su capacidad nominal sin modular hoy.", "No hay efecto si el sensor de 'Entering Water' está operando correctamente."], respuesta_correcta:0, explicacion:"El sensor de leaving water es el que el controlador usa para modular la capacidad del chiller y mantener el set-point. Sin él, el sistema no puede ajustar su operación correctamente." },
  { id:"ns_0828", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga de 550 PSI con R-410A. ¿Causa?", opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy.", "Falta de refrigerante líquido que impide que el sistema enfríe el aire hoy.", "Válvula de expansión electrónica bloqueada en la posición de abierta total.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo."], respuesta_correcta:0, explicacion:"Descarga de 550 PSI con R-410A es una condición crítica que requiere atención inmediata. Sin disipación adecuada de calor, ya sea por condensador sucio o ventilador fallando, la presión de descarga alcanza niveles peligrosamente altos." },
  { id:"ns_0829", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Average Response Time'. ¿Qué medida toma?", opciones:["Implementar software de despacho inteligente y zonificación de técnicos hoy.", "Aumentar el número de técnicos en la nómina aunque no haya llamadas hoy.", "Reducir el tiempo de almuerzo de los técnicos para que estén más disponibles.", "Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas."], respuesta_correcta:0, explicacion:"El despacho inteligente con zonificación de técnicos optimiza la asignación de recursos y reduce el tiempo de respuesta promedio de forma eficiente y escalable." },
  { id:"ns_0830", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería fluctuar entre 0 y 24VDC hoy hoy.", "La placa exterior está operando correctamente enviando la señal de control.", "El compresor inverter está aterrizado y consume el voltaje de comunicación.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior."], respuesta_correcta:0, explicacion:"La señal entre S2 y S3 en sistemas inverter debe ser DC pulsante (0-24V). Un voltaje fijo de 24VDC indica falla de comunicación porque no hay modulación de datos entre las unidades." },
  { id:"ns_0831", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Defrost Sensor' falla en circuito abierto?", opciones:["El sistema nunca entrará en modo de deshielo y el serpentín se congelará.", "El sistema entrará en modo de deshielo cada 30 minutos sin importar el hielo.", "El compresor se quemará debido a la falta de control de sobrecalentamiento.", "La unidad operará solo en modo refrigeración permanentemente por seguridad."], respuesta_correcta:0, explicacion:"Si el sensor de defrost falla en circuito abierto, la placa nunca recibe la senal de temperatura fria necesaria para iniciar el deshielo. El hielo se acumula progresivamente hasta bloquear el flujo de aire del serpentin." },
  { id:"ns_0832", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un sistema VRF. ¿Por qué es vital pesar la carga?", opciones:["Los sistemas VRF son de carga crítica y las presiones no son indicadores.", "Es un requisito legal de la EPA para sistemas con más de 50 libras de gas.", "Para asegurar que el aceite POE regrese correctamente a los compresores hoy.", "Para evitar que la garantía del fabricante se anule tras la instalación."], respuesta_correcta:0, explicacion:"Los sistemas VRF tienen carga crítica calculada por el fabricante basada en la longitud de tuberías y cantidad de evaporadores. Las presiones varían con la modulación de capacidad, haciendo que el pesaje sea el único método confiable." },
  { id:"ns_0833", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Reversal'. ¿Qué sucede si se ignora el error?", opciones:["El compresor girará al revés y no bombeará aceite ni refrigerante líquido.", "La unidad funcionará al 50% de su capacidad nominal debido al desfase fase.", "El motor se quemará instantáneamente al intentar vencer la inercia carga.", "Las válvulas de expansión se cerrarán por seguridad al detectar el error."], respuesta_correcta:0, explicacion:"Phase Reversal causa rotación inversa del compresor, impidiendo el bombeo de aceite lubricante y la circulación de refrigerante. Esto resulta en daño mecánico rápido de los componentes internos." },
  { id:"ns_0834", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. Subenfriamiento 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged) hoy hoy.", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio térmico.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F indica que el sistema no tiene suficiente refrigerante para producir líquido subenfriado en la salida del condensador. Esta es la confirmación diagnóstica más clara de un sistema severamente undercharged." },
  { id:"ns_0835", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos."], respuesta_correcta:0, explicacion:"Para Smart Homes se requieren técnicos con conocimiento en redes y protocolos de comunicación para la integración de termostatos, sensores y automatización del hogar." },
  { id:"ns_0836", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué indica una temperatura de succión muy alta en el cabezal?", opciones:["Sobrecalentamiento excesivo que dañará la lubricación de compresores pronto.", "Que el sistema está operando a su máxima eficiencia de evaporación hoy hoy.", "Falta de refrigerante líquido en el recibidor principal del rack paralelo hoy.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura."], respuesta_correcta:0, explicacion:"Una temperatura de succión muy elevada causa sobrecalentamiento del gas que entra al compresor. Esto aumenta la temperatura de descarga y reduce la capacidad lubricante del aceite, llevando a desgaste prematuro de los componentes internos." },
  { id:"ns_0837", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. ¿Qué revisa?", opciones:["Presencia de aire en la tubería, paddle roto o transductor descalibrado hoy.", "La carga de refrigerante que podría estar congelando el agua en tubos hoy.", "El sentido de rotación del motor del compresor centrífugo del sistema hoy.", "La apertura de las válvulas de expansión del circuito de refrigeración hoy."], respuesta_correcta:0, explicacion:"Con bomba funcionando, la alarma de flow switch señala un problema en el sensor de detección: paddle roto, aire en la tubería, o transductor descalibrado que genera la falsa alarma." },
  { id:"ns_0838", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy."], respuesta_correcta:0, explicacion:"El goteo solo cuando el compresor para indica contrapendiente o bloqueo parcial en el drenaje que retiene agua acumulada durante la operación y la libera al detenerse el equipo." },
  { id:"ns_0839", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de 0.9 en suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire hoy.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy."], respuesta_correcta:0, explicacion:"La presión estática de 0.9\" en suministro frente a 0.2\" en retorno demuestra que la restricción principal está en los conductos de suministro. Difusores cerrados o conductos restringidos son la causa directa." },
  { id:"ns_0840", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre 20°F y 30°F hoy.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos hoy.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en modo calor esta por debajo del rango normal de 20-30F, indicando capacidad de calefaccion insuficiente. La causa tipica es baja carga, exceso de CFM, o mala absorcion de calor exterior." },
  { id:"ns_0841", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar prueba de acidez del aceite y usar filtros succión de limpieza hoy.", "Añadir aditivo sellador de fugas para prevenir fallas futuras en líneas hoy.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.", "Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy."], respuesta_correcta:0, explicacion:"El procedimiento correcto post-burnout requiere medir la acidez del aceite del sistema para evaluar la contaminación, e instalar filtros de succión de limpieza que protejan al compresor nuevo de los residuos ácidos y partículas carbonizadas." },
  { id:"ns_0842", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. ¿Estado?", opciones:["Funcionamiento correcto; la purga está separando los no condensables hoy.", "Falla en el serpentín de condensación interno de la unidad de purga hoy.", "El sistema tiene una fuga masiva de agua hacia el lado del refrigerante.", "La temperatura del evaporador es demasiado alta para que la purga trabaje."], respuesta_correcta:0, explicacion:"Si la purga expulsa mucho aire pero retiene el refrigerante, funciona correctamente. Su diseño está optimizado para separar no condensables y mantener la carga de refrigerante del sistema." },
  { id:"ns_0843", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si el 'Oil Separator' queda pegado en posición abierta?", opciones:["Gas caliente de descarga pasará directo al depósito aceite y succión hoy.", "El rack se quedará sin aceite en pocos minutos al no poder separarlo gas.", "Los compresores se apagarán por alta presión al bloquearse el flujo gas.", "El nivel de aceite en los cárteres subirá tanto que dañará los pistones hoy."], respuesta_correcta:0, explicacion:"Un separador con flotador abierto permite que el gas de descarga a alta presión pase directo al depósito de aceite. Esto genera un cortocircuito de gas caliente que reduce la eficiencia del rack y puede empujar aceite hacia la succión." },
  { id:"ns_0844", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. ¿Qué KPI usa?", opciones:["Número de llamadas de nuevos clientes que mencionan haber visto la unidad hoy.", "La cantidad de millas recorridas por cada vehículo en zonas residenciales.", "El costo total del diseño e instalación del rótulo dividido entre 12 meses.", "El aumento en la velocidad promedio de técnicos al conducir camionetas nuevas."], respuesta_correcta:0, explicacion:"El número de llamadas de nuevos clientes que vieron la camioneta es el indicador más directo del impacto de las unidades rotuladas como herramienta de marketing." },
  { id:"ns_0845", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. ¿Qué revisa?", opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy.", "La carga de refrigerante líquido basándose en el visor del evaporador hoy.", "Si la válvula de expansión está inyectando demasiado líquido al sistema.", "El estado de los filtros de aire de la manejadora de aire del edificio hoy."], respuesta_correcta:0, explicacion:"La alta presión de condensación en un chiller con condensador de agua requiere verificar primero la temperatura del agua de torre y la bomba de condensador como causas más directas." },
  { id:"ns_0846", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión de 125 PSI y descarga 400 PSI con R-410A. ¿Estado aire?", opciones:["Funcionamiento normal bajo condiciones de carga térmica estándar hoy hoy.", "Falta de refrigerante que impide que temperatura del aire baje a 55 grados.", "Exceso de carga que está elevando la presión de descarga innecesariamente.", "Compresor con eficiencia reducida que no logra enfriar el aire correctamente."], respuesta_correcta:0, explicacion:"Presiones de succión de 125 PSI y descarga de 400 PSI con R-410A representan operación normal. El diferencial de presión es correcto para condiciones estándar de carga térmica." },
  { id:"ns_0847", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. ¿Qué estrategia?", opciones:["Programa de membresías mantenimiento para convertir clientes en recurrentes.", "Aumentar el precio de la primera visita para maximizar la ganancia hoy.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos.", "Despedir a técnicos que no logren vender un sistema nuevo en cada visita."], respuesta_correcta:0, explicacion:"Las membresías de mantenimiento transforman clientes ocasionales en recurrentes, siendo la estrategia más efectiva para construir una base de ingresos estable." },
  { id:"ns_0848", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una restricción en la válvula de expansión hoy.", "Si el ventilador interior está sucio y no sopla suficiente aire frío hoy.", "El voltaje de la línea eléctrica que podría estar por debajo de 200V hoy.", "Si el control remoto está configurado en una temperatura demasiado baja hoy."], respuesta_correcta:0, explicacion:"La protección de temperatura de descarga se activa por refrigerante insuficiente o restricción en la EEV, ambas condiciones causan que el compresor descargue gas sobrecalentado." },
  { id:"ns_0849", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba calor, ¿qué sucede si 'Check Valve' condensador falla abierta?", opciones:["En modo calor el refrigerante hará bypass a TXV impidiendo calentamiento hoy.", "El sistema funcionará mejor al haber menos restricción al flujo líquido hoy.", "La presión de descarga subirá hasta que switch de alta apague el equipo hoy.", "El compresor se quemará por el retorno de líquido masivo en el arranque hoy."], respuesta_correcta:0, explicacion:"La check valve del condensador al fallar abierta permite que el refrigerante haga bypass en modo calor. Sin pasar por la TXV no hay restriccion, no hay cambio de presion y no hay calentamiento efectivo." },
  { id:"ns_0850", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o inyección de líquido?", opciones:["Para enfriar gas de succión y evitar que descarga dañe el aceite hoy hoy.", "Para aumentar la presión de succión cuando carga en vitrinas es baja hoy.", "Para limpiar el interior de compresores de acumulaciones de carbonilla hoy.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos hoy."], respuesta_correcta:0, explicacion:"La inyección Quench absorbe calor del gas mediante evaporación del refrigerante líquido inyectado. Esto controla la temperatura de descarga del compresor, protegiendo el aceite lubricante de la carbonización y degradación química." },
  { id:"ns_0851", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. ¿Criterio?", opciones:["El volumen de agua y la accesibilidad para eliminación segura del fluido hoy.", "Cuál de las dos herramientas es más nueva y hace menos ruido al operar hoy.", "La preferencia del cliente sobre qué herramienta quiere ver en su casa hoy.", "Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy."], respuesta_correcta:0, explicacion:"Un técnico Senior selecciona la herramienta basándose en factores técnicos objetivos: la cantidad de agua a extraer y qué tan accesible es el punto de acumulación. Esto garantiza una intervención eficiente y una eliminación segura del fluido." },
  { id:"ns_0852", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar prueba presión a tubos del evaporador para buscar rupturas hoy.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.", "Aumentar la temperatura del agua helada para evitar que vapor condense hoy.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy."], respuesta_correcta:0, explicacion:"La alarma de agua detectada por la purga indica posible ruptura en tubos del evaporador. La prueba de presión es la acción urgente para localizar la fuga y prevenir daño mayor." },
  { id:"ns_0853", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión 130 PSI y descarga 380 PSI. Subenfriamiento 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango.", "Falta de refrigerante líquido; el subenfriamiento debería ser 15 grados hoy.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno hoy.", "Compresor fallando; la diferencia presión entre succión y descarga es baja hoy."], respuesta_correcta:0, explicacion:"Las presiones de 130/380 PSI con subenfriamiento de 12°F son valores óptimos para R-410A. Confirman carga de refrigerante correcta y funcionamiento adecuado de todos los componentes del ciclo de refrigeración." },
  { id:"ns_0854", categoria:"NATE_SR_PACKAGE", pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. ¿Qué revisa?", opciones:["El voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo hoy.", "Si los contactos principales están quemados o soldados entre sí hoy.", "El capacitor de arranque del compresor que podría estar descargado hoy.", "La continuidad de los fusibles de potencia de la línea de 240 voltios hoy."], respuesta_correcta:0, explicacion:"La bobina del contactor necesita voltaje adecuado para crear el campo magnético que cierra los contactos. Voltaje bajo o un núcleo con suciedad u óxido son las causas más directas de que el contactor zumbe sin completar el cierre mecánico." },
  { id:"ns_0855", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico cobra 'por fuera' a clientes. ¿Qué acción toma?", opciones:["Despido inmediato y posible acción legal según el contrato de trabajo hoy.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras hoy.", "Ignorar la situación si el técnico es el que más dinero genera hoy.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."], respuesta_correcta:0, explicacion:"Cobrar por fuera es una falta que justifica despido inmediato y acción legal, ya que el técnico desvía ingresos que pertenecen a la empresa y viola su contrato." },
  { id:"ns_0856", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en el recibidor?", opciones:["Para evitar fraccionamiento de la mezcla y asegurar composición correcta hoy.", "Para que el refrigerante se mezcle más rápido con el aceite POE del rack hoy.", "Para prevenir que las válvulas de descarga de compresores se calienten hoy.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."], respuesta_correcta:0, explicacion:"El R-448A debe cargarse siempre en fase líquida para mantener la composición correcta de sus cinco componentes. La carga en gas provocaría fraccionamiento, alterando las presiones de operación y reduciendo la eficiencia del sistema." },
  { id:"ns_0857", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. ¿Efecto?", opciones:["El controlador no podrá calcular la carga térmica real del edificio hoy.", "El compresor se apagará inmediatamente por seguridad de flujo de agua hoy.", "La unidad operará siempre al 100% de su capacidad nominal sin modular hoy.", "No hay efecto si el sensor de 'Leaving Water' está operando correctamente hoy."], respuesta_correcta:0, explicacion:"El sensor de entering water permite calcular la carga térmica (Delta T x flujo). Sin él, el controlador no puede determinar cuánta capacidad necesita el sistema." },
  { id:"ns_0858", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga de 550 PSI con R-410A. ¿Causa?", opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy.", "Falta de refrigerante líquido que impide que el sistema enfríe el aire hoy.", "Válvula de expansión electrónica bloqueada en la posición de abierta total.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo."], respuesta_correcta:0, explicacion:"Una descarga de 550 PSI con R-410A es crítica y apunta directamente a falta de rechazo de calor en el condensador. Ya sea por suciedad extrema o falla del ventilador, el condensador no puede disipar el calor del refrigerante comprimido." },
  { id:"ns_0859", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Average Response Time'. ¿Qué medida toma?", opciones:["Implementar software de despacho inteligente y zonificación de técnicos hoy.", "Aumentar el número de técnicos en la nómina aunque no haya llamadas hoy.", "Reducir el tiempo de almuerzo de los técnicos para que estén más disponibles.", "Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas."], respuesta_correcta:0, explicacion:"El software de despacho inteligente con zonificación es la medida técnica más directa para reducir el tiempo de respuesta al asignar al técnico óptimo para cada llamada." },
  { id:"ns_0860", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería fluctuar entre 0 y 24VDC hoy hoy.", "La placa exterior está operando correctamente enviando la señal de control.", "El compresor inverter está aterrizado y consume el voltaje de comunicación.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior."], respuesta_correcta:0, explicacion:"La comunicación inverter entre S2 y S3 utiliza voltaje DC pulsante. Un valor fijo de 24VDC indica ausencia de modulación de datos, lo que significa falla en la comunicación digital." },
  { id:"ns_0861", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Defrost Sensor' falla en circuito abierto?", opciones:["El sistema nunca entrará en modo de deshielo y el serpentín se congelará.", "El sistema entrará en modo de deshielo cada 30 minutos sin importar el hielo.", "El compresor se quemará debido a la falta de control de sobrecalentamiento.", "La unidad operará solo en modo refrigeración permanentemente por seguridad."], respuesta_correcta:0, explicacion:"Con el sensor de defrost en circuito abierto, la placa no detecta cuando el serpentin necesita deshielo. El sistema nunca entra en modo defrost y el hielo bloquea el serpentin exterior progresivamente." },
  { id:"ns_0862", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un sistema VRF. ¿Por qué es vital pesar la carga?", opciones:["Los sistemas VRF son de carga crítica y las presiones no son indicadores.", "Es un requisito legal de la EPA para sistemas con más de 50 libras de gas.", "Para asegurar que el aceite POE regrese correctamente a los compresores hoy.", "Para evitar que la garantía del fabricante se anule tras la instalación."], respuesta_correcta:0, explicacion:"En VRF, la carga de refrigerante se calcula por fórmula del fabricante (carga de fábrica + volumen de tuberías adicionales). Las presiones no son confiables como indicador de carga porque el sistema modula constantemente su capacidad." },
  { id:"ns_0863", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Reversal'. ¿Qué sucede si se ignora el error?", opciones:["El compresor girará al revés y no bombeará aceite ni refrigerante líquido.", "La unidad funcionará al 50% de su capacidad nominal debido al desfase fase.", "El motor se quemará instantáneamente al intentar vencer la inercia carga.", "Las válvulas de expansión se cerrarán por seguridad al detectar el error."], respuesta_correcta:0, explicacion:"Ignorar Phase Reversal permite que el compresor gire al revés sin bombear aceite ni refrigerante, causando falla mecánica inmediata por falta de lubricación en cojinetes." },
  { id:"ns_0864", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. Subenfriamiento 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged) hoy hoy.", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio térmico.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F con presiones moderadas es el diagnóstico definitivo de falta severa de refrigerante. No hay masa suficiente en el sistema para que el condensador complete la condensación y entregue líquido subenfriado." },
  { id:"ns_0865", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos."], respuesta_correcta:0, explicacion:"Smart Homes exige técnicos capacitados en redes y protocolos de comunicación para conectar e integrar dispositivos IoT con los sistemas de climatización." },
  { id:"ns_0866", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué indica una temperatura de succión muy alta en el cabezal?", opciones:["Sobrecalentamiento excesivo que dañará la lubricación de compresores pronto.", "Que el sistema está operando a su máxima eficiencia de evaporación hoy hoy.", "Falta de refrigerante líquido en el recibidor principal del rack paralelo hoy.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura."], respuesta_correcta:0, explicacion:"El sobrecalentamiento excesivo del gas en el cabezal de succión indica que el refrigerante se ha evaporado completamente y se ha calentado mucho más de lo necesario. Esto perjudica la lubricación y eleva peligrosamente la temperatura de descarga." },
  { id:"ns_0867", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. ¿Qué revisa?", opciones:["Presencia de aire en la tubería, paddle roto o transductor descalibrado hoy.", "La carga de refrigerante que podría estar congelando el agua en tubos hoy.", "El sentido de rotación del motor del compresor centrífugo del sistema hoy.", "La apertura de las válvulas de expansión del circuito de refrigeración hoy."], respuesta_correcta:0, explicacion:"Flow Switch Alarm con bomba operando indica problema del sensor de flujo: paddle dañado, presencia de aire, o transductor de presión diferencial que necesita recalibración." },
  { id:"ns_0868", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy."], respuesta_correcta:0, explicacion:"El goteo al parar el compresor indica contrapendiente o bloqueo parcial del drenaje en la parte superior, reteniendo agua durante la operación que se libera al detenerse la unidad." },
  { id:"ns_0869", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de 0.9 en suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire hoy.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy."], respuesta_correcta:0, explicacion:"La distribución de presión estática 0.9\"/0.2\" confirma restricción en el lado de suministro. Los conductos de suministro restringidos, colapsados o difusores cerrados son la fuente del problema." },
  { id:"ns_0870", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre 20°F y 30°F hoy.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos hoy.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en calefaccion es insuficiente (rango normal 20-30F). Indica baja capacidad de calefaccion, usualmente por falta de refrigerante, exceso de flujo de aire interior o absorcion deficiente de calor exterior." },
  { id:"ns_0871", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar prueba de acidez del aceite y usar filtros succión de limpieza hoy.", "Añadir aditivo sellador de fugas para prevenir fallas futuras en líneas hoy.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.", "Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy."], respuesta_correcta:0, explicacion:"Cuando un compresor se quema, produce ácidos fluorhídrico y clorhídrico que corroen el sistema. La prueba de acidez verifica la contaminación y los filtros de succión capturan partículas sólidas, ambos críticos para la sobrevivencia del compresor nuevo." },
  { id:"ns_0872", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. ¿Estado?", opciones:["Funcionamiento correcto; la purga está separando los no condensables hoy.", "Falla en el serpentín de condensación interno de la unidad de purga hoy.", "El sistema tiene una fuga masiva de agua hacia el lado del refrigerante.", "La temperatura del evaporador es demasiado alta para que la purga trabaje."], respuesta_correcta:0, explicacion:"Purga que expulsa mucho aire y poco refrigerante funciona correctamente, cumpliendo su función de separar y remover gases no condensables del sistema de refrigeración." },
  { id:"ns_0873", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué sucede si el 'Oil Separator' queda pegado en posición abierta?", opciones:["Gas caliente de descarga pasará directo al depósito aceite y succión hoy.", "El rack se quedará sin aceite en pocos minutos al no poder separarlo gas.", "Los compresores se apagarán por alta presión al bloquearse el flujo gas.", "El nivel de aceite en los cárteres subirá tanto que dañará los pistones hoy."], respuesta_correcta:0, explicacion:"Con el flotador del separador trabado abierto, no hay barrera entre la descarga de alta presión y el depósito de aceite. El gas caliente pasa directamente, pudiendo empujar el aceite fuera del depósito y reducir la eficiencia del rack." },
  { id:"ns_0874", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. ¿Qué KPI usa?", opciones:["Número de llamadas de nuevos clientes que mencionan haber visto la unidad hoy.", "La cantidad de millas recorridas por cada vehículo en zonas residenciales.", "El costo total del diseño e instalación del rótulo dividido entre 12 meses.", "El aumento en la velocidad promedio de técnicos al conducir camionetas nuevas."], respuesta_correcta:0, explicacion:"Medir las llamadas de nuevos clientes que mencionan la camioneta rotulada es el KPI más preciso para evaluar el retorno de la inversión en branding vehicular." },
  { id:"ns_0875", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. ¿Qué revisa?", opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy.", "La carga de refrigerante líquido basándose en el visor del evaporador hoy.", "Si la válvula de expansión está inyectando demasiado líquido al sistema.", "El estado de los filtros de aire de la manejadora de aire del edificio hoy."], respuesta_correcta:0, explicacion:"Alta presión de condensación en condensador de agua: lo primero es verificar la temperatura del agua de torre y que la bomba de condensador esté funcionando correctamente." },
  { id:"ns_0876", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión de 125 PSI y descarga 400 PSI con R-410A. ¿Estado aire?", opciones:["Funcionamiento normal bajo condiciones de carga térmica estándar hoy hoy.", "Falta de refrigerante que impide que temperatura del aire baje a 55 grados.", "Exceso de carga que está elevando la presión de descarga innecesariamente.", "Compresor con eficiencia reducida que no logra enfriar el aire correctamente."], respuesta_correcta:0, explicacion:"Succión de 125 PSI y descarga de 400 PSI con R-410A son presiones normales de operación. El sistema está funcionando dentro de los parámetros de diseño para condiciones de carga térmica estándar." },
  { id:"ns_0877", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. ¿Qué estrategia?", opciones:["Programa de membresías mantenimiento para convertir clientes en recurrentes.", "Aumentar el precio de la primera visita para maximizar la ganancia hoy.", "Gastar más dinero en anuncios de Google para atraer siempre clientes nuevos.", "Despedir a técnicos que no logren vender un sistema nuevo en cada visita."], respuesta_correcta:0, explicacion:"La membresía de mantenimiento es la herramienta probada para convertir clientes de una sola visita en clientes recurrentes con relación a largo plazo." },
  { id:"ns_0878", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. ¿Qué revisa?", opciones:["Carga de refrigerante baja o una restricción en la válvula de expansión hoy.", "Si el ventilador interior está sucio y no sopla suficiente aire frío hoy.", "El voltaje de la línea eléctrica que podría estar por debajo de 200V hoy.", "Si el control remoto está configurado en una temperatura demasiado baja hoy."], respuesta_correcta:0, explicacion:"La temperatura de descarga excesiva del compresor es causada por carga baja de refrigerante o restricción en la válvula de expansión que reduce el efecto de enfriamiento del gas de succión." },
  { id:"ns_0879", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba calor, ¿qué sucede si 'Check Valve' condensador falla abierta?", opciones:["En modo calor el refrigerante hará bypass a TXV impidiendo calentamiento hoy.", "El sistema funcionará mejor al haber menos restricción al flujo líquido hoy.", "La presión de descarga subirá hasta que switch de alta apague el equipo hoy.", "El compresor se quemará por el retorno de líquido masivo en el arranque hoy."], respuesta_correcta:0, explicacion:"Si la check valve del condensador falla abierta, el refrigerante en modo calor circula sin pasar por la TXV. Sin la restriccion del dispositivo de expansion, no se produce el cambio de presion necesario para calentar." },
  { id:"ns_0880", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o inyección de líquido?", opciones:["Para enfriar gas de succión y evitar que descarga dañe el aceite hoy hoy.", "Para aumentar la presión de succión cuando carga en vitrinas es baja hoy.", "Para limpiar el interior de compresores de acumulaciones de carbonilla hoy.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos hoy."], respuesta_correcta:0, explicacion:"La válvula Quench protege el sistema inyectando una cantidad controlada de líquido que se evapora y absorbe calor excesivo. Sin esta protección, temperaturas de descarga elevadas carbonizarían el aceite y dañarían las válvulas del compresor." },
  { id:"ns_0881", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. ¿Criterio?", opciones:["El volumen de agua y la accesibilidad para eliminación segura del fluido hoy.", "Cuál de las dos herramientas es más nueva y hace menos ruido al operar hoy.", "La preferencia del cliente sobre qué herramienta quiere ver en su casa hoy.", "Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy."], respuesta_correcta:0, explicacion:"La decisión entre aspiradora y bomba se toma evaluando la cantidad de agua y las condiciones de acceso. Un profesional elige la herramienta que resuelve el problema de forma segura y eficiente según las condiciones específicas del sitio." },
  { id:"ns_0882", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar prueba presión a tubos del evaporador para buscar rupturas hoy.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.", "Aumentar la temperatura del agua helada para evitar que vapor condense hoy.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy."], respuesta_correcta:0, explicacion:"Water Detected es una alarma crítica que requiere prueba de presión inmediata a los tubos del evaporador para identificar rupturas que permiten la entrada de agua al lado del refrigerante." },
  { id:"ns_0883", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión 130 PSI y descarga 380 PSI. Subenfriamiento 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango.", "Falta de refrigerante líquido; el subenfriamiento debería ser 15 grados hoy.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno hoy.", "Compresor fallando; la diferencia presión entre succión y descarga es baja hoy."], respuesta_correcta:0, explicacion:"Presiones de 130/380 PSI con 12°F de subenfriamiento confirman operación óptima. Todos los parámetros están dentro del rango normal para R-410A, indicando carga correcta y buen funcionamiento." },
  { id:"ns_0884", categoria:"NATE_SR_PACKAGE", pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. ¿Qué revisa?", opciones:["El voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo hoy.", "Si los contactos principales están quemados o soldados entre sí hoy.", "El capacitor de arranque del compresor que podría estar descargado hoy.", "La continuidad de los fusibles de potencia de la línea de 240 voltios hoy."], respuesta_correcta:0, explicacion:"Revisar el voltaje de la bobina y el estado del núcleo es el procedimiento estándar cuando un contactor zumba. Un voltaje de bobina inferior al 85% del nominal o residuos en las caras polares impiden que la armadura cierre completamente contra el resorte de retorno." },
  { id:"ns_0885", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico cobra 'por fuera' a clientes. ¿Qué acción toma?", opciones:["Despido inmediato y posible acción legal según el contrato de trabajo hoy.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras hoy.", "Ignorar la situación si el técnico es el que más dinero genera hoy.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."], respuesta_correcta:0, explicacion:"El cobro por fuera a clientes es una violación grave; la acción correcta es el despido inmediato y la evaluación de acciones legales conforme al contrato laboral." },
  { id:"ns_0886", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en el recibidor?", opciones:["Para evitar fraccionamiento de la mezcla y asegurar composición correcta hoy.", "Para que el refrigerante se mezcle más rápido con el aceite POE del rack hoy.", "Para prevenir que las válvulas de descarga de compresores se calienten hoy.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."], respuesta_correcta:0, explicacion:"Como mezcla zeotrópica, el R-448A se fracciona si se carga en vapor. Cada componente tiene una presión de vapor distinta, por lo que cargar en líquido es la única forma de garantizar que la composición en el sistema sea la especificada por el fabricante." },
  { id:"ns_0887", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. ¿Efecto?", opciones:["El controlador no podrá calcular la carga térmica real del edificio hoy.", "El compresor se apagará inmediatamente por seguridad de flujo de agua hoy.", "La unidad operará siempre al 100% de su capacidad nominal sin modular hoy.", "No hay efecto si el sensor de 'Leaving Water' está operando correctamente hoy."], respuesta_correcta:0, explicacion:"Sin sensor de entering water, el controlador pierde la referencia para calcular la carga térmica del edificio y no puede modular adecuadamente la capacidad del chiller." },
  { id:"ns_0888", categoria:"NATE_SR_HVAC", pregunta:"Un sistema residencial presenta una presión de descarga de 550 PSI con R-410A. ¿Causa?", opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy.", "Falta de refrigerante líquido que impide que el sistema enfríe el aire hoy.", "Válvula de expansión electrónica bloqueada en la posición de abierta total.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo."], respuesta_correcta:0, explicacion:"Descarga de 550 PSI es peligrosamente alta para R-410A. Un condensador sucio o ventilador fallando impide el rechazo de calor, causando acumulación de presión que puede activar el switch de alta presión o dañar el compresor." },
  { id:"ns_0889", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Average Response Time'. ¿Qué medida toma?", opciones:["Implementar software de despacho inteligente y zonificación de técnicos hoy.", "Aumentar el número de técnicos en la nómina aunque no haya llamadas hoy.", "Reducir el tiempo de almuerzo de los técnicos para que estén más disponibles.", "Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas."], respuesta_correcta:0, explicacion:"El despacho inteligente con zonificación geográfica reduce el tiempo de respuesta al optimizar automáticamente la asignación de técnicos según ubicación y disponibilidad." },
  { id:"ns_0890", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería fluctuar entre 0 y 24VDC hoy hoy.", "La placa exterior está operando correctamente enviando la señal de control.", "El compresor inverter está aterrizado y consume el voltaje de comunicación.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior."], respuesta_correcta:0, explicacion:"En sistemas inverter, la señal de comunicación S2-S3 debe fluctuar entre 0 y 24VDC. Un voltaje constante indica que no hay transmisión de datos: falla de comunicación entre unidades." },
  { id:"ns_0891", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Defrost Sensor' falla en circuito abierto?", opciones:["El sistema nunca entrará en modo de deshielo y el serpentín se congelará.", "El sistema entrará en modo de deshielo cada 30 minutos sin importar el hielo.", "El compresor se quemará debido a la falta de control de sobrecalentamiento.", "La unidad operará solo en modo refrigeración permanentemente por seguridad."], respuesta_correcta:0, explicacion:"El sensor de defrost en circuito abierto elimina la senal de temperatura al controlador. Sin verificar que el serpentin esta frio, el sistema nunca cumple la condicion de inicio de deshielo y el hielo se acumula." },
  { id:"ns_0892", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un sistema VRF. ¿Por qué es vital pesar la carga?", opciones:["Los sistemas VRF son de carga crítica y las presiones no son indicadores.", "Es un requisito legal de la EPA para sistemas con más de 50 libras de gas.", "Para asegurar que el aceite POE regrese correctamente a los compresores hoy.", "Para evitar que la garantía del fabricante se anule tras la instalación."], respuesta_correcta:0, explicacion:"Los VRF requieren pesaje exacto porque la modulación variable de sus compresores inverter hace que las presiones fluctúen constantemente. Solo el peso de refrigerante especificado por el fabricante garantiza el rendimiento correcto del sistema." },
  { id:"ns_0893", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Reversal'. ¿Qué sucede si se ignora el error?", opciones:["El compresor girará al revés y no bombeará aceite ni refrigerante líquido.", "La unidad funcionará al 50% de su capacidad nominal debido al desfase fase.", "El motor se quemará instantáneamente al intentar vencer la inercia carga.", "Las válvulas de expansión se cerrarán por seguridad al detectar el error."], respuesta_correcta:0, explicacion:"Phase Reversal causa rotación inversa del compresor. Sin circulación de aceite ni refrigerante en la dirección correcta, los componentes mecánicos fallan rápidamente." },
  { id:"ns_0894", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. Subenfriamiento 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged) hoy hoy.", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio térmico.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F es la señal inequívoca de falta severa de refrigerante. El sistema no tiene suficiente masa de refrigerante para completar la condensación y producir líquido subenfriado en la salida del condensador." },
  { id:"ns_0895", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos."], respuesta_correcta:0, explicacion:"Smart Homes demanda técnicos con formación en redes y protocolos de comunicación para integrar sistemas inteligentes de climatización con la infraestructura del hogar." },
  { id:"ns_0896", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué indica una temperatura de succión muy alta en el cabezal?", opciones:["Sobrecalentamiento excesivo que dañará la lubricación de compresores pronto.", "Que el sistema está operando a su máxima eficiencia de evaporación hoy hoy.", "Falta de refrigerante líquido en el recibidor principal del rack paralelo hoy.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura."], respuesta_correcta:0, explicacion:"Cuando la temperatura de succión es muy alta, indica sobrecalentamiento severo. Los compresores semi-herméticos dependen del gas de succión para enfriar el motor; sin ese enfriamiento, el aceite pierde propiedades y los componentes se desgastan rápidamente." },
  { id:"ns_0897", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. ¿Qué revisa?", opciones:["Presencia de aire en la tubería, paddle roto o transductor descalibrado hoy.", "La carga de refrigerante que podría estar congelando el agua en tubos hoy.", "El sentido de rotación del motor del compresor centrífugo del sistema hoy.", "La apertura de las válvulas de expansión del circuito de refrigeración hoy."], respuesta_correcta:0, explicacion:"Alarma de flow switch con bomba encendida apunta a problemas del sensor: paddle roto, aire en tubería, o transductor descalibrado, no a problemas del sistema de refrigeración." },
  { id:"ns_0898", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy."], respuesta_correcta:0, explicacion:"El goteo solo al parar el compresor indica un drenaje con contrapendiente o parcialmente obstruido que retiene condensado durante la operación y lo libera al cesar el funcionamiento." },
  { id:"ns_0899", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de 0.9 en suministro y 0.2 en retorno. ¿Problema?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire hoy.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy."], respuesta_correcta:0, explicacion:"Presión estática de 0.9\" en suministro versus 0.2\" en retorno indica restricción predominante en el suministro. Conductos de suministro restringidos o difusores cerrados causan esta distribución asimétrica." },
  { id:"ns_0900", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre 20°F y 30°F hoy.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos hoy.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en modo calor no es aceptable (lo normal es 20-30F). Este diferencial bajo indica que la bomba de calor no transfiere suficiente calor, por falta de carga, flujo de aire excesivo o fallas en la absorcion exterior." },
  { id:"ns_0901", categoria:"NATE_SR_PACKAGE", pregunta:"Un ultra-congelador médico (-80°C) presenta una alarma de temperatura. El sistema es de cascada. ¿Cuál es la sospecha técnica Senior?", opciones:["Falla en el compresor de la etapa de baja o pérdida de carga de refrigerante especial.", "El ventilador del condensador de la etapa de alta está girando demasiado rápido.", "La junta de la puerta está permitiendo una infiltración mínima de humedad ambiente.", "El lubricante POE se ha solidificado debido a que el calentador de cárter falló."], respuesta_correcta:0, explicacion:"En un sistema de cascada, la etapa de baja temperatura es responsable de alcanzar los -80°C. Si hay alarma de temperatura, la causa más crítica es falla del compresor de la etapa baja o pérdida del refrigerante especial de baja temperatura, ya que sin este circuito es imposible mantener -80°C." },
  { id:"ns_0902", categoria:"NATE_SR_HVAC", pregunta:"Un sistema BMS reporta 'Token Loss' en una red MS/TP de BACnet. ¿Qué problema físico busca el Senior?", opciones:["Interferencia electromagnética o una resistencia de terminación (EOL) faltante.", "Falta de voltaje de 24V en el transformador que alimenta al controlador principal.", "Direccionamiento MAC duplicado en dos dispositivos de la misma sub-red de control.", "El cable de comunicación está aterrizado en ambos extremos causando un bucle."], respuesta_correcta:0, explicacion:"El 'Token Loss' en una red BACnet MS/TP indica problemas en la capa física de comunicación. La interferencia electromagnética corrompe las señales y una resistencia de terminación (EOL) faltante causa reflexiones en el cable que impiden la comunicación correcta del token." },
  { id:"ns_0903", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC busca reducir costos mediante 'Economía de Escala'. ¿Qué acción técnica la representa?", opciones:["Estandarizar una sola marca de equipo para toda la empresa y negociar precios por volumen.", "Contratar a más técnicos junior para reducir el costo promedio de la hora hombre.", "Eliminar el uso de software de despacho para evitar el pago de licencias mensuales.", "Diversificar los servicios ofreciendo plomería y pintura además de aire acondicionado."], respuesta_correcta:0, explicacion:"La economía de escala en HVAC se logra estandarizando una sola marca de equipo y negociando precios por volumen, reduciendo el costo unitario de materiales significativamente." },
  { id:"ns_0904", categoria:"NATE_SR_PACKAGE", pregunta:"Se encuentra 'Cera' (Waxing) en el dispositivo de expansión de un sistema de baja temperatura con R-22. ¿Causa?", opciones:["Uso de aceite mineral con un punto de flóculo demasiado alto para la aplicación.", "Reacción química entre el refrigerante y la humedad residual en el sistema.", "Descomposición del barniz del motor del compresor debido a una quemadura previa.", "El aceite POE absorbió humedad y se convirtió en un polímero sólido pegajoso."], respuesta_correcta:0, explicacion:"El waxing ocurre cuando el aceite mineral alcanza su punto de flóculo (cloud point) a bajas temperaturas, separándose y formando cera que obstruye el dispositivo de expansión. En aplicaciones de baja temperatura con R-22, se necesita aceite mineral con punto de flóculo muy bajo o cambiar a aceite alquilbenceno." },
  { id:"ns_0905", categoria:"NATE_SR_HVAC", pregunta:"Al realizar una prueba de combustión en un horno de alta eficiencia, se detecta un CO de 400 PPM. ¿Decisión Senior?", opciones:["Apagar el equipo inmediatamente; es una condición peligrosa de combustión incompleta.", "Ajustar la presión de gas en el manifold y volver a medir tras 10 minutos de operación.", "Indicar al cliente que el valor es aceptable mientras no haya olor a gas en la casa.", "Limpiar los quemadores con aire comprimido y asumir que el valor bajará solo."], respuesta_correcta:0, explicacion:"Un nivel de CO de 400 PPM indica combustión incompleta severa, lo cual es una condición peligrosa que puede causar intoxicación por monóxido de carbono. El protocolo Senior es apagar el equipo inmediatamente para proteger la seguridad de los ocupantes." },
  { id:"ns_0906", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor en modo refrigeración tiene una descarga de 400 PSI y succión de 150 PSI. El subenfriamiento es 2°F. ¿Estado?", opciones:["Sobrecarga de refrigerante que está inundando el serpentín del evaporador.", "Falta de refrigerante líquido o una válvula de expansión (TXV) fallida.", "Falla del ventilador del condensador que eleva la presión de alta innecesariamente.", "Operación normal considerando una carga térmica extremadamente alta en el interior."], respuesta_correcta:0, explicacion:"Descarga de 400 PSI, succion de 150 PSI y subenfriamiento de solo 2F indica exceso de refrigerante. El evaporador esta inundado de liquido, la succion esta alta por retorno de liquido, y el poco subenfriamiento confirma sobrecarga." },
  { id:"ns_0907", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior observa que su equipo usa 'Lijar' en lugar de un cortador de tubo para quitar rebabas. ¿Riesgo?", opciones:["Introducción de partículas metálicas al sistema que dañarán las válvulas y el compresor.", "Que la tubería no asiente correctamente en la conexión flare causando una fuga.", "Pérdida de la certificación de la tubería de cobre para uso en alta presión.", "Reducción del diámetro interno del tubo que afectará el flujo de refrigerante."], respuesta_correcta:0, explicacion:"Lijar genera partículas metálicas finas de cobre que pueden entrar al sistema refrigerante. Estas partículas dañan las válvulas de expansión, obstruyen filtros y causan desgaste en las partes móviles del compresor. Se debe usar un desbarbador (reamer) adecuado." },
  { id:"ns_0908", categoria:"NATE_SR_CHILLERS", pregunta:"En un chiller enfriado por agua, el 'Approach' del condensador es de 0°F. ¿Qué sospecha el Senior?", opciones:["Sensores de temperatura descalibrados o un error en el transductor de presión.", "El sistema está operando con una eficiencia de transferencia de calor perfecta.", "El flujo de agua de la torre es tan alto que los sensores no logran estabilizarse.", "Existe aire atrapado en la parte superior del condensador bloqueando el sensor."], respuesta_correcta:0, explicacion:"Un approach de condensador de 0°F es físicamente imposible bajo condiciones normales de operación. Indica un error de calibración en los sensores de temperatura o el transductor de presión." },
  { id:"ns_0909", categoria:"NATE_SR_PACKAGE", pregunta:"Una unidad paquete industrial muestra un error de 'Internal Overload' en el compresor 1, pero el amperaje es normal. ¿Causa?", opciones:["El protector térmico está fallando mecánicamente o hay un punto caliente en el borne.", "La carga de refrigerante es ligeramente baja y no enfría el motor lo suficiente.", "El compresor está operando con un voltaje de 208V en un sistema de 240V.", "La viscosidad del aceite es demasiado baja causando fricción interna invisible."], respuesta_correcta:0, explicacion:"Si el amperaje es normal pero el protector térmico interno se dispara, el problema no es eléctrico sino del protector mismo. Un protector térmico defectuoso puede disparar prematuramente, o puede haber un punto caliente en la conexión del borne (resistencia alta localizada) que genera calor excesivo en ese punto sin afectar el amperaje total." },
  { id:"ns_0910", categoria:"NATE_SR_CEO", pregunta:"Un CEO debe asegurar que su empresa cumple con la 'Sección 608' de la Clean Air Act. ¿Cuál es el registro más crítico?", opciones:["El registro de recuperación y disposición de refrigerante por cada unidad de servicio.", "La certificación NATE de cada técnico que realiza instalaciones residenciales.", "El historial de mantenimiento preventivo de la flota de vehículos de la empresa.", "Las facturas de compra de nitrógeno y otros gases no inflamables usados en obra."], respuesta_correcta:0, explicacion:"La Sección 608 de la Clean Air Act exige registros detallados de recuperación y disposición de refrigerante por cada unidad; su ausencia es la falta más grave ante una auditoría." },
  { id:"ns_0911", categoria:"NATE_SR_HVAC", pregunta:"Al enfriar aire a carga parcial, la Humedad Relativa (RH) en la habitación tiende a subir. ¿Cómo lo corrige el Senior?", opciones:["Reduciendo la velocidad del soplador para aumentar el tiempo de contacto en el serpentín.", "Aumentando la carga de refrigerante para bajar la presión de succión del sistema.", "Instalando un termostato que controle únicamente la temperatura de bulbo seco.", "Abriendo los dampers de aire exterior para introducir aire más seco del ambiente."], respuesta_correcta:0, explicacion:"A carga parcial, el serpentín enfría menos y su temperatura superficial sube por encima del punto de rocío, reduciendo la deshumidificación. Reducir la velocidad del soplador baja la temperatura del serpentín, aumentando el tiempo de contacto y mejorando la remoción de humedad." },
  { id:"ns_0912", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, se observa que el separador de aceite está muy caliente en la parte superior pero frío en la inferior. ¿Diagnóstico?", opciones:["El separador está inundado de refrigerante líquido o el flotador está trabado.", "El sistema de calefacción interna del aceite está operando a su máxima potencia.", "Falta de flujo de gas de descarga a través del componente por una obstrucción.", "Es una condición normal de estratificación térmica dentro del separador de aceite."], respuesta_correcta:0, explicacion:"La parte superior caliente indica entrada de gas de descarga, pero la parte inferior fría indica acumulación de refrigerante líquido o aceite frío atrapado. El flotador trabado impide el drenaje normal, causando inundación en la parte baja del separador." },
  { id:"ns_0913", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC quiere mejorar su 'Conversion Rate' de presupuestos. ¿Qué herramienta técnica ayuda más?", opciones:["Software de ventas con fotos del diagnóstico, opciones de eficiencia y financiamiento.", "Reducir el precio de los equipos un 10% por debajo del promedio del mercado local.", "Aumentar el periodo de garantía de la mano de obra a 10 años en todas las ventas.", "Contratar a vendedores externos que no tengan conocimientos técnicos de HVAC."], respuesta_correcta:0, explicacion:"Un software de ventas con fotos del diagnóstico, opciones de eficiencia y financiamiento facilita la decisión del cliente al hacer la propuesta visual, clara y financiable." },
  { id:"ns_0914", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter presenta el error 'Overcurrent Protection'. El compresor no arranca y solo zumba. ¿Qué prueba?", opciones:["Resistencia de las bobinas (U, V, W) y si alguna fase está aterrizada a tierra.", "El capacitor de arranque del compresor aunque se trate de un sistema inverter.", "El voltaje de la red AC de entrada que podría estar por debajo de los 180V.", "La comunicación entre la unidad interior y exterior mediante el cable de señal."], respuesta_correcta:0, explicacion:"Ante sobrecorriente con compresor que zumba sin arrancar, el Senior mide las bobinas U, V, W para detectar devanado abierto, cortocircuito entre fases o aterrizaje a tierra que impide el arranque." },
  { id:"ns_0915", categoria:"NATE_SR_CHILLERS", pregunta:"Un sistema de agua helada tiene un Delta T de 2°F (Diseño es 10°F). Las bombas están al 100%. ¿Acción Senior?", opciones:["Cerrar las válvulas de balanceo para reducir el flujo y aumentar el intercambio.", "Agregar más chillers al lazo para compensar la falta de enfriamiento del agua.", "Aumentar la velocidad de las bombas para forzar una mayor transferencia térmica.", "Cambiar el set-point del chiller a una temperatura más baja de forma inmediata."], respuesta_correcta:0, explicacion:"Un Delta T de 2°F (diseño 10°F) con bombas al 100% indica flujo excesivo. Cerrar válvulas de balanceo reduce el flujo, aumenta el Delta T y mejora la eficiencia del intercambio térmico." },
  { id:"ns_0916", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que 'ajustó' una TXV cerrándola 5 vueltas porque la succión era alta. ¿Crítica del Senior?", opciones:["La succión alta se diagnostica primero por carga térmica o eficiencia, no se ajusta la TXV.", "Debió cerrarla solo 2 vueltas y esperar 10 minutos para ver el cambio de presión.", "Las válvulas de expansión térmicas modernas no se pueden ajustar mecánicamente.", "Cerrar la válvula causará que el compresor se queme por falta de retorno de aceite."], respuesta_correcta:0, explicacion:"Una presión de succión alta puede tener múltiples causas: exceso de carga térmica, filtro de aire sucio, exceso de refrigerante, etc. Ajustar la TXV sin diagnosticar la causa raíz enmascara el problema real y puede crear nuevos síntomas." },
  { id:"ns_0917", categoria:"NATE_SR_CEO", pregunta:"Un CEO analiza el 'Break-Even Point'. Si los costos variables (materiales) suben, ¿qué debe pasar con el precio?", opciones:["El precio debe subir o el volumen de ventas debe incrementarse para mantener margen.", "El precio debe mantenerse igual para no perder competitividad en el mercado local.", "Los costos fijos (renta, seguros) deben reducirse para compensar el alza de materiales.", "Se debe eliminar el pago de horas extras para absorber el costo extra de las piezas."], respuesta_correcta:0, explicacion:"Si los costos variables suben, el precio de venta debe aumentar o el volumen de ventas debe crecer para mantener el margen de contribución y cubrir los costos fijos." },
  { id:"ns_0918", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Low Oil Temperature'. El calentador está encendido. ¿Qué revisa el Senior?", opciones:["El sensor de temperatura de aceite o una migración excesiva de refrigerante al cárter.", "La viscosidad del aceite que es demasiado baja para la temperatura de consigna.", "Si la bomba de aceite está operando en sentido inverso tras un fallo eléctrico.", "El flujo de agua helada que es demasiado alto y enfría indirectamente al motor."], respuesta_correcta:0, explicacion:"Con calentador encendido y baja temperatura de aceite, el sensor puede estar defectuoso o hay migración excesiva de refrigerante al cárter que absorbe calor y enfría el aceite por evaporación." },
  { id:"ns_0919", categoria:"NATE_SR_HVAC", pregunta:"Un motor de soplador PSC consume 8 amperios (Placa indica 6.5). El capacitor es nuevo. ¿Causa?", opciones:["Presión estática muy baja (ductos abiertos) o motor con devanados parcialmente en corto.", "Filtros de aire extremadamente sucios que obligan al motor a trabajar con más carga.", "Uso de un capacitor de menor capacidad (MFD) al especificado por el fabricante.", "El voltaje de alimentación es de 240V cuando el motor es de diseño para 208V."], respuesta_correcta:0, explicacion:"Un motor PSC que consume más amperaje del nominal con capacitor nuevo indica baja impedancia mecánica o eléctrica. Presión estática muy baja (sin restricción) permite que el motor gire libremente a alta carga, o un devanado parcialmente en corto reduce la impedancia eléctrica." },
  { id:"ns_0920", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se utiliza una válvula 'Bypass' de gas caliente hacia el recibidor?", opciones:["Para mantener la presión del recibidor y asegurar el flujo de líquido hacia vitrinas en invierno.", "Para deshelar los evaporadores de baja temperatura de forma rápida y eficiente.", "Para enfriar el aceite antes de que entre al separador de aceite centrífugo hoy.", "Para reducir el consumo eléctrico de los compresores de la etapa de alta presión."], respuesta_correcta:0, explicacion:"En invierno, la presión del recibidor puede bajar demasiado por la condensación eficiente en clima frío. La válvula bypass de gas caliente inyecta gas de descarga al recibidor para mantener la presión necesaria y asegurar el flujo de líquido hacia las vitrinas." },
  { id:"ns_0921", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Surge' a carga completa. ¿Qué factor Senior revisa?", opciones:["Incondensables en el sistema, condensador sucio o falta de carga de refrigerante.", "Los álabes de entrada (vanes) que están demasiado abiertos para el flujo de gas.", "El variador de frecuencia que está operando a una frecuencia demasiado baja hoy.", "La temperatura del agua helada de salida que es superior al set-point de diseño."], respuesta_correcta:0, explicacion:"Surge a carga completa indica que el compresor no puede mantener la elevación de presión requerida. Causas: incondensables que elevan la descarga, condensador sucio, o falta de refrigerante." },
  { id:"ns_0922", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere implementar un programa de 'Referidos'. ¿Qué métrica define el éxito real?", opciones:["Costo de Adquisición de Cliente (CAC) del referido comparado con el CAC de marketing pagado.", "Número total de clientes que mencionaron la promoción en sus redes sociales personales.", "El monto total de los descuentos otorgados a los clientes que refirieron a otros hoy.", "La cantidad de técnicos que lograron vender un sistema nuevo gracias a un referido."], respuesta_correcta:0, explicacion:"El éxito real de un programa de referidos se mide comparando el CAC del cliente referido vs. el CAC de marketing pagado; los referidos deben ser significativamente más baratos." },
  { id:"ns_0923", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no enfría. Al medir voltaje entre S2 y S3 el multímetro marca 0V fijos. ¿Causa?", opciones:["Falla total en la placa electrónica (interior o exterior) que genera la señal.", "Es el voltaje normal de operación cuando el sistema está en modo de espera hoy.", "El cable de comunicación S3 está desconectado en alguno de los dos extremos.", "El compresor está operando a su frecuencia mínima y no requiere señal de control."], respuesta_correcta:0, explicacion:"Un voltaje de 0V fijos entre S2 y S3 indica que ninguna placa genera la señal de comunicación. Puede ser falla total de la placa electrónica (interior o exterior) que produce la señal pulsante." },
  { id:"ns_0924", categoria:"NATE_SR_HEATPUMP", pregunta:"En modo calefacción, una bomba de calor tiene un sobrecalentamiento de 40°F. ¿Qué indica?", opciones:["Falta de refrigerante o una restricción en el dispositivo de expansión exterior.", "Exceso de carga de refrigerante que está inundando la unidad interior hoy.", "Operación óptima para un sistema que trabaja con temperaturas exteriores bajo cero.", "La válvula inversora está permitiendo un bypass de gas caliente hacia la succión."], respuesta_correcta:0, explicacion:"Un sobrecalentamiento de 40F es excesivamente alto (lo normal es 8-15F). Indica que el refrigerante se evapora demasiado pronto en el serpentin exterior por falta de carga o restriccion en la TXV exterior." },
  { id:"ns_0925", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que 'completó' la carga de R-410A pesando el gas en estado gaseoso. ¿Qué hace el Senior?", opciones:["Recuperar el gas y recargar en estado líquido para asegurar la composición de la mezcla.", "Aceptar el trabajo si las presiones de succión y descarga se ven normales hoy.", "Pedir al técnico que añada 1 libra extra de líquido para compensar el error previo.", "Indicar que el R-410A es una mezcla azeotrópica y no importa el estado de carga."], respuesta_correcta:0, explicacion:"El R-410A es una mezcla casi-azeotrópica que debe cargarse en estado líquido para mantener la proporción correcta de sus componentes (R-32 y R-125). Cargar en gas causa fraccionamiento que altera las presiones y el rendimiento del sistema." },
  { id:"ns_0926", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿cuál es el síntoma de una válvula reguladora de presión de cárter (CPR) ajustada muy baja?", opciones:["Baja capacidad de enfriamiento tras un deshielo al restringir demasiado el retorno de gas.", "Sobrecalentamiento excesivo del motor del compresor durante la operación normal hoy.", "Disparo frecuente del interruptor de alta presión debido al exceso de masa gaseosa.", "Paso de refrigerante líquido al cárter del compresor por falta de restricción."], respuesta_correcta:0, explicacion:"Una CPR ajustada muy baja restringe excesivamente el flujo de gas hacia el compresor tras un deshielo, cuando la carga térmica es alta. Esto limita la cantidad de gas que el compresor puede succionar, reduciendo la capacidad de enfriamiento del sistema." },
  { id:"ns_0927", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un approach de evaporador de 8°F (Nominal 2°F). El flujo de agua es correcto. ¿Acción?", opciones:["Limpieza mecánica de tubos del evaporador y verificar el tratamiento de agua helada.", "Agregar refrigerante líquido hasta que el approach baje a los 2 grados ideales.", "Reducir la velocidad de la bomba de agua helada para aumentar el tiempo de intercambio.", "Cambiar los sensores de temperatura asumiendo que están descalibrados por el tiempo."], respuesta_correcta:0, explicacion:"Approach de evaporador de 8°F vs. nominal 2°F con flujo correcto indica fouling en los tubos. La limpieza mecánica y verificar el tratamiento de agua restauran la eficiencia térmica." },
  { id:"ns_0928", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 125 PSI y descarga de 450 PSI con R-410A. El subenfriamiento es 22°F. ¿Estado?", opciones:["Restricción en el lado de alta (filtro o TXV) o condensador extremadamente sucio.", "Sistema sobrecargado de refrigerante que está inundando el serpentín exterior hoy.", "Funcionamiento normal para un día con carga térmica alta y temperatura de 105°F.", "Compresor con eficiencia reducida que no logra crear el diferencial de presión."], respuesta_correcta:0, explicacion:"Succión de 125 PSI con descarga muy alta de 450 PSI y subenfriamiento elevado de 22°F indica acumulación de líquido en el lado de alta. Una restricción en el filtro deshidratador o TXV, o un condensador sucio, impide el flujo normal elevando la descarga y el subenfriamiento." },
  { id:"ns_0929", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que el 'Revenue per Employee' es bajo. ¿Qué auditoría técnica realiza?", opciones:["Uso de tiempo no facturable, retrabajos (callbacks) y precisión en el despacho.", "El costo promedio de las piezas de repuesto que se compran mensualmente hoy.", "La cantidad de anuncios que se publican en las plataformas de redes sociales.", "Si los técnicos están usando herramientas de marca premium o genéricas hoy."], respuesta_correcta:0, explicacion:"El tiempo no facturable, los retrabajos (callbacks) y la precisión del despacho son los factores operativos que más impactan el Revenue per Employee en una empresa HVAC." },
  { id:"ns_0930", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua por la unidad interior. El drenaje está libre. ¿Causa Senior?", opciones:["Falta de refrigerante que causa escarcha parcial y goteo fuera de la bandeja de drenaje.", "El ventilador interior está girando tan rápido que succiona el agua del serpentín.", "La bomba de condensados integrada ha fallado mecánicamente y no evacúa nada.", "Humedad relativa en la habitación superior al 95% que satura el serpentín hoy."], respuesta_correcta:0, explicacion:"Con drenaje libre, la escarcha parcial causada por falta de refrigerante crea goteo irregular fuera de la bandeja de condensado al derretirse, ya que la formación de hielo no es uniforme en el serpentín." },
  { id:"ns_0931", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿cuál es el propósito de la 'Check Valve' en paralelo con la TXV interior?", opciones:["Permitir el flujo libre de refrigerante en modo calefacción sin restricción de la TXV.", "Asegurar que el aceite regrese al compresor únicamente durante el modo frío hoy.", "Proteger a la válvula de expansión de las presiones altas del modo calefacción.", "Regular la presión de succión del sistema para evitar la congelación del serpentín."], respuesta_correcta:0, explicacion:"La check valve en paralelo con la TXV interior permite que el refrigerante fluya libremente en modo calefaccion sin restriccion de la TXV interior. En calefaccion, la expansion ocurre en la TXV exterior, no en la interior." },
  { id:"ns_0932", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Junior quiere usar sellador de fugas en un VRF. El Senior se lo prohíbe por:", opciones:["Riesgo de obstrucción de las micro-válvulas EEV y daño al aceite POE.", "El sellador es inflamable y pone en riesgo la seguridad de la instalación hoy.", "La EPA prohíbe el uso de selladores en sistemas con más de 20 libras de gas.", "El costo del sellador es superior al costo de encontrar y reparar la fuga hoy."], respuesta_correcta:0, explicacion:"Los sistemas VRF usan válvulas de expansión electrónicas (EEV) con orificios muy pequeños que el sellador puede obstruir. Además, el sellador puede contaminar el aceite POE y afectar la lubricación del compresor, causando fallas costosas." },
  { id:"ns_0933", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una caída de presión de agua baja en el evaporador. ¿Cómo afecta la capacidad?", opciones:["La capacidad disminuye debido a la baja transferencia térmica por falta de flujo.", "La capacidad aumenta ya que el refrigerante tiene más tiempo para enfriar el agua.", "No afecta la capacidad, pero el compresor consumirá más energía eléctrica hoy.", "El chiller entrará en modo de ahorro de energía automáticamente por control hoy."], respuesta_correcta:0, explicacion:"Baja caída de presión de agua indica bajo flujo por el evaporador. Con menos flujo, la transferencia de calor se reduce y la capacidad de enfriamiento del chiller disminuye proporcionalmente." },
  { id:"ns_0934", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene un Delta T de 25°F y succión baja. El Senior sospecha de:", opciones:["Bajo flujo de aire (filtros sucios o motor soplador fallando).", "Exceso de carga de refrigerante que está inundando el serpentín interior hoy.", "Falla de la válvula de expansión térmica que está abierta al 100% de flujo.", "Presión estática del sistema extremadamente baja debido a conductos abiertos."], respuesta_correcta:0, explicacion:"Un Delta T alto de 25°F con succión baja indica que poco aire pasa por el evaporador. Filtros sucios o un motor de soplador fallando reducen el CFM, lo que enfría más el poco aire que pasa (Delta T alto) pero reduce la absorción total de calor (succión baja)." },
  { id:"ns_0935", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir la rotación de personal técnico. ¿Qué beneficio no monetario es más valorado?", opciones:["Equilibrio vida-trabajo (horarios predecibles y guardias justas).", "Tener camionetas nuevas con logotipos profesionales y GPS de última generación.", "Recibir uniformes de marca premium con bordados personalizados cada temporada.", "Organizar eventos sociales mensuales con asistencia obligatoria para el equipo."], respuesta_correcta:0, explicacion:"El equilibrio vida-trabajo con horarios predecibles y guardias justas es el beneficio no monetario más valorado por los técnicos, superando a los beneficios materiales." },
  { id:"ns_0936", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué sucede si la válvula de retención del condensador falla abierta?", opciones:["Migración masiva de refrigerante al condensador durante el paro en clima frío.", "Aumento en la presión de succión de todos los compresores conectados al rack.", "El aceite se quedará atrapado en el condensador y no regresará al rack paralelo.", "El sistema entrará en modo de ahorro de energía al reducir la carga del motor."], respuesta_correcta:0, explicacion:"Sin la válvula check del condensador, el refrigerante líquido migra masivamente hacia el condensador frío durante los periodos de paro en clima frío. Esto vacía el recibidor y al arrancar no habrá suficiente líquido para alimentar las vitrinas." },
  { id:"ns_0937", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Surge' a carga parcial. ¿Cómo se ajusta operativamente?", opciones:["Bajando la presión de descarga o aumentando el flujo de gas por el impulsor.", "Cerrando la válvula de expansión para reducir la masa de refrigerante total.", "Incrementando la velocidad de la bomba de agua helada del edificio central hoy.", "Aumentando la temperatura del agua de la torre para subir la descarga hoy."], respuesta_correcta:0, explicacion:"El surge a carga parcial se corrige reduciendo la relación de presiones: bajando la presión de descarga o aumentando el flujo de gas por el impulsor mediante vanes o VFD." },
  { id:"ns_0938", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 145 PSI y descarga de 380 PSI con R-410A. Sobrecalentamiento 0°F. ¿Causa?", opciones:["Válvula de expansión (TXV) fallida en la posición de abierta total.", "Falta de refrigerante líquido que impide que la descarga suba a niveles 450.", "Evaporador interior con flujo de aire extremadamente alto por un motor ECM.", "Compresor perdiendo eficiencia volumétrica por desgaste interno de pistones."], respuesta_correcta:0, explicacion:"Succión alta de 145 PSI con sobrecalentamiento de 0°F indica inundación del evaporador con líquido refrigerante. Una TXV abierta totalmente permite paso descontrolado de refrigerante, saturando el evaporador y enviando líquido de vuelta al compresor." },
  { id:"ns_0939", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere aumentar el 'Customer Lifetime Value'. ¿Qué estrategia lanza?", opciones:["Contratos de mantenimiento preventivo con beneficios exclusivos y descuentos.", "Aumentar los precios de instalación para maximizar la ganancia del primer día.", "Eliminar el departamento de servicio para enfocarse solo en ventas de equipos.", "Reducir la garantía de mano de obra a 30 días para evitar gastos futuros hoy."], respuesta_correcta:0, explicacion:"Los contratos de mantenimiento preventivo con beneficios exclusivos y descuentos retienen clientes por años, maximizando el Customer Lifetime Value de forma sostenible." },
  { id:"ns_0940", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿qué sucede si la válvula de retención de un compresor falla abierta?", opciones:["El refrigerante migrará al compresor parado, causando arranques inundados.", "La presión de succión aumentará en todo el sistema del rack de refrigeración.", "El aceite se quedará atrapado en el condensador y no regresará al rack hoy.", "El compresor consumirá el doble de amperaje al intentar arrancar con carga."], respuesta_correcta:0, explicacion:"Sin la válvula check de descarga, el gas de alta presión del cabezal y el refrigerante del condensador migran al compresor apagado. Al reiniciar, el compresor intenta comprimir el líquido acumulado, causando un golpe de líquido potencialmente destructivo." },
  { id:"ns_0941", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Unbalance' del 4%. ¿Qué riesgo técnico existe?", opciones:["Sobrecalentamiento excesivo del motor del compresor y fallo prematuro.", "El chiller funcionará al 96% de su capacidad nominal sin riesgo alguno hoy.", "La unidad de purga empezará a operar para compensar el desequilibrio eléctrico.", "La válvula de expansión se cerrará para proteger el circuito de refrigerante."], respuesta_correcta:0, explicacion:"Un desbalance de fase del 4% puede causar incrementos de corriente de hasta 25% en un devanado del motor, generando calor excesivo que acorta drásticamente la vida del aislamiento." },
  { id:"ns_0942", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no enfría. El compresor exterior no arranca pero el ventilador sí. ¿Prueba?", opciones:["Medir resistencia de las bobinas del compresor y voltaje DC de la placa IPM.", "Cambiar el capacitor de arranque por uno de mayor capacidad inmediatamente hoy.", "Puentear el interruptor de alta presión para ver si el compresor enciende hoy.", "Agregar 2 libras de refrigerante R-410A para descartar una fuga total de gas."], respuesta_correcta:0, explicacion:"Con el ventilador exterior funcionando pero compresor sin arrancar, el Senior mide la resistencia de las bobinas del compresor y el voltaje DC del IPM para determinar si es falla mecánica o electrónica." },
  { id:"ns_0943", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una presión estática de retorno de 0.6 pulg. W.C. El diseño es 0.2. ¿Consecuencia?", opciones:["Ruido excesivo, bajo flujo de aire y posible falla del motor del soplador.", "Aumento en la eficiencia del intercambio de calor por la velocidad del aire.", "Menor consumo eléctrico del motor al tener una restricción en la succión hoy.", "Mejora en la deshumidificación del ambiente al pasar el aire más lento hoy."], respuesta_correcta:0, explicacion:"Una presión estática de retorno de 0.6\" W.C. (tres veces el diseño de 0.2\") causa restricción severa del flujo de aire, ruido excesivo por turbulencia, y sobrecarga del motor del soplador que puede resultar en falla prematura del motor." },
  { id:"ns_0944", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Check Valve' de la unidad interior falla abierta?", opciones:["En modo refrigeración, el refrigerante hará bypass a la TXV y no enfriará.", "En modo calefacción, el sistema se bloqueará por alta presión de descarga.", "El aceite se quedará atrapado en el evaporador y el compresor fallará hoy.", "La válvula inversora no podrá cambiar de posición por falta de diferencial."], respuesta_correcta:0, explicacion:"La check valve interior permite bypass en modo calefaccion. Si falla abierta (stuck open), en modo refrigeracion el refrigerante hace bypass a la TXV interior, eliminando la restriccion necesaria para enfriar." },
  { id:"ns_0945", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior observa que un Junior no usa 'Brazing Shield' al soldar. ¿Riesgo?", opciones:["Daño térmico a componentes sensibles como válvulas o aislamiento de cables.", "Que la soldadura de plata no se adhiera correctamente por falta de calor hoy.", "Aumento del consumo de oxígeno y acetileno durante el proceso de soldadura.", "La formación de óxido en la superficie externa de la tubería de cobre hoy."], respuesta_correcta:0, explicacion:"El brazing shield (escudo térmico) protege componentes adyacentes del calor intenso de la antorcha. Sin él, válvulas con sellos internos, aislamiento de cables y otros materiales sensibles pueden sufrir daño térmico irreversible." },
  { id:"ns_0946", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de 'Leaving Water' descalibrado (marca menos). ¿Riesgo?", opciones:["Congelación de los tubos del evaporador debido a un set-point real bajo.", "El compresor se apagará por alta presión antes de alcanzar la temperatura.", "La unidad de purga operará innecesariamente expulsando gas al ambiente hoy.", "Aumento en el consumo de energía eléctrica por ciclos de carga excesivos hoy."], respuesta_correcta:0, explicacion:"Un sensor de leaving water que marca menos de lo real hace que el controlador siga enfriando más allá del set-point verdadero, arriesgando congelación de los tubos del evaporador." },
  { id:"ns_0947", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué indica una temperatura de descarga de 250°F constante?", opciones:["Problema grave de sobrecalentamiento de succión o falla interna del compresor.", "Operación normal para un rack que usa R-404A en condiciones de carga alta.", "Que el enfriador de aceite del rack paralelo está funcionando perfectamente.", "Falta de refrigerante líquido en el recibidor que impide el enfriamiento hoy."], respuesta_correcta:0, explicacion:"Una descarga de 250°F constante con R-404A es anormalmente alta (normal: 150-200°F). Esto indica sobrecalentamiento severo de succión, posible falla de la válvula Quench, o daño en las válvulas internas del compresor que causan re-compresión." },
  { id:"ns_0948", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere aumentar el 'Referral Rate'. ¿Qué acción es la más efectiva?", opciones:["Ofrecer una recompensa o descuento tanto al que refiere como al nuevo cliente.", "Pagar por anuncios en el periódico local para que la gente conozca la marca.", "Reducir el precio de todos los servicios para que los clientes hablen bien.", "Contratar a un vendedor de puerta en puerta para buscar clientes referidos."], respuesta_correcta:0, explicacion:"Un programa de referidos que recompensa a ambas partes (quien refiere y el nuevo cliente) crea un ciclo virtuoso de recomendaciones que reduce el costo de adquisición." },
  { id:"ns_0949", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta una vibración en la frecuencia de paso de álabes. ¿Causa?", opciones:["Alineación incorrecta del impulsor o flujo de gas turbulento en la entrada.", "Desgaste natural de los cojinetes de rodillos del motor de alta velocidad.", "Falta de aceite en el sistema de lubricación por inyección del compresor hoy.", "El variador de frecuencia está generando armónicos que afectan al motor hoy."], respuesta_correcta:0, explicacion:"La vibración a la frecuencia de paso de álabes (BPF) se relaciona con problemas de alineación del impulsor o flujo de gas turbulento en la entrada que genera pulsaciones rítmicas." },
  { id:"ns_0950", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 420 PSI. El aire sale a 65°F. ¿Problema?", opciones:["Bajo flujo de aire o carga de refrigerante ligeramente baja.", "Funcionamiento normal considerando la temperatura exterior de 100 grados hoy.", "Exceso de carga de refrigerante que inunda el serpentín del condensador hoy.", "Compresor con válvulas dañadas que no logran enfriar el aire correctamente."], respuesta_correcta:0, explicacion:"Temperatura de suministro de 65°F (debería ser ~55°F) con descarga elevada de 420 PSI indica que el evaporador no transfiere calor eficientemente. Bajo flujo de aire por filtros sucios o falta leve de refrigerante son las causas más probables." },
  { id:"ns_0951", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir la 'Liquidez Inmediata'. ¿Qué métrica utiliza?", opciones:["Cash Ratio (Efectivo y equivalentes dividido por pasivos corrientes).", "Gross Profit Margin (Margen bruto sobre ventas totales del periodo actual).", "Return on Investment (Retorno sobre la inversión de las nuevas camionetas).", "Debt-to-Equity Ratio (Relación entre deuda total y capital de los socios)."], respuesta_correcta:0, explicacion:"El Cash Ratio (efectivo y equivalentes / pasivos corrientes) mide la capacidad inmediata de pagar deudas solo con el efectivo disponible, siendo la métrica de liquidez más estricta." },
  { id:"ns_0952", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un sensor de flujo tipo 'Diferencial de Presión'. El valor es 0 PSI con bomba ON. ¿Causa?", opciones:["Líneas de impulsión del sensor tapadas o bomba girando en sentido inverso.", "Carga de refrigerante insuficiente que impide la presión en el evaporador.", "El variador de frecuencia de la bomba está operando a su frecuencia mínima.", "Existe aire atrapado en la carcasa del compresor centrífugo del sistema hoy."], respuesta_correcta:0, explicacion:"Con la bomba encendida y diferencial de 0 PSI, las líneas de impulsión del sensor están tapadas (no leen presión) o la bomba gira en sentido inverso (no genera diferencial de presión)." },
  { id:"ns_0953", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un equipo donde se instaló un compresor de 2 HP en lugar de 2.5 HP. ¿Efecto?", opciones:["El compresor operará con sobrecarga constante y fallará prematuramente.", "El sistema será más eficiente al reducir el consumo eléctrico total hoy.", "La válvula de expansión compensará la diferencia de capacidad sin problemas.", "El evaporador se congelará debido a que el compresor succiona menos gas."], respuesta_correcta:0, explicacion:"Un compresor subdimensionado debe trabajar más tiempo y más duro para intentar satisfacer la demanda de enfriamiento, operando en sobrecarga constante. Esto eleva el amperaje, sobrecalienta el motor y reduce drásticamente su vida útil." },
  { id:"ns_0954", categoria:"NATE_SR_RACK", pregunta:"En un rack paralelo, ¿cuál es la función de la válvula reguladora de presión de evaporación (EPR)?", opciones:["Mantener una presión mínima en el evaporador para controlar la temperatura de la vitrina.", "Evitar que el refrigerante líquido regrese al cabezal de succión del rack paralelo hoy.", "Aumentar la presión de descarga de los compresores de la etapa de baja presión hoy.", "Regular el flujo de aceite desde el separador hacia los cárteres de los motores hoy."], respuesta_correcta:0, explicacion:"La EPR se instala en la línea de succión de cada evaporador para mantener una presión mínima constante, independientemente de la presión de succión del rack. Esto controla la temperatura del evaporador y evita que el producto se congele en vitrinas de media temperatura." },
  { id:"ns_0955", categoria:"NATE_SR_CEO", pregunta:"Un CEO HVAC quiere reducir el 'Average Response Time'. ¿Qué medida toma?", opciones:["Implementar software de despacho inteligente y zonificación de técnicos hoy.", "Aumentar el número de técnicos en la nómina aunque no haya llamadas hoy.", "Reducir el tiempo de almuerzo de los técnicos para que estén más disponibles.", "Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy."], respuesta_correcta:0, explicacion:"El software de despacho inteligente con zonificación geográfica es la solución más efectiva para reducir el Average Response Time de manera sistemática." },
  { id:"ns_0956", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC fijos. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería fluctuar entre 0 y 24VDC hoy hoy.", "La placa exterior está operando correctamente enviando la señal de control hoy.", "El compresor inverter está aterrizado y consume el voltaje de comunicación.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior hoy."], respuesta_correcta:0, explicacion:"La señal de comunicación S2-S3 debe ser DC pulsante (0-24V). Un voltaje fijo de 24VDC indica que no hay modulación de datos entre las unidades, confirmando una falla de comunicación." },
  { id:"ns_0957", categoria:"NATE_SR_HEATPUMP", pregunta:"En una bomba de calor, ¿qué sucede si el 'Defrost Sensor' falla en circuito abierto?", opciones:["El sistema nunca entrará en modo de deshielo y el serpentín se congelará.", "El sistema entrará en modo de deshielo cada 30 minutos sin importar el hielo.", "El compresor se quemará debido a la falta de control de sobrecalentamiento hoy.", "La unidad operará solo en modo refrigeración permanentemente por seguridad hoy."], respuesta_correcta:0, explicacion:"Con el defrost sensor en circuito abierto, la placa no recibe lectura de temperatura del serpentin exterior. Sin cumplir la condicion de temperatura baja, el ciclo de deshielo nunca se activa y el hielo se acumula." },
  { id:"ns_0958", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior revisa un sistema VRF. ¿Por qué es vital pesar la carga?", opciones:["Los sistemas VRF son de carga crítica y las presiones no son indicadores.", "Es un requisito legal de la EPA para sistemas con más de 50 libras de gas.", "Para asegurar que el aceite POE regrese correctamente a los compresores hoy.", "Para evitar que la garantía del fabricante se anule tras la instalación hoy."], respuesta_correcta:0, explicacion:"Los sistemas VRF operan con compresores inverter que modulan velocidad continuamente, causando fluctuaciones normales de presión. Por ello, el método de presiones es inútil y se debe pesar la carga según las especificaciones del fabricante." },
  { id:"ns_0959", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una falla de 'Phase Reversal'. ¿Qué sucede si se ignora el error?", opciones:["El compresor girará al revés y no bombeará aceite ni refrigerante líquido.", "La unidad funcionará al 50% de su capacidad nominal debido al desfase fase.", "El motor se quemará instantáneamente al intentar vencer la inercia carga hoy.", "Las válvulas de expansión se cerrarán por seguridad al detectar el error hoy."], respuesta_correcta:0, explicacion:"La inversión de fases causa rotación inversa del compresor centrífugo, impidiendo la circulación de aceite y refrigerante, lo que resulta en daño mecánico por falta de lubricación." },
  { id:"ns_0960", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 110 PSI y descarga de 350 PSI. Subenfriamiento 0°F. ¿Causa?", opciones:["Falta de refrigerante líquido severa en el sistema (Undercharged) hoy hoy.", "Válvula de expansión (TXV) fallida en la posición de abierta total hoy hoy.", "Condensador exterior extremadamente sucio que no permite el intercambio térmico.", "Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."], respuesta_correcta:0, explicacion:"Subenfriamiento de 0°F confirma falta severa de refrigerante. Sin suficiente masa de refrigerante, el condensador entrega mezcla bifásica en lugar de líquido subenfriado, afectando todo el rendimiento del ciclo de refrigeración." },
  { id:"ns_0961", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico vende piezas usadas como nuevas. ¿Acción?", opciones:["Despido inmediato y política de cero tolerancia para proteger la reputación.", "Advertencia verbal indicando que debe informar al cliente si la pieza es usada.", "Ignorar si el cliente no se queja y el equipo funciona correctamente hoy hoy.", "Pedirle que compense la diferencia de precio al cliente en la próxima visita."], respuesta_correcta:0, explicacion:"Vender piezas usadas como nuevas es fraude al cliente; la política de cero tolerancia con despido inmediato protege la reputación y la integridad del negocio." },
  { id:"ns_0962", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Oil Loss' excesivo. El eductor está limpio. ¿Qué revisa?", opciones:["Operación constante a carga muy baja que impide el arrastre de aceite.", "Si el compresor está girando a más RPM de las indicadas por el variador hoy.", "La temperatura del evaporador que es demasiado alta para separar el aceite.", "Si la unidad de purga está extrayendo aceite junto con los incondensables hoy."], respuesta_correcta:0, explicacion:"La operación constante a carga muy baja reduce el arrastre de aceite por el gas de succión. El aceite se acumula en el evaporador y no retorna al compresor, causando pérdida progresiva." },
  { id:"ns_0963", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera una auditoría de seguridad. ¿Qué falta en una escalera es 'roja'?", opciones:["Fisuras visibles en los rieles laterales o peldaños con grasa/aceite.", "Que la escalera sea de fibra de vidrio en lugar de aluminio ligero hoy.", "La falta de la etiqueta con el nombre del técnico dueño de la herramienta.", "Que el ángulo de inclinación sea de 70 grados en lugar de los 75 nominales."], respuesta_correcta:0, explicacion:"Fisuras en los rieles comprometen la integridad estructural de la escalera, y grasa o aceite en los peldaños causa resbalones. Ambas son condiciones de 'bandera roja' que requieren retirar la escalera del servicio inmediatamente por riesgo de caída." },
  { id:"ns_0964", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué indica una presión de aceite que fluctúa con la presión de succión?", opciones:["Falla en la válvula diferencial de aceite o bomba de aceite desgastada.", "Operación normal ya que la bomba depende de la presión de base del sistema.", "Que el separador de aceite está retornando gas caliente al cárter del motor.", "Presencia de aire en las líneas de lubricación que causa cavitación hoy."], respuesta_correcta:0, explicacion:"La presión neta de aceite debe ser independiente de la presión de succión (diferencial constante). Si fluctúa con la succión, la válvula diferencial no está regulando correctamente, o la bomba de aceite está desgastada y no mantiene el diferencial." },
  { id:"ns_0965", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir el 'Technician ROI'. ¿Qué datos combina?", opciones:["Ingresos generados y callbacks versus el costo total de compensación (Burden).", "Número de clientes nuevos atraídos versus el costo de marketing del mes hoy.", "Horas trabajadas versus millas recorridas por la camioneta asignada hoy hoy.", "La calificación de Google Reviews versus el número de uniformes comprados."], respuesta_correcta:0, explicacion:"El Technician ROI combina los ingresos generados y los callbacks (calidad) versus el costo total de compensación (Burden), dando una visión completa del retorno por técnico." },
  { id:"ns_0966", categoria:"NATE_SR_HVAC", pregunta:"Un sistema comercial con dampers multizona tiene una zona siempre caliente. ¿Qué revisa?", opciones:["El actuador del damper de esa zona y la señal de 24V/0-10V del termostato.", "La carga de refrigerante del chiller principal que alimenta a la manejadora.", "Si el motor del soplador está girando a la velocidad máxima permitida hoy.", "La presión estática del conducto de retorno general del sistema de aire hoy."], respuesta_correcta:0, explicacion:"En un sistema multizona, si una zona siempre está caliente, el problema más probable es que el damper de esa zona no está abriendo. Verificar el actuador del damper y la señal de control (24V o 0-10V) del termostato zonal es el paso diagnóstico correcto." },
  { id:"ns_0967", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene un approach de evaporador negativo. ¿Cómo lo interpreta el Senior?", opciones:["Error en la calibración de sensores de temperatura o presión de succión.", "Transferencia térmica perfecta que excede los límites teóricos de diseño.", "El flujo de agua es tan alto que no permite la estabilización térmica hoy.", "El sensor de temperatura de salida está tocando una superficie caliente hoy."], respuesta_correcta:0, explicacion:"Un approach de evaporador negativo viola las leyes de la termodinámica en condiciones normales. Siempre indica error de calibración en sensores de temperatura o presión del sistema." },
  { id:"ns_0968", categoria:"NATE_SR_MINISPLIT", pregunta:"Un VRF muestra error de 'Communication - Indoor Unit missing'. ¿Qué es lo primero?", opciones:["Verificar alimentación eléctrica de esa unidad y fusibles de su placa hoy.", "Cambiarlos cables de comunicación de todo el bus por cables blindados hoy.", "Resetear el direccionamiento de todas las unidades desde la exterior hoy.", "Reemplazar la placa electrónica de la unidad exterior asumiendo fallo hoy."], respuesta_correcta:0, explicacion:"Cuando una unidad interior 'desaparece' del bus de comunicación VRF, lo primero es verificar que tenga alimentación eléctrica y que los fusibles de su placa estén intactos antes de buscar problemas de comunicación." },
  { id:"ns_0969", categoria:"NATE_SR_MANAGEMENT", pregunta:"Al realizar un retrofit de R-22 a R-407C, el Senior exige cambiar el aceite. ¿Razón?", opciones:["El aceite mineral no retorna con HFC y causará falla de lubricación pronto.", "El R-407C descompone químicamente el aceite mineral en pocos días de uso.", "El aceite POE es necesario para aumentar la presión de descarga del sistema.", "Las válvulas de expansión térmicas solo funcionan con aceite de polioléster."], respuesta_correcta:0, explicacion:"Los refrigerantes HFC como el R-407C no son miscibles con aceite mineral. Sin miscibilidad, el aceite se queda atrapado en el evaporador y no retorna al compresor, causando falla de lubricación que destruye los cojinetes y las partes móviles." },
  { id:"ns_0970", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir el 'Callbacks Rate' al 1%. ¿Qué inversión es vital?", opciones:["Procesos de Control de Calidad (QC) post-instalación y entrenamiento técnico.", "Comprar herramientas de marca premium para todos los técnicos del equipo hoy.", "Aumentar el salario de los técnicos para que trabajen con más motivación hoy.", "Contratar a un supervisor que revise físicamente cada trabajo terminado hoy hoy."], respuesta_correcta:0, explicacion:"Reducir callbacks al 1% requiere procesos de Control de Calidad post-instalación y entrenamiento técnico continuo que aseguren que cada trabajo se haga correctamente la primera vez." },
  { id:"ns_0971", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller centrífugo presenta 'Pumping' (Surge). El Senior nota agua de torre a 45°F.", opciones:["El agua está demasiado fría; suba la temperatura para estabilizar presiones.", "El agua está perfecta; el problema es una falta severa de carga de gas hoy.", "La torre está enviando aire al condensador junto con el agua helada hoy.", "Los ventiladores de la torre están girando en sentido contrario al diseño hoy."], respuesta_correcta:0, explicacion:"Agua de torre a 45°F reduce excesivamente la presión de condensación. El bajo lift causa que el compresor centrífugo entre en surge. Se debe subir la temperatura del agua para estabilizar." },
  { id:"ns_0972", categoria:"NATE_SR_HVAC", pregunta:"Un motor de soplador ECM está 'haciendo hunting' (sube y baja RPM). ¿Causa?", opciones:["Alta presión estática o restricciones severas en el sistema de conductos.", "El termostato está enviando señales contradictorias de velocidad a la placa.", "El capacitor de marcha está fallando y no mantiene el torque del motor hoy.", "La humedad en el aire está afectando los sensores magnéticos internos hoy."], respuesta_correcta:0, explicacion:"Los motores ECM modulan la velocidad para mantener CFM constante. Ante alta presión estática, el motor sube RPM para compensar, pero al llegar a su límite oscila entre velocidades intentando alcanzar el flujo programado, causando el efecto de hunting." },
  { id:"ns_0973", categoria:"NATE_SR_CEO", pregunta:"Un CEO nota que el 'Direct Labor Cost' es del 45% de los ingresos. ¿Interpretación?", opciones:["Costo muy alto; indica ineficiencia operativa o precios de venta muy bajos.", "Porcentaje excelente que asegura rentabilidad neta superior al 25% hoy hoy.", "Indica que los técnicos venden muchos accesorios y planes de mantenimiento.", "Valor irrelevante si el margen bruto de materiales es superior al 60% hoy."], respuesta_correcta:0, explicacion:"Un Direct Labor Cost del 45% de los ingresos es excesivo para la industria HVAC; indica ineficiencia operativa, exceso de tiempo no facturable o precios de venta demasiado bajos." },
  { id:"ns_0974", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿qué indica una temperatura de succión muy fría (escarcha en cabezal)?", opciones:["Retorno de líquido que pone en riesgo la integridad de los compresores.", "Que el sistema está operando a su máxima eficiencia de enfriamiento hoy hoy.", "Falta de refrigerante en el recibidor que causa expansión prematura hoy.", "Que las válvulas EPR de todas las vitrinas están abiertas al 100% hoy hoy."], respuesta_correcta:0, explicacion:"Escarcha en el cabezal de succión es evidencia clara de retorno de refrigerante líquido. El líquido no evaporado enfría la tubería por debajo de 32°F, formando hielo. Esta condición puede causar golpe de líquido y daño catastrófico en los compresores." },
  { id:"ns_0975", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller con R-134a tiene succión de 35 PSI. ¿Cuál es el riesgo Senior?", opciones:["Congelación de los tubos del evaporador (Saturación bajo 32°F).", "Sobrecalentamiento del motor por falta de masa de refrigerante hoy hoy.", "Falla mecánica por falta de lubricación al no haber arrastre de aceite hoy.", "Aumento excesivo del consumo eléctrico al intentar comprimir gas ralo hoy."], respuesta_correcta:0, explicacion:"A 35 PSI de succión, el R-134a satura aproximadamente a 29°F, por debajo del punto de congelación del agua. Esto crea riesgo directo de congelar los tubos del evaporador." },
  { id:"ns_0976", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico reporta que terminó vacío en 10 min en sistema de 10 ton. ¿Acción?", opciones:["Repetir vacío; es imposible eliminar humedad profunda en ese tiempo hoy hoy.", "Felicitar al técnico por tener una bomba de vacío de 12 CFM nueva hoy hoy.", "Verificar el visor de líquido para confirmar si el sistema está seco hoy hoy.", "Permitir carga si el vacuómetro digital marca 450 micrones estables hoy."], respuesta_correcta:0, explicacion:"Un sistema de 10 toneladas tiene un volumen interno grande donde la humedad se adhiere a superficies y se disuelve en el aceite. Diez minutos de vacío son físicamente insuficientes para que toda esa humedad se evapore y sea evacuada." },
  { id:"ns_0977", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere medir 'Customer Churn'. ¿Qué métrica monitorea más hoy?", opciones:["Tasa de cancelación de contratos de mantenimiento vs renovaciones hoy hoy.", "Cantidad de llamadas de emergencia recibidas durante la temporada alta hoy.", "Número de me gusta y comentarios positivos en la página de Facebook hoy.", "El margen de utilidad de cada contrato de mantenimiento preventivo vendido."], respuesta_correcta:0, explicacion:"La tasa de cancelación de contratos de mantenimiento vs. renovaciones mide directamente el Customer Churn, mostrando cuántos clientes recurrentes se pierden en cada periodo." },
  { id:"ns_0978", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se instalan solenoides en línea de líquido de cada vitrina?", opciones:["Controlar temperatura mediante el corte del flujo de refrigerante hoy hoy.", "Evitar que el aceite se acumule en el evaporador durante la operación hoy.", "Aumentar el subenfriamiento del gas antes de entrar a la válvula TXV hoy.", "Proteger al compresor de un posible retorno de líquido en el arranque hoy."], respuesta_correcta:0, explicacion:"Las solenoides de líquido individuales permiten un control independiente de cada vitrina cortando el suministro de refrigerante cuando se alcanza la temperatura deseada. Esto implementa el control por pump-down y evita alimentación innecesaria." },
  { id:"ns_0979", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene una purga manual. El técnico purga pero presión no baja. ¿Causa?", opciones:["Aire atrapado y el gas expulsado es mezcla de aire y refrigerante hoy hoy.", "La purga está en el punto más bajo del condensador por error técnico hoy.", "El refrigerante es de tipo azeotrópico y no se separa de incondensables.", "La temperatura del agua de torre es demasiado alta para purgar aire hoy hoy."], respuesta_correcta:0, explicacion:"Al purgar, el aire atrapado se mezcla con refrigerante y sale como mezcla gaseosa. La presión no baja porque la presión parcial del aire restante sigue siendo significativa en el sistema." },
  { id:"ns_0980", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene una succión de 125 PSI y descarga de 450 PSI. ¿Estado?", opciones:["Sistema con exceso de carga de refrigerante (Overcharged) hoy hoy hoy hoy.", "Falta de refrigerante líquido que impide que descarga suba a 500 PSI hoy.", "Restricción en el dispositivo de expansión que eleva la presión de alta hoy.", "Compresor perdiendo eficiencia volumétrica por desgaste de los pistones hoy."], respuesta_correcta:0, explicacion:"Succión de 125 PSI con descarga alta de 450 PSI y subenfriamiento elevado indica exceso de refrigerante. El condensador está parcialmente inundado de líquido, reduciendo su área de condensación efectiva y elevando la presión de descarga." },
  { id:"ns_0981", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller de tornillo presenta 'Oil Foaming'. ¿Qué daño Senior previene?", opciones:["Falla de lubricación en rodamientos y posible cavitación de la bomba hoy hoy.", "Aumento en la presión de condensación por exceso de aceite en el sistema.", "Congelación de los tubos del evaporador al bajar la temperatura de ebullición.", "Desgaste prematuro de los álabes del compresor centrífugo por impacto hoy."], respuesta_correcta:0, explicacion:"La espuma de aceite (oil foaming) impide que la bomba de aceite suministre lubricante a los rodamientos y puede causar cavitación de la bomba, resultando en falla de lubricación." },
  { id:"ns_0982", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un técnico Senior observa que un ayudante soldó sin nitrógeno. ¿Consecuencia?", opciones:["Formación de hollín (soot) que tapará filtros y orificios de expansión hoy.", "Que la soldadura de plata no se adhiera al cobre por falta de oxígeno hoy.", "El cobre se volverá quebradizo y fallará mecánicamente por el calor hoy hoy.", "No hay consecuencia técnica si la tubería es de menos de 1/2 pulgada hoy hoy."], respuesta_correcta:0, explicacion:"Soldar sin purga de nitrógeno permite que el oxígeno atrapado reaccione con el cobre caliente, formando hollín (soot/escamas de óxido cúprico). Estas partículas circulan y obstruyen filtros deshidratadores y orificios de válvulas de expansión." },
  { id:"ns_0983", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere reducir 'Vehicle Downtime'. ¿Qué acción es la más efectiva hoy?", opciones:["Programa de mantenimiento preventivo riguroso y flota de reserva mínima.", "Obligar a los técnicos a reparar sus propias camionetas el fin de semana.", "Comprar solo vehículos usados para reducir el impacto financiero inicial hoy.", "Eliminar el uso de GPS para evitar que técnicos conduzcan distancias largas."], respuesta_correcta:0, explicacion:"Un mantenimiento preventivo riguroso de la flota combinado con vehículos de reserva mínima asegura disponibilidad continua y minimiza el Vehicle Downtime." },
  { id:"ns_0984", categoria:"NATE_SR_RACK", pregunta:"En un rack, ¿por qué se usa una válvula 'Quench' o inyección de líquido?", opciones:["Para enfriar gas de succión y evitar que descarga dañe el aceite hoy hoy hoy.", "Para aumentar la presión de succión cuando carga en vitrinas es baja hoy hoy.", "Para limpiar el interior de compresores de acumulaciones de carbonilla hoy.", "Para ayudar al retorno de aceite desde los evaporadores más lejanos hoy hoy."], respuesta_correcta:0, explicacion:"La válvula de inyección Quench es un control de seguridad que limita la temperatura de descarga. Al evaporar refrigerante líquido en la línea de succión o descarga, absorbe calor excesivo y mantiene el aceite dentro de su rango de estabilidad térmica." },
  { id:"ns_0985", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller presenta 'Flow Switch Alarm' con bomba ON. ¿Qué revisa el Senior?", opciones:["Paddle roto, aire en la tubería o sensor diferencial descalibrado hoy hoy.", "La carga de refrigerante que podría estar congelando el agua en tubos hoy.", "El sentido de rotación del motor del compresor centrífugo del sistema hoy.", "La apertura de las válvulas de expansión del circuito de refrigeración hoy."], respuesta_correcta:0, explicacion:"Flow Switch Alarm con bomba encendida apunta al sensor de detección: paddle roto, aire atrapado en la tubería, o sensor diferencial descalibrado que genera la alarma falsamente." },
  { id:"ns_0986", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter gotea agua dentro solo cuando compresor para. ¿Causa?", opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.", "La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.", "El serpentín está tan frío que el agua se congela y luego se derrite rápido.", "La humedad en la habitación es superior al 95% y satura el serpentín hoy."], respuesta_correcta:0, explicacion:"El goteo solo al parar el compresor indica contrapendiente o bloqueo parcial en el drenaje que retiene agua durante la operación y la libera cuando la unidad se detiene." },
  { id:"ns_0987", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene presión estática de 0.9 en suministro y 0.2 en retorno. ¿Qué es?", opciones:["Restricción severa en conductos de suministro o difusores cerrados hoy hoy.", "Los conductos de retorno son demasiado pequeños para el volumen de aire hoy.", "El filtro de aire está completamente tapado y no deja pasar el flujo hoy.", "El motor del soplador está girando en sentido contrario al de diseño hoy."], respuesta_correcta:0, explicacion:"Presión estática de 0.9\" en suministro frente a 0.2\" en retorno muestra que la restricción del sistema está concentrada en el lado de suministro. Conductos restringidos o difusores cerrados son la causa directa." },
  { id:"ns_0988", categoria:"NATE_SR_HEATPUMP", pregunta:"Una bomba de calor tiene un Delta T de 15°F en modo calor. ¿Es aceptable?", opciones:["No, un Delta T saludable en modo calor debe estar entre 20°F y 30°F hoy.", "Sí, las bombas de calor siempre tienen un diferencial menor que hornos hoy.", "Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.", "No, indica que las resistencias de apoyo no están funcionando en el ciclo."], respuesta_correcta:0, explicacion:"Un Delta T de 15F en modo calor es inferior al rango normal de 20-30F. Refleja capacidad insuficiente, cuyas causas comunes son baja carga de refrigerante, flujo de aire excesivo o mala absorcion de calor en el serpentin exterior." },
  { id:"ns_0989", categoria:"NATE_SR_MANAGEMENT", pregunta:"Un Senior lidera reemplazo de compresor 10 HP. ¿Qué paso es vital post-quemadura?", opciones:["Realizar prueba acidez aceite y usar filtros succión de limpieza hoy hoy.", "Añadir aditivo sellador de fugas para prevenir fallas futuras en líneas hoy.", "Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.", "Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy."], respuesta_correcta:0, explicacion:"El paso más importante tras un burnout es evaluar la contaminación con una prueba de acidez del aceite e instalar filtros de succión de limpieza. Sin estos pasos, los ácidos y residuos del compresor quemado destruirán el compresor de reemplazo." },
  { id:"ns_0990", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene purga que marca 'Water Detected'. ¿Qué acción es urgente?", opciones:["Realizar prueba presión a tubos del evaporador para buscar rupturas hoy hoy.", "Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.", "Aumentar la temperatura del agua helada para evitar que vapor condense hoy.", "Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy."], respuesta_correcta:0, explicacion:"Water Detected por la purga requiere acción urgente: prueba de presión a los tubos del evaporador para identificar la ruptura que está permitiendo la infiltración de agua al refrigerante." },
  { id:"ns_0991", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene succión 130 PSI y descarga 380 PSI. Subenfriamiento 12°F. ¿Estado?", opciones:["Funcionamiento óptimo; las presiones y el subenfriamiento están en rango.", "Falta de refrigerante líquido; el subenfriamiento debería ser 15 grados hoy.", "Exceso de carga; el subenfriamiento indica que el condensador está lleno hoy.", "Compresor fallando; la diferencia presión entre succión y descarga es baja hoy."], respuesta_correcta:0, explicacion:"Presiones de 130/380 PSI con subenfriamiento de 12°F están dentro del rango óptimo para R-410A. El subenfriamiento entre 10-15°F confirma carga correcta y todos los componentes funcionando adecuadamente." },
  { id:"ns_0992", categoria:"NATE_SR_PACKAGE", pregunta:"En unidad paquete, contactor compresor zumba pero no cierra. ¿Qué revisa?", opciones:["Voltaje en la bobina (24V) y si hay suciedad u óxido en el núcleo hoy hoy.", "Si los contactos principales están quemados o soldados entre sí hoy hoy hoy.", "El capacitor de arranque del compresor que podría estar descargado hoy hoy.", "La continuidad de los fusibles de potencia de la línea de 240 voltios hoy."], respuesta_correcta:0, explicacion:"El diagnóstico de un contactor que zumba sin cerrar siempre comienza midiendo el voltaje de la bobina y verificando el estado mecánico del núcleo. Estas dos condiciones determinan directamente si la fuerza electromagnética es suficiente para vencer el resorte y cerrar los contactos de potencia." },
  { id:"ns_0993", categoria:"NATE_SR_CEO", pregunta:"Un CEO descubre que un técnico cobra 'por fuera' a clientes. ¿Qué acción toma?", opciones:["Despido inmediato y posible acción legal según contrato de trabajo hoy hoy.", "Hablar con el técnico y pedirle una comisión por esos trabajos extras hoy.", "Ignorar la situación si el técnico es el que más dinero genera hoy hoy hoy.", "Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."], respuesta_correcta:0, explicacion:"El cobro por fuera a clientes es fraude laboral grave; el despido inmediato con posible acción legal según el contrato es la respuesta proporcional y necesaria." },
  { id:"ns_0994", categoria:"NATE_SR_RACK", pregunta:"Un rack usa R-448A. ¿Por qué es fundamental cargar líquido en recibidor?", opciones:["Para evitar fraccionamiento de mezcla y asegurar composición correcta hoy.", "Para que el refrigerante se mezcle más rápido con aceite POE del rack hoy.", "Para prevenir que válvulas de descarga de compresores se calienten hoy hoy.", "Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."], respuesta_correcta:0, explicacion:"Toda mezcla zeotrópica como el R-448A debe cargarse en fase líquida. Esto asegura que los cinco componentes de la mezcla entren al sistema en la proporción especificada, evitando el fraccionamiento que alteraría el rendimiento del sistema." },
  { id:"ns_0995", categoria:"NATE_SR_CHILLERS", pregunta:"Un chiller tiene sensor de 'Entering Water' roto. ¿Efecto Senior?", opciones:["El controlador no podrá calcular la carga térmica real del edificio hoy hoy.", "El compresor se apagará inmediatamente por seguridad de flujo de agua hoy.", "La unidad operará siempre al 100% de su capacidad nominal sin modular hoy.", "No hay efecto si el sensor de 'Leaving Water' está operando correctamente hoy."], respuesta_correcta:0, explicacion:"Sin sensor de entering water operativo, el controlador no puede calcular la carga térmica del edificio (Delta T), afectando directamente su capacidad de modular la operación del chiller." },
  { id:"ns_0996", categoria:"NATE_SR_HVAC", pregunta:"Un sistema tiene descarga de 550 PSI con R-410A. Condensador limpio. ¿Causa?", opciones:["Incondensables (aire) en el sistema o ventilador exterior fallando hoy hoy.", "Falta de refrigerante líquido que impide que el sistema enfríe el aire hoy.", "Válvula de expansión electrónica bloqueada en posición de abierta total hoy.", "El compresor está perdiendo eficiencia y no logra comprimir el gas ralo hoy."], respuesta_correcta:0, explicacion:"Con condensador limpio, una descarga de 550 PSI indica incondensables (aire o nitrógeno) atrapados en el sistema que elevan artificialmente la presión, o un ventilador exterior que no funciona correctamente impidiendo la convección forzada necesaria." },
  { id:"ns_0997", categoria:"NATE_SR_CEO", pregunta:"Un CEO quiere entrar al mercado 'Smart Homes'. ¿Qué equipo técnico requiere?", opciones:["Técnicos capacitados en redes, protocolos de comunicación e integración hoy.", "Personal experto en la instalación de conductos de lámina galvanizada hoy.", "Instaladores de paneles solares con certificación eléctrica industrial hoy.", "Vendedores que se enfoquen en la eficiencia SEER de los equipos básicos hoy."], respuesta_correcta:0, explicacion:"Smart Homes necesita técnicos capacitados en redes y protocolos de comunicación para integrar sistemas HVAC inteligentes con la infraestructura tecnológica del hogar." },
  { id:"ns_0998", categoria:"NATE_SR_RACK", pregunta:"En rack paralelo, ¿qué indica una temperatura de succión muy alta en cabezal?", opciones:["Sobrecalentamiento excesivo que dañará la lubricación de compresores pronto.", "Que el sistema está operando a su máxima eficiencia de evaporación hoy hoy.", "Falta de refrigerante líquido en recibidor principal del rack paralelo hoy.", "Que las válvulas EPR de todas las vitrinas están cerradas por temperatura."], respuesta_correcta:0, explicacion:"Un sobrecalentamiento excesivo en el cabezal de succión significa que los compresores operan con gas demasiado caliente, lo que reduce la capacidad lubricante del aceite, aumenta la temperatura de descarga y puede dañar permanentemente los devanados del motor." },
  { id:"ns_0999", categoria:"NATE_SR_MINISPLIT", pregunta:"Un mini-split inverter no calienta. Voltaje entre S2 y S3 es 24V fijos. ¿Causa?", opciones:["Falla de comunicación; el voltaje debería fluctuar entre 0 y 24V hoy hoy hoy.", "La placa exterior está operando correctamente enviando la señal de control.", "El compresor inverter está aterrizado y consume el voltaje de comunicación.", "Falta de alimentación de 240VAC en los terminales L1 y L2 de la exterior hoy."], respuesta_correcta:0, explicacion:"La comunicación inverter entre S2 y S3 usa voltaje DC pulsante. Un valor fijo de 24V indica que no hay modulación de señal, confirmando una falla de comunicación digital entre las unidades." },
  { id:"ns_1000", categoria:"NATE_SR_PACKAGE", pregunta:"Para un CEO/Senior, ¿cuál es el indicador de éxito técnico y comercial definitivo?", opciones:["Cero callbacks, alta rentabilidad neta y técnicos certificados en formación.", "Tener la mayor cantidad de clientes en la base de datos de la ciudad hoy.", "Comprar la flota de camionetas más modernas cada año de forma constante hoy.", "Que el termostato del cliente siempre marque 72 grados sin importar el clima."], respuesta_correcta:0, explicacion:"Cero callbacks significa trabajo hecho correctamente la primera vez, alta rentabilidad refleja eficiencia operativa, y técnicos certificados en formación aseguran crecimiento sostenible. Estos tres indicadores combinan calidad técnica con visión empresarial a largo plazo." }
];

